		#region TestPerformance_FinalisePickAndSave_DBHits

		public void TestPerformance_FinalisePickAndSave_DBHits()
		{
			// create 10 locations
			var data = new TestDataSimpleEnvironment(Factory, 10, 1);

			// create 100 receives with 10 lines in each location
			var locations = data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations;
			for (var l = 0; l < 10; l++)
			{
				for (var r = 0; r < 10; r++)
				{
					Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R" + l + r, data.Part1, 2m, locations[l], "");
				}
			}
			Factory.Save();

			// create a single order and pick
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 2m);
			var pick = Helper.CreatePickNew(false, false, order);
			Factory.Save();

			// finalise orders, pick and save
			var newFactory = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);

			pickInNewFactory.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(pickInNewFactory.Orders.Cast<WhsOrder>().Single());

			pickInNewFactory.FinalisePick();
			AssertIsFinalisedPrecondition(pickInNewFactory);

			Factory.Save();

			var expectedNoMoreThan_5_DBHitsPerTable = new Dictionary<string, int>();
			AssertDbHits(expectedNoMoreThan_5_DBHitsPerTable, newFactory, true);
		}

