		void AssertPerformance_OrderedInventoryAutoAllocateCore(int expectedHits, Action<WhsPickOrderedInventory> allocateInventory, bool enableHeldGoodsForOrders = true)
		{
			using (WarehouseDataRegistry.Instance.EnableHeldGoodsForOrders.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, enableHeldGoodsForOrders))
			{
				var data = new TestDataSimpleEnvironment(Factory, 10, 1);
				Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, true);
				Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);

				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
				for (var i = 0; i < 5; i++)
				{
					Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 6m, data.Whs1.DefaultLocation, ZDate.Empty, ZDate.Empty, "Black", "", "", "");
					Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 4m, data.Whs1.DefaultLocation, ZDate.Empty, ZDate.Empty, "Green", "", "", "");
				}
				receive.FinaliseDocket();
				AssertIsFinalisedPrecondition(receive);

				var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
				var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 6m);
				var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O3", data.Part1, 7m);
				var order4 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O4", data.Part1, 8m);
				var order5 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O5", data.Part1, 9m);
				var order6 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O6", data.Part1, 10m);
				var order7 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O7", data.Part1, 11m);
				Factory.Save();

				var pick = Helper.CreatePickNew(order1, order2, order3, order4, order5, order6, order7);
				var orderedInventories = pick.OrderedInventories;
				AssertEquals("Precondition: OrderedInventories exist", 1, orderedInventories.Count);

				pick.ClearAllocatedItems();
				AssertPersistentPropertiesHitCount("AvailableInventories should not access docket line properties extensively.", typeof(WhsInventoryView), expectedHits, () =>
				{
					foreach (WhsPickOrderedInventory inventory in orderedInventories)
					{
						allocateInventory(inventory);
					}
				});
			}
		}

