		#region Customs Stuff

		public void TestIsCustomsTransaction()
		{
			var pickInterface = (IWhsPick)Pick;
			AssertEquals(false, Pick.IsCustomsTransaction);
			AssertEquals(false, pickInterface.IsCustomsTransaction);

			var order = Factory.New<WhsOrder>();
			AssertEquals(false, order.IsCustomsTransaction);
			AssertEquals(false, order.IsCustomsDataVisible);

			Pick.Orders.Add(order);
			AssertEquals(false, Pick.IsCustomsTransaction);
			AssertEquals(false, pickInterface.IsCustomsTransaction);

			order.WD_DocketSubType = CodeLists.OrderType.Codes.Customs;
			AssertEquals(true, order.IsCustomsTransaction);
			AssertEquals(true, Pick.IsCustomsTransaction);
			AssertEquals(true, pickInterface.IsCustomsTransaction);
			AssertEquals(true, order.IsCustomsDataVisible);
		}

		public void TestIsCustomsTransaction_MixedWithNormalOrder()
		{
			AssertEquals(false, Pick.IsCustomsTransaction);

			var normalOrder = Factory.New<WhsOrder>();
			AssertEquals(false, normalOrder.IsCustomsTransaction);
			AssertEquals(false, normalOrder.IsCustomsDataVisible);

			Pick.Orders.Add(normalOrder);
			AssertEquals(false, Pick.IsCustomsTransaction);

			var customsOrder = Factory.New<WhsOrder>();
			customsOrder.WD_DocketSubType = CodeLists.OrderType.Codes.Customs;
			AssertEquals(true, customsOrder.IsCustomsTransaction);
			AssertEquals(true, customsOrder.IsCustomsDataVisible);

			Pick.Orders.Add(customsOrder);
			AssertEquals(true, Pick.IsCustomsTransaction);
		}

