		#region TestRunPreSaveValidation

		public void TestRunPreSaveValidation()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);

			var otherFactory = new BusinessObjectFactory();
			var orderLineInOtherFactory = otherFactory.Load<WhsOrderLine>(orderLine.PK);
			orderLineInOtherFactory.WE_TransactionQuantity = 5m; // make the pick lines over released.
			AssertEquals("Precondition: Release Lines not built.", false, orderLineInOtherFactory.IsReleaseLineCollectionBuilt);

			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			pickInOtherFactory.RunPreSaveValidation();
			AssertEquals("Release Lines should not be built if we are on the Release Screen.", false,
				orderLineInOtherFactory.IsReleaseLineCollectionBuilt);
			AssertEquals("No Errors should be on the Pick.", false, pick.HasErrors);

			pickInOtherFactory.IsAlterPick = true;
			pickInOtherFactory.RunPreSaveValidation();
			AssertEquals("Release Lines should be built during Pre-Save Validtion of a Release Pick.", true,
				orderLineInOtherFactory.IsReleaseLineCollectionBuilt);
			AssertHasError(orderLineInOtherFactory.ReleaseLines[0].QuantityInfo,
				"Quantity Met cannot be greater than Quantity Ordered");

			orderLineInOtherFactory.ClearReleaseLines();
			AssertEquals("Precondition: Release Lines are cleared.", false,
				orderLineInOtherFactory.IsReleaseLineCollectionBuilt);

			pickInOtherFactory.RunPreSaveValidation();
			AssertEquals("Order should not have finalised.", false, pickInOtherFactory.IsFinalised);
			AssertEquals("Release Lines should be built during Pre-Save Validtion of a Release Pick.", true,
				orderLineInOtherFactory.IsReleaseLineCollectionBuilt);
			AssertHasError(orderLineInOtherFactory.ReleaseLines[0].QuantityInfo,
				"Quantity Met cannot be greater than Quantity Ordered");
		}

		public void TestRunPreSaveValidation_WithDeletedPickLine()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			pick.IsAlterPick = true;
			AssertEquals("Precondition", 1, pick.GetAllPickLines().Count());

			var availableInventory = pick.OrderedInventories[0].AvailableInventories[0];
			var poke = availableInventory.AvailableInventoriesSplitByPickedDetails;
			availableInventory.PickLines.Single().Delete();
			AssertEquals(0m, availableInventory.PickLineQuantity);
			AssertNoExceptionThrown(() => pick.RunPreSaveValidation());
		}

