		void AssertAttachedDocketTypeMatchesPickType(Func<WhsPickableDocket> getDocket, string pickType, string expectedError)
		{
			var pick = Factory.New<WhsPick>();
			pick.WP_PickType = pickType;

			var docket = getDocket();

			var notify = new TestNotificationBuffer();
			pick.NotificationManager.Push(notify);

			if (string.IsNullOrEmpty(expectedError))
			{
				pick.Orders.Add(docket);
				AssertEquals(pick.PK, docket.WD_WP);
			}
			else
			{
				AssertEquals("Prerequisite", null, notify.LastEvent);
				AssertExceptionThrown<WhsException>("Pick type and docket type must match.", () => pick.Orders.Add(docket));
				AssertEquals(expectedError, notify.LastEvent.Message);
			}
		}

		const string ExpectedMissmatchErrrorMessageORD = "Error: This Pick can only be used with Order job types. Attach an order of this type, or cancel the Pick and create a new one to proceed.";
		const string ExpectedMissmatchErrrorMessageORD_ExpectHeldInventory = "Error: This Pick can only be used with orders for held inventory. Attach an order of this type, or cancel the Pick and create a new one to proceed.";
		const string ExpectedMissmatchErrrorMessageORD_ExpectAvailableInventory = "Error: This Pick can only be used with orders not containing held inventory. Attach an order of this type, or cancel the Pick and create a new one to proceed.";
		const string ExpectedMissmatchErrrorMessageWOR = "Error: This Pick can only be used with Work Order job types. Attach an order of this type, or cancel the Pick and create a new one to proceed.";
		const string ExpectedMissmatchErrrorMessageDWO = "Error: This Pick can only be used with Dynamic Work Order job types. Attach an order of this type, or cancel the Pick and create a new one to proceed.";

