		#region TestGetPickTypeToMatchDocket

		public void TestGetPickTypeToMatchDocket()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			var orderNoLines = Helper.CreateWhsOrder(data.Org1, data.Whs1, "ORD-01");

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "ORD-01", data.Part1, 10m);

			var heldInventoryOrder = Helper.CreateWhsOrder(data.Org1, data.Whs1, "ORD-02");
			var heldInventoryOrderLine = Helper.CreateWhsOrderLine(heldInventoryOrder, data.Part1, 10m);
			heldInventoryOrderLine.WE_WHC_NKOrderedHeldCode = "DAM";

			var workOrder = Helper.CreateWhsWorkOrderWithLine(data.Org1, data.Whs1, "WOR-01", data.Part1, 10m);

			var dynamicWorkOrder = Helper.CreateWhsDynamicWorkOrderWithLine(data.Org1, data.Whs1, "DWO-01", data.Part1, 10m);

			var actualOrderNoLinesPickType = WhsPick.GetPickTypeToMatchDockets(new[] { orderNoLines } );
			var orderPickType = WhsPick.GetPickTypeToMatchDockets(new[] { order });
			var heldInventoryOrderPickType = WhsPick.GetPickTypeToMatchDockets(new[] { heldInventoryOrder });
			var workOrderPickType = WhsPick.GetPickTypeToMatchDockets(new[] { workOrder });
			var dynamicWorkOrderPickType = WhsPick.GetPickTypeToMatchDockets(new[] { dynamicWorkOrder });

			AssertEquals(PickType.Codes.Order, actualOrderNoLinesPickType);
			AssertEquals(PickType.Codes.Order, orderPickType);
			AssertEquals(PickType.Codes.HeldInventoryOrder, heldInventoryOrderPickType);
			AssertEquals(PickType.Codes.WorkOrder, workOrderPickType);
			AssertEquals(PickType.Codes.DynamicWorkOrder, dynamicWorkOrderPickType);
		}

