		public void TestOnFactorySaving_UpdatesPickStatus()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			WhsOrder order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", data.Notify);
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order, data.Part1, 1000m);
			Pick.Orders.Add(order);
			Factory.Save();
			AssertEquals("PreCondition", PickStatus.Codes.Building, Pick.WP_PickStatus);

			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.None;
			Factory.Save();
			AssertEquals(PickStatus.Codes.Created, Pick.WP_PickStatus);

			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Factory.Save();
			AssertEquals(PickStatus.Codes.Building, Pick.WP_PickStatus);

			Pick.WP_PickStatus = PickStatus.Codes.PickSlip;
			Factory.Save();
			AssertEquals(PickStatus.Codes.Building, Pick.WP_PickStatus);

			Pick.WP_PickStatus = PickStatus.Codes.Cancelled;
			Factory.Save();
			AssertEquals(PickStatus.Codes.Cancelled, Pick.WP_PickStatus);

			Pick.WP_PickStatus = PickStatus.Codes.Finalised;
			Pick.WP_FinalizedDateUtc = ZDateTime.UtcNow;
			order.WD_DocketStatus = WhsOrderStatus.Codes.Departed;
			order.WD_FinalisedDate = ZDateTimeOffset.UtcNow;
			Factory.Save();
			AssertEquals(PickStatus.Codes.Finalised, Pick.WP_PickStatus);
		}

