		public void TestOnFinaliseSucceeded_PackageJobFinalise_MultiPickForOneConsolidationHU()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var packingHelper = new PackingTestHelper(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 50m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick1 = Helper.CreatePickNew(order1);
			var pickLine1 = pick1.GetAllPickLines().Single();
			pickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine1.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;

			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
			var pick2 = Helper.CreatePickNew(order2);
			var pickLine2 = pick2.GetAllPickLines().Single();
			pickLine2.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine2.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;

			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O3", data.Part1, 10m);
			var pick3 = Helper.CreatePickNew(order3);
			var pickLine3 = pick3.GetAllPickLines().Single();
			pickLine3.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine3.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;
			Factory.Save();

			var pkgJob1 = PkgPackageJob.LoadOrCreatePackageJob(order1);
			var pkg1 = packingHelper.CreatePackage(pkgJob1, "PKG1", 1, PkgUnit.Box);
			packingHelper.CreatePackageDivot(pkg1, pickLine1);

			var pkgJob2 = PkgPackageJob.LoadOrCreatePackageJob(order2);
			var pkg2 = packingHelper.CreatePackage(pkgJob2, "PKG2", 1, PkgUnit.Box);
			packingHelper.CreatePackageDivot(pkg2, pickLine2);

			var pkgJob3 = PkgPackageJob.LoadOrCreatePackageJob(order3);
			var pkg3 = packingHelper.CreatePackage(pkgJob3, "PKG3", 1, PkgUnit.Box);
			packingHelper.CreatePackageDivot(pkg3, pickLine3);

			var handlingUnit = packingHelper.CreatePkgHandlingUnit(data.Whs1.WW_GB_RelatedCompanyBranch, "3PL");
			var handlingUnitPackageJob = PkgPackageJob.LoadOrCreatePackageJob(handlingUnit);
			var handlingUnitPackage = packingHelper.CreatePackage(handlingUnitPackageJob, "HU1", 1, PkgUnit.Package);
			packingHelper.PackHandlingUnit(handlingUnitPackage, pkg1, handlingUnitPackage);
			packingHelper.PackHandlingUnit(handlingUnitPackage, pkg2, handlingUnitPackage);
			packingHelper.PackHandlingUnit(handlingUnitPackage, pkg3, handlingUnitPackage);
			handlingUnitPackage.KP_ClosedTimeUtc = ZDateTime.Now;
			Factory.Save();

			pick1.FinaliseAllOrders();
			pick1.FinalisePick();
			Factory.Save();

			AssertEquals("Package Job's IsFinalised flag set to true when pick finalised.", true, pkgJob1.KJ_IsFinalized);
			AssertEquals("Package Job of handling unit's IsFinalised flag shouldn't set to true when have Pick not finalised", false, handlingUnitPackageJob.KJ_IsFinalized);

			pick2.FinaliseAllOrders();
			pick2.FinalisePick();
			Factory.Save();

			AssertEquals("Package Job's IsFinalised flag set to true when pick finalised.", true, pkgJob2.KJ_IsFinalized);
			AssertEquals("Package Job of handling unit's IsFinalised flag shouldn't set to true when have Pick not finalised", false, handlingUnitPackageJob.KJ_IsFinalized);

			pick3.FinaliseAllOrders();
			pick3.FinalisePick();
			Factory.Save();

			AssertEquals("Package Job's IsFinalised flag set to true when pick finalised.", true, pkgJob3.KJ_IsFinalized);
			AssertEquals("Package Job of handling unit's IsFinalised flag should set to true when all Pick finalised.", true, handlingUnitPackageJob.KJ_IsFinalized);
		}

		public void TestOnFinaliseSucceeded_PackageJobFinalise_LoadHU()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var packingHelper = new PackingTestHelper(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var load = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation, jobID: "L1");
			var yesterday = ZDateTimeOffset.Today.AddDays(-1);
			load.WLO_StartTime = yesterday;
			load.WLO_TransportationUnitNumber = "4543";
			load.WLO_CompleteTime = yesterday;
			order.WD_WLO_PlannedLoad = load.PK;
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			var pickLine = pick.GetAllPickLines().Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;
			Factory.Save();

			var pkgJob = PkgPackageJob.LoadOrCreatePackageJob(order);
			var package = packingHelper.CreatePackage(pkgJob, "PKG1", 1, PkgUnit.Box);
			packingHelper.CreatePackageDivot(package, pickLine);
			package.KP_ClosedTimeUtc = ZDateTime.UtcNow;

			var handlingUnit = packingHelper.CreatePkgHandlingUnit(data.Whs1.WW_GB_RelatedCompanyBranch, "3PL");
			var handlingUnitPackageJob = PkgPackageJob.LoadOrCreatePackageJob(handlingUnit);
			var handlingUnitPackage = packingHelper.CreatePackage(handlingUnitPackageJob, "HU1", 1, PkgUnit.Package);
			packingHelper.PackHandlingUnit(handlingUnitPackage, package, handlingUnitPackage);
			handlingUnitPackage.KP_ClosedTimeUtc = ZDateTime.UtcNow;
			Factory.Save();

			var pivotPKG = Helper.CreateLoadPkgPackagePivot(package.PK, load);
			pivotPKG.WLP_LoadedTime = ZDateTimeOffset.Now;
			pivotPKG.WLP_GS_NKLoadingUser = "LTS";

			var pivotHU = Helper.CreateLoadPkgPackagePivot(handlingUnitPackage.PK, load);
			pivotHU.WLP_LoadedTime = ZDateTimeOffset.Now;
			pivotHU.WLP_GS_NKLoadingUser = "LTS";

			var handlingUnitLoad = Factory.New<PkgHandlingUnit>();
			handlingUnitLoad.KPU_GB_Branch = data.Whs1.WW_GB_RelatedCompanyBranch;
			handlingUnitLoad.KPU_JobContext = "3PL";

			var handlingUnitLoadPackageJob = PkgPackageJob.LoadOrCreatePackageJob(handlingUnitLoad);
			var handlingUnitLoadPackage = PackingHelper.CreatePackage(handlingUnitLoadPackageJob, "LoadHU", 1, PkgUnit.Package);

			PackingHelper.PackHandlingUnit(handlingUnitLoadPackage, handlingUnitPackage, handlingUnitLoadPackage);
			package.KP_KP_TopHandlingUnitPackage = handlingUnitLoadPackage.PK;

			var pivotLoadHU = Helper.CreateLoadPkgPackagePivot(handlingUnitLoadPackage.PK, load);
			pivotLoadHU.WLP_LoadedTime = ZDateTimeOffset.Now;
			pivotLoadHU.WLP_GS_NKLoadingUser = "LTS";
			Factory.Save();

			pick.FinaliseAllOrders();
			pick.FinalisePick();
			Factory.Save();

			AssertEquals("Package Job's IsFinalised flag set to true when pick finalised.", true, pkgJob.KJ_IsFinalized);
			AssertEquals("Package Job of handling unit's IsFinalised flag set to true when pick finalised.", true, handlingUnitLoadPackageJob.KJ_IsFinalized);

			AssertEquals("Order package is closed.", true, package.IsClosed);
			AssertEquals("Consolidated HU package is closed.", true, handlingUnitPackage.IsClosed);
			AssertEquals("Load HU package is NOT closed.", false, handlingUnitLoadPackage.IsClosed);
		}

