		#region TestClone

		public void TestClone()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_IsAwaitingReplenishment = true;
			pick.WP_PickCasesByLabel = true;
			pick.WP_CartoniseSplitCases = true;
			pick.WP_ForceSplitCaseUOMTypeAllocation = true;
			pick.WP_PickOption = "AUT";
			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.Ready;

			var clonedPick = (WhsPick)pick.Clone();
			Assert("New Object", !Object.ReferenceEquals(pick, clonedPick));

			AssertNotEquals("Pick No should not be cloned", pick.WP_PickNo, clonedPick.WP_PickNo);
			AssertNotEquals("WP_IsAwaitingReplenishment should not be cloned", pick.WP_IsAwaitingReplenishment, clonedPick.WP_IsAwaitingReplenishment);
			AssertNotEquals("WP_TaskPlanningStatus should not be cloned", TaskPlanningStatus.Codes.Ready, clonedPick.WP_TaskPlanningStatus);

			AssertEquals("WP_WW_Whs same", pick.WP_WW_Whs, clonedPick.WP_WW_Whs);
			AssertEquals("WP_WL_DockDoor same", pick.WP_WL_DockDoor, clonedPick.WP_WL_DockDoor);
			AssertEquals("WP_WA_DynamicPickAreaOverride same", pick.WP_WA_DynamicPickAreaOverride, clonedPick.WP_WA_DynamicPickAreaOverride);
			AssertEquals("WP_PickOption same", pick.WP_PickOption, clonedPick.WP_PickOption);
			AssertEquals("WP_PickPalletsByLabel same", pick.WP_PickPalletsByLabel, clonedPick.WP_PickPalletsByLabel);
			AssertEquals("PickPriority same", pick.PickPriority, clonedPick.PickPriority);
			AssertEquals("WP_PickCasesByLabel same", pick.WP_PickCasesByLabel, clonedPick.WP_PickCasesByLabel);
			AssertEquals("WP_CartoniseSplitCases same", pick.WP_CartoniseSplitCases, clonedPick.WP_CartoniseSplitCases);
			AssertEquals("WP_ForcePickByCaseUOMTypeAllocation same", pick.WP_ForcePickByCaseUOMTypeAllocation, clonedPick.WP_ForcePickByCaseUOMTypeAllocation);
			AssertEquals("WP_ForceSplitCaseUOMTypeAllocation same", pick.WP_ForceSplitCaseUOMTypeAllocation, clonedPick.WP_ForceSplitCaseUOMTypeAllocation);
		}

