			AssertEquals("Ordered inventories owner updated with the new order line added.", 3, pick.OrderedInventories[0].Owners.Count);
			AssertEquals("Ordered inventories quantity updated with the new order line added.", 30m, pick.OrderedInventories[0].QuantityOrdered);
