		public void TestRemoveDeletedPickByBOMInventoryFromCaches_ThrowsIfNotDeleted()
		{
			TestRemoveDeletedPickByBOMInventoryFromCachesCore(isDeleted: false);
		}

		public void TestRemoveDeletedPickByBOMInventoryFromCaches()
		{
			TestRemoveDeletedPickByBOMInventoryFromCachesCore(isDeleted: true);
		}

		void TestRemoveDeletedPickByBOMInventoryFromCachesCore(bool isDeleted)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;

			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(bike, frame, 1m, Constants.PkgUnit.Unit);
			var location = data.Whs1.FindLocation("A-1");
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, wheel, 4m, location);
			Helper.CreateWhsReceiveInventoryLine(receive, frame, 2m, location);
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive.IsFinalised);
			Factory.Save();

			var kitOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "KIT1", bike, 2m);
			var kitOrderLine = kitOrder.Lines[0];
			var pick = Helper.CreatePickNew(kitOrder);
			Factory.Save();

			pick.ClearInventoryCache();
			var kitReceive = Factory.LoadTop1<WhsDocket>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			var kitReceiveLine = kitReceive.Lines.Single();

			var orderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(oi => oi.Owners.Contains(kitOrderLine));
			AssertEquals(true, pick.AllInventories.Any(inv => inv.PK == kitReceiveLine.PK));
			AssertEquals(true, pick.FindInventoryByOrderedInventoryFromAllInventories(orderedInventory).Any(inv => inv.PK == kitReceiveLine.PK));
			AssertEquals(true, orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>().Single().Inventory.Any(inv => inv.PK == kitReceiveLine.PK));

			if (isDeleted)
			{
				kitReceiveLine.Delete();
				pick.RemoveDeletedPickByBOMInventoryFromCaches(kitReceiveLine, kitOrderLine.WE_OP, kitOrder.WD_OH_Client);

				AssertEquals(false, pick.AllInventories.Any(inv => inv.PK == kitReceiveLine.PK));
				AssertEquals(false, pick.FindInventoryByOrderedInventoryFromAllInventories(orderedInventory).Any(inv => inv.PK == kitReceiveLine.PK));
				AssertEquals(false, orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>().Single().Inventory.Any(inv => inv.PK == kitReceiveLine.PK));
			}
			else
			{
				AssertExceptionThrown<ArgumentException>("We can only remove deleted inventory from the caches.",
					() => pick.RemoveDeletedPickByBOMInventoryFromCaches(kitReceiveLine, kitOrderLine.WE_OP, kitOrder.WD_OH_Client));
			}
		}

