			pick.AddOrders(new[] { order2 });
			pick.ClearAllInventoriesCache();
			AssertContainsExactElementsInAnyOrder("Should return all relevant inventories.", new[] { receive1_inv1, receive1_inv2, receive2_inv1 }, pick.GetFilteredInventories(new ZQuery()));
			AssertContainsExactElementsInAnyOrder("Should return filtered inventories.", new[] { receive2_inv1 }, pick.GetFilteredInventories(new ZQuery(WhsInventoryViewSchema.WI_PalletID, "Z3")));
			AssertContainsExactElementsInAnyOrder("AllInventories should be unaffected.", new[] { receive1_inv1, receive1_inv2, receive2_inv1 }, pick.AllInventories);
		}

		public void TestGetFilteredInventories_DbHits()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);

			for (int i = 1; i <= 25; i++)
			{
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, data.Whs1.DefaultLocation, "Z" + i);
			}

			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals(true, receive.IsFinalised);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);

			var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);

			var inventories = pickInFactory2.GetFilteredInventories(new ZQuery());

			foreach (var inventory in inventories)
			{
				var poke1 = inventory.AllPickLines;
				var poke2 = inventory.InDocketLine;
			}

			var expectedDbHits = new Dictionary<string, int>()
			{
				{ OrgHeaderSchema.Constants.TableName, 1 },
				{ OrgMiscServSchema.Constants.TableName, 1 },
				{ OrgSupplierPartSchema.Constants.TableName, 1 },
				{ WhsWarehouseSchema.Constants.TableName, 1 },
				{ WhsPickSchema.Constants.TableName, 1 },
				{ WhsDocketSchema.Constants.TableName, 1 },
				{ WhsInventoryViewSchema.Constants.TableName, 1 },
				{ WhsDocketLineSchema.Constants.TableName, 2 },
				{ WhsPickLineSchema.Constants.TableName, 2 },
			};

			AssertDbHits(expectedDbHits, factory2);
		}

