			var customsOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 3m);
			customsOrder.WD_DocketSubType = OrderType.Codes.Customs;
			pick.AddOrders(new[] { customsOrder });
			AssertContainsExactElementsInAnyOrder("Should load free store and customs inventory line.", new[] { inventory1, inventory3 }, pick.AllInventories);

			var iprOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			iprOrder.WD_DocketSubType = OrderType.Codes.Customs;
			iprOrder.WD_IsInwardsProcessingJob = true;
			pick.AddOrders(new[] { iprOrder });
			AssertContainsExactElementsInAnyOrder("Should load all inventory.", new[] { inventory1, inventory2, inventory3 }, pick.AllInventories);
		}

		public void TestAllInventories_ExcludesKitsWithSecondaryProductsForDisassemblyWorkOrder()
		{
			var warehouse = Helper.CreateWarehouse("WHS", "A", 2, 1);
			Helper.EnableWarehouseForBond(warehouse, true);
			warehouse.WW_IsVirtualWarehouse = true;

			var area = Helper.CreateArea(warehouse, "IPR", AreaTypes.Codes.InwardProcessing);
			var row = Helper.CreateRowAndGenerateLocations(warehouse, "I");
			var location = row.Locations.Single();
			location.WLV_WA_PutawayArea = area.PK;
			location.WLV_WA_PickingArea = area.PK;
			Factory.Save();

			var client = Helper.CreateClient("C1");
			var component = Helper.CreateProduct("Component", client);
			var mainProduct1 = Helper.CreateProduct("Main Product", client);
			var secondaryProduct = Helper.CreateProduct("Secondary Product", client);

			var componentReceive = Helper.CreateWhsReceive(client, warehouse, "R1");
			componentReceive.WD_DocketSubType = ReceiveType.Codes.Customs;
			componentReceive.WD_IsInwardsProcessingJob = true;

			Helper.CreateWhsReceiveInventoryLine(componentReceive, component.PK, 10m, warehouse.DefaultLocationInInwardProcessingArea.PK, palletID: "", entryKey: "ENT-1");
			componentReceive.FinaliseDocket();
			AssertIsFinalisedPrecondition(componentReceive);

			Factory.Save();

			var componentBOM = Helper.CreateProductBOM(mainProduct1, component, 2m, "UNT");
			var secondaryProductBOM = Helper.CreateSecondaryProduct(mainProduct1, secondaryProduct, 5m);
			var componentUsage = secondaryProductBOM.ComponentUsages.AddNew();
			componentUsage.OPP_OE_Component = componentBOM.PK;
			componentUsage.OPP_ComponentQuantity = 0.5m;

			var randomProduct1 = Helper.CreateProduct("RP1", client);
			Helper.CreateProductBOM(secondaryProduct, randomProduct1, 2m, "UNT");
			var randomProduct2 = Helper.CreateProduct("RP2", client);
			Helper.CreateProductBOM(component, randomProduct2, 2m, "UNT");

			Factory.Save();

			var assemblyWorkOrder1 = Helper.CreateWhsWorkOrderWithLine(client, warehouse, "ExtRef", mainProduct1, 5m);
			assemblyWorkOrder1.WD_DocketSubType = WorkOrderType.Codes.Assemble;
			assemblyWorkOrder1.WD_IsInwardsProcessingJob = true;
			assemblyWorkOrder1.WD_RequiredDate = ZDateTimeOffset.Now;

			var productParam = assemblyWorkOrder1.Lines[0].Product.ParamsByWhsAndClient.AddNew();
			productParam.W3_OH = client.PK;
			productParam.W3_WW = warehouse.PK;
			productParam.W3_WL_InwardsProcessingStagingLocationBOM = location.PK;

			Helper.CreatePickNew(assemblyWorkOrder1);
			assemblyWorkOrder1.FinaliseDocketAlwaysFinalisingPick();
			AssertIsFinalisedPrecondition(assemblyWorkOrder1);
			AssertIsFinalisedPrecondition(assemblyWorkOrder1.Receive);

			Factory.Save();

			var disassemblyWorkOrder = Helper.CreateWhsWorkOrder(client, warehouse);
			disassemblyWorkOrder.WD_DocketSubType = WorkOrderType.Codes.Disassemble;
			disassemblyWorkOrder.WD_IsInwardsProcessingJob = true;

			Helper.CreateWhsWorkOrderLine(disassemblyWorkOrder, mainProduct1, 1m);

			var pick1 = Factory.New<WhsPick>();
			pick1.AddOrders(new[] { disassemblyWorkOrder });
			AssertContainsExactElementsInAnyOrder("No inventories should be loaded.", Array.Empty<WhsInventoryView>(), pick1.AllInventories);

			var mainProduct2 = Helper.CreateProduct("Main Product 2", client);
			Helper.CreateProductBOM(mainProduct2, mainProduct1, 1m, "UNT");

			var assemblyWorkOrder2 = Helper.CreateWhsWorkOrderWithLine(client, warehouse, "ExtRef", mainProduct2, 1m);
			assemblyWorkOrder2.WD_DocketSubType = WorkOrderType.Codes.Assemble;
			assemblyWorkOrder2.WD_IsInwardsProcessingJob = true;
			assemblyWorkOrder2.WD_RequiredDate = ZDateTimeOffset.Now;

			var pick2 = Helper.CreatePickNew(assemblyWorkOrder2);
			var expectedInventory = assemblyWorkOrder1.Receive.Inventory.Cast<WhsInventoryView>().Single(i => i.WI_OP == mainProduct1.PK);
			AssertContainsExactElementsInAnyOrder("Inventory for kit should be loaded.", new[] { expectedInventory }, pick2.AllInventories);
		}

