			var componentAssemblyLine2 = assemblyWorkOrder2.Lines.AddNew();
			componentAssemblyLine2.WE_OP = mainProduct1.PK;
			componentAssemblyLine2.WE_TransactionQuantity = 10m;
			componentAssemblyLine2.WE_WE_ParentDocketLine = mainProductAssemblyLine2.PK;

			var pick2 = Helper.CreatePickNew(assemblyWorkOrder2);
