		public void TestAllInventories_ForAvailableInventoryOrders()
		{
			var data = new TestDataSimpleEnvironment(Helper.Factory, 3, 1);
			var location = data.Whs1.FindLocation("A-1");

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			var receiveLine1 = Helper.CreateWhsReceiveLine(receive, data.Part1, 8m, location, "");
			var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part1, 9m, location, "");
			var receiveLine3 = Helper.CreateWhsReceiveLine(receive, data.Part1, 6m, location, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Held);
			var receiveLine4 = Helper.CreateWhsReceiveLine(receive, data.Part1, 7m, location, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Damaged);
			receive.FinaliseDocketWithoutUserConfirmation();
			Factory.Save();

			var inv1 = receiveLine1.Inventory[0];
			var inv2 = receiveLine2.Inventory[0];

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);

			var pick = Helper.CreatePickByAttachingOrders(order);
			var orderedInventory = pick.OrderedInventories[0];

			AssertEquals("Available inventory is rolled up.", 1, orderedInventory.AvailableInventories.Count);
			AssertContainsExactElementsInAnyOrder("Only available inventory lines are used.", new[] { inv1, inv2 }, orderedInventory.AvailableInventories[0].Inventory);
			AssertEquals(17m, orderedInventory.AvailableInventories[0].QuantityAvailableToPick);
			AssertEquals(17m, orderedInventory.AvailableInventories[0].QuantityTotal);
		}

