				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
				var receiveLine1 = Helper.CreateWhsReceiveLine(receive, data.Part1, 6m, location, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Held);
				var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part1, 7m, location, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Held);
				var receiveLine3 = Helper.CreateWhsReceiveLine(receive, data.Part1, 8m, location, "");
				var receiveLine4 = Helper.CreateWhsReceiveLine(receive, data.Part1, 9m, location, "");
				receive.FinaliseDocketWithoutUserConfirmation();
				Factory.Save();

				var inv1 = receiveLine1.Inventory[0];
				var inv2 = receiveLine2.Inventory[0];
				var inv3 = receiveLine3.Inventory[0];
				var inv4 = receiveLine4.Inventory[0];

				var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				var order1Line = Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
				order1Line.WE_WHC_NKOrderedHeldCode = InventoryHoldCodes.Codes.Held;

				var pick = Helper.CreatePickByAttachingOrders(order1);
				var orderedInventory = pick.OrderedInventories[0];

				AssertEquals("Held inventory is rolled up.", 1, orderedInventory.AvailableInventories.Count);
				AssertContainsExactElementsInAnyOrder("Only held inventory lines are used.", new[] { inv1, inv2 }, orderedInventory.AvailableInventories[0].Inventory);
				AssertEquals(13m, orderedInventory.AvailableInventories[0].QuantityAvailableToPick);
				AssertEquals(13m, orderedInventory.AvailableInventories[0].QuantityTotal);
			}
		}

		public void TestAllInventories()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateMultiWarehouseClientProductInventory(TestDataForInventory.StockType.WithoutBondEntryKeys);

			// 1 Client 1 SupplierPart
