			Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order2, data.Part2, 10m);
			pick = Helper.CreatePickByAttachingOrders(order2);
			AssertContainsExactElementsInAnyOrder("Only 2 inventory lines should be loaded.", new[] { data.Line111, data.Line112 },
				pick.AllInventories);
			pick.Orders.RemoveAll();

			// 2 Clients 1 SupplierPart
			var order3 = Helper.CreateWhsOrder(data.Org2, data.Whs1);
			Helper.CreateWhsOrderLine(order3, data.Part1, 10m);
			pick = Helper.CreatePickByAttachingOrders(new[] { order1, order3 });
			AssertContainsExactElementsInAnyOrder("Only 2 inventory lines should be loaded.", new[] { data.Line111, data.Line211 },
				pick.AllInventories);

			// 2 Clients 2 SupplierParts
			var order4 = Helper.CreateWhsOrder(data.Org2, data.Whs1);
			Helper.CreateWhsOrderLine(order4, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order4, data.Part2, 10m);
