				{
					data.Line111, data.Line112, data.Line211, data.Line212, data.Line213, data.Line214, data.Line215, data.Line216,
					data.Line217, data.LineNonBonded
				}, pick.AllInventories);
		}

		public void TestClearAllInventories()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			AssertContainsExactElementsInAnyOrder("Only 1 inventory line should be loaded.", new[] { data.Line111 },
				pick.AllInventories);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Factory.Save();
			AssertContainsExactElementsInAnyOrder("Only 1 inventory line should be loaded.", new[] { data.Line111 },
				pick.AllInventories);
			AssertEquals(
				"This Inventory line shouldn't have been loaded because AllInventories Collection wasn't refreshed after new receive was finalised",
				false, pick.AllInventories.Contains(receive.Inventory[0]));

			pick.ClearAllInventoriesCache();
			AssertContainsExactElementsInAnyOrder("Only 2 inventory line should be loaded.",
				new[] { data.Line111, receive.Inventory[0] }, pick.AllInventories);
		}

		public void TestClearAllInventoriesCache_ClearsAttribCacheAsWell()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);
			var receive1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			var inventory1 = Helper.CreateWhsReceiveInventoryLine(receive1, data.Part1, 10m, ZDate.Empty, ZDate.Empty, "RED", "", "", "");
			receive1.AllocateLocationsWithMock();
			receive1.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive1);
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m).WE_PartAttrib1 = "RED";
			Factory.Save();

			var pick = Helper.CreatePickNew(order1);
			AssertContainsExactElementsInAnyOrder("Only 1 inventory line should be loaded.", new[] { inventory1 }, pick.AllInventories);

			var orderedInventory1 = pick.OrderedInventories[0];
			AssertEquals(1, orderedInventory1.AvailableInventories.Count);
			AssertContainsExactElementsInAnyOrder(new[] { inventory1 }, orderedInventory1.AvailableInventories[0].Inventory);

			var receive2 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R2");
			var inventory2 = Helper.CreateWhsReceiveInventoryLine(receive2, data.Part1, 10m, ZDate.Empty, ZDate.Empty, "BLUE", "", "", "");
			receive2.AllocateLocationsWithMock();
			receive2.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive2);
			Factory.Save();

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order2, data.Part1, 10m).WE_PartAttrib1 = "BLUE";
			pick.Orders.Add(order2);

			var orderedInventoryRed = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(o => o.PartAttrib1 == "RED");
			var orderedInventoryBlue = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(o => o.PartAttrib1 == "BLUE");
			AssertEquals(1, orderedInventoryRed.AvailableInventories.Count);
			AssertContainsExactElementsInAnyOrder(new[] { inventory1 }, orderedInventoryRed.AvailableInventories[0].Inventory);
			AssertEquals(1, orderedInventoryBlue.AvailableInventories.Count);
			AssertContainsExactElementsInAnyOrder(new[] { inventory2 }, orderedInventoryBlue.AvailableInventories[0].Inventory);
		}

		public void TestAllInventories_WithTransfers()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var receiveInventory = receive.Inventory[0];
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			var orderPickLine = orderLine.PickLines.Single();

			var transferLine = Helper.PickAndMakeInTransitTransfer(orderPickLine, ZDateTimeOffset.Now);
			Factory.Save();

			var transferInventory = transferLine.Inventory[0];
			pick.ClearAllInventoriesCache();
			AssertContainsExactElementsInAnyOrder(new[] { receiveInventory, transferInventory }, pick.AllInventories);

			transferLine.FinaliseDocketLine();
			AssertIsFinalisedPrecondition(transferLine);
			orderPickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;

			// This is specifically testing that when there is no stock on the in-transit transfer line, it is
			// filtered out. To simulate this situation we pick the in-transit transfer line and prevent creation of another one.
			using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
			{
				Factory.Save();
				AssertEquals("Precondition: Total Units is reduced.", 0m, transferInventory.WI_TotalUnits);
			}

			pick.ClearAllInventoriesCache();
			AssertContainsExactElementsInAnyOrder(new[] { receiveInventory }, pick.AllInventories);
		}

