		void TestDockDoorLocationString_UpdateFromWorkFlow_ReadOnlyCore(ZString pickstatus, bool expectedError)
		{
			var ddlLocationType = Helper.CreateLocationType("123", LocationClasses.Codes.DDL);
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			var whs1 = data.Whs1;
			whs1.FindLocation("A-1").WLV_WLT_LocationType = ddlLocationType.PK;

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 1m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var trigger = pick.WorkflowItems.Triggers.AddNew();
			trigger.P9_Description = "Trigger 1";
			trigger.TriggerConditions.TriggerEventCode = Events.CustomisableEvent01.Code;
			var action = trigger.ProcessTaskNotifications.AddNew();
			action.PQ_TriggerType = WorkflowTriggerActionTypeConstants.Codes.ImmediateFieldChange;
			action.PQ_FieldName = "DockDoorLocationString";
			action.PQ_FieldValue = "A-1";
			Factory.Save();

			pick.WP_PickStatus = pickstatus;

			if (expectedError)
			{
				pick.Logs.AddNew(Events.CustomisableEvent01); // This should trigger ImmediateFieldChange without running LogWalker
				AssertEquals("if location string is not valid should not change default.", whs1.DefaultInboundDockDoorLocation.WLV_LocationString, pick.DockDoorLocationString);
				AssertHasRowWarning(trigger, "Failure with 1 reasons:\r\nProperty WhsPick.DockDoorLocationString of type ZString is read-only and cannot be changed by the Set Field (IFC) trigger action. Target Object: 'Pick P00000001'. Source: A-1, Target: ");
			}
			else
			{
				pick.Logs.AddNew(Events.CustomisableEvent01); // This should trigger ImmediateFieldChange without running LogWalker
