		#region TestAddOrders_SortsOrderedInventoriesOnce

		public void TestAddOrders_SortsOrderedInventoriesOnce()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);

			var orders = new List<WhsOrder>();

			for (int i = 0; i < 11; i++)
			{
				orders.Add(Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + i, data.Part1, 1m));
			}

			var orderPart2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "OtherOrder", data.Part2, 1m);
			var pick = Helper.CreatePickNew(new[] { orders[0], orderPart2 });

			var sortCount = 0;
			var orderedInventory = pick.OrderedInventories[0];

			pick.OrderedInventories.Sort(new ReverseComparer<WhsPickOrderedInventory>(new SortItemsForPicking())); // Undo the sort order

			((IBusinessObjectCollection)pick.OrderedInventories).SortChanged += (s, e) =>
			{
				pick.OrderedInventories.Sort(new ReverseComparer<WhsPickOrderedInventory>(new SortItemsForPicking())); // Undo the sort order
				sortCount++;
			};

			pick.AddOrders(orders.Skip(1));

			AssertContainsExactElementsInAnyOrder("Precondition: Should have attached orders.", orders.Append(new[] { orderPart2 }), pick.Orders);
			AssertEquals("Precondition: Two OrderedInventories.", 2, pick.OrderedInventories.Count);
			AssertEquals("Should have sorted OrderedInventories twice (once in production and once to reverse the sorting for the test).", 2, sortCount);
		}

		class ReverseComparer<T> : IComparer<T>
		{
			public ReverseComparer(IComparer<T> comparer)
			{
				this.comparer = comparer;
			}

			readonly IComparer<T> comparer;

			public int Compare(T x, T y)
			{
				return comparer.Compare(y, x);
			}
		}

		#endregion

		#region TestAddOrders_UpdatesCrossDockAllocations

		public void TestAddOrders_UpdatesCrossDockAllocations()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 5m);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 5m);
			var reservedPickLine1 = orderLine1.ReserveStockIfAbleTo(inventory);
			var reservedPickLine2 = orderLine2.ReserveStockIfAbleTo(inventory);
			AssertNotNull("Precondition: stock is reserved.", reservedPickLine1);
			AssertNotNull("Precondition: stock is reserved.", reservedPickLine2);

			var pick = Factory.New<WhsPick>();
			pick.AddOrders(new[] { order1, order2 });
			AssertContainsExactElementsInAnyOrder("Precondition: Should have attached orders.", new[] { order1, order2 }, pick.Orders);

			var availableInventory = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single();
			AssertEquals("Should have picked 2x5 Units from reserved Inventory.", 10m, availableInventory.PickLineQuantity);
			AssertContainsExactElementsInAnyOrder(new[] { reservedPickLine1, reservedPickLine2 }, availableInventory.PickLines);

			AssertEquals("reservedPickLine1.ReservedQuantity", 5m, reservedPickLine1.ReservedQuantity);
			AssertEquals("Should be one Release Line created.", 1, orderLine1.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be the full ordered amount.", 5m, orderLine1.SumOfUnitsMet);
			AssertEquals("Units Sent should be the full ordered amount.", 5m, order1.WD_UnitsSent);
			AssertEquals("When Pick is set, Reserved Pick Lines should be refreshed.", 0, orderLine1.ReservedPickLines.Count);

			AssertEquals("reservedPickLine2.ReservedQuantity", 5m, reservedPickLine2.ReservedQuantity);
			AssertEquals("Should be one Release Line created.", 1, orderLine2.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be the full ordered amount.", 5m, orderLine2.SumOfUnitsMet);
			AssertEquals("Units Sent should be the full ordered amount.", 5m, order2.WD_UnitsSent);
			AssertEquals("When Pick is set, Reserved Pick Lines should be refreshed.", 0, orderLine2.ReservedPickLines.Count);
		}

