			Assert("Should contain error in logs", pick.Logs.GetAllLogs().Cast<StmALog>().Any(x => x.SL_SE_NKEvent == "ERR"));
			var log = pick.Logs.GetAllLogs().Cast<StmALog>().First(x => x.SL_SE_NKEvent == "ERR");
