			var pick2 = Factory.New<WhsPick>();
			pick2.ThrowExceptionIfTest = false; // Allow unsuccesful attach
			pick2.AddOrders(new[] { order });

			AssertEquals("Precondition: Should not have attached order as it was already attached to a pick.", 0, pick2.Orders.Count);
			AssertEquals("Pick1 should contain error in logs", true, pick1.Logs.GetAllLogs().Cast<StmALog>().Any(x => x.SL_SE_NKEvent == "ERR"));
			AssertEquals("Pick2 should *not* contain error in logs", false, pick2.Logs.GetAllLogs().Cast<StmALog>().Any(x => x.SL_SE_NKEvent == "ERR"));
		}

