		#region TestAddOrders_LogsUnitValidationErrorOnlyForNewProductsInPick

		public void TestAddOrders_LogsUnitValidationErrorOnlyForNewProductsInPick()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateMultiWarehouseClientProductInventory();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order1);

			// These unit conversions are wrong
			Helper.CreateProductUnit(data.Part1, "BOX", 0.3);
			Helper.CreateProductUnit(data.Part2, "PCK", 0.33);

			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O3", data.Part2, 10m);
			pick.AddOrders(new[] { order2, order3 });
			AssertContainsExactElementsInAnyOrder("Precondition: Should have attached orders.", new[] { order1, order2, order3 }, pick.Orders);

			// There should be only one error log added - for data.Part2
			AssertEquals("There should be only one such log.", 1, pick.Logs.GetAllLogs().Cast<StmALog>().Count(x => x.SL_SE_NKEvent == "ERR"));
