		#region TestRemoveOrders_UpdatesPickStatus

		public void TestRemoveOrders_UpdatesPickStatus()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			var order_WithoutShortfall = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			order_WithoutShortfall.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithoutShortfall, data.Part1, 10m);

			var order_WithShortfallAndNoneFullfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
			order_WithShortfallAndNoneFullfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.None;
			Helper.CreateWhsOrderLine(order_WithShortfallAndNoneFullfillment, data.Part1, 1000m);

			var order_WithShortfallAndAllFulfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "3");
			order_WithShortfallAndAllFulfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithShortfallAndAllFulfillment, data.Part1, 1000m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order_WithoutShortfall);
			AssertEquals("Precondition.", PickStatus.Codes.Created, pick.WP_PickStatus);

			pick.AddOrders(new[] { order_WithShortfallAndNoneFullfillment, order_WithShortfallAndAllFulfillment });
			AssertContainsExactElementsInAnyOrder("Should have attached orders.", new[] { order_WithoutShortfall, order_WithShortfallAndNoneFullfillment, order_WithShortfallAndAllFulfillment }, pick.Orders);
			AssertEquals("AddOrders should have updated pick status.", PickStatus.Codes.Building, pick.WP_PickStatus);

			pick.RemoveOrders(new[] { order_WithoutShortfall, order_WithShortfallAndNoneFullfillment, order_WithShortfallAndAllFulfillment });
			AssertEquals("Should have NO attached orders.", 0, pick.Orders.Count);
			AssertEquals("RemoveOrders should have updated pick status.", PickStatus.Codes.Created, pick.WP_PickStatus);
		}

