		#region TestMultiOrderePickBOM

		public void TestMultiOrderePickBOM()
		{
			var data = new TestDataSimpleEnvironment(Factory, 5, 5);
			var mainProduct = Helper.CreateProduct(data.Org1, "MP1");
			mainProduct.OP_IsComponentPickedOnSalesOrder = true;
			var bomComponentProduct1 = Helper.CreateProduct(data.Org1, "BOM1");
			var bomPartForMainProduct1 = Helper.CreateProductBOM(mainProduct, bomComponentProduct1, 1m, Constants.PkgUnit.Unit);

			var bomComponentProduct2 = Helper.CreateProduct(data.Org1, "BOM2");
			var bomPartForMainProduct2 = Helper.CreateProductBOM(mainProduct, bomComponentProduct2, 3m, Constants.PkgUnit.Unit);

			Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, mainProduct, AttributeNumber.One, true);

			var inventoryLocation = data.Whs1.FindLocation("A-1-1");
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, mainProduct, 2m, data.Whs1.FindLocation("A-1-1"), ZDate.Empty,
				ZDate.Empty, "PA1", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, mainProduct, 2m, data.Whs1.FindLocation("A-1-2"), ZDate.Empty,
				ZDate.Empty, "PA2", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, mainProduct, 1m, data.Whs1.FindLocation("A-1-3"), ZDate.Empty,
				ZDate.Empty, "PA3", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, bomComponentProduct1, 20m, data.Whs1.FindLocation("A-2-1"));
			Helper.CreateWhsReceiveInventoryLine(receive, bomComponentProduct2, 20m, data.Whs1.FindLocation("A-2-2"));

			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive.IsFinalised);
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine11 = Helper.CreateWhsOrderLine(order1, mainProduct, 7m);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine21 = Helper.CreateWhsOrderLine(order2, mainProduct, 15m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order1, order2);
			AssertEquals("PickLineQuantity should be 7, 5 directly picked plus 2 assembled.", 7m, orderLine11.PickLineQuantity);
			AssertEquals("TotalPickLineQuantityFromComponents should be 2", 2m, orderLine11.TotalPickLineQuantityFromComponents);

			AssertEquals("PickLineQuantity should be 4, all from assembly.", 4m, orderLine21.PickLineQuantity);
