		#region TestOrdersCountChanged

		public void TestOrdersCountChanged()
		{
			WhsWarehouse whs = Helper.CreateWarehouse("1");
			OrgHeader org = Helper.CreateClient();
			OrgSupplierPart part1 = Helper.CreateProduct(org, "P1");
			OrgSupplierPart part2 = Helper.CreateProduct(org, "P2");
			WhsOrder order1 = Helper.CreateWhsOrder(org, whs, "1");
			WhsOrder order2 = Helper.CreateWhsOrder(org, whs, "2");
			WhsOrderLine orderLine1 = Helper.CreateWhsOrderLine(order1, part1, 10m);
			WhsOrderLine orderLine2 = Helper.CreateWhsOrderLine(order2, part2, 10m);

			Pick.Orders.Add(order1);

			AssertEquals("Should of merged 1 OrderedInventory", 1, Pick.OrderedInventories.Count);
			AssertEquals("Should of loaded one order", 1, Pick.Orders.Count);
			AssertEquals("Should of set Pick Whs", whs, Pick.Warehouse);
			AssertEquals("Should of set Order FK to Pick", Pick.PK, order1.WD_WP);
			AssertEquals("Should of set Order Status", DocketStatus.Codes.AttachedToPick, order1.WD_DocketStatus);
			AssertCollectionContains(order1, Pick.Orders);

			Pick.Orders.Add(order2);

			AssertEquals("Should of merged another OrderedInventory", 2, Pick.OrderedInventories.Count);
			AssertEquals("Should of loaded one order", 2, Pick.Orders.Count);
			AssertEquals("Should of set Order FK to Pick", Pick.PK, order2.WD_WP);
			AssertEquals("Should of set Order Status", DocketStatus.Codes.AttachedToPick, order2.WD_DocketStatus);
			AssertCollectionContains(order2, Pick.Orders);

			Pick.ThrowExceptionIfTest = false;
			Pick.Orders.Remove(order2);

			AssertEquals("Should of unmerged OrderedInventory", 1, Pick.OrderedInventories.Count);
			AssertEquals("Should of cleared Order FK to Pick", ZGuid.Empty, order2.WD_WP);
			AssertEquals("Should of cleared Order Status", DocketStatus.Codes.Entered, order2.WD_DocketStatus);
			AssertCollectionNotContains(order2, Pick.Orders);

			var cartonisationMutex = new ZGlobalMutex(MutexIDs.WhsPickAllocatingPackageLabels, pick.PK.ToString());
			cartonisationMutex.Lock();

			using (cartonisationMutex)
			{
				AssertEquals("Precondition", true, pick.IsCartonising);

				Pick.Orders.Add(order2);
				AssertCollectionNotContains("Should *not* have added the Order to a pick being cartonised.", order2, Pick.Orders);

				Notify.DefaultResponse = true;
				Pick.NotificationManager.Push(Notify);
				order2.WD_PickOption = WhsPickOption.Codes.ManualWithAutoAllocate;
				Pick.Orders.Add(order2);
				AssertCollectionNotContains("Should *not* have added the Order to a cartonised pick.", order2, Pick.Orders);
			}

			Pick.Orders.Add(order2);
			AssertCollectionContains("Precondition.", order1, Pick.Orders);
			AssertCollectionContains(
				"Should have added the Order as the Cartonisation mutex was released and WP_IsCartonised isnt set.", order2,
				Pick.Orders);
			Pick.Orders.Remove(order2);

			Pick.WP_IsCartonised = true;
			Pick.Orders.Add(order2);
			Pick.Orders.Remove(order1);
			AssertCollectionNotContains("Should *not* have added the Order to a cartonised pick.", order2, Pick.Orders);
			AssertCollectionNotContains("Should have removed the unpicked Order from a cartonised pick.", order1, Pick.Orders);

			AssertEquals("Precondition: Pick should have no orders left", 0, Pick.Orders.Count);
			AssertEquals("Order should have cartonisation status cancelled when last order is detached", false, Pick.WP_IsCartonised);

			order2.WD_PickOption = WhsPickOption.Codes.ManualWithAutoAllocate;
			Pick.Orders.Add(order2);
			AssertCollectionContains("Should have added the Order to an uncartonised pick.", order2, Pick.Orders);
		}

