		#region TestDetachingAnOrderDoesNotUncommitTheAllocatedInventoryIfCartonised

		public void TestDetachOrder_UncommitsAllocatedInventoryIfCartonised()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines(10m, 20m, 30m, 40m, 50m);

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", Notify);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2", Notify);
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 20m);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 30m);
			var orderLine3 = Helper.CreateWhsOrderLine(order2, data.Part1, 40m);
			Factory.Save();

			var pick = Helper.CreatePickNew(new[] { order1, order2 });
			AssertEquals("Precondition", 2, pick.Orders.Count);

			var inventories = Helper.LoadInventory(data.Org1, data.Part1);
			AssertEquals("Precondition", 150m, inventories.UnitsTotal);
			AssertEquals("Precondition", 90m, inventories.UnitsCommitted);

			var cartonisationMutex = new ZGlobalMutex(MutexIDs.WhsPickAllocatingPackageLabels, pick.PK.ToString());
			cartonisationMutex.Lock();

			using (cartonisationMutex)
			{
				AssertEquals("Precondition", true, pick.IsCartonising);

				pick.Orders.Remove(order2);
				AssertEquals("Should *not* unallocate stock from removed order while pick is cartonising", 90m, inventories.UnitsCommitted);
				AssertEquals("Should *not* alter SumOfUnitsMet while pick is cartonising", orderLine2.SumOfUnitsMet, 30m);
				AssertEquals("Should *not* alter SumOfUnitsMet while pick is cartonising", orderLine3.SumOfUnitsMet, 40m);
			}

			pick.WP_IsCartonised = true;
			pick.Orders.Remove(order2);
			AssertEquals("Should unallocate stock from removed order when pick is cartonised", 20m, inventories.UnitsCommitted);
			AssertEquals("Should alter SumOfUnitsMet when pick is cartonised", orderLine2.SumOfUnitsMet, 0m);
			AssertEquals("Should alter SumOfUnitsMet when pick is cartonised", orderLine3.SumOfUnitsMet, 0m);
		}

