		#region TestDetachOrder_DeleteReceiveForUnpickedPickOnSaleOrder

		public void TestDetachOrder_DeleteReceiveForUnpickedPickOnSaleOrder()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, wheel, 70m, data.Whs1.FindLocation("A-1"));
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive.IsFinalised);

			var pick = Factory.New<WhsPick>();
			pick.WP_WW_Whs = data.Whs1.PK;
			pick.DockDoorPK = data.Whs1.WW_DefaultInboundDockDoor;
			pick.WP_PickOption = WhsPickOption.Codes.Manual;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption: WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, bike, 2m);

			pick.AddOrders(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			Factory.Save();
			AssertEquals("Added component orderline should exist.", 1, orderLine.ChildComponentLines.Count);
			AssertEquals("Should be allocated.", 1, orderLine.ChildComponentLines.First().PickLines.Count);

			var createdReceive = Factory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			var createdReceiveLine = createdReceive.Lines[0];
			var relatedPickLine = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine.PK))[0];
			var link = createdReceiveLine.BOMComponentLinks.First();

			AssertEquals("Precondition", false, createdReceive.IsDeleted);
			AssertEquals("Precondition", false, createdReceiveLine.IsDeleted);
			AssertEquals("Precondition", false, relatedPickLine.IsDeleted);
			AssertEquals("Precondition", false, link.IsDeleted);
			AssertEquals("Precondition: Kit and Component Lines all have Pick Lines allocated.", true, order.Lines.All(l => l.PickLines.Count > 0));

			pick.Orders.Remove(order);
			Factory.Save();

			AssertEquals(true, createdReceive.IsDeleted);
			AssertEquals(true, createdReceiveLine.IsDeleted);
			AssertEquals(true, relatedPickLine.IsDeleted);
			AssertEquals(true, link.IsDeleted);
			AssertEquals("Precondition: All Pick Lines were deleted.", true, order.Lines.All(l => l.PickLines.Count == 0));
		}

