			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2", Notify);
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 20m);
			var orderLine3 = Helper.CreateWhsOrderLine(order2, data.Part1, 30m);
			Factory.Save();

			Pick.PickOrdersWithAllocationMock(new[] { order1, order2 });

			AssertEquals("Precondition", 2, Pick.Orders.Count);
			AssertEquals(10m, orderLine1.SumOfUnitsMet);
			AssertEquals(20m, orderLine2.SumOfUnitsMet);
			AssertEquals(30m, orderLine3.SumOfUnitsMet);
			AssertEquals(1, orderLine1.PickLines.Count);
			AssertEquals(1, orderLine2.PickLines.Count);
			AssertEquals(1, orderLine3.PickLines.Count);

			var anotherFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInAnotherFactory = anotherFactory.Load<WhsPick>(Pick.PK);
			var orderLine1InAnotherFactory = anotherFactory.Load<WhsOrderLine>(orderLine1.PK);
			var orderLine2InAnotherFactory = anotherFactory.Load<WhsOrderLine>(orderLine2.PK);
			var orderLine3InAnotherFactory = anotherFactory.Load<WhsOrderLine>(orderLine3.PK);
			var order1InAnotherFactory = anotherFactory.Load<WhsOrder>(order1.PK);
			var order2InAnotherFactory = anotherFactory.Load<WhsOrder>(order2.PK);

			pickInAnotherFactory.Orders.Remove(order2InAnotherFactory);
			AssertEquals("orderLine1 SumOfUnitsMet", 10m, orderLine1InAnotherFactory.SumOfUnitsMet);
			AssertEquals("orderLine2 SumOfUnitsMet", 0m, orderLine2InAnotherFactory.SumOfUnitsMet);
			AssertEquals("orderLine3 SumOfUnitsMet", 0m, orderLine3InAnotherFactory.SumOfUnitsMet);
			AssertEquals("orderLine1 PickLines.Count", 1, orderLine1InAnotherFactory.PickLines.Count);
			AssertEquals("orderLine2 PickLines.Count", 0, orderLine2InAnotherFactory.PickLines.Count);
			AssertEquals("orderLine3 PickLines.Count", 0, orderLine3InAnotherFactory.PickLines.Count);

			pickInAnotherFactory.Orders.Remove(order1InAnotherFactory);
			AssertEquals("orderLine1 SumOfUnitsMet", 0m, orderLine1InAnotherFactory.SumOfUnitsMet);
			AssertEquals("orderLine1 PickLines.Count", 0, orderLine1InAnotherFactory.PickLines.Count);
		}

