		#region TestDetachOrder_ReservedLinesAreClearedOut

		public void TestDetachOrder_ReservedLinesAreClearedOut()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var reservedPickLine = orderLine1.ReserveStockIfAbleTo(inventory);
			AssertEquals("Precondition: Stock is reserved.", 5m, reservedPickLine.ReservedQuantity);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Order is fully picked.", 5m, orderLine1.PickLineQuantity);
			AssertEquals("Order is fully picked.", 5m, orderLine2.PickLineQuantity);

			var nonReservedPickLine = orderLine2.PickLines.Single(); // non-reserved line
			reservedPickLine.WZ_GS_NKAssignedTo = "E";
			reservedPickLine.WZ_VerifiedEmpty = "E";

			// detach order
			pick.Orders.Remove(order);
			AssertEquals("Normal pick lines should be deleted on detaching.", true, nonReservedPickLine.IsDeleted);
			AssertEquals("Reserved Picklines should not be deleted.", false, reservedPickLine.IsDeleted);
			AssertEquals("Reserved Picklines should be cleared out.", ZDateTimeOffset.Empty, reservedPickLine.WZ_PickedDateTime);
			AssertEquals("Reserved Picklines should be cleared out.", "", reservedPickLine.WZ_GS_NKAssignedTo);
			AssertEquals("Reserved Picklines should be cleared out.", "", reservedPickLine.WZ_VerifiedEmpty);
			AssertEquals("Reserved Picklines should retain reserve qty.", 5m, reservedPickLine.WZ_Units);
			AssertEquals("Reserved Picklines should retain reserve qty backup.", 5m, reservedPickLine.WZ_OriginalReservedQty);
		}

