		#region TestDetachOrder_ReleaseLinesAreMaintained

		public void TestDetachOrder_ReleaseLinesAreMaintained()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 5m);
			var order1Line = order1.Lines[0];
			var order2Line = order2.Lines[0];
			Factory.Save();

			var pick = Helper.CreatePickNew(order1, order2);
			order2Line.ReleaseLines[0].Quantity -= 1m;

			AssertEquals("Order is fully picked.", 5m, order1Line.PickLineQuantity);
			AssertEquals("Order is fully picked.", 5m, order2Line.PickLineQuantity);
			AssertEquals("Order is fully released.", 5m, order1Line.ReleaseLines[0].Quantity);
			AssertEquals("Order is fully released.", 4m, order2Line.ReleaseLines[0].Quantity);
			AssertEquals("Order is fully released.", 1m, order1Line.ReleaseLines[0].UnreleasedQty);
			AssertEquals("Order is fully released.", 1m, order2Line.ReleaseLines[0].UnreleasedQty);

			// detach order
			pick.Orders.Remove(order2);
			AssertEquals("Order is fully picked.", 5m, order1Line.PickLineQuantity);
			AssertEquals("Order is fully released.", 5m, order1Line.ReleaseLines[0].Quantity);
			AssertEquals("Order is fully released.", 0m, order1Line.ReleaseLines[0].UnreleasedQty);

			AssertNoExceptionThrown(() => order1Line.ReleaseLines[0].Quantity -= 1m);
			AssertEquals("Released Quantity decreased by 1.", 4m, order1Line.ReleaseLines[0].Quantity);
			AssertEquals("Order should no longer be fully released.", 1m, order1Line.ReleaseLines[0].UnreleasedQty);

			AssertEquals(0m, order2Line.PickLineQuantity);
			AssertEquals(0, order2Line.ReleaseLines.Count);
		}

