		#region TestDetachOrder_Cartonised

		public void TestDetachOrder_Cartonised()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;
			var org = data.Org1;
			var part = Helper.CreateProduct(org, "PR1");

			var whsGroup = Helper.CreateWhsCartonGroup("1", "WhsOrg");
			var whsSize = Helper.CreateWhsCartonSize("WH", 10, 20, 40, 80, 160, 320, new ZByte(100), Constants.Length.Metres, Constants.Weight.Kilograms);
			whsGroup.CartonSizes.Add(whsSize);
			data.Whs1.WarehouseAddress.Header.MiscServ.OM_WCG_CartonGroup = whsGroup.PK;

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", part, 5);
			var inventoryLine2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", part, 5);
			var splitCaseRefType = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Metres, 3, Constants.Weight.Kilograms, UOMPackTypesList.Codes.SplitCase);
			part.OP_StockKeepingUnit = splitCaseRefType.F3_Code;
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, part, 10);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;

			AssertEquals(DocketStatus.Codes.AttachedToPick, order.WD_DocketStatus);
			AssertEquals("Precondition", true, pick.WP_CartoniseSplitCases);
			Factory.Save();

			pick.AllocatePackageLabels();
			AssertEquals("Precondition - Cartonised", true, pick.WP_IsCartonised);

			pick.Orders.Remove(order);
			AssertEquals("If order is not picked, it can be detached from pick.", false, pick.Orders.Contains(order));
			AssertEquals("No errors should be shown.", false, ((NotificationBuffer)pick.NotificationSubscriber).HasErrors);
			AssertEquals("If order is the last one on the pick, the pick's cartonized status should be cancelled", false, pick.WP_IsCartonised);
		}

		#endregion

		#region TestDetachOrder_Cartonising

		public void TestDetachOrder_Cartonising()
		{
			// Should only be allowed to detach order while cartonising if we are cartonising in this instance
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			Factory.Save();

			var assertionRan = false;
			var mock = new Mock<IAllocatePackageLabelsStrategy>();
			mock.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			mock.Setup(m => m.PickCasesByLabel(It.IsAny<WhsPick>())).Returns(true);
			mock.Setup(m => m.PickPalletsByLabel(It.IsAny<WhsPick>())).Returns(true);
			mock.Setup(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(() =>
			{
				// ~~~ Inside critical region of factory1 ~~~
				AssertEquals("Precondition.", true, pick.IsCartonising);
				AssertEquals("Precondition.", 1, pick.Orders.Count);

				var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
				var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);
				var orderInFactory2 = factory2.Load<WhsOrder>(order.PK);

				pickInFactory2.Orders.Remove(orderInFactory2);
				AssertEquals("Should not have removed order as this factory doesn't have the lock.", true, pickInFactory2.Orders.Contains(orderInFactory2));
				AssertEquals("Should have shown error", true, ((NotificationBuffer)pickInFactory2.NotificationSubscriber).HasErrors);
				AssertEquals("Should have shown error",
					"Error: Cannot perform this operation because the Pick is Cartonized or being Cartonized.",
					((NotificationBuffer)pickInFactory2.NotificationSubscriber).Events[0].Message);

				((NotificationBuffer)pickInFactory2.NotificationSubscriber).Clear();
				pick.Orders.Remove(order);
				AssertEquals("Should have removed order as this instance has the lock.", false, pick.Orders.Contains(order));
				AssertEquals("Should have no errors", false, ((NotificationBuffer)pick.NotificationSubscriber).HasErrors);

				assertionRan = true;
				return CartonisationResult.Cartonised;
			});

			pick.SetAllocatePackageLabelsStrategyForTest(mock.Object);
			pick.AllocatePackageLabels();
			AssertEquals(true, assertionRan);
		}

