		#region TestDetachOrder_CannotDetachPartiallyPickedOrders

		public void TestDetachOrder_CannotDetachPartiallyPickedOrders()
		{
			TestDetachOrder_CannotDetachPartiallyPickedOrders(usingInTransitTransfers: false);
		}

		public void TestDetachOrder_CannotDetachPartiallyPickedOrders_InTransit()
		{
			TestDetachOrder_CannotDetachPartiallyPickedOrders(usingInTransitTransfers: true);
		}

		void TestDetachOrder_CannotDetachPartiallyPickedOrders(bool usingInTransitTransfers)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order1, order2);
			var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(pick);
			AssertEquals("Precondition", 20m, totalPickLineQuantity);
			AssertEquals("Precondition", 2, pick.Orders.Count);

			var pickLine = order1.Lines[0].PickLines.Single();
			if (usingInTransitTransfers)
			{
				Helper.PickAndMakeInTransitTransfer(pickLine, ZDateTimeOffset.Now);
				Factory.Save();
			}
			else
			{
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;

				using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
				{
					Factory.Save();
					AssertEquals("Precondition: Picked Directly.", ZGuid.Empty,
						order1.Lines[0].PickLines.Single().WZ_WE_OriginalPickedInventoryLine);
				}
			}

			// try detaching partially picked order
			pick.Orders.Remove(order1);
			AssertEquals("If order is partially or fully picked, it cannot be detached from pick.", 2, pick.Orders.Count);
			var notifications = (NotificationBuffer)pick.NotificationSubscriber;
			AssertEquals("Should have shown error", true, notifications.HasErrors);
			AssertEquals("Should have shown error",
				"Error: Cannot perform this operation because the Order is partially or fully picked.",
				notifications.Events[0].Message);
			notifications.Clear();

			// try detaching allocated but not picked order
			pick.Orders.Remove(order2);
			AssertEquals("If order is not picked, it can be detached from pick.", 1, pick.Orders.Count);
			AssertEquals("No errors should be shown.", false, notifications.HasErrors);
		}

		#endregion

