		#region TestDetachOrder_ChecksAllPickStrategies

		public void TestDetachOrder_ChecksAllPickStrategies_OrderCanBeDetached()
		{
			var data = new EnvTestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var pickByLabelStrategyMock = new Mock<IWhsPickByLabelPickStrategy>();
			var pickByTrolleyStrategyMock = new Mock<IWhsPickByTrolleyPickStrategy>();
			var pickByLabelErrorNotification = new ErrorNotification(OrderErrorTypes.CannotPerformThisOperationBecauseOrderHasPackagesAssignedToPickByLabelJob);
			var pickByTrolleyErrorNotification = new ErrorNotification(OrderErrorTypes.CannotPerformThisOperationBecauseOrderHasPackagesAssignedToTrolleyJob);
			pickByLabelStrategyMock.Setup(s => s.IsOrderActionAllowed(order, PickOrderAction.DetachOrder, out pickByLabelErrorNotification)).Returns(true).Verifiable();
			pickByTrolleyStrategyMock.Setup(s => s.IsOrderActionAllowed(order, PickOrderAction.DetachOrder, out pickByTrolleyErrorNotification)).Returns(true).Verifiable();

			using (ObjectFactory.Substitute("IWhsPickByLabelPickStrategy", pickByLabelStrategyMock.Object))
			using (ObjectFactory.Substitute("IWhsPickByTrolleyPickStrategy", pickByTrolleyStrategyMock.Object))
			{
				pick.Orders.Remove(order);
				pickByLabelStrategyMock.VerifyAll();
				pickByTrolleyStrategyMock.VerifyAll();
			}

			AssertCollectionNotContains("If all strategies allow detachment, order should be detached", order, pick.Orders);
		}

		public void TestDetachOrder_ChecksAllPickStrategies_OrderCannotBeDetached()
		{
			var data = new EnvTestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var pickByLabelStrategyMock = new Mock<IWhsPickByLabelPickStrategy>();
			var pickByTrolleyStrategyMock = new Mock<IWhsPickByTrolleyPickStrategy>();
			var pickByLabelErrorNotification = new ErrorNotification(OrderErrorTypes.CannotPerformThisOperationBecauseOrderHasPackagesAssignedToPickByLabelJob);
			var pickByTrolleyErrorNotification = new ErrorNotification(OrderErrorTypes.CannotPerformThisOperationBecauseOrderHasPackagesAssignedToTrolleyJob);
			pickByLabelStrategyMock.Setup(s => s.IsOrderActionAllowed(order, PickOrderAction.DetachOrder, out pickByLabelErrorNotification)).Returns(true).Verifiable();
			pickByTrolleyStrategyMock.Setup(s => s.IsOrderActionAllowed(order, PickOrderAction.DetachOrder, out pickByTrolleyErrorNotification)).Returns(false).Verifiable();

			using (ObjectFactory.Substitute("IWhsPickByLabelPickStrategy", pickByLabelStrategyMock.Object))
			using (ObjectFactory.Substitute("IWhsPickByTrolleyPickStrategy", pickByTrolleyStrategyMock.Object))
			{
				pick.Orders.Remove(order);
				pickByLabelStrategyMock.VerifyAll();
				pickByTrolleyStrategyMock.VerifyAll();
			}

			var notifications = (NotificationBuffer)pick.NotificationSubscriber;
			AssertCollectionContains("If strategy disallows detachment, order should not be detached", order, pick.Orders);
			AssertEquals("Should have shown error", true, notifications.HasErrors);
			AssertEquals("Should have shown error",
				"Error: Cannot perform this operation because the order has packages assigned to a trolley job.",
				notifications.Events[0].Message);
		}

