		#region TestDetachOrder_RecalculatesExtendedLinePrice_PartialShortfall

		public void TestDetachOrder_RecalculatesExtendedLinePrice_PartialShortfall() => TestDetachOrder_ExtendedLinePrice_PartialShortfall(shouldRecalculate: true);

		public void TestDetachOrder_DoesNotRecalculateExtendedLinePrice_PartialShortfall() => TestDetachOrder_ExtendedLinePrice_PartialShortfall(shouldRecalculate: false);

		void TestDetachOrder_ExtendedLinePrice_PartialShortfall(bool shouldRecalculate)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Org1.MiscServ.OM_WhsIsRecalculateOrderPricing = shouldRecalculate;
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 5m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			order.Lines[0].WE_UnitPriceAfterDiscount = 5m;

			if (!shouldRecalculate)
			{
				order.Lines[0].WE_ExtendedLinePrice = 50m;
			}

			AssertEquals("Precondition: LinePrice used transaction quantity prior to picking.", 50m, order.Lines[0].WE_ExtendedLinePrice);

			var pick = Helper.CreatePickNew(order);
			AssertEquals("LinePrice.", shouldRecalculate ? 25m : 50m, order.Lines[0].WE_ExtendedLinePrice);

			if (!shouldRecalculate)
			{
				order.Lines[0].WE_ExtendedLinePrice = 25m;
			}

			pick.Orders.Remove(order);
			AssertEquals("LinePrice.", shouldRecalculate ? 50m : 25m, order.Lines[0].WE_ExtendedLinePrice);
		}

