		#region TestDetachOrder_SaveFailure

		public void TestDetachOrder_SaveFailure()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			AssertEquals("Precondition: Pick has 1 order.", 1, pick.Orders.Count);

			pick.Orders.Remove(order);
			pick.CancelPick();

			BusinessObjectFactory.SavingEventHandler handler = f =>
			{
				f.ServiceContainer.AddAfterOnSavingService(new ServiceThatThrowsException(f));
			};
			Factory.Saving += handler;

			Helper.AssertZCannotSaveExceptionThrown("Test", Factory.Save);

			Factory.Saving -= handler;
			AssertNoExceptionThrown("When detaching first, then cancel pick and save, no exception will be thrown.", () => Factory.Save());
		}

