		public void TestAttachOrder_DoesNotClearExtendedLinePrice_ManualPick() => TestAttachOrder_ExtendedLinePrice_ManualPick(shouldRecalculate: false);

		void TestAttachOrder_ExtendedLinePrice_ManualPick(bool shouldRecalculate)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Org1.MiscServ.OM_WhsIsRecalculateOrderPricing = shouldRecalculate;
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			order.WD_PickOption = WhsPickOption.Codes.Manual;
			order.Lines[0].WE_UnitPriceAfterDiscount = 5m;

			if (!shouldRecalculate)
			{
				order.Lines[0].WE_ExtendedLinePrice = 50m;
			}

			AssertEquals("Precondition: LinePrice used transaction quantity prior to picking.", 50m, order.Lines[0].WE_ExtendedLinePrice);

			Helper.CreatePickNew(order);
			AssertEquals("Should not have allocated any stock.", 0m, order.Lines[0].PickLineQuantity);
			AssertEquals("LinePrice.", shouldRecalculate ? 0m : 50m, order.Lines[0].WE_ExtendedLinePrice);
		}

