		#region TestAttachingAndDettachingOrdersUpdatesPickStatus

		public void TestAttachingAndDettachingOrdersUpdatesPickStatus()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			WhsOrder order_WithoutShortfall = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", data.Notify);
			order_WithoutShortfall.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithoutShortfall, data.Part1, 10m);

			WhsOrder order_WithShortfallAndNoneFullfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2", data.Notify);
			order_WithShortfallAndNoneFullfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.None;
			Helper.CreateWhsOrderLine(order_WithShortfallAndNoneFullfillment, data.Part1, 1000m);

			WhsOrder order_WithShortfallAndAllFulfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "3", data.Notify);
			order_WithShortfallAndAllFulfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithShortfallAndAllFulfillment, data.Part1, 1000m);
			Factory.Save();

			Pick.Orders.Add(order_WithoutShortfall);
			Pick.PickOrdersWithAllocationMock();
			AssertEquals("Precondition", PickStatus.Codes.Created, Pick.WP_PickStatus);

			Pick.Orders.Add(order_WithShortfallAndNoneFullfillment);
			AssertEquals(PickStatus.Codes.Created, Pick.WP_PickStatus);

			Pick.Orders.Add(order_WithShortfallAndAllFulfillment);
			AssertEquals(PickStatus.Codes.Building, Pick.WP_PickStatus);

			Pick.Orders.Remove(order_WithShortfallAndAllFulfillment);
			AssertEquals(PickStatus.Codes.Created, Pick.WP_PickStatus);
		}

		#endregion

		#region TestAttachingAndDettachingOrdersUpdatesCrossDockAllocations

		[TestDate(2014, 1, 1)]
		public void TestAttachingAndDettachingOrdersUpdatesCrossDockAllocations()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var reservedPickLine = orderLine.ReserveStockIfAbleTo(inventory);
			AssertNotNull("Precondition: stock is reserved.", reservedPickLine);

			var pick = Factory.New<WhsPick>();
			AssertEquals("Should be no Ordered Inventories on a Pick with no Orders.", 0, pick.OrderedInventories.Count);

			pick.Orders.Add(order);
			AssertEquals("Should have 1 ordered Inventory.", 1, pick.OrderedInventories.Count);

			var availableInventory = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single();
			AssertEquals("Should have picked 5 Units from reserved Inventory.", 5m, availableInventory.PickLineQuantity);
			AssertContainsExactElementsInAnyOrder(new[] { reservedPickLine }, availableInventory.PickLines);
			AssertEquals("reservedPickLine.ReservedQuantity", 5m, reservedPickLine.ReservedQuantity);
			AssertEquals("Should be one Release Line created.", 1, orderLine.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be the full ordered amount.", 5m, orderLine.SumOfUnitsMet);

			pick.Orders.Remove(order);
			AssertEquals("Should have no Ordered Inventory after detaching the order.", 0, pick.OrderedInventories.Count);
			AssertEquals("reservedPickLine.ReservedQuantity", 5m, reservedPickLine.ReservedQuantity);
			AssertEquals("Release Lines should be cleared.", 0, orderLine.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be Zero.", 0m, orderLine.SumOfUnitsMet);
		}

		#endregion

		#region TestAttachingOrderToExistingPickUpdatesCrossDockAllocations

		public void TestAttachingOrderToExistingPickUpdatesCrossDockAllocations()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 5m);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 5m);
			var reservedPickLine1 = orderLine1.ReserveStockIfAbleTo(inventory);
			var reservedPickLine2 = orderLine2.ReserveStockIfAbleTo(inventory);
			AssertNotNull("Precondition: stock is reserved.", reservedPickLine1);
			AssertNotNull("Precondition: stock is reserved.", reservedPickLine2);

			var pick = Factory.New<WhsPick>();
			AssertEquals("Should be no Ordered Inventories on a Pick with no Orders.", 0, pick.OrderedInventories.Count);

			pick.Orders.Add(order1);
			AssertEquals("Should have 1 ordered Inventory.", 1, pick.OrderedInventories.Count);

			var availableInventory = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single();
			AssertEquals("Should have picked 5 Units from reserved Inventory.", 5m, availableInventory.PickLineQuantity);
			AssertContainsExactElementsInAnyOrder(new[] { reservedPickLine1 }, availableInventory.PickLines);
			AssertEquals("reservedPickLine1.ReservedQuantity", 5m, reservedPickLine1.ReservedQuantity);
			AssertEquals("Should be one Release Line created.", 1, orderLine1.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be the full ordered amount.", 5m, orderLine1.SumOfUnitsMet);
			AssertEquals("Units Sent should be the full ordered amount.", 5m, order1.WD_UnitsSent);

			pick.Orders.Add(order2);
			AssertEquals("Should have picked 5 Units from reserved Inventory.", 10m, availableInventory.PickLineQuantity);
			AssertContainsExactElementsInAnyOrder(new[] { reservedPickLine1, reservedPickLine2 }, availableInventory.PickLines);
			AssertEquals("reservedPickLine2.ReservedQuantity", 5m, reservedPickLine2.ReservedQuantity);
			AssertEquals("Should be one Release Line created.", 1, orderLine2.ReleaseLines.Count);
			AssertEquals("Sum of Units Met should be the full ordered amount.", 5m, orderLine2.SumOfUnitsMet);
			AssertEquals("Units Sent should be the full ordered amount.", 5m, order2.WD_UnitsSent);
		}

