		#region TestAttachingOrdersLogsUnitValidationErrorsIfAny

		public void TestAttachingOrdersLogsUnitValidationErrorsIfAny()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			// this unit conversion is wrong
			Helper.CreateProductUnit(data.Part1, "BOX", 0.3);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);

			Assert("Should contain error in logs", pick.Logs.GetAllLogs().Cast<StmALog>().Any(x => x.SL_SE_NKEvent == "ERR"));
			var log = pick.Logs.GetAllLogs().Cast<StmALog>().First(x => x.SL_SE_NKEvent == "ERR");
			AssertEquals(string.Format("Error Report: Product {0}, Bad Unit Conversion", data.Part1.OP_PartNum),
				log.DisplayEventReference);

			AssertEquals("There should be only one such log.", 1,
				pick.Logs.GetAllLogs().Cast<StmALog>().Count(x => x.SL_SE_NKEvent == "ERR"));
			// detaching and attaching the order
			pick.Orders.Remove(order);
			pick.Orders.Add(order);
			// new error log will be added
			AssertEquals("There should be 2 such logs now.", 2,
				pick.Logs.GetAllLogs().Cast<StmALog>().Count(x => x.SL_SE_NKEvent == "ERR"));
		}

		#endregion

		#region TestAttachingOrdersLogsUnitValidationErrorOnlyForNewProductsInPick

		public void TestAttachingOrdersLogsUnitValidationErrorOnlyForNewProductsInPick()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateMultiWarehouseClientProductInventory();

			var orderOld = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10);
			Factory.Save();
			var pick = Helper.CreatePickNew(orderOld);
			AssertEquals("Precondition. There are no error logs in a pick.", 0,
				pick.Logs.GetAllLogs().Cast<StmALog>().Count(x => x.SL_SE_NKEvent == "ERR"));

			// these unit conversions are wrong
			Helper.CreateProductUnit(data.Part1, "BOX", 0.3);
			Helper.CreateProductUnit(data.Part2, "PCK", 0.33);
			// we create order with line which contains product already existing in the pick
			var orderNew = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 15);
			// and another few lines with "new" product for the pick
			Helper.CreateWhsOrderLine(orderNew, data.Part2, 7);
			Helper.CreateWhsOrderLine(orderNew, data.Part2, 9);
			pick.Orders.Add(orderNew);

			// There should be only one error log added - for data.Part2
			AssertEquals("There should be only one such log.", 1,
				pick.Logs.GetAllLogs().Cast<StmALog>().Count(x => x.SL_SE_NKEvent == "ERR"));
			var log = pick.Logs.GetAllLogs().Cast<StmALog>().First(x => x.SL_SE_NKEvent == "ERR");
			AssertEquals(string.Format("Error Report: Product {0}, Bad Unit Conversion", data.Part2.OP_PartNum),
				log.DisplayEventReference);
		}

