		#region TestAllocateCrossDockLines_PicksFromCrossDockFirst

		public void TestAllocateCrossDockLines_PicksFromCrossDockFirst()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines(10m, 20m, 30m, 40m, 50m);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 55m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 30m);

			Helper.CreateReservePickLine(orderLine1, data.Receive11.Inventory[4], 50m);
			Helper.CreateReservePickLine(orderLine1, data.Receive11.Inventory[3], 5m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.PickOrdersWithAllocationMock(new WhsOrder[] { order });

			var orderedInventory = pick.OrderedInventories[0];
			AssertEquals(85m, orderedInventory.PickLineQuantity);

			// order line 2 should have allocated 10 units from 1st inventory row
			AssertEquals(10m, orderedInventory.AvailableInventories[0].PickLineQuantity);
			AssertEquals(1, orderedInventory.AvailableInventories[0].PickLines.Count());
			AssertEquals(orderLine2.PK, orderedInventory.AvailableInventories[0].PickLines.ElementAt(0).WZ_WE_TransactionLine);

			// order line 2 should have allocated the remaining 20 units from 2nd inventory row
			AssertEquals(20m, orderedInventory.AvailableInventories[1].PickLineQuantity);
			AssertEquals(1, orderedInventory.AvailableInventories[1].PickLines.Count());
			AssertEquals(orderLine2.PK, orderedInventory.AvailableInventories[1].PickLines.ElementAt(0).WZ_WE_TransactionLine);

			// order line 1 should have allocated 5 units from the cross docked 4th inventory line
			AssertEquals(5m, orderedInventory.AvailableInventories[3].PickLineQuantity);
			AssertEquals(1, orderedInventory.AvailableInventories[3].PickLines.Count());
			AssertEquals(orderLine1.PK, orderedInventory.AvailableInventories[3].PickLines.ElementAt(0).WZ_WE_TransactionLine);

			// order line 1 should have allocated 50 units from the cross docked 5th inventory line
			AssertEquals(50m, orderedInventory.AvailableInventories[4].PickLineQuantity);
			AssertEquals(1, orderedInventory.AvailableInventories[4].PickLines.Count());
			AssertEquals(orderLine1.PK, orderedInventory.AvailableInventories[3].PickLines.ElementAt(0).WZ_WE_TransactionLine);

			AssertEquals("CrossDock PickType should be Order.", PickType.Codes.Order, pick.WP_PickType);
		}

