		#region TestAllocateCrossDockLines_CrossDockAllocationsAreClearedImmediatelyWhenUsed

		public void TestAllocateCrossDockLines_CrossDockAllocationsAreClearedImmediatelyWhenUsed()
		{
			var data = new TestDataForInventory(Factory, Notify);
			data.CreateSimpleInventoryManyLines(10m, 20m, 30m, 40m, 50m);
			data.MakeSimpleInventoryLinesMergebleForPicking();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 6m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 15m);

			var reservedOrder = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var reservedOrderLine1 = Helper.CreateWhsOrderLine(reservedOrder, data.Part1, 6m);
			var reservedOrderLine2 = Helper.CreateWhsOrderLine(reservedOrder, data.Part1, 15m);

			Helper.CreateReservePickLine(reservedOrderLine1, data.Line112, 6m);
			Helper.CreateReservePickLine(reservedOrderLine2, data.Line113, 15m);

			Helper.CreateReservePickLine(orderLine1, data.Line112, 6m);
			Helper.CreateReservePickLine(orderLine2, data.Line113, 15m);
			AssertEquals(12m, data.Line112.WI_CrossDockQuantity);
			AssertEquals(30m, data.Line113.WI_CrossDockQuantity);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order);
			AssertOrderedInventory(pick.OrderedInventories[0], 21m, 21m, 21m);
			AssertAvailableInventory(pick.OrderedInventories[0].AvailableInventories[0], 21m, 21m, 129m);
			AssertEquals("Units Sent should be updated correctly.", 21m, order.WD_UnitsSent);
			AssertEquals(6m, data.Line112.WI_CrossDockQuantity);
			AssertEquals(15m, data.Line113.WI_CrossDockQuantity);

			pick.Orders.Remove(order);
			AssertEquals("Units Sent should be reduced to 0 when Order is removed from Pick.", 0m, order.WD_UnitsSent);

			pick.PickOrdersWithAllocationMock(order);
			pick.ClearAllocatedItems();
			pick.AutoAllocateItemsWithMock();
			var orderedInventory1 = pick.OrderedInventories[0];
			var availableInventory1 = orderedInventory1.AvailableInventories[0];
			AssertOrderedInventory(orderedInventory1, 21m, 21m, 21m);
			AssertAvailableInventory(availableInventory1, 21m, 21m, 129m);
			AssertEquals("Units Sent should be updated correctly.", 21m, order.WD_UnitsSent);
			AssertEquals(6m, data.Line112.WI_CrossDockQuantity);
			AssertEquals(15m, data.Line113.WI_CrossDockQuantity);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine21 = Helper.CreateWhsOrderLine(order2, data.Part1, 4m);

			var pick2 = Factory.New<WhsPick>();
			pick2.Orders.Add(order2);

			var orderedInventory2 = pick2.OrderedInventories[0];
			var availableInventory2 = orderedInventory2.AvailableInventories[0];
			AssertOrderedInventory(orderedInventory2, 4m, 21m, 0m);
			AssertAvailableInventory(availableInventory2, 0m, 21m, 108m);
			AssertEquals("CrossDock PickType should be Order.", PickType.Codes.Order, pick.WP_PickType);
		}

		#endregion

		#region TestAllocateCrossDockLines_InvalidCrossDockAllocationsAreDeleted

		public void TestAllocateCrossDockLines_InvalidCrossDockAllocationsAreDeleted()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventory1 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m);
			var inventory2 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 10m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 15m);
			var dodgyPickLine = Factory.New<WhsPickLine>();
			dodgyPickLine.WZ_WE_TransactionLine = orderLine1.PK;
			dodgyPickLine.WZ_WE_InventoryLine = inventory1.WI_WE_InDocketLine;
			dodgyPickLine.WZ_Units = 10m;

			var overpickedLine = orderLine2.ReserveStockIfAbleTo(inventory2, 8m);
			overpickedLine.WZ_Units = 15m; // over-pick

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Dodgy pickline should be deleted.", true, dodgyPickLine.IsDeleted);
			AssertEquals("Line should be fully picked.", 10m, orderLine1.PickLineQuantity);
			AssertEquals("Pick line should be reduced to available qty.", 10m, overpickedLine.WZ_Units);
			AssertEquals("Only available stock should be picked.", 10m, orderLine2.PickLineQuantity);
			AssertEquals("CrossDock PickType should be Order.", PickType.Codes.Order, pick.WP_PickType);
			AssertNoExceptionThrown(() => Factory.Save()); // ensure no dodgy data left
		}

