		void AssertOrderedInventory(WhsPickOrderedInventory orderedInventory, ZDecimal quantityOrdered,
			ZDecimal quantityCrossDocked, ZDecimal pickLineQuantity)
		{
			AssertEquals("Quantity Ordered is incorrect", quantityOrdered, orderedInventory.QuantityOrdered);
			AssertEquals("Quantity CrossDocked is incorrect", quantityCrossDocked, orderedInventory.QuantityCrossDocked);
			AssertEquals("Quantity Picked is incorrect", pickLineQuantity, orderedInventory.PickLineQuantity);
		}

		void AssertAvailableInventory(WhsPickAvailableInventory availableInventory, ZDecimal pickLineQuantity,
			ZDecimal quantityCrossDocked, ZDecimal quantityAvailable)
		{
			AssertEquals("Quantity Picked is incorrect", pickLineQuantity, availableInventory.PickLineQuantity);
			AssertEquals("Quantity CrossDocked is incorrect", quantityCrossDocked, availableInventory.QuantityCrossDocked);
			AssertEquals("Quantity Available To Pick is incorrect", quantityAvailable,
				availableInventory.QuantityAvailableToPick);
		}

