		#region TestAnyPackagesOnOrders

		public void TestAnyPackagesOnOrders()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "2", data.Part1, 5m);
			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "3", data.Part1, 5m);
			var order4 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "4", data.Part1, 5m);
			var order5 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "5", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order1, order2, order3, order4, order5);
			AssertEquals("Precondition", false, pick.AnyPackagesOnOrders);
			Factory.Save();

			order1.PackageJob.Packages.AddNew();
			AssertEquals(true, pick.AnyPackagesOnOrders);

			order2.PackageJob.Packages.AddNew();
			AssertEquals(true, pick.AnyPackagesOnOrders);

			order1.PackageJob.Packages.RemoveAllFromRelationship();
			AssertEquals(true, pick.AnyPackagesOnOrders);

			order2.PackageJob.Packages.RemoveAllFromRelationship();
			AssertEquals(false, pick.AnyPackagesOnOrders);

			var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);
			AssertEquals(false, pickInFactory2.AnyPackagesOnOrders);
			AssertTableHitCount(1, PkgPackageJobSchema.Constants.TableName, factory2);
			AssertTableHitCount(1, PkgPackageSchema.Constants.TableName, factory2);
		}

