		public void TestAnyPackageSentToRTUS_DBHits()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "2", data.Part1, 5m);
			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "3", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order1, order2, order3);

			order1.PackageJob.Packages.AddNew();
			order2.PackageJob.Packages.AddNew();
			var package3 = order3.PackageJob.Packages.AddNew();
			package3.IsSentToRTUS = true;
			Factory.Save();

			var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);

			var expectedDbHits = new Dictionary<string, int>()
			{
				{ GenAddOnColumnSchema.Constants.TableName, 1 },
				{ PkgPackageSchema.Constants.TableName, 1 },
				{ PkgPackageJobSchema.Constants.TableName, 1 },
				{ WhsDocketSchema.Constants.TableName, 1 },
				{ WhsPickSchema.Constants.TableName, 1 },
				{ WhsWarehouseSchema.Constants.TableName, 1 },
			};

			using (AssertDbHitsWithUsefulQueryInformation(expectedDbHits, factory2))
