		#region TestHasNonAllocatedOrderedInventory

		public void TestHasNonAllocatedOrderedInventory()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory(true);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "W1");
			Helper.CreateWhsOrderLine(order, data.Part1, 100m);
			Factory.Save();

			Pick.Orders.Add(order);
			Pick.AutoAllocateItemsWithMock();
			AssertEquals(ZBool.False, Pick.HasNonAllocatedOrderedInventory);

			order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "W2");
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Pick = Helper.CreatePick_OLD(data.Whs1);
			Pick.Orders.Add(order);
			Pick.AutoAllocateItemsWithMock();
			AssertEquals(ZBool.True, Pick.HasNonAllocatedOrderedInventory);
		}

