		public void TestHasUnpickedPickLines_UnpickedPickLinePickedFromPutawayLocation()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);

			var pick = Helper.CreatePickNew(order);

			var pickLine = pick.GetAllPickLines().Single();
			pickLine.WZ_WE_OriginalPickedInventoryLine = ZGuid.NewZGuid();

			AssertEquals("Precondition: Unpicked", true, pickLine.WZ_PickedDateTime.IsEmpty);
			AssertEquals("Precondition: Picked from putaway location", true, pickLine.IsPickedFromPutawayLocation);

			AssertEquals("Postcondition: Unpicked lines picked from putaway location should return false", false, pick.HasUnpickedPickLines);
		}

		public void TestHasUnpickedPickLines_PickLinePickedFromPutawayLocationAndPickedFromDockDoor()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);

			var pick = Helper.CreatePickNew(order);

			var pickLine = pick.GetAllPickLines().Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine.WZ_WE_OriginalPickedInventoryLine = ZGuid.NewZGuid();

			AssertEquals("Precondition: Picked", true, pickLine.WZ_PickedDateTime.IsValid);
			AssertEquals("Precondition: Picked from putaway location", true, pickLine.IsPickedFromPutawayLocation);

			AssertEquals("Postcondition: Picked line, picked from putaway location should return false", false, pick.HasUnpickedPickLines);
		}

		public void TestHasUnpickedPickLines_SingleShortedButPickedLine()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);

			var pick = Helper.CreatePickNew(order);
			pick.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 5m;

			var pickLine = pick.GetAllPickLines().Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;

