		public void TestHasUnpickedPickLines_HasPickLinesWithUnitsOfZero()
		{
			var data = new TestDataSimpleEnvironment(Helper.Factory, 4, 1);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory1 = receive1.Inventory[0];
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m);
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var reservedPickLine1 = orderLine.ReserveStockIfAbleTo(inventory1);
			Helper.Factory.Save();
			var pick = Helper.CreatePickNew(order);
			var orderedInventory = pick.OrderedInventories[0];
			orderedInventory.AvailableInventories[0].Allocate = false;
			orderedInventory.AvailableInventories[1].Allocate = true;
			var pickLines = orderLine.PickLines;
			Helper.Factory.Save();
			AssertEquals(2, pickLines.Count);
			pickLines[1].WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLines[1].WZ_WE_OriginalPickedInventoryLine = ZGuid.NewZGuid();
			AssertEquals("Should have a pickLine with 0 Units", 0m, pickLines[0].WZ_Units);
			AssertEquals("Should have a pickLine with WZ_Units > 0", 10m, pickLines[1].WZ_Units);
			AssertEquals("PickLine0 is NOT Picked", false, pickLines[0].WZ_PickedDateTime.IsValid);
			AssertEquals("PickLine0 is NOT Picked from putaway location", false, pickLines[0].IsPickedFromPutawayLocation);
			AssertEquals("PickLine1 is Picked", true, pickLines[1].WZ_PickedDateTime.IsValid);
			AssertEquals("PickLine1 is Picked from putaway location", true, pickLines[1].IsPickedFromPutawayLocation);

			AssertEquals("Should ignore the pickLine with 0 Units and return false", false, pick.HasUnpickedPickLines);
		}

