		#region TestIsPartiallyOrFullyPickedFromPutawayLocation

		public void TestIsPartiallyOrFullyPickedFromPutawayLocation()
		{
			var now = ZDateTimeOffset.Now;
			var data = new TestDataSimpleEnvironment(Factory);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", now, data.Part1, 10m);
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", now, data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 20m,
				WhsPickOption.Codes.Manual);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition", 0m, Helper.GetTotalPickLineQuantity(pick));
			AssertEquals("When nothing was allocated yet pick must not be marked as picked.", false,
				pick.IsPartiallyOrFullyPickedFromPutawayLocation);

			pick.AutoAllocateItemsWithMock();
			AssertEquals("Precondition", 20m, Helper.GetTotalPickLineQuantity(pick));
			AssertEquals("Allocated pick should not be marked as picked.", false,
				pick.IsPartiallyOrFullyPickedFromPutawayLocation);

			var pickLine = pick.GetAllPickLines().First();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			AssertEquals("Pick with any picked pick line should be marked as picked.", true,
				pick.IsPartiallyOrFullyPickedFromPutawayLocation);

			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Empty;
			AssertEquals("Precondition.", false, pick.IsPartiallyOrFullyPickedFromPutawayLocation);

			pickLine.WZ_WE_OriginalPickedInventoryLine = receive2.Lines[0].PK;
			AssertEquals("Pick with any In-Transit pick line should be marked as picked from putaway location.", true,
				pick.IsPartiallyOrFullyPickedFromPutawayLocation);
		}

