		#region TestIsWorkOrderPick

		public void TestIsWorkOrderPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var workOrder = Helper.CreateWhsWorkOrder(data.Org1, data.Whs1);
			var dynamicWorkOrder = Helper.CreateWhsDynamicWorkOrder(data.Org1, data.Whs1);

			var pick1 = Factory.New<WhsPick>();
			var pick2 = Factory.New<WhsPick>();
			var pick1Interface = (IWhsPick)pick1;
			var pick2Interface = (IWhsPick)pick2;
			AssertEquals("Prerequisite", false, pick1.IsWorkOrderPick);
			AssertEquals("Prerequisite", false, pick2.IsWorkOrderPick);
			AssertEquals("Prerequisite", false, pick1Interface.IsWorkOrderPick);
			AssertEquals("Prerequisite", false, pick2Interface.IsWorkOrderPick);

			pick1.Orders.Add(workOrder);
			pick2.Orders.Add(dynamicWorkOrder);

			AssertEquals(true, pick1.IsWorkOrderPick);
			AssertEquals(true, pick2.IsWorkOrderPick);
			AssertEquals(true, pick1Interface.IsWorkOrderPick);
			AssertEquals(true, pick2Interface.IsWorkOrderPick);
			pick1.Orders.Remove(workOrder);
			pick2.Orders.Remove(dynamicWorkOrder);

			AssertEquals("Expect PickType to remain set", true, pick1.IsWorkOrderPick);
			AssertEquals("Expect PickType to remain set", true, pick2.IsWorkOrderPick);
			AssertEquals("Expect PickType to remain set", true, pick1Interface.IsWorkOrderPick);
			AssertEquals("Expect PickType to remain set", true, pick2Interface.IsWorkOrderPick);
		}

