		#region TestIsHeldInventoryOrderPick

		public void TestIsHeldInventoryOrderPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			var emptyOrder = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var availableInventoryOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5);
			var heldInventoryOrder = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var heldInventoryOrderLine = Helper.CreateWhsOrderLine(heldInventoryOrder, data.Part1, 5);
			heldInventoryOrderLine.WE_WHC_NKOrderedHeldCode = InventoryHoldCodes.Codes.Damaged;
			var workOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5);
			var dynamicWorkOrder = Helper.CreateWhsDynamicWorkOrderWithLine(data.Org1, data.Whs1, data.Part1, 5);

			var emptyOrderPick = Factory.New<WhsPick>();
			var availableInventoryOrderPick = Factory.New<WhsPick>();
			var heldOrderPick = Factory.New<WhsPick>();
			var workOrderPick = Factory.New<WhsPick>();
			var dynamicWorkOrderPick = Factory.New<WhsPick>();

			AssertEquals("Prerequisite", false, emptyOrderPick.IsHeldInventoryOrderPick);
			AssertEquals("Prerequisite", false, availableInventoryOrderPick.IsHeldInventoryOrderPick);
			AssertEquals("Prerequisite", false, heldOrderPick.IsHeldInventoryOrderPick);
			AssertEquals("Prerequisite", false, workOrderPick.IsHeldInventoryOrderPick);
			AssertEquals("Prerequisite", false, dynamicWorkOrderPick.IsHeldInventoryOrderPick);

			emptyOrderPick.Orders.Add(emptyOrder);
			availableInventoryOrderPick.Orders.Add(availableInventoryOrder);
			heldOrderPick.Orders.Add(heldInventoryOrder);
			workOrderPick.Orders.Add(workOrder);
			dynamicWorkOrderPick.Orders.Add(dynamicWorkOrder);

			AssertEquals(false, emptyOrderPick.IsHeldInventoryOrderPick);
			AssertEquals(false, availableInventoryOrderPick.IsHeldInventoryOrderPick);
			AssertEquals(true, heldOrderPick.IsHeldInventoryOrderPick);
			AssertEquals(false, availableInventoryOrderPick.IsHeldInventoryOrderPick);
			AssertEquals(false, availableInventoryOrderPick.IsHeldInventoryOrderPick);

			heldOrderPick.Orders.Remove(heldInventoryOrder);

			AssertEquals("Expect PickType to remain set", true, heldOrderPick.IsHeldInventoryOrderPick);
		}

