		#region TestIsUpdatingAllocationLogSuspended

		public void TestIsUpdatingAllocationLogSuspended()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "W1");
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);

			AssertEquals("Precondition: Updating allocation log should not be suspended.", false, pick.IsUpdatingAllocationLogSuspended);

			using (pick.SuspendUpdatingAllocationLog())
			{
				AssertEquals("Updating allocation log should be suspended.", true, pick.IsUpdatingAllocationLogSuspended);

				using (pick.SuspendUpdatingAllocationLog())
				{
					AssertEquals("Updating allocation log should be suspended.", true, pick.IsUpdatingAllocationLogSuspended);
				}

				AssertEquals("Updating allocation log should be suspended.", true, pick.IsUpdatingAllocationLogSuspended);
			}

			AssertEquals("Updating allocation log should not be suspended.", false, pick.IsUpdatingAllocationLogSuspended);
		}

