			AssertEquals(
				"When WW_IsPickByUOMEnabled on pick is enabled (warehouse setting does not effected), it should populate pack type in all pick lines.",
				true, pickLines.All(pl => pl.WZ_F3_NKAllocatedPackType == "UNT"));
		}

