		#region TestCreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLines

		public void TestCreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLines_CancelPick()
		{
			CreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLinesCore((pick) => pick.CancelPick());
		}

		public void TestCreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLines_DetatchedOrder()
		{
			CreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLinesCore((pick) =>
			{
				pick.Factory.Save();
				pick.Orders.RemoveAll();
			});
		}

		void CreatePickShouldPopulatePackTypeForReservedLines_IncludeSplitLinesCore(
			Action<WhsPick> actionToRemoveOrderFromPick)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;
			data.Part1.PartUnits.RemoveAndDeleteAll();
			Helper.CreateProductUnit(data.Part1, "PLT", 100);
			Helper.CreateProductUnit(data.Part1, "BOX", 10);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 1000m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 254m);
			var orderline = order.Lines[0];
			orderline.ReserveStockIfAbleTo(receive.Inventory[0]);
			Factory.Save();
			AssertEquals("Precondition - Order line must have one pick line.", 1, orderline.PickLines.Count);

			var pick = Helper.CreatePickNew(order);
			var pickLinesIncludingSplitLines = pick.GetAllPickLines();
			AssertEquals("There must be 3 pick lines including split lines.", 3, pickLinesIncludingSplitLines.Count());
			AssertEquals("PLT",
				pickLinesIncludingSplitLines.Single(pl => pl.WZ_Units == 200).WZ_F3_NKAllocatedPackType); // created by split line
			AssertEquals("BOX",
				pickLinesIncludingSplitLines.Single(pl => pl.WZ_Units == 50).WZ_F3_NKAllocatedPackType); // created by split line
			AssertEquals("UNT",
				pickLinesIncludingSplitLines.Single(pl => pl.WZ_OriginalReservedQty == 254 && pl.WZ_Units == 4)
					.WZ_F3_NKAllocatedPackType); // original reserved line has original reserved quantity
			actionToRemoveOrderFromPick(pick);
			Factory.Save();

			var newFactory = new BusinessObjectFactory { RefreshEnabled = false };
			var orderlineInNewFactory = newFactory.Load<WhsOrderLine>(orderline.PK);

			var newPickline = orderlineInNewFactory.PickLines.Single();
			AssertEquals("Orginal reserved Quantity must remain as before.", 254m, newPickline.WZ_OriginalReservedQty);
			AssertEquals("Pack type must be cleared.", "", newPickline.WZ_F3_NKAllocatedPackType);

			var newFactoryToRecreatePick = new BusinessObjectFactory { RefreshEnabled = false };
			var orderInNewFactoryToRecreatePick = newFactoryToRecreatePick.Load<WhsOrder>(order.PK);
			var pickInNewFactoryToRecreatePick =
				new WhsTestHelperFunctions(newFactoryToRecreatePick).CreatePickNew(orderInNewFactoryToRecreatePick);
			var newlyCreatedPickLinesIncludingSplitLines = pickInNewFactoryToRecreatePick.GetAllPickLines();
			AssertEquals(
				"There must be 3 pick lines including split lines after cancelling or detaching the old pick and recreating the pick.",
				3, newlyCreatedPickLinesIncludingSplitLines.Count());
			AssertEquals("PLT",
				newlyCreatedPickLinesIncludingSplitLines.Single(pl => pl.WZ_Units == 200)
					.WZ_F3_NKAllocatedPackType); // created by split line
			AssertEquals("BOX",
				newlyCreatedPickLinesIncludingSplitLines.Single(pl => pl.WZ_Units == 50)
					.WZ_F3_NKAllocatedPackType); // created by split line
			AssertEquals("UNT",
				newlyCreatedPickLinesIncludingSplitLines.Single(pl => pl.WZ_OriginalReservedQty == 254 && pl.WZ_Units == 4)
					.WZ_F3_NKAllocatedPackType); // original reserved line has original reserved quantity
		}

