		public void TestForcePickUOMTypeAllocation_BothPropertiesReadOnlyWhenPickIsCanceled()
		{
			var data = new EnvTestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			AssertEquals("Precondition - Pick line should not have a pack type allocated.", "", order.Lines.Single().PickLines.Single().WZ_F3_NKAllocatedPackType);
			AssertEquals("WP_ForcePickByCaseUOMTypeAllocation should not be readonly.", false, pick.WP_ForcePickByCaseUOMTypeAllocationInfo.ReadOnly);
			AssertEquals("WP_ForceSplitCaseUOMTypeAllocation should not be readonly.", false, pick.WP_ForceSplitCaseUOMTypeAllocationInfo.ReadOnly);

			pick.CancelPick();
			Factory.Save();

