		public void TestForcePickUOMTypeAllocation_BothPropertiesRefreshBindingCalledDuringPackTypeAssignment()
		{
			var data = new EnvTestDataSimpleEnvironment(Factory);
			var whs = data.Whs1;
			whs.WW_IsPickByUOMEnabled = true;
			data.Part1.PartUnits.RemoveAndDeleteAll();
			Helper.CreateProductUnit(data.Part1, "PLT", 10);

			Helper.CreateWhsReceiveWithInventory(data.Org1, whs, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, whs, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew();
			var casForceRefreshHitCount = 0;
			var spcForceRefreshHitCount = 0;
			pick.WP_ForcePickByCaseUOMTypeAllocationInfo.ValueChanged += (sender, e) => casForceRefreshHitCount++;
			pick.WP_ForceSplitCaseUOMTypeAllocationInfo.ValueChanged += (sender, e) => spcForceRefreshHitCount++;
			Factory.Save();

			pick.AddOrders(new WhsPickableDocket[] { order });
			pick.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 10m;
			Factory.Save();

			Assert("Precondition - Pick lines should all have pack type allocated.", pick.GetAllPickLines().All(p => p.WZ_F3_NKAllocatedPackType != ""));
			AssertEquals("Refresh binding should have been called exactly once during the pack type assignment.", 1, casForceRefreshHitCount);
			AssertEquals("Refresh binding should have been called exactly once during the pack type assignment.", 1, spcForceRefreshHitCount);
		}

