		public void TestWP_TaskPlanningStatus_ShouldSetToNotReadyForPlanningAfterWarehouseChanged()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var releaseGroup = Helper.CreateReleaseGroup("RG1", "RG1");
			var warehouse1 = Helper.CreateWarehouse("WH1", "A", 2, 2);
			warehouse1.WW_GG_ReleaseGroup = releaseGroup.PK;
			var warehouse2 = Helper.CreateWarehouse("WH2", "A", 2, 2);
			Factory.Save();

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, warehouse1, "R1", data.Part1, 20m);
			Factory.Save();
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, warehouse2, "R2", data.Part1, 20m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, warehouse1, "O1", data.Part1, 20m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, warehouse2, "O2", data.Part1, 20m);
			var pick = Factory.New<WhsPick>();
			Factory.Save();

			AssertNullOrEmptyOrWhitespace("Precondition", pick.WP_TaskPlanningStatus);

			pick.Orders.Add(order1);
			Factory.Save();

			AssertEquals("Task Planning Status should be Not Ready For Planing after changed to warehouse with valid release group", TaskPlanningStatus.Codes.NotReady, pick.WP_TaskPlanningStatus);

			pick.Orders.RemoveAll();
			Factory.Save();

			pick.WP_WW_Whs = warehouse2.PK;
			pick.Orders.Add(order2);
			Factory.Save();

			AssertNullOrEmpty("Task Planning Status should be empty after changed to warehouse without valid release group", pick.WP_TaskPlanningStatus);
		}

		public void TestWP_TaskPlanningStatus_ShouldBeClearAfterFinalised()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var releaseGroup = Helper.CreateReleaseGroup("RG1", "RG1");
			data.Whs1.WW_GG_ReleaseGroup = releaseGroup.PK;

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 20m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 20m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.Ready;
			AssertEquals(TaskPlanningStatus.Codes.Ready, pick.WP_TaskPlanningStatus);
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertEquals("Precondition.", true, pick.IsFinalised);
			AssertNullOrEmptyOrWhitespace(pick.WP_TaskPlanningStatus);

			Factory.Save();
			AssertNullOrEmptyOrWhitespace(pick.WP_TaskPlanningStatus);
		}

