		void TestWP_TaskPlanningStatus_SetStatusToReady_CartoniseAndPickByLableFlagCore(bool cartoniseSplitCases, bool pickCasesByLabel, bool pickPalletsByLabel, bool isCartonised, string expectStatus)
		{
			using (WarehouseDataRegistry.Instance.AutomaticallySetPickTaskPlanningStatusToReadyForPlanning.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var data = new TestDataSimpleEnvironment(Factory);
				var releaseGroup = Helper.CreateReleaseGroup("RG1", "RG1");
				data.Whs1.WW_GG_ReleaseGroup = releaseGroup.PK;

				var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 20m);
				Factory.Save();

				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 20m);
				var pick = Factory.New<WhsPick>();
				pick.PickOrdersWithAllocationMock(order, saveFactory: false);
				pick.WP_CartoniseSplitCases = cartoniseSplitCases;
				pick.WP_PickCasesByLabel = pickCasesByLabel;
				pick.WP_PickPalletsByLabel = pickPalletsByLabel;
				pick.WP_IsCartonised = isCartonised;
				Factory.Save();

				AssertEquals(false, pick.WP_IsAwaitingReplenishment);
