		#region TestWP_PrecentageComplete

		public void TestWP_PrecentageComplete()
		{
			var data = new TestDataSimpleEnvironment(Factory, 20, 1); // 20 locations in total, one location picked is 5%.
			data.Org1.MiscServ.OM_IMPartAttrib1Type = PartAttributeTypeList.Codes.VIN;
			Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);

			var locations = data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations;

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			// create stock for all 20 locations 1 Part1 and 5 Part2 per each location
			for (int i = 0; i < 20; i++)
			{
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, locations[i], ZDate.Empty, ZDate.Empty,
					"SN:00" + i, "", "", "");
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 5m, locations[i]);
			}
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine11 = Helper.CreateWhsOrderLine(order1, data.Part1, 10m); // 10 first locations
			var orderLine12 = Helper.CreateWhsOrderLine(order1, data.Part2, 25m); // 5 first locations

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine21 = Helper.CreateWhsOrderLine(order2, data.Part1, 10m); // 10 last locations
			var orderLine22 = Helper.CreateWhsOrderLine(order2, data.Part2, 75m); // 15 last locations
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.PickOrdersWithAllocationMock(new WhsPickableDocket[] { order1, order2 });
			pick.AutoAllocateItemsWithMock();

			AssertEquals("None of the Locations should be Picked yet", (ZByte)0, pick.WP_PercentageComplete);

			order1.FinaliseDocket();
			pick.ReCalculatePercentageComplete(); // try to recalculate and see if the value changed
			AssertEquals("Order should be finalised", true, order1.IsFinalised);
			AssertEquals("Order finalisation shouldn't affect the Percentage Complete", (ZByte)0, pick.WP_PercentageComplete);

			// mark 15 last locations for Part2 as Picked
			foreach (WhsPickLine pickLine in orderLine22.PickLines)
			{
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Today;
			}
			AssertEquals(
				"Ever through Part2 has been picked from 15 locations, they still have Part1 units to pick, so shouldn't count as fully picked",
				(ZByte)0, pick.WP_PercentageComplete);

			orderLine21.PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			AssertEquals("One of the locations was cleared of Part1 too, so now this location should be marked as fully picked.",
				(ZByte)5, pick.WP_PercentageComplete);

			WarehouseDataRegistry.Instance.DisplayPickStatus.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			pick.ReCalculatePercentageComplete(); // try to recalculate and see if the value changed
			AssertEquals(
				"When Registry settings are set to not Display Percentage Complete, then the actual value shouldn't be affected.",
				(ZByte)5, pick.WP_PercentageComplete);
			WarehouseDataRegistry.Instance.DisplayPickStatus.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			pick.ReCalculatePercentageComplete(); // try to recalculate and see if the value changed

			order2.FinaliseDocket();
			AssertEquals("Order should be finalised", true, order2.IsFinalised);

			pick.FinalisePick();
			AssertEquals("Pick should be Finalised", true, pick.IsFinalised);
			AssertEquals("All locations (100%) should be marked as Picked if Pick was finalised", (ZByte)100,
				pick.WP_PercentageComplete);
		}

		#region TestReCalculatePercentageComplete

		public void TestReCalculatePercentageComplete()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1); // 2 locations in total, one location picked is 50%.
			var locations = data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations;

			WhsReceive receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 5m, locations[0]);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 5m, locations[1]);
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			WhsOrder order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			WhsOrderLine orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.PickOrdersWithAllocationMock(order);
			pick.AutoAllocateItemsWithMock();

			AssertEquals("None of the Locations should be Picked yet", (ZByte)0, pick.WP_PercentageComplete);

			orderLine.PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			AssertEquals("One Location should be Picked", (ZByte)50, pick.WP_PercentageComplete);

			// simulate situation when PercentCompleted is incorrect
			pick.WP_PercentageComplete = 0;
			AssertEquals("We assigned wrong value for test so Percentage Complete should be 0", (ZByte)0,
				pick.WP_PercentageComplete);

			pick.ReCalculatePercentageComplete();
			AssertEquals("The Percentage Complete should be recalculated and show correct value of one Location Picked",
				(ZByte)50, pick.WP_PercentageComplete);
		}

		#endregion

		#region TestReCalculatePercentageComplete_PickByBOM

		public void TestReCalculatePercentageComplete_PickByBOM()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, wheel, 100m, data.Whs1.FindLocation("A-1"));
			Helper.CreateWhsReceiveInventoryLine(receive, bike, 20m, data.Whs1.FindLocation("A-2"));
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive.IsFinalised);

			var pick = Factory.New<WhsPick>();
			pick.WP_WW_Whs = data.Whs1.PK;
			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultInboundDockDoor;
			pick.WP_PickOption = WhsPickOption.Codes.Manual;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption: WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, bike, 30m);

			pick.AddOrders(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			Factory.Save();
			AssertEquals("Added component orderline should exist.", 1, orderLine.ChildComponentLines.Count);
			AssertEquals("Should be allocated.", true, orderLine.ChildComponentLines.First().PickLines.Count > 0);

			var pickLine1 = orderLine.PickLines.Single(l => l.WZ_Units == 20m);
			var pickLine2 = orderLine.PickLines.Single(l => l.WZ_Units == 10m);
			var wheelPickLine = orderLine.ChildComponentLines.Single().PickLines.Single();

			AssertEquals("None of the Locations should be Picked yet", (ZByte)0, pick.WP_PercentageComplete);

			wheelPickLine.WZ_PickedDateTime = ZDateTimeOffset.Today;
			AssertEquals("One Location should be Picked", (ZByte)50, pick.WP_PercentageComplete);

			// simulate situation when PercentCompleted is incorrect
			pick.WP_PercentageComplete = 0;
			AssertEquals("We assigned wrong value for test so Percentage Complete should be 0", (ZByte)0,
				pick.WP_PercentageComplete);

			pick.ReCalculatePercentageComplete();
			AssertEquals("The Percentage Complete should be recalculated and show correct value of one Location Picked",
				(ZByte)50, pick.WP_PercentageComplete);

			pickLine1.WZ_PickedDateTime = ZDateTimeOffset.Today;
			AssertEquals("One Location should be Picked", (ZByte)100, pick.WP_PercentageComplete);

			// simulate situation when PercentCompleted is incorrect
			pick.WP_PercentageComplete = 0;
			AssertEquals("We assigned wrong value for test so Percentage Complete should be 0", (ZByte)0,
				pick.WP_PercentageComplete);

			pick.ReCalculatePercentageComplete();
			AssertEquals("The Percentage Complete should be recalculated and show correct value of one Location Picked",
				(ZByte)100, pick.WP_PercentageComplete);
		}

