		public void TestReCalculatePercentageComplete_WhenOrdersAttachedAndDetatched()
		{
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			var locations = data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations;
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 15m, locations[0]);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 20m, locations[1]);
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var orderForPart1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLineForPart1 = Helper.CreateWhsOrderLine(orderForPart1, data.Part1, 10m);

			var orderForPart2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
