		#region TestSuspendPickPercentageRecalculation

		public void TestSuspendPickPercentageRecalculation()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, location1, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m, location2, "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition: Percentage Complete should be zero.", (byte)0, pick.WP_PercentageComplete);

			var pickLine = orderLine.PickLines[0];
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pick.WP_PercentageComplete = 0;

			using (pick.SuspendPickPercentageRecalculation())
			{
				using (pick.SuspendPickPercentageRecalculation())
				{
					pick.ReCalculatePercentageComplete();
					AssertEquals("While Percentage Recalculation is suspended, Percentage should not update.", (byte)0,
						pick.WP_PercentageComplete);
				}

				pick.ReCalculatePercentageComplete();
				AssertEquals("While Percentage Recalculation is suspended, Percentage should not update.", (byte)0,
					pick.WP_PercentageComplete);
			}

			AssertEquals("Percentage Recalculation is not suspended, Percentage should update when it was resumed.", (byte)50,
				pick.WP_PercentageComplete);
		}

		#endregion

