			AssertIsFinalisedPrecondition(order);

			var pickLine1 = orderLine.PickLines[0];
			var pickLine2 = orderLine.PickLines.First(pl => pl != pickLine1);

			int assertionHitCount = 0;
			EventHandler handler = (sender, e) =>
			{
				assertionHitCount++;
				AssertEquals("Percentage Complete Calculation is suspended during finalise, should remain as zero.", (byte)0,
					pick.WP_PercentageComplete);
			};

			pickLine1.WZ_PickedDateTimeInfo.ValueChanged += handler;
			pickLine2.WZ_PickedDateTimeInfo.ValueChanged += handler;
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(pick);
			AssertEquals("Percentage Complete should be correct after finalisation.", (byte)100, pick.WP_PercentageComplete);
			AssertEquals("Ensure Assertions were hit.", 2, assertionHitCount);
		}

