		#region TestWP_WW_Whs_SetsDockDoorLocation

		public void TestWP_WW_Whs_SetsDockDoorLocation()
		{
			var ddlLocationType = Helper.CreateLocationType("XYZ", LocationClasses.Codes.DDL);

			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			data.Whs1.CreateDefaultDockDoorLocationIfNeeded_ForTest();
			var locationA1 = data.Whs1.FindLocation("A-1");
			var locationA2 = data.Whs1.FindLocation("A-2");
			locationA1.WLV_WLT_LocationType = ddlLocationType.PK;

			var whs2 = Helper.CreateWarehouse("WH2", "B", 2, 1);
			whs2.CreateDefaultDockDoorLocationIfNeeded_ForTest();

			var pick = Factory.New<WhsPick>();
			AssertEquals("Precondition", true, pick.WP_WW_Whs.IsEmpty);
			AssertEquals("Precondition", true, pick.DockDoorPK.IsEmpty);
			AssertEquals("Precondition", true, data.Whs1.WW_DefaultOutboundDockDoor.IsValid);
			AssertEquals("Precondition", true, whs2.WW_DefaultOutboundDockDoor.IsValid);

			pick.WP_WW_Whs = data.Whs1.PK;
			AssertEquals("When setting warehouse pick should get default dock door location of the warehouse.",
				data.Whs1.WW_DefaultOutboundDockDoor, pick.DockDoorPK);

			pick.DockDoorPK = locationA1.PK;
			AssertEquals("Client can change to another dock door location from same warehouse.", locationA1.PK,
				pick.DockDoorPK);

			pick.WP_WW_Whs = data.Whs1.PK;
			AssertEquals(
				"Reassigning warehouse should not override client entered dock door location, unless warehouse changed.",
				locationA1.PK, pick.DockDoorPK);

			pick.WP_WW_Whs = whs2.PK;
			AssertEquals("Changing warehouse should also change dock door location to default from that warehouse.",
				whs2.WW_DefaultOutboundDockDoor, pick.DockDoorPK);

			pick.WP_WW_Whs = ZGuid.Empty;
			AssertEquals("Removing warehouse should also remove dock door location.", ZGuid.Empty, pick.DockDoorPK);

			var client = Helper.CreateClient();
			var part = Helper.CreateProduct(client, "P1");
			var workOrder = Helper.CreateWhsWorkOrderWithLine(client, data.Whs1, part, 10m);
			pick.Orders.Add(workOrder);
			AssertEquals("Dock door location should not be populated for work order picks.", ZGuid.Empty, pick.DockDoorPK);

			pick.WP_WW_Whs = whs2.PK;
			AssertEquals("Dock door location should not be populated for work order picks.", ZGuid.Empty, pick.DockDoorPK);
		}

		#endregion

		#region TestDockDoorPK_SetsWarehouse

		public void TestDockDoorPK_SetsWarehouse_DockDoorPK()
		{
			var ddlLocationType = Helper.CreateLocationType("123", LocationClasses.Codes.DDL);

			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var locationA1 = data.Whs1.FindLocation("A-1");
			var locationA2 = data.Whs1.FindLocation("A-2");
			locationA1.WLV_WLT_LocationType = ddlLocationType.PK;

			var whs2 = Helper.CreateWarehouse("WH2", "B", 2, 1);
			Factory.Save();

			var expectedDockDoorLocationErrorMessage = "Please enter a Dock Door.";
			var expectedWarehouseErrorMessage = "This Dock Door does not belong to Warehouse on the Pick.";

			var pick = Factory.New<WhsPick>();
			AssertNoError("Precondition", pick.DockDoorPKInfo, expectedDockDoorLocationErrorMessage);
			AssertNoError("Precondition", pick.DockDoorPKInfo, expectedWarehouseErrorMessage);

			// set dock door location
			pick.DockDoorPK = locationA1.PK;
			AssertEquals("Setting dock door location should set warehouse if it was not pre-set.", data.Whs1.PK, pick.WP_WW_Whs);
			AssertNoError(pick.DockDoorPKInfo, expectedDockDoorLocationErrorMessage);
			AssertNoError(pick.DockDoorPKInfo, expectedWarehouseErrorMessage);

			// set not dock door location
			pick.DockDoorPK = locationA2.PK;
			AssertHasError(pick.DockDoorPKInfo, expectedDockDoorLocationErrorMessage);
			AssertNoError(pick.DockDoorPKInfo, expectedWarehouseErrorMessage);

			// set dock door location from different warehouse
			pick.DockDoorPK = whs2.WW_DefaultOutboundDockDoor;
			AssertEquals("Setting dock door location should not modify pre-set warehouse.", data.Whs1.PK, pick.WP_WW_Whs);
			AssertNoError(pick.DockDoorPKInfo, expectedDockDoorLocationErrorMessage);
			AssertHasError(pick.DockDoorPKInfo, expectedWarehouseErrorMessage);

			// removing dock door location should not clear warehouse (should be mandatory if any orders attached)
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			pick.Orders.Add(order);
			pick.DockDoorPK = ZGuid.Empty;
			AssertEquals("Removing dock door location should not modify pre-set warehouse.", data.Whs1.PK, pick.WP_WW_Whs);
			AssertHasError(pick.DockDoorPKInfo, expectedDockDoorLocationErrorMessage);
			AssertNoError(pick.DockDoorPKInfo, expectedWarehouseErrorMessage);
		}

