		#region TestDockDoorPK

		public void TestDockDoorPK()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var ddlLocationType = Helper.CreateLocationType("123", LocationClasses.Codes.DDL);
			var locationA1 = data.Whs1.FindLocation("A-1");
			locationA1.WLV_WLT_LocationType = ddlLocationType.PK;
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			AssertEquals("Default should be empty.", ZGuid.Empty, pick.DockDoorPK);

			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultOutboundDockDoor;
			AssertEquals("Should be equal to WP_WL_DockDoor if it is the only one set.", data.Whs1.WW_DefaultOutboundDockDoor, pick.DockDoorPK);

			pick.WP_WL_DockDoor = ZGuid.Empty;
			AssertEquals("Should be empty.", ZGuid.Empty, pick.DockDoorPK);

			pick.DockDoorPK = data.Whs1.WW_DefaultOutboundDockDoor;
			AssertEquals("Should be correct when set.", data.Whs1.WW_DefaultOutboundDockDoor, pick.DockDoorPK);

			pick.WP_WW_Whs = data.Whs1.PK;
			pick.WP_PickOption = WhsPickOption.Codes.Manual;
			Factory.Save();

			var dda = Factory.New<WhsDockDoorAssignment>();
			dda.WDA_WL_AssignedDockDoor = locationA1.PK;
			pick.WP_WDA_DockDoorAssignment = dda.PK;
			AssertEquals("Should be equal to WDA_WL_AssignedDockDoor if both are set (not functionally possible).", locationA1.PK, pick.DockDoorPK);

			pick.WP_WL_DockDoor = ZGuid.Empty;
			AssertEquals("Should be equal to value on dock door assignment if it the only one set.", locationA1.PK, pick.DockDoorPK);

			pick.DockDoorPK = data.Whs1.WW_DefaultOutboundDockDoor;
			AssertEquals("Set should set when WDA_WL_AssignedDockDoor is set.", data.Whs1.WW_DefaultOutboundDockDoor, pick.DockDoorPK);

			dda.WDA_FirstPutawayToDockDoorUtc = ZDateTime.UtcNow;
			pick.DockDoorPK = locationA1.PK;
			AssertEquals("Set should ignore set when WDA_FirstPutawayToDockDoorUtc is set.", data.Whs1.WW_DefaultOutboundDockDoor, pick.DockDoorPK);
		}

