		#region TestDBHitsForOrderedInventory

		[StressTest]
		public void TestDBHitsForOrderedInventory()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var orderList = new List<WhsOrder>();
			for (int orderCount = 0; orderCount < 10; orderCount++)
			{
				var postfix = orderCount.ToString();
				var client = Helper.CreateClient("C" + postfix);
				var order = Helper.CreateWhsOrder(client, data.Whs1, "O" + postfix, WhsPickOption.Codes.Manual);
				for (int orderLineCount = 0; orderLineCount < 10; orderLineCount++)
				{
					var product = Helper.CreateProduct(client, "P" + postfix + orderLineCount.ToString());
					Helper.CreateWhsReceiveWithInventory(client, data.Whs1, "R" + postfix + orderLineCount.ToString(),
						ZDateTimeOffset.Today.AddDays(-1), product, 2, true, true);

					Helper.CreateWhsOrderLine(order, product, 1m);
				}
				orderList.Add(order);
			}

			var pick = Helper.CreatePickNew(orderList.ToArray());
			Factory.Save();

			var newFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
			var initialLoadCount = newFactory.DatabaseLoadCount;

			const int HitsFromLoadingPickInNewFactory = 1;
			var poke = pickInNewFactory.OrderedInventories;
			var expectedDbHits = new Dictionary<string, int>()
			{
				{ OrgHeaderSchema.Constants.TableName, 1 },
				{ OrgMiscServSchema.Constants.TableName, 1 },
				{ OrgSupplierPartSchema.Constants.TableName, 2 },
				{ WhsDocketSchema.Constants.TableName, 1 },
				{ WhsDocketLineSchema.Constants.TableName, 1 },
				{ WhsPickSchema.Constants.TableName, HitsFromLoadingPickInNewFactory },
				{ WhsPickLineSchema.Constants.TableName, 2 },
				{ WhsWarehouseSchema.Constants.TableName, 1 },
			};

			// initital DB count 26
			// changed from 18 to 17 by A.V
			// changed from 17 to 8 by BRS
			// changed from 8 to 7 by IGM/BAS
			// changed from 7 to 6 by MMC
			AssertDbHits(expectedDbHits, newFactory);
		}

