		#region TestDistinctClientProductPickFacesInWhsAwaitingReplenishment

		public void TestDistinctClientProductPickFacesInWhsAwaitingReplenishment()
		{
			var data = new PickFaceViewTestData(Factory, warehouses: 2, clients: 2, locationsPerWarehouse: 3);
			var locationsWhs1 = data.Locations[data.Warehouses[0]];
			var locationsWhs2 = data.Locations[data.Warehouses[1]];
			var normalLocation =
				Helper.CreateLocationType("NOR", "NormalLocation", false, 2, LocationClasses.Codes.NOR);
			locationsWhs1[0].WLV_WLT_LocationType = normalLocation.PK;
			locationsWhs2[0].WLV_WLT_LocationType = normalLocation.PK;

			int replenishMin = 1;
			var pickFace1 = Helper.CreateProductPickFace(data.Parts[0], data.Clients[0], locationsWhs1[1], replenishMin++);
			var pickFace2 = Helper.CreateProductPickFace(data.Parts[0], data.Clients[0], locationsWhs2[1], replenishMin++);
			var pickFace3 = Helper.CreateProductPickFace(data.Parts[1], data.Clients[1], locationsWhs2[2], replenishMin++);
			Factory.Save();

			var receive1 = Helper.CreateWhsReceive(data.Clients[0].PK, data.Warehouses[0].PK, "R1", Helper.Notify);
			Helper.CreateWhsReceiveInventoryLine(receive1, data.Parts[0], 100m, locationsWhs1[0]);
			receive1.FinaliseDocket();

			var receive2 = Helper.CreateWhsReceive(data.Clients[0].PK, data.Warehouses[1].PK, "R2", Helper.Notify);
			Helper.CreateWhsReceiveInventoryLine(receive2, data.Parts[0], 100m, locationsWhs2[0]);
			receive2.FinaliseDocket();

			var receive3 = Helper.CreateWhsReceive(data.Clients[1].PK, data.Warehouses[1].PK, "R3", Helper.Notify);
			Helper.CreateWhsReceiveInventoryLine(receive3, data.Parts[1], 100m, locationsWhs2[0]);
			receive3.FinaliseDocket();
			Factory.Save();

			var transfer1 = Helper.CreateWhsTransfer(data.Clients[0].PK, data.Warehouses[0].PK, "T1", Helper.Notify);
			var transferLine1 = Helper.CreateWhsTransferLine(transfer1, data.Parts[0], 100m, locationsWhs1[0].PK, locationsWhs1[1].PK);
			transferLine1.RunPreSaveValidation();

			var transfer2 = Helper.CreateWhsTransfer(data.Clients[0].PK, data.Warehouses[1].PK, "T2", Helper.Notify);
			var transferLine2 = Helper.CreateWhsTransferLine(transfer2, data.Parts[0], 100m, locationsWhs2[0].PK, locationsWhs2[1].PK);
			transferLine2.RunPreSaveValidation();

			var transfer3 = Helper.CreateWhsTransfer(data.Clients[1].PK, data.Warehouses[1].PK, "T3", Helper.Notify);
			var transferLine3 = Helper.CreateWhsTransferLine(transfer3, data.Parts[1], 100m, locationsWhs2[0].PK, locationsWhs2[2].PK);
			transferLine3.RunPreSaveValidation();
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Clients[0].PK, data.Warehouses[0].PK, data.Clients[0].PK, "order1");
			Helper.CreateWhsOrderLine(order1, data.Parts[0], 30m);
			var pick1 = Helper.CreatePickNew(false, false, order1);
			var order2 = Helper.CreateWhsOrder(data.Clients[1].PK, data.Warehouses[1].PK, data.Clients[1].PK, "order2");
			Helper.CreateWhsOrderLine(order2, data.Parts[1], 40m);
			var pick2 = Helper.CreatePickNew(false, false, order2);
			var order3 = Helper.CreateWhsOrder(data.Clients[0].PK, data.Warehouses[1].PK, data.Clients[0].PK, "order3");
			Helper.CreateWhsOrderLine(order3, data.Parts[0], 30m);
			var pick3 = Helper.CreatePickNew(false, false, order3);
			Factory.Save();

			AssertEquals(1, pick1.DistinctClientProductPickFacesInWhsAwaitingReplenishment.Count);
			AssertEquals(1, pick3.DistinctClientProductPickFacesInWhsAwaitingReplenishment.Count);

			AssertEquals(data.Clients[0].OH_Code, pick1.DistinctClientProductPickFacesInWhsAwaitingReplenishment[0].ClientCode);
			AssertEquals(data.Parts[0].OP_PartNum, pick1.DistinctClientProductPickFacesInWhsAwaitingReplenishment[0].ProductCode);
			AssertEquals(data.Clients[0].OH_Code, pick3.DistinctClientProductPickFacesInWhsAwaitingReplenishment[0].ClientCode);
			AssertEquals(data.Parts[0].OP_PartNum, pick3.DistinctClientProductPickFacesInWhsAwaitingReplenishment[0].ProductCode);
		}

