		protected virtual void TestStandardReadOnly(ZPropertyInfo info)
		{
			TestReadOnly(info, false, true, true, true, true);
		}

		void TestCartonisationReadOnly(Func<WhsPick, ZPropertyInfo> getInfo)
		{
			var factory2 = new BusinessObjectFactory();
			var pick1 = factory2.New<WhsPick>();

			var whs = factory2.New<WhsWarehouse>();
			pick1.WP_WW_Whs = whs.PK;
			TestFinalisedOrCancelledReadOnly(getInfo(pick1), pick1);

			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R", data.Part2, 2m);
			Factory.Save();

			var bomProduct = Helper.CreateProductBOM(data.Part1, data.Part2);
			var workOrder = Helper.CreateWhsWorkOrderWithLine(data.Org1, data.Whs1, data.Part1, 1m);

			var pick2 = Helper.CreatePickNew(workOrder);
			AssertEquals("Precondition", true, pick2.IsWorkOrderPick);
			//Should be ReadOnly for Work Order Picks
			TestReadOnly(getInfo(pick2), true, true, true, true, true, pick2, attachOrder: false);

			var pick3 = Helper.CreatePickNew();
			// Precondition
			TestFinalisedOrCancelledReadOnly(getInfo(pick3), pick3);

			var mutex = new ZGlobalMutex(MutexIDs.WhsPickAllocatingPackageLabels, pick3.PK.ToString());
			mutex.Lock();

			using (mutex)
			{
				AssertEquals("Precondition", true, pick3.IsCartonising);
				//Should be ReadOnly for Cartonising Picks.
				TestReadOnly(getInfo(pick3), true, true, true, true, true, pick3, attachOrder: false);
			}

			// Precondition
			TestFinalisedOrCancelledReadOnly(getInfo(pick3), pick3);

			pick3.WP_IsCartonised = true;
			//Should be ReadOnly for Cartonised Picks.
			TestReadOnly(getInfo(pick3), true, true, true, true, true, pick3, attachOrder: false);
		}

		void TestFinalisedOrCancelledReadOnly(ZPropertyInfo info, WhsPick pick)
		{
			TestReadOnly(info, false, false, true, true, false, pick);
		}

		protected void TestReadOnly(ZPropertyInfo info, bool created, bool pickSlip, bool finalised, bool cancelled,
			bool hasOrdersAttached, WhsPick pick = null, bool attachOrder = true)
		{
			pick = pick ?? Pick;

			pick.WP_PickStatus = PickStatus.Codes.Created;
			AssertEquals(info.Name + " should " + (created ? "" : " not ") + "be readonly if pick is Created", created,
				pick.ZPropertyInfoHash[info.Name].ReadOnly);
			pick.WP_PickStatus = PickStatus.Codes.PickSlip;
			AssertEquals(info.Name + " should " + (pickSlip ? "" : " not ") + "be readonly if pick is PickSlipPrinted", pickSlip,
				pick.ZPropertyInfoHash[info.Name].ReadOnly);
			pick.WP_PickStatus = PickStatus.Codes.Finalised;
			AssertEquals(info.Name + " should " + (finalised ? "" : " not ") + "be readonly if pick is Finalised", finalised,
				pick.ZPropertyInfoHash[info.Name].ReadOnly);
			pick.WP_PickStatus = PickStatus.Codes.Cancelled;
			AssertEquals(info.Name + " should " + (cancelled ? "" : " not ") + "be readonly if pick is Cancelled", cancelled,
				pick.ZPropertyInfoHash[info.Name].ReadOnly);

			pick.WP_PickStatus = PickStatus.Codes.Created;
			AssertEquals(info.Name + " should " + (created ? "" : " not ") + "be readonly if pick is Created", created,
				pick.ZPropertyInfoHash[info.Name].ReadOnly);

			if (attachOrder)
			{
				pick.Orders.Add(pick.Factory.New<WhsOrder>());
				AssertEquals(
					info.Name + " should " + (hasOrdersAttached ? "" : " not ") + "be readonly if pick has at least one Order",
					hasOrdersAttached, pick.ZPropertyInfoHash[info.Name].ReadOnly);
			}
		}

