		void AssertAutoPackOrdersAndPrintLabels(bool isPrinting)
		{
			// setup data
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "r1", data.Part1, 500);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "r2", data.Part2, 500);
			Helper.CreateProductUnit(data.Part1, "PLT", 4);
			Helper.CreateProductUnit(data.Part2, "PLT", 10);

			// setup the printer
			Helper.CreateDefaultPrinter(PackingRegistry.DefaultTargetLabelDocumentForTesting, GlbStaff.CurrentUser, Factory.New<IStmPrintQueue>().PK, 1);
			Factory.Save();

			// setup orders
			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			Helper.CreateWhsOrderLine(order1, data.Part1, 7m).WE_F3_NKPackType = "PLT";
			Helper.CreateWhsOrderLine(order1, data.Part2, 7m).WE_F3_NKPackType = "PLT";

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
			Helper.CreateWhsOrderLine(order2, data.Part1, 7m).WE_F3_NKPackType = "PLT";
			Helper.CreateWhsOrderLine(order2, data.Part2, 7m).WE_F3_NKPackType = "PLT";

			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "3");
			Helper.CreateWhsOrderLine(order3, data.Part1, 7m).WE_F3_NKPackType = "PLT";
			Helper.CreateWhsOrderLine(order3, data.Part2, 7m).WE_F3_NKPackType = "PLT";

			// setup pick
			var pick = Helper.CreatePickNew(order1, order2, order3);
			pick.AutoAllocateItemsWithMock();

			// test
			AssertEquals("Precondition", 0, order1.PackageJob.Packages.Count);
			AssertEquals("Precondition", 0, order2.PackageJob.Packages.Count);
			AssertEquals("Precondition", 0, order3.PackageJob.Packages.Count);

			using (WarehouseDataRegistry.Instance.DisablePrintingLabelsOnAutoPack.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, !isPrinting))
			{
				var success = pick.AutoPackOrdersAndPrintLabels(Notify);
				AssertEquals("There should be no errors", true, success);
			}

			var printJobs = Factory.Load<IStmPrintJob>(new ZQuery());
			AssertAutoPackedItems(order1.PackageJob, data);
			AssertAutoPackedItems(order2.PackageJob, data);
			AssertAutoPackedItems(order3.PackageJob, data);

			if (isPrinting)
			{
				AssertEquals("There should be a print job for all 14 packages of all 3 orders. (3x14 = meaning of life).", 42, printJobs.Length);
			}
			else
			{
				AssertEquals("There should be no print jobs when printing is disabled.", 0, printJobs.Length);
			}
		}

		public void TestAutoPackOrdersAndPrintLabels_AvoidFactorySaveOnValidationError()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			data.Part1.OP_Depth = 20m;
			data.Part1.OP_Width = 20m;
			data.Part1.OP_Height = 20m;
			data.Part1.OP_MeasureUQ = "M";

			data.Part1.OP_WeightUQ = Core.Constants.Weight.Kilograms;
			data.Part1.OP_CubicUQ = Core.Constants.Volume.CubicMetres;

			Helper.CreateProductUnit(data.Part1, "PLT", 10m);

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 110m);
			Factory.Save();

			// setup orders
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 1m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
			order2.Lines[0].WE_F3_NKPackType = "PLT";

			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O3", data.Part1, 1m);

			// setup picks
			var pick = Helper.CreatePickNew(order1, order2, order3);
			Factory.Save();

			var packtype = Factory.LoadFromUniqueKey<RefPackType>(RefPackTypeSchema.F3_Code, new ZString("PLT"));
			packtype.F3_Length = 1m;
			packtype.F3_Width = 1m;
			packtype.F3_Height = 1m;

			packtype.F3_Weight = 15m;
			packtype.F3_UnitOfWeight = Core.Constants.Weight.Kilograms;
			packtype.F3_UnitOfDimension = Core.Constants.Length.Metres;

			order1.WD_AddPalletWeightToOrder = false;
			order2.WD_AddPalletWeightToOrder = true;

			Factory.Save();

			using (PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, Core.Constants.Volume.CubicCentimeters))
			{
				var isSuccess = pick.AutoPackOrdersAndPrintLabels(Notify);
				AssertEquals(
					@"Order W00000003 cannot be saved due to the following validation errors:
Error - KP_Volume: The number 1,000,000 is too large, the maximum value allowed for Volume is 999,999.999.",
					Notify.AsString.Trim());

				AssertEquals(false, isSuccess);
				var newFactory = new BusinessObjectFactory();
				var order1InNewFactory = newFactory.Load<WhsOrder>(order1.PK);
				var order2InNewFactory = newFactory.Load<WhsOrder>(order2.PK);
				var order3InNewFactory = newFactory.Load<WhsOrder>(order3.PK);

				AssertEquals("Packages should have been created and saved for first order.", 1, order1InNewFactory.PackageJob.Packages.Count);
				AssertEquals("Packages should not have been created and saved for second order.", 0, order2InNewFactory.PackageJob.Packages.Count);
				AssertEquals("Packages should not have been created and saved for third order.", 0, order3InNewFactory.PackageJob.Packages.Count);
			}
		}

		public void TestAutoPackOrdersAndPrintLabels_NoPackages()
		{
			var data = new TestDataSimpleEnvironment(Factory);

