		void AssertAutoPackedItems(PkgPackageJob packageJob, TestDataSimpleEnvironment data)
		{
			// expect 14x PLT, 7 with 4 items each, 7 with with 10 items each.
			var part1Packages =
				packageJob.Packages.Where(p => p.KP_F3_NKPackType == "PLT" && p.PackedItemDivots[0].KI_PackedQty == 4);
			var part2Packages =
				packageJob.Packages.Where(p => p.KP_F3_NKPackType == "PLT" && p.PackedItemDivots[0].KI_PackedQty == 10);

			AssertEquals(14, packageJob.Packages.Count);
			AssertEquals(7, part1Packages.Count());
			AssertEquals(7, part2Packages.Count());

			foreach (var package in part1Packages)
			{
				var divot = package.PackedItemDivots.Single();
				AssertEquals(4m, divot.KI_PackedQty);
			}

			foreach (var package in part2Packages)
			{
				var divot = package.PackedItemDivots.Single();
				AssertEquals(10m, divot.KI_PackedQty);
			}
		}

