		#region TestResetOrderLines_CustomsData

		public void TestResetOrderLines_CustomsData()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			var orderToBeRemoved = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 1m);
			orderToBeRemoved.WD_DocketSubType = OrderType.Codes.Customs;

			var orderToRemainInPick = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "2", data.Part1, 2m);
			orderToRemainInPick.WD_DocketSubType = OrderType.Codes.Customs;

			var customsDataInOrderToBeRemoved = CreateCustomsData(orderToBeRemoved, "1111", 1, 1m, "1", 2m, 3m);
			var customsDataInOrderToRemainInPick = CreateCustomsData(orderToRemainInPick, "2222", 2, 2m, "2", 3m, 4m);

			var pick = Helper.CreatePickNew(orderToBeRemoved, orderToRemainInPick);
			Factory.Save();
			AssertEquals("Precondition", DocketStatus.Codes.AttachedToPick, orderToBeRemoved.WD_DocketStatus);
			AssertEquals("Precondition", DocketStatus.Codes.AttachedToPick, orderToRemainInPick.WD_DocketStatus);
			AssertCustomsDataProperties(customsDataInOrderToBeRemoved, "1111", 1, 1m, "1", 2m, 3m);
			AssertCustomsDataProperties(customsDataInOrderToRemainInPick, "2222", 2, 2m, "2", 3m, 4m);

			pick.Orders.Remove(orderToBeRemoved);
			Factory.Save();

			AssertEquals($"DocketStatus should be changed to '{DocketStatus.Codes.Entered}'", DocketStatus.Codes.Entered, orderToBeRemoved.WD_DocketStatus);
			AssertEquals($"DocketStatus should remain '{DocketStatus.Codes.AttachedToPick}'", DocketStatus.Codes.AttachedToPick, orderToRemainInPick.WD_DocketStatus);

			AssertCustomsDataProperties(customsDataInOrderToBeRemoved, "", 0, 1m, "1", 2m, 3m);
			AssertCustomsDataProperties(customsDataInOrderToRemainInPick, "2222", 2, 2m, "2", 3m, 4m);
		}

		static WhsBondedWarehouseAttribute CreateCustomsData(WhsOrder order, string entryKey, short lineNo, decimal customsQty, string tariff, decimal customsSecondQty, decimal customsThirdQty)
		{
			var customsData = order.Lines.Single().CustomsData;
			customsData.WB_EntryKey = entryKey;
			customsData.WB_EntryLineNo = lineNo;
			customsData.WB_CustomsQty = customsQty;
			customsData.WB_CustomsSecondQuantity = customsSecondQty;
			customsData.WB_CustomsThirdQuantity = customsThirdQty;
			customsData.WB_Tariff = tariff;
			return customsData;
		}

		static void AssertCustomsDataProperties(WhsBondedWarehouseAttribute customsData, string entryKey, short lineNo, decimal customsQty, string tariff, decimal customsSecondQty, decimal customsThirdQty)
		{
			AssertEquals($"Expected value for Entry Key must be {entryKey}", entryKey, customsData.WB_EntryKey);
			AssertEquals($"Expected value for Line No must be {lineNo}", lineNo, customsData.WB_EntryLineNo);
			AssertEquals($"Expected value for Customs Qty must be {customsQty}", customsQty, customsData.WB_CustomsQty);
			AssertEquals($"Expected value for Customs Qty must be {customsSecondQty}", customsSecondQty, customsData.WB_CustomsSecondQuantity);
			AssertEquals($"Expected value for Customs Qty must be {customsThirdQty}", customsThirdQty, customsData.WB_CustomsThirdQuantity);
			AssertEquals($"Expected value for Tariff must be {tariff}", tariff, customsData.WB_Tariff);
		}

