		[GuiTest]
		[StressTest]
		public void TestPickOrders_WhenAutoPick_DBHits()
		{
			var expectedNumberOfDBHits = 64;
			const int numberOfInventoriesToCreate = 200;

			var data = new TestDataSimpleEnvironment(Factory, 10, 10);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			for (int i = 0; i < numberOfInventoriesToCreate / 2; i++)
			{
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m);
			}

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var adjustment = Helper.CreateWhsAdjustment(data.Org1, data.Whs1, "A1", Notify);
			for (int i = 0; i < numberOfInventoriesToCreate / 2; i++)
			{
				Helper.CreateWhsAdjustmentLine(adjustment, data.Part1, 1m, data.Whs1.DefaultLocation);
			}

			adjustment.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(adjustment);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var otherFactory = new BusinessObjectFactory();
			var orderInOtherFactory = otherFactory.Load<WhsOrder>(order.PK);
			int dbHitsBeforePick = otherFactory.DatabaseLoadCount;

			var expectedDBHits = new Dictionary<string, int>();
			expectedDBHits.Add(JobDocAddressSchema.Constants.TableName, 1);
			expectedDBHits.Add(OrgAddressSchema.Constants.TableName, 3);
			expectedDBHits.Add(OrgAddressCapabilitySchema.Constants.TableName, 1);
