			expectedDBHits.Add(OrgPartUnitSchema.Constants.TableName, 1);
			expectedDBHits.Add(OrgSupplierPartSchema.Constants.TableName, 1);
			expectedDBHits.Add(OrgPartRelationSchema.Constants.TableName, 1);
			expectedDBHits.Add(PkgPackageJobSchema.Constants.TableName, 1);
			expectedDBHits.Add(ProcessTaskNotificationSchema.Constants.TableName, 1);
			expectedDBHits.Add(ProcessTasksSchema.Constants.TableName, 2);
			expectedDBHits.Add(ProcessCompanyLinkRuleSchema.Constants.TableName, 1);
			expectedDBHits.Add(ProcessTaskTemplateSchema.Constants.TableName, 2);
			expectedDBHits.Add(ProductionRuleSchema.Constants.TableName, 1);
			expectedDBHits.Add(StmALogSchema.Constants.TableName, 2);
			expectedDBHits.Add(StmEventSchema.Constants.TableName, 4);  // increased by LBM from 2 to 3
			expectedDBHits.Add(WhsAreaSchema.Constants.TableName, 1);
			expectedDBHits.Add(WhsDocketSchema.Constants.TableName, 2);
			expectedDBHits.Add(WhsDocketLineSchema.Constants.TableName, 6);
			expectedDBHits.Add(WhsInventoryViewSchema.Constants.TableName, 1);
			expectedDBHits.Add(WhsLocationViewSchema.Constants.TableName, 3);
			expectedDBHits.Add(WhsPickFaceSchema.Constants.TableName, 1);
			// increased by A.V from 3 to 4 - due to rework of pick line collections
			expectedDBHits.Add(WhsPickLineSchema.Constants.TableName, 5);
			expectedDBHits.Add(WhsRowSchema.Constants.TableName, 1);
			expectedDBHits.Add(WhsWarehouseSchema.Constants.TableName, 1);
			expectedDBHits.Add(GlbBranchSchema.Constants.TableName, 3);
			expectedDBHits.Add(GlbStaffSchema.Constants.TableName, 1);
			expectedDBHits.Add(GlbCompanySchema.Constants.TableName, 2);
			expectedDBHits.Add(JobHeaderSchema.Constants.TableName, 1);
			expectedDBHits.Add(WhsLocationTypeSchema.Constants.TableName, 2);
			expectedDBHits.Add(WhsProductParamsByWhsAndClientSchema.Constants.TableName, 1);
			expectedDBHits.Add(RefCountrySchema.Constants.TableName, 1);
			expectedDBHits.Add(RefPackTypeSchema.Constants.TableName, 1);
			expectedDBHits.Add(RefPacksSchema.Constants.TableName, 1);
			expectedDBHits.Add(RefTimeZoneSchema.Constants.TableName, 1);
			expectedDBHits.Add(RefTimeZoneSetSchema.Constants.TableName, 1);
			expectedDBHits.Add(RefUNLOCOSchema.Constants.TableName, 1);

			var pick = otherFactory.New<WhsPick>();

			using (AssertDbHitsWithUsefulQueryInformation(expectedDBHits, otherFactory))
			using (RowFactory.SetCachedTables())
			{
				pick.PickOrders(orderInOtherFactory);
			}

			AssertEquals("Precondition", PickStatus.Codes.Created, pick.WP_PickStatus);

			CombineAssertions(() =>
			{
				var actualHits = otherFactory.DatabaseLoadCount - dbHitsBeforePick;
				Assert(string.Format("Expected {0} or fewer hits, but saw {1}", expectedNumberOfDBHits, actualHits),
					actualHits <= expectedNumberOfDBHits);

				AssertDbHits(expectedDBHits, otherFactory);
			});
