		#region TestPickOrders_WhenAutoPick_DBHits_WithCrossDocking

		[GuiTest]
		[StressTest]
		public void TestPickOrders_WhenAutoPick_DBHits_WithCrossDocking()
		{
			const int numberOfInventoriesToCreate = 100;

			var data = new TestDataSimpleEnvironment(Factory, 10, 10);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			for (int i = 0; i < numberOfInventoriesToCreate; i++)
			{
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m);
			}

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);

			for (int i = 0; i < numberOfInventoriesToCreate / 2; i++)
			{
				var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 2m);
				AssertNotNull("Precondition - Divot was created.", orderLine.ReserveStockIfAbleTo(receive.Inventory[i * 2]));
				AssertNotNull("Precondition - Divot was created.", orderLine.ReserveStockIfAbleTo(receive.Inventory[(i * 2) + 1]));
			}

			Factory.Save();

			var otherFactory = new BusinessObjectFactory();
			var orderInOtherFactory = otherFactory.Load<WhsOrder>(order.PK);

			using (RowFactory.SetCachedTables())
			{
				orderInOtherFactory.RunPreSaveValidation();
				orderInOtherFactory.Validation.ValidateAll();
			}

			var expectedDBHitsForValidation = new Dictionary<string, int>()
			{
				// irrelevant db hits, mainly coming from dbo.JobDocAddress Validation
				{ OrgAddressCapabilitySchema.Constants.TableName, 1 },
				{ OrgCusCodeSchema.Constants.TableName, 1 },
				{ OrgContactSchema.Constants.TableName, 1 },
				{ OrgCompanyDataSchema.Constants.TableName, 1 },
				{ OrgAddressSchema.Constants.TableName, 3 },

				/*** warehouse validation related db hits ***/
				// hit from loading order in other factory
				{ WhsDocketSchema.Constants.TableName, 1 },
				// 1 from Loading Client
				{ OrgHeaderSchema.Constants.TableName, 1 },
				// Custom field validation
				{ OrgCustomLabelsSchema.Constants.TableName, 1 },
				// Loading Warehouse
				{ WhsWarehouseSchema.Constants.TableName, 1 },
				// Loading Areas in Warehouse
				{ WhsAreaSchema.Constants.TableName, 1 },
				// Loading Containers
				{ WhsDocketContainerSchema.Constants.TableName, 1 },
				// 1 hit from Order Consignee
				{ JobDocAddressSchema.Constants.TableName, 1 },
				// 1 hit from loading Lines on Order
				// 1 for loading Lines attached to Inventory
				{ WhsDocketLineSchema.Constants.TableName, 3 },
				// Loading Products
				{ OrgSupplierPartSchema.Constants.TableName, 1 },
				// Loading Client attribute info
				{ OrgMiscServSchema.Constants.TableName, 1 },
				// Loading Related Org Info
				{ OrgPartRelationSchema.Constants.TableName, 1 },
				// Loading Unit Conversions
				{ OrgPartUnitSchema.Constants.TableName, 1 },
				// 1 hit for loading Pick Lines attached to Order Lines
				// 1 hit for loading Pick Lines attached to Inventory
				{ WhsPickLineSchema.Constants.TableName, 3 },
				// 1 hit from loading Inventory attached to Divots & Inventory attached to Docket Lines
				{ WhsInventoryViewSchema.Constants.TableName, 2 },
				// Loading Locations on Inventory
				{ WhsLocationViewSchema.Constants.TableName, 2 },
				// Loading Row for Inventory Locations
				{ WhsRowSchema.Constants.TableName, 1 },
				// Due to Order totals update
				{ PkgPackageJobSchema.Constants.TableName, 1 },
				{ RefCountrySchema.Constants.TableName, 1 },
				{ RefPacksSchema.Constants.TableName, 1 },
				// Due to Offset synchronization update
				{ GlbBranchSchema.Constants.TableName, 1 },
				{ RefTimeZoneSchema.Constants.TableName, 1 },
				{ RefTimeZoneSetSchema.Constants.TableName, 1 },
				{ RefUNLOCOSchema.Constants.TableName, 1 },
			};

			AssertDbHits(expectedDBHitsForValidation, otherFactory);

			using (RowFactory.SetCachedTables())
			{
				var pick = otherFactory.New<WhsPick>();
				pick.WP_WW_Whs = data.Whs1.PK;
				pick.PickOrders(orderInOtherFactory);
			}

			var expectedDBHitsForPick = new Dictionary<string, int>(expectedDBHitsForValidation);
			// irrelevant db hits
			expectedDBHitsForPick.Add(ProcessCompanyLinkRuleSchema.Constants.TableName, 1);
			expectedDBHitsForPick.Add(ProcessTaskTemplateSchema.Constants.TableName, 2);
			expectedDBHitsForPick.Add(ProcessTaskNotificationSchema.Constants.TableName, 1);
			expectedDBHitsForPick.Add(RefPackTypeSchema.Constants.TableName, 1);
			expectedDBHitsForPick.Add(StmALogSchema.Constants.TableName, 2);
			expectedDBHitsForPick.Add(StmEventSchema.Constants.TableName, 4); // increased by LBM from 2 to 3

			/*** pick related db hits ***/
			// Allocation
			expectedDBHitsForPick.Add(WhsProductParamsByWhsAndClientSchema.Constants.TableName, 1);
			// Pick Loading its Orders
			expectedDBHitsForPick[WhsDocketSchema.Constants.TableName] += 1;
			// 1 hit from loading all Inventory for Pick
			// 1 hit for Synchronising Inventory before allocation
			expectedDBHitsForPick[WhsInventoryViewSchema.Constants.TableName] += 1;
			// loading Pick faces
			expectedDBHitsForPick.Add(WhsPickFaceSchema.Constants.TableName, 1);
			// 1 hit for loading DocketLine
			expectedDBHitsForPick[WhsDocketLineSchema.Constants.TableName] += 1;
			expectedDBHitsForPick[WhsLocationViewSchema.Constants.TableName] += 1;
			expectedDBHitsForPick.Add(ProcessTasksSchema.Constants.TableName, 2);
			// Loading Location Type for DockDoorLocation
			expectedDBHitsForPick.Add(WhsLocationTypeSchema.Constants.TableName, 1);
			// 1 hit for Docket.Workflow
			expectedDBHitsForPick[GlbBranchSchema.Constants.TableName] += 1;
			expectedDBHitsForPick.Add(GlbStaffSchema.Constants.TableName, 1);
			expectedDBHitsForPick.Add(GlbCompanySchema.Constants.TableName, 1);
			expectedDBHitsForPick.Add(JobHeaderSchema.Constants.TableName, 1);
			// 1 hit for creating new package job
			expectedDBHitsForPick[PkgPackageJobSchema.Constants.TableName] += 1;

			AssertDbHits(expectedDBHitsForPick, otherFactory);
		}

