		#region TestPickOrders_WhenAutoPick_AllocationError

		public void TestPickOrders_WhenAutoPick_AllocationError()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 50m);

			WhsPick.AutoPickEventArgs args = null;
			var pick = Factory.New<WhsPick>();
			pick.AutoPickAttempt += (sender, e) => { args = e; };

			var allocationEngineMock = new Mock<IAllocationEngineManager>();
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(It.IsAny<WhsPick>(), It.IsAny<INotifications>(), It.IsNotNull<IPickStrategy>(), It.IsAny<IEnumerable<WhsPickOrderedInventory>>()))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) => AllocationResult.ErrorOrWarning)
				.Callback((WhsPick p, INotifications n, IPickStrategy ps, IEnumerable<WhsPickOrderedInventory> poi) =>
				{
					n.AddError("Some allocation error.");
				});

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			using (Globals.SetIsUserInteractiveForTest(false))
			{
				pick.PickOrders(new WhsOrder[] { order });
			}

			AssertEquals("Error raised, StockWasAllocated should be false.", false, args.StockWasAllocated);
			AssertEquals(false, args.IsPickWaitingReplenishment);
			AssertEquals("Issue occurred during allocation: Some allocation error.", args.AutoAllocateErrorMessage.TrimEnd());
			AssertEquals(WhsPick.NoStockWarningMessage, args.Message);
			AssertEquals("No stock allocated.", 0m, order.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals(false, order.Pick.IsInDatabase);
			AssertEquals(PickStatus.Codes.Created, pick.WP_PickStatus);
		}

