		public void TestPickOrders_WhenAutoPick_CalculatesUnitsSentCorrectly_NewOrdersAdded()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 50m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 60m);
			Factory.Save();

			AssertEquals("Precondition: Product volume.", 0.02m, data.Part1.OP_Cubic);
			AssertEquals("Precondition: Product weight.", 2m, data.Part1.OP_Weight);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			Helper.CreateWhsOrderLine(order, data.Part1, 50m);
			AssertEquals("Precondition", 0m, order.WD_UnitsSent);
			AssertEquals("Precondition", 0m, order.WD_CubicSent);
			AssertEquals("Precondition", 0m, order.WD_WeightSent);

			WhsPick.AutoPickEventArgs args = null;
			var pick = Factory.New<WhsPick>();
			pick.AutoPickAttempt += (sender, e) => { args = e; };

			var pickOrdersResult1 = pick.PickOrdersWithAllocationMock(new WhsOrder[] { order });
			AssertEquals("Pick orders is successful.", true, pickOrdersResult1);
			AssertEquals("Pick " + order.Pick.WP_PickNo + " has been created.", args.Message);
			AssertEquals("Order's WD_UnitsSent is updated.", 50m, order.WD_UnitsSent);
			AssertEquals("Order's WD_CubicSent is updated.", 1m, order.WD_CubicSent);
			AssertEquals("Order's WD_WeightSent is updated.", 100m, order.WD_WeightSent);

			var newOrder = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			Helper.CreateWhsOrderLine(newOrder, data.Part1, 60m);
			AssertEquals("Precondition", 0m, newOrder.WD_UnitsSent);
			AssertEquals("Precondition", 0m, newOrder.WD_CubicSent);
			AssertEquals("Precondition", 0m, newOrder.WD_WeightSent);

			// add a new order to the pick
			pick.Orders.Add(newOrder);
			AssertEquals("Precondition", 2, pick.Orders.Count);

			var pickOrdersResult2 = pick.PickOrdersWithAllocationMock();
			AssertEquals("Pick orders is successful.", true, pickOrdersResult2);
			AssertEquals("Order's WD_UnitsSent is the same.", 50m, order.WD_UnitsSent);
			AssertEquals("Order's WD_CubicSent is the same.", 1m, order.WD_CubicSent);
			AssertEquals("Order's WD_WeightSent is the same.", 100m, order.WD_WeightSent);

			AssertEquals("New Order's WD_UnitsSent is updated.", 60m, newOrder.WD_UnitsSent);
			AssertEquals("New Order's WD_CubicSent is updated.", 1.2m, newOrder.WD_CubicSent);
			AssertEquals("New Order's WD_WeightSent is updated.", 120m, newOrder.WD_WeightSent);
		}

