		#region TestPickOrders_WhenManualPick

		public void TestPickOrders_WhenManualPick()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			data.Whs1.CreateDefaultDockDoorLocationIfNeeded_ForTest();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsPickableDocketLine(order, data.Part1, 50);

			var pick1 = Factory.New<WhsPick>();
			bool manualPickSucceededEventFired1 = false;
			pick1.ManualPickSucceeded += (s, e) => manualPickSucceededEventFired1 = true;

			order.WD_PickOption = WhsPickOption.Codes.Manual;
			pick1.PickOrdersWithAllocationMock(new WhsOrder[] { order });
			AssertEquals("Manual pick should not Auto-Allocate stock.", 0m, order.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals("Successful Manual Pick should call Factory.Save().", true, order.Pick.IsInDatabase);
			AssertEquals("Successful Manual Pick should fire event.", true, manualPickSucceededEventFired1);
			order.Pick.CancelPick(); // clean up to detach Order
			Factory.Save();

			var pick2 = Factory.New<WhsPick>();
			bool manualPickSucceededEventFired2 = false;
			pick2.ManualPickSucceeded += (s, e) => manualPickSucceededEventFired2 = true;

			order.WD_PickOption = WhsPickOption.Codes.ManualWithAutoAllocate;
			pick2.PickOrdersWithAllocationMock(new WhsOrder[] { order });
			AssertEquals("Manual pick w/Auto-Allocate should Auto-Allocate stock.", 50m, order.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals("Successful Manual Pick should call Factory.Save().", true, order.Pick.IsInDatabase);
			AssertEquals("Successful Manual Pick should fire event.", true, manualPickSucceededEventFired2);

			// manual pick with a cross dock line should allocate the cross dock line
			var pick3 = Factory.New<WhsPick>();
			bool manualPickSucceededEventFired3 = false;
			pick3.ManualPickSucceeded += (s, e) => manualPickSucceededEventFired3 = true;

