			order3.WD_PickOption = WhsPickOption.Codes.Manual;
			var orderLine3 = Helper.CreateWhsOrderLine(order3, data.Part1, 10m);
			Helper.CreateReservePickLine(orderLine3, data.Line111, 10m);
			pick3.PickOrdersWithAllocationMock(new WhsOrder[] { order3 });
			AssertEquals("Manual pick with cross dock line should Allocate stock.", 10m, order3.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals("Successful Manual Pick should call Factory.Save().", true, order3.Pick.IsInDatabase);
			AssertEquals("Successful Manual Pick should fire event.", true, manualPickSucceededEventFired3);
		}

