		#region TestPickOrders_WhenValidationError

		public void TestPickOrders_WhenValidationError()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			WhsOrder order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			WhsOrderLine line = order.Lines.AddNew();
			line.WE_TransactionQuantity = 5;

			WhsPick.DocketPickabilityEventArgs args = null;
			Pick.PickOrdersFailed += (sender, e) =>
			{
				args = e;
			};

			bool pickSuccess = Pick.PickOrders();
			AssertEquals(false, pickSuccess);
			AssertGetPickabilityResult("No Orders are attached to the Pick.", NotificationTypes.Error, false, false, args);
			AssertNull(order.Pick);

			order.WD_DocketStatus = DocketStatus.Codes.Held;
			Pick.PickOrders(new WhsOrder[] { order });
			AssertGetPickabilityResult("This Order is Held. Only Entered (Saved) Orders can be attached to a Pick.",
				NotificationTypes.Error, false, false, args);
			AssertNull(order.Pick);
			AssertEquals("Pick failed, Orders should not remain on the Pick.", 0, Pick.Orders.Count);

			Pick.Orders.Add(order);
			Pick.PickOrdersWithAllocationMock();
			AssertGetPickabilityResult("This Order is Held. Only Entered (Saved) Orders can be attached to a Pick.",
				NotificationTypes.Error, false, false, args);
			AssertEquals("Pick failed, but Order already existed on Pick and so should not be removed.", 1, Pick.Orders.Count);

			// no need to test all possible validation failures as they are tested in PickableDocket's TestGetPickability()
		}

		void AssertGetPickabilityResult(ZString expectedMsg, NotificationTypes expectedMsgType, bool expectedPickability,
			bool expectedPickExists,
			WhsPick.DocketPickabilityEventArgs args)
		{
			AssertEquals(expectedMsg, args.Message);
			AssertEquals(expectedMsgType, args.MessageType);
			AssertEquals(expectedPickability, args.IsDocketPickable);
			AssertEquals(expectedPickExists, args.PickAlreadyExists);
		}

