		#region TestPickOrders_WeightSentAndVolumeHasErrors

		public void TestPickOrders_WeightSentAndVolumeHasErrors()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var partWithExcessiveWeight = data.Part1;
			var partWithExcessiveVolume = data.Part2;
			var partWithExcessiveWeightAndVolume = Helper.CreateProduct(data.Org1, "P3");
			var partWithProperWeightAndVolume = Helper.CreateProduct(data.Org1, "P4");

			Helper.SetProductWeightAndVolume(partWithExcessiveWeight, 999999.99m, Constants.Weight.Kilograms, 0.2m,
				Constants.Volume.CubicMetres);
			Helper.SetProductWeightAndVolume(partWithExcessiveVolume, 99.0m, Constants.Weight.Kilograms, 999999.99m,
				Constants.Volume.CubicMetres);
			Helper.SetProductWeightAndVolume(partWithExcessiveWeightAndVolume, 999999.99m, Constants.Weight.Kilograms,
				999999.99m, Constants.Volume.CubicMetres);
			Helper.SetProductWeightAndVolume(partWithProperWeightAndVolume, 9.0m, Constants.Weight.Kilograms, 9.0m,
				Constants.Volume.CubicMetres);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, partWithExcessiveWeight, 15m);
			Helper.CreateWhsReceiveInventoryLine(receive, partWithExcessiveVolume, 15m);
			Helper.CreateWhsReceiveInventoryLine(receive, partWithExcessiveWeightAndVolume, 15m);
			Helper.CreateWhsReceiveInventoryLine(receive, partWithProperWeightAndVolume, 15m);
			receive.WD_TotalWeight = 1m; // Hack to save receive to DB so that it won't exceed the DB limit
			receive.WD_TotalCubic = 1m;
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var orderWithErrors = Helper.CreateWhsOrder(data.Org1, data.Whs1, "TestOrder1");
			Helper.CreateWhsOrderLine(orderWithErrors, partWithExcessiveWeight, 15m);
			Helper.CreateWhsOrderLine(orderWithErrors, partWithExcessiveVolume, 5m);
			Helper.CreateWhsOrderLine(orderWithErrors, partWithExcessiveWeightAndVolume, 15m);
			Helper.CreateWhsOrderLine(orderWithErrors, partWithProperWeightAndVolume, 5m);
			AssertEquals("There should be two notification for excess weight and volume.", 2,
				orderWithErrors.Notifications.Count());
			AssertCollectionContains(
				"Error - WD_TotalCubic: The number 20,000,047.80 is too large, the maximum value allowed for Volume is 999,999.999.",
				orderWithErrors.Notifications.Select(n => n.Message));
			AssertCollectionContains(
				"Error - WD_TotalWeight: The number 30,000,539.70 is too large, the maximum value allowed for Weight is 999,999.999.",
				orderWithErrors.Notifications.Select(n => n.Message));

			var anotherOrderWithErrors = Helper.CreateWhsOrder(data.Org1, data.Whs1, "TestOrder2");
			Helper.CreateWhsOrderLine(anotherOrderWithErrors, partWithExcessiveVolume, 3m);

			// pick both orders
			WhsPick.DocketPickabilityEventArgs args = null;
			var pick = Factory.New<WhsPick>();
			pick.PickOrdersFailed += (sender, e) => { args = e; };
			pick.PickOrdersWithAllocationMock(new WhsPickableDocket[] { orderWithErrors, anotherOrderWithErrors });
			AssertEquals(@"Please check your order lines. One or multiple products have excessive Weight / Volume.
To fix the Weight / Volume go to Maintain > Warehouse > Products and amend the gross Weight / Volume for these products.",
				args.Message.ToString());

			var orderWithErrorsOtherthanExcessiveWeightOrVolume = Helper.CreateWhsOrder(data.Org1, data.Whs1, "TestOrder3");
			orderWithErrorsOtherthanExcessiveWeightOrVolume.WD_RequiredDate = ZDateTimeOffset.Empty; // Hack to introduce an error
			Helper.CreateWhsOrderLine(orderWithErrorsOtherthanExcessiveWeightOrVolume, partWithProperWeightAndVolume, 6m);

			WhsPick.DocketPickabilityEventArgs argsWithErrors = null;
			var pick2 = Factory.New<WhsPick>();
			pick2.PickOrdersFailed += (sender, e) => { argsWithErrors = e; };
			pick2.PickOrders(new WhsOrder[] { orderWithErrorsOtherthanExcessiveWeightOrVolume });
			AssertEquals("This Order has no Required By Date.", argsWithErrors.Message);

			var manualPickWithAutoAllocateWithErrors = Helper.CreateWhsOrder(data.Org1, data.Whs1, "TestOrder4");
			Helper.CreateWhsOrderLine(manualPickWithAutoAllocateWithErrors, partWithExcessiveVolume, 3m);
			Helper.CreateWhsOrderLine(manualPickWithAutoAllocateWithErrors, partWithExcessiveWeight, 15m);
			manualPickWithAutoAllocateWithErrors.WD_PickOption = WhsPickOption.Codes.ManualWithAutoAllocate;

			WhsPick.DocketPickabilityEventArgs argsManual = null;
			var pick3 = Factory.New<WhsPick>();
			pick3.PickOrdersFailed += (sender, e) => { argsManual = e; };
			pick3.PickOrdersWithAllocationMock(new WhsOrder[] { manualPickWithAutoAllocateWithErrors });
			AssertEquals(@"Please check your order lines. One or multiple products have excessive Weight / Volume.
To fix the Weight / Volume go to Maintain > Warehouse > Products and amend the gross Weight / Volume for these products.",
				argsManual.Message.ToString());
		}

