		#region TestPickOrders_WithWorkOrderDisassembly

		/// <summary>
		/// Parts below the top level should be put away, as long as the top level can be Disassembled (flag on the Product)
		/// </summary>
		public void TestPickOrders_WithWorkOrderDisassembly()
		{
			var data = new TestDataForBOM(Factory);
			data.CreateBOMProductsInInventory(); // 100 bikes
			data.CreateBOMComponentsInInventory(); // 10 engines + 20 wheels
			data.BOM.BikeWheel.OP_CanDisassembleKit = false; // don't let the Wheels be disassembled
			Factory.Save();

			// create disassembly for 2 bikes, 2 wheels and 2 engines (unrelated to each other)
			WhsWorkOrder workOrder = Helper.CreateWhsWorkOrder(data.Org1, data.Whs1);
			WhsWorkOrderLine bikeLine = Helper.CreateWhsWorkOrderLine(workOrder, data.BOM.Bike, 2m);
			WhsWorkOrderLine wheelLine = Helper.CreateWhsWorkOrderLine(workOrder, data.BOM.BikeWheel, 2m);
			WhsWorkOrderLine engineLine = Helper.CreateWhsWorkOrderLine(workOrder, data.BOM.BikeEngine, 2m);
			workOrder.WD_DocketSubType = WorkOrderType.Codes.Disassemble;
			workOrder.WD_AutoFinaliseBOMIntoInventory = true;

			// setup BOM staging areas for all products so that we can auto-finalise the WorkOrder's Receive
			WhsLocation bomStagingLocation = data.Whs1.Areas[0].PickLocations[0];
			WhsProductParamsByWhsAndClient bikeProductParams = bikeLine.Product.ParamsByWhsAndClient.AddNew();
			WhsProductParamsByWhsAndClient wheelProductParams = wheelLine.Product.ParamsByWhsAndClient.AddNew();
			WhsProductParamsByWhsAndClient engineProductParams = engineLine.Product.ParamsByWhsAndClient.AddNew();
			bikeProductParams.W3_WW = data.Whs1.PK;
			wheelProductParams.W3_WW = data.Whs1.PK;
			engineProductParams.W3_WW = data.Whs1.PK;
			bikeProductParams.W3_WL_StagingLocationBOM = bomStagingLocation.PK;
			wheelProductParams.W3_WL_StagingLocationBOM = bomStagingLocation.PK;
			engineProductParams.W3_WL_StagingLocationBOM = bomStagingLocation.PK;

			// pick the Work Order
			Pick.PickOrdersWithAllocationMock(workOrder);
			AssertEquals("Precondition - Pick failed.", true, workOrder.IsAttachedToPickButNotFinalised);

			// check stock levels before we disassemble / putaway the components
			AssertEquals("Precondition - 2 Bikes should have been picked for disassembly.", 98m,
				data.BOM.InventoryQueries.Bike.UnitsAvailable);
			AssertEquals("Precondition - 2 Engines should have been picked for disassembly.", 8m,
				data.BOM.InventoryQueries.BikeEngine.UnitsAvailable);
			AssertEquals("Precondition - Wheels cannot be disassembled, should not have picked any.", 20m,
				data.BOM.InventoryQueries.BikeWheel.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.WheelRim.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.WheelTyre.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.EngineBlock.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.EnginePiston.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.PistonHead.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.PistonCrank.UnitsAvailable);
			AssertEquals("Precondition", 0m, data.BOM.InventoryQueries.PistonRing.UnitsAvailable);

			// finalise the WorkOrder which auto-creates and finalises the receive (placing stock into inventory)
			workOrder.FinaliseDocketAlwaysFinalisingPick();
			AssertIsFinalisedPrecondition(workOrder);
			AssertIsFinalisedPrecondition(workOrder.Receive);

			data.BOM.InventoryQueries.ReloadAll();

			// Bike Line -- stock placed back into inventory
			AssertEquals("2 x Engines should be placed back into Inventory.", 8m + 2m,
				data.BOM.InventoryQueries.BikeEngine.UnitsAvailable);
			AssertEquals("4 x Wheels should be placed back into Inventory.", 20m + 4m,
				data.BOM.InventoryQueries.BikeWheel.UnitsAvailable);
			AssertEquals("The Bike should not have been placed into Inventory (it should have been disassembled).", 98m + 0m,
				data.BOM.InventoryQueries.Bike.UnitsAvailable);

			// Engine Line -- stock placed back into inventory
			AssertEquals("2 x Engine Blocks should be placed back into Inventory.", 0m + 2m,
				data.BOM.InventoryQueries.EngineBlock.UnitsAvailable);
			AssertEquals("8 x Engine Pistons should be placed back into Inventory.", 0m + 8m,
				data.BOM.InventoryQueries.EnginePiston.UnitsAvailable);
			AssertEquals("Engine Pistons should not have been disassembled.", 0m,
				data.BOM.InventoryQueries.PistonHead.UnitsAvailable);
			AssertEquals("Engine Pistons should not have been disassembled.", 0m,
				data.BOM.InventoryQueries.PistonCrank.UnitsAvailable);
			AssertEquals("Engine Pistons should not have been disassembled.", 0m,
				data.BOM.InventoryQueries.PistonRing.UnitsAvailable);

			// Wheel Line - stock not placed back into inventory (because parent part(s) cannot be disassembled)
			AssertEquals("The Wheels cannot be disassembled and thus rims should not have been placed back into Inventory.", 0m,
				data.BOM.InventoryQueries.WheelRim.UnitsAvailable);
			AssertEquals("The Wheels cannot be disassembled and thus tyres should not have been placed back into Inventory.", 0m,
				data.BOM.InventoryQueries.WheelTyre.UnitsAvailable);
		}

