		void TestPickOrders_BOM_NotEnoughKitAvailableToPick_NoOrderedAttributes_ComponentOrderLinesCreated(ZString pickOption, bool shouldCreateComponentLines)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 2);
			Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, PartAttributeTypeList.Codes.BatchNumber);
			Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, data.Part2, AttributeNumber.One, true);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			var receiveLine = Helper.CreateWhsReceiveLine(receive, data.Part2, 100m);
			var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part1, 5m);
			receiveLine.WE_PartAttrib1 = "1";
			receiveLine2.WE_PartAttrib1 = "1";
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Helper.CreateProductBOM(data.Part1, data.Part2);
			data.Part1.OP_IsComponentPickedOnSalesOrder = true;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Factory.Save();

			AssertEquals("Precondition", 2, order.Lines.Count);
			var pick = Helper.CreatePickNew(pickOption, new[] { order });
			pick.PickOrdersWithAllocationMock(); // Mock rules with FIFO, we are testing the higher level BOM parts

			if (shouldCreateComponentLines)
			{
				AssertEquals(3, order.Lines.Count);
				AssertEquals(2, order.Pick.OrderedInventories.Count);
				var orderedInventory1 = order.Pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(oi => oi.ProductCode == data.Part1.OP_PartNum);
				var orderedInventory2 = order.Pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(oi => oi.ProductCode == data.Part2.OP_PartNum);
				AssertEquals(10m, orderedInventory1.PickLineQuantity);
				AssertEquals(5m, orderedInventory2.PickLineQuantity);
			}
			else
			{
				AssertEquals(0m, order.Pick.OrderedInventories[0].PickLineQuantity);
				AssertEquals(2, order.Lines.Count);
				AssertEquals(1, order.Pick.OrderedInventories.Count);
			}
		}

		public void TestPickOrders_BOM_NotEnoughKitAvailableToPick_NoOrderedAttributes_ComponentOrderLinesCreated_NotEnoughComponentsToSatisfyShortfall()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 2);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			Helper.CreateWhsReceiveLine(receive, data.Part2, 12m);
			Helper.CreateWhsReceiveLine(receive, data.Part1, 5m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Helper.CreateProductBOM(data.Part1, data.Part2);
			data.Part1.OP_IsComponentPickedOnSalesOrder = true;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Factory.Save();

			AssertEquals("Precondition", 3, order.Lines.Count);
			var pick = Helper.CreatePickNew(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals(5, order.Lines.Count);
			AssertEquals(2, pick.OrderedInventories.Count);
			AssertEquals(10m, order.Lines[3].WE_TransactionQuantity);
			AssertEquals(2m, order.Lines[4].WE_TransactionQuantity);
			AssertEquals(data.Part2.PK, order.Lines[3].WE_OP);
			AssertEquals(data.Part2.PK, order.Lines[4].WE_OP);
			AssertEquals("5 plus 12 from assembly.", 17m, pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals(12m, pick.OrderedInventories[1].PickLineQuantity);
			AssertEquals(data.Part1.PK, pick.OrderedInventories[0].SupplierPartPK);
			AssertEquals(data.Part2.PK, pick.OrderedInventories[1].SupplierPartPK);
		}

