		void TestPickOrders_BOM_NotEnoughKitAvailableToPick_OrderedAttributes_ComponentOrderLinesNotCreated(Action<WhsDocketLine> setDocketLineAttribute, AttributeNumber? attributeNumber)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 2);
			if (attributeNumber.HasValue)
			{
				Helper.SetClientAllAttributeType(data.Org1, false);
				Helper.SetClientAttributeType(data.Org1, attributeNumber.Value, true);
				Helper.SetProductAttributeUse(data.Org1, data.Part1, attributeNumber.Value, true);
				Helper.SetProductAttributeUse(data.Org1, data.Part2, attributeNumber.Value, true);
			}

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			var receiveLine = Helper.CreateWhsReceiveLine(receive, data.Part2, attributeNumber == AttributeNumber.Serial ? 1m : 100m);
			var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part1, attributeNumber == AttributeNumber.Serial ? 1m : 5m);
			setDocketLineAttribute(receiveLine);
			setDocketLineAttribute(receiveLine2);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Helper.CreateProductBOM(data.Part1, data.Part2);
			data.Part1.OP_IsComponentPickedOnSalesOrder = true;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, attributeNumber == AttributeNumber.Serial ? 1m : 5m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, attributeNumber == AttributeNumber.Serial ? 1m : 5m);
			setDocketLineAttribute(orderLine2);
			Factory.Save();

			AssertEquals("Precondition", 2, order.Lines.Count);
			var pick = Helper.CreatePickNew(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals("Component order line created to satisfy shortfall on orderLine2", 3, order.Lines.Count);
			AssertEquals(3, order.Pick.OrderedInventories.Count);
			AssertEquals(attributeNumber == AttributeNumber.Serial ? 1m : 5m, order.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals(attributeNumber == AttributeNumber.Serial ? 1m : 5m, order.Pick.OrderedInventories[1].PickLineQuantity);
			AssertEquals(attributeNumber == AttributeNumber.Serial ? 1m : 5m, order.Pick.OrderedInventories[2].PickLineQuantity);
			AssertEquals(data.Part1.OP_PartNum, order.Pick.OrderedInventories[0].ProductCode);
			AssertEquals(data.Part1.OP_PartNum, order.Pick.OrderedInventories[1].ProductCode);
			AssertEquals(data.Part2.OP_PartNum, order.Pick.OrderedInventories[2].ProductCode);
		}

