			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals("Component order line created to satisfy shortfall on orderLine1; no component line created for shortfall on orderLine2/orderLine3.", 4, order.Lines.Count);
			AssertEquals(3, order.Pick.OrderedInventories.Count);
			AssertEquals(5m, order.Pick.OrderedInventories[0].PickLineQuantity);
			AssertEquals(5m, order.Pick.OrderedInventories[1].PickLineQuantity);
