		public void TestPickOrders_BOM_NotEnoughKitAvailableToPick_MultipleKits()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var kit2 = Helper.CreateProduct("KIT2", data.Org1);
			var component2 = Helper.CreateProduct("COMP2", data.Org1);
			Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, PartAttributeTypeList.Codes.BatchNumber);
			Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, data.Part2, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, kit2, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, component2, AttributeNumber.One, true);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			var receiveLine1 = Helper.CreateWhsReceiveLine(receive, data.Part1, 5m);
			var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part2, 100m);
			var receiveLine3 = Helper.CreateWhsReceiveLine(receive, kit2, 5m);
			var receiveLine4 = Helper.CreateWhsReceiveLine(receive, component2, 100m);
			receiveLine1.WE_PartAttrib1 = "1";
			receiveLine2.WE_PartAttrib1 = "1";
			receiveLine3.WE_PartAttrib1 = "1";
			receiveLine4.WE_PartAttrib1 = "1";
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Helper.CreateProductBOM(data.Part1, data.Part2);
			Helper.CreateProductBOM(kit2, component2);
			data.Part1.OP_IsComponentPickedOnSalesOrder = true;
			kit2.OP_IsComponentPickedOnSalesOrder = true;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var orderLine3 = Helper.CreateWhsOrderLine(order, kit2, 5m);
			var orderLine4 = Helper.CreateWhsOrderLine(order, kit2, 5m);
			orderLine1.WE_PartAttrib1 = "1";
			Factory.Save();

			AssertEquals("Precondition", 4, order.Lines.Count);
			var pick = Helper.CreatePickNew(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts

			var pickLineQtyPart1WithAttrib = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Where(o => o.ProductCode == data.Part1.OP_PartNum && o.PartAttrib1 == "1").Select(o => (int)o.PickLineQuantity).Sum();
			var pickLineQtyPart1NoAttrib = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Where(o => o.ProductCode == data.Part1.OP_PartNum && o.PartAttrib1.IsEmpty).Select(o => (int)o.PickLineQuantity).Sum();
			var pickLineQtyPart2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Where(o => o.ProductCode == data.Part2.OP_PartNum).Select(o => (int)o.PickLineQuantity).Sum();
			var pickLineQtyKit2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Where(o => o.ProductCode == kit2.OP_PartNum).Select(o => (int)o.PickLineQuantity).Sum();
			var pickLineQtyComponent2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Where(o => o.ProductCode == component2.OP_PartNum).Select(o => (int)o.PickLineQuantity).Sum();

			AssertEquals("2 new component lines should be created to satisfy shortfall in orderLine2 and orderLine4", 6, order.Lines.Count);
			AssertEquals(5, pick.OrderedInventories.Count);
			AssertEquals(5, pickLineQtyPart1WithAttrib);
			AssertEquals(5, pickLineQtyPart1NoAttrib);
			AssertEquals(5, pickLineQtyPart2);
			AssertEquals("Including the assembled Kit Pick Line which has empty attribute.", 10, pickLineQtyKit2);
			AssertEquals(5, pickLineQtyComponent2);
		}

