		#region TestPickOrders_BOM_ComplexAttributeCombinations

		[GuiTest]
		public void TestPickOrders_BOM_ComplexAttributeCombinations()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.SetClientAllAttributeType(data.Org1, false);
			Helper.SetProductAllAttributeUse(data.Org1, data.Part1, true);
			Helper.SetProductAllAttributeUse(data.Org1, data.Part2, true);
			Factory.Save();

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			var expiryDate = new ZDate(DateTime.Now.Year + 20, 1, 1);
			var packingDate = new ZDate(DateTime.Now.Year + 3, 1, 1);
			var receiveLineAllAttributes = CreateReceiveLineWithAttributes(receive, data.Part1, 10m, "1", "2", "3", expiryDate, packingDate, "KEY");
			var receiveLine5Attributes = CreateReceiveLineWithAttributes(receive, data.Part1, 10m, "1", ZString.Empty, "3", expiryDate, packingDate, "KEY");
			var receiveLine4Attributes = CreateReceiveLineWithAttributes(receive, data.Part1, 10m, ZString.Empty, ZString.Empty, "3", expiryDate, packingDate, "KEY");
			var receiveLine3Attributes = CreateReceiveLineWithAttributes(receive, data.Part1, 10m, ZString.Empty, ZString.Empty, ZString.Empty, expiryDate, packingDate, "KEY");
			var receiveLine2Attributes = CreateReceiveLineWithAttributes(receive, data.Part1, 30m, ZString.Empty, ZString.Empty, ZString.Empty, expiryDate, packingDate, ZString.Empty);
			var receiveLineComponentProduct = CreateReceiveLineWithAttributes(receive, data.Part2, 500m, ZString.Empty, ZString.Empty, ZString.Empty, expiryDate, packingDate, ZString.Empty);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			Helper.CreateProductBOM(data.Part1, data.Part2);
			data.Part1.OP_IsComponentPickedOnSalesOrder = true;
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLineAllAttributes = CreateOrderLineWithAttributes(order, data.Part1, 10m, "1", "2", "3", expiryDate, packingDate, "KEY");
			var orderLine4Attributes1 = CreateOrderLineWithAttributes(order, data.Part1, 10m, "1", ZString.Empty, ZString.Empty, expiryDate, packingDate, "KEY"); // Going to component assembly; seems non-deterministic
			var orderLine4Attributes2 = CreateOrderLineWithAttributes(order, data.Part1, 10m, ZString.Empty, ZString.Empty, "3", expiryDate, packingDate, "KEY"); // Picking from receiveLine5Attributes instead of receiveLine4Attributes
			var orderLine3Attributes = CreateOrderLineWithAttributes(order, data.Part1, 10m, ZString.Empty, ZString.Empty, ZString.Empty, expiryDate, packingDate, "KEY");
			var orderLine2Attributes = CreateOrderLineWithAttributes(order, data.Part1, 10m, ZString.Empty, ZString.Empty, ZString.Empty, expiryDate, packingDate, ZString.Empty);
			var orderLine1Attribute = CreateOrderLineWithAttributes(order, data.Part1, 10m, ZString.Empty, ZString.Empty, ZString.Empty, ZDate.Empty, packingDate, ZString.Empty);
			var orderLine0Attributes = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			Factory.Save();

			AssertEquals("Precondition", 7, order.Lines.Count);
			var pick = Helper.CreatePickNew(new[] { order });
			pick.PickOrders();
			AssertEquals("New component order line created to satisfy shortfall on orderLine0Attributes", 8, order.Lines.Count);
			AssertEquals(receiveLineAllAttributes.PK, orderLineAllAttributes.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine5Attributes.PK, orderLine4Attributes1.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine4Attributes.PK, orderLine4Attributes2.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine3Attributes.PK, orderLine3Attributes.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine2Attributes.PK, orderLine2Attributes.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine2Attributes.PK, orderLine1Attribute.PickLines.Single().InventoryLine.PK);
			AssertEquals(receiveLine2Attributes.PK, orderLine0Attributes.PickLines[0].InventoryLine.PK);
			AssertEquals(receiveLineComponentProduct.PK, order.Lines[7].PickLines[0].InventoryLine.PK);
		}

		WhsReceiveLine CreateReceiveLineWithAttributes(WhsReceive receive, OrgSupplierPart part, ZDecimal qty, ZString attrib1, ZString attrib2, ZString attrib3, ZDate expiryDate, ZDate packingDate, ZString bondedEntryKey)
		{
			var receiveLine = Helper.CreateWhsReceiveLine(receive, part, qty);
			receiveLine.WE_PartAttrib1 = attrib1;
			receiveLine.WE_PartAttrib2 = attrib2;
			receiveLine.WE_PartAttrib3 = attrib3;
			receiveLine.WE_ExpiryDate = expiryDate;
			receiveLine.WE_PackingDate = packingDate;
			receiveLine.WE_BondedEntryKey = bondedEntryKey;
			return receiveLine;
		}

		WhsOrderLine CreateOrderLineWithAttributes(WhsOrder order, OrgSupplierPart part, ZDecimal qty, ZString attrib1, ZString attrib2, ZString attrib3, ZDate expiryDate, ZDate packingDate, ZString bondedEntryKey)
		{
			var orderLine = Helper.CreateWhsOrderLine(order, part, qty);
			orderLine.WE_PartAttrib1 = attrib1;
			orderLine.WE_PartAttrib2 = attrib2;
			orderLine.WE_PartAttrib3 = attrib3;
			orderLine.WE_ExpiryDate = expiryDate;
			orderLine.WE_PackingDate = packingDate;
			orderLine.WE_BondedEntryKey = bondedEntryKey;
			return orderLine;
		}

