		#region TestPickOrders_ConcurrencyErrorOnWhsPickLine

		[TestDate(2014, 1, 1)]
		public void TestPickOrders_ConcurrencyErrorOnWhsPickLine_OnSave() // Issue 00922914
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventory = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 100m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pickLine = Helper.CreateReservePickLine(orderLine, inventory, 10m);
			Factory.Save();

			Factory.Saving += delegate
			{
				var anotherFactory = new BusinessObjectFactory() { RefreshEnabled = false };
				var pickLineInAnotherFactory = anotherFactory.Load<WhsPickLine>(pickLine.PK);
				pickLineInAnotherFactory.WZ_Units = 9m;
				anotherFactory.Save();
			};

			AssertEquals("Precondition - WhsPickLine is same as before in the first factory.", 10m, pickLine.WZ_Units);

			// this will cause a concurrency exception
			pickLine.WZ_GS_NKAssignedTo = "E";

			bool attemptedToPick = false;
			var pick = Factory.New<WhsPick>();
			pick.SaveFailureEvent += (sender, e) =>
			{
				attemptedToPick = true;
				AssertEquals("Message should be correct.",
					@"While you have been working with this form, another user has made changes.

The system cannot automatically merge your changes because there are conflicts with critical fields.
Please cancel your changes and reload the form.

The following objects have critical changes and cannot be merged:
Warehouse Order W00000002 (CargoWise Support @ 01 Jan 2014 00:00:00)
	Volume Sent
	Docket Status
	Units Sent
	Weight Sent
	Net Weight
	Field used by system (Critical change)
WhsPickLine (CargoWise Support @ 01 Jan 2014 00:00:00)
	Field used by system
	Units To Pick (Critical change)
", e.Message);
			};
			AssertNoExceptionThrown(() => pick.PickOrdersWithAllocationMock(new[] { order }));
			AssertEquals("Should have attempted to pick the order.", true, attemptedToPick);
		}

