		#region TestPickOrders_OverCommitTriggerErrorOnSave

		public void TestPickOrders_OverCommitTriggerErrorOnSave()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventory = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 100m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var reservedPickLine = orderLine.ReserveStockIfAbleTo(inventory);
			AssertEquals("Precondition: Stock is reserved.", 10m, reservedPickLine.ReservedQuantity);

			Factory.Saving += delegate
			{
				var otherFactory = new BusinessObjectFactory { RefreshEnabled = false };
				var helperInOtherFactory = new WhsTestHelperFunctions(otherFactory);
				var orderInOtherFactory =
					helperInOtherFactory.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 95m);
				helperInOtherFactory.CreatePickNew_WithoutAllocationEngineMock(orderInOtherFactory);
			};

			bool attemptedToPick = false;
			var pick = Factory.New<WhsPick>();
			pick.SaveFailureEvent += (sender, e) =>
			{
				attemptedToPick = true;
				AssertEquals("Message should be correct.",
					"Another user has taken some of the stock that you have tried to allocate.\r\nClose and re-open the form, then reallocate stock.",
					e.Message);
			};

			// Pick Orders does a Factory.Save()
			AssertNoExceptionThrown(() => pick.PickOrdersWithAllocationMock(order));
			AssertEquals("Should have attempted to pick the order.", true, attemptedToPick);
		}

