		#region TestPickOrders_CallsAllocatePackageLabels_AfterAllocatingStockAndSuccesfullySaving

		public void TestPickOrders_CallsAllocatePackageLabels_AfterAllocatingStockAndSuccesfullySaving()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "Order Ref #1");
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;

			var succesfullyAutoPickedEventHit = false;
			pick.AutoPickAttempt += (s, e) => succesfullyAutoPickedEventHit = e.StockWasAllocated;

			var assertionHit = false;
			var allocatePackagesMock = new Mock<IAllocatePackageLabelsStrategy>();
			allocatePackagesMock.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			allocatePackagesMock.Setup(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(() =>
			{
				assertionHit = true;
				AssertEquals("Should have tried to cartonise after allocating stock and saving", false, pick.HasChanges);
				AssertEquals("Should have tried to cartonise after allocating stock and saving", true,
					succesfullyAutoPickedEventHit);
				return CartonisationResult.Cartonised;
			});
			allocatePackagesMock.Setup(m => m.PickCasesByLabel(It.IsAny<WhsPick>())).Returns(true);
			allocatePackagesMock.Setup(m => m.PickPalletsByLabel(It.IsAny<WhsPick>())).Returns(true);

			pick.SetAllocatePackageLabelsStrategyForTest(allocatePackagesMock.Object);
			pick.PickOrdersWithAllocationMock();
			allocatePackagesMock.VerifyAll();
			AssertEquals(true, assertionHit);
		}

		#endregion

		#region TestPickOrders_DoesntCallAllocatePackageLabels_WhenAwaitingReplenishment

		public void TestPickOrders_DoesntCallAllocatePackageLabels_WhenAwaitingReplenishment()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var transferLine = Helper.CreateWhsTransferLine(transfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			transferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, transfer.IsFinalised);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.WP_PickPalletsByLabel = true;

			var allocatePackagesMock = new Mock<IAllocatePackageLabelsStrategy>();
			allocatePackagesMock.Setup(s => s.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			allocatePackagesMock.Setup(s => s.CartoniseSplitCases(It.IsAny<WhsPick>(), false)).Returns(CartonisationResult.Cartonised);
			allocatePackagesMock.Setup(s => s.PickPalletsByLabel(It.IsAny<WhsPick>())).Returns(true);
			allocatePackagesMock.Setup(s => s.PickCasesByLabel(It.IsAny<WhsPick>())).Returns(true);

			pick.SetAllocatePackageLabelsStrategyForTest(allocatePackagesMock.Object);
			pick.PickOrdersWithAllocationMock(order);
			AssertEquals(true, pick.WP_IsAwaitingReplenishment);

			allocatePackagesMock.Verify(s => s.RunChecksPriorToCartonisingOrPickingByLabel(pick, It.IsAny<bool>()), Times.Never());
			allocatePackagesMock.Verify(s => s.CartoniseSplitCases(pick, false), Times.Never());
			allocatePackagesMock.Verify(s => s.PickPalletsByLabel(pick), Times.Never());
			allocatePackagesMock.Verify(s => s.PickCasesByLabel(pick), Times.Never());
		}

		#endregion

