		#region TestPickOrders_DoesntCallAllocatePackageLabels_IfSaveFails

		public void TestPickOrders_DoesntCallAllocatePackageLabels_IfSaveFails()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "Order Ref #1");
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;

			var succesfullyAutoPickedEventHit = false;
			pick.AutoPickAttempt += (s, e) => succesfullyAutoPickedEventHit = e.StockWasAllocated;

			var hitSaving = false;
			var allocatePackagesMock = new Mock<IAllocatePackageLabelsStrategy>();
			pick.SetAllocatePackageLabelsStrategyForTest(allocatePackagesMock.Object);

			Factory.Saving += f =>
			{
				hitSaving = true;
				throw new ZCannotSaveException("Trigger Failed", "Or something like that", ExceptionType.BusinessFailure);
			};

			pick.PickOrdersWithAllocationMock();
			allocatePackagesMock.Verify(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>()), Times.Never());
			allocatePackagesMock.Verify(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>()), Times.Never());
			AssertEquals(true, hitSaving);
			AssertEquals(false, pick.WP_IsCartonised);
			AssertEquals(false, pick.IsCartonising);
		}

