		public void TestPickingAllPickLines_DBHits()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.EnableWarehouseForBond(data.Whs1, true);

			for (int index = 0; index < 10; index++)
			{
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R" + index, data.Part1, 1m, $"BEK-{index + 1}");
