			var orders = new List<WhsOrder>();

			for (int index = 0; index < 10; index++)
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + index, data.Part1, 1m);
				order.WD_DocketSubType = OrderType.Codes.Customs;
				order.Lines[0].WE_BondedEntryKey = $"BEK-{index + 1}";
				order.Lines[0].CustomsData.WB_EntryKey = "BEK";
				order.Lines[0].CustomsData.WB_EntryLineNo = (ZShort)index + 1;
				orders.Add(order);
