				var component = Helper.CreateProduct("Component" + index, data.Org1);
				Helper.CreateProductBOM(kit, component);
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R" + index, component, 1m);
			}

			Factory.Save();

			var workOrders = new List<WhsWorkOrder>(1);
			var order = Helper.CreateWhsWorkOrder(data.Org1, data.Whs1);
			for (int index = 0; index < 10; index++)
			{
				Helper.CreateWhsWorkOrderLine(order, kits[index], 1m);
			}
			workOrders.Add(order);

			var pick = Helper.CreatePickNew(workOrders.ToArray());
			var newFactory = new BusinessObjectFactory();
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);

			using (RowFactory.SetCachedTables())
			{
				foreach (var pickLine in pickInNewFactory.GetAllPickLines())
				{
					pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
				}

				newFactory.Save();
			}

			var locationTypeHits = newFactory.GetTableHitCount(WhsLocationTypeSchema.Constants.TableName);
			var locationViewHits = newFactory.GetTableHitCount(WhsLocationViewSchema.Constants.TableName);
			var glbStaffHits = newFactory.GetTableHitCount(GlbStaffSchema.Constants.TableName);
			var glbBranchHits = newFactory.GetTableHitCount(GlbBranchSchema.Constants.TableName);

			var expectedDbHits = new Dictionary<string, int>
			{
				{ GlbStaffSchema.Constants.TableName, glbStaffHits },
				{ GlbBranchSchema.Constants.TableName, glbBranchHits },
