		#region TestAutoAllocate_WithSortThenClear

		public void TestAutoAllocate_WithSortThenClear()
		{
			TestAutoAllocate_WithSortThenClear_Core(shouldAddFetchHints: true);
		}

		public void TestAutoAllocate_NoFetchHints_WithSortThenClear()
		{
			TestAutoAllocate_WithSortThenClear_Core(shouldAddFetchHints: false);
		}

		void TestAutoAllocate_WithSortThenClear_Core(bool shouldAddFetchHints)
		{
			var data = new TestDataForInventory(Factory);
			data.CreateMultiWarehouseClientProductInventory(TestDataForInventory.StockType.WithoutBondEntryKeys);

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			var order2 = Helper.CreateWhsOrder(data.Org2, data.Whs1, "1");
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 1m);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part2, 2m);
			var orderLine3 = Helper.CreateWhsOrderLine(order2, data.Part2, 3m);
			orderLine3.WE_PartAttrib1 = "PA1";

			Pick.Orders.Add(order1);
			Pick.Orders.Add(order2);

			// undo the sort done when orders are attached and OrderedInventories are created
			Pick.OrderedInventories.Sort("QuantityOrdered", ListSortDirection.Ascending);

			var orderedInventory1 = Pick.OrderedInventories[0];
			var orderedInventory2 = Pick.OrderedInventories[1];
			var orderedInventory3 = Pick.OrderedInventories[2];

			Pick.AutoAllocateItemsWithMock(shouldAddFetchHints: shouldAddFetchHints);

			AssertEquals("Items should now be sorted", orderedInventory3, Pick.OrderedInventories[0]);
			AssertEquals("Items should now be sorted", orderedInventory1, Pick.OrderedInventories[1]);
			AssertEquals("Items should now be sorted", orderedInventory2, Pick.OrderedInventories[2]);

			AssertEquals("Items should now be allocated", 1m, orderedInventory1.PickLineQuantity);
			AssertEquals("Items should now be allocated", 2m, orderedInventory2.PickLineQuantity);
			AssertEquals("Items should now be allocated", 3m, orderedInventory3.PickLineQuantity);

			Pick.ClearAllocatedItems();

			AssertEquals("Allocations should now be cleared", 0m, orderedInventory1.PickLineQuantity);
			AssertEquals("Allocations should now be cleared", 0m, orderedInventory2.PickLineQuantity);
			AssertEquals("Allocations should now be cleared", 0m, orderedInventory3.PickLineQuantity);
		}

		[GuiTest]
		public void TestAutoAllocate_WhenUsingPickByUom()
		{
			// Arrange

			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			data.Whs1.WW_IsPickByUOMEnabled = true;

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);

			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 16m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine21 = Helper.CreateWhsOrderLine(order2, data.Part1, 32m);
			var orderLine22 = Helper.CreateWhsOrderLine(order2, data.Part1, 14m);
			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3");
			var orderLine3 = Helper.CreateWhsOrderLine(order3, data.Part1, 4m);
			var order4 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O4");
			var orderLine41 = Helper.CreateWhsOrderLine(order4, data.Part1, 6m);
			var orderLine42 = Helper.CreateWhsOrderLine(order4, data.Part1, 2m);
			Pick.Orders.AddRange(new[] { order1, order2, order3, order4 });

			// Act

			var result = Pick.AutoAllocateItems();

			// Assert
			AssertEquals(string.Empty, result);

			var pickLines = Pick
				.GetAllPickLines()
				.ToArray();
			var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(Pick);
			AssertEquals("Expecting 74 UNT for picking", 74m, totalPickLineQuantity);
			AssertEquals("Expecting 8 pick lines", 8, pickLines.Length);

			var pickLinesForOrder1 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine1.PK)
				.ToArray();

			AssertEquals("Expecting 2 pick lines for order 1", 2, pickLinesForOrder1.Length);
			AssertEquals("Expecting 12 UNT (CTN) pick line for order 1", 1,
				pickLinesForOrder1.Count(pickLine => pickLine.WZ_Units == 12m && pickLine.WZ_F3_NKAllocatedPackType == "CTN"));
			AssertEquals("Expecting 4 UNT pick line for order 1", 1,
				pickLinesForOrder1.Count(pickLine => pickLine.WZ_Units == 4m && pickLine.WZ_F3_NKAllocatedPackType == "UNT"));

			var pickLinesForOrder21 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine21.PK)
				.ToArray();

			AssertEquals("Expecting 1 pick lines for order 2 line 1", 1, pickLinesForOrder21.Length);
			AssertEquals("Expecting 32 UNT (CTN) pick line for order 2 line 1", 1,
				pickLinesForOrder21.Count(pickLine => pickLine.WZ_Units == 32m && pickLine.WZ_F3_NKAllocatedPackType == "CTN"));

			var pickLinesForOrder22 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine22.PK)
				.ToArray();

			AssertEquals("Expecting 2 pick lines for order 2 line 2", 2, pickLinesForOrder22.Length);
			AssertEquals("Expecting 4 UNT (CTN) pick line for order 2 line 2", 1,
				pickLinesForOrder22.Count(pickLine => pickLine.WZ_Units == 4m && pickLine.WZ_F3_NKAllocatedPackType == "CTN"));
			AssertEquals("Expecting 10 UNT pick line for order 2 line 2", 1,
				pickLinesForOrder22.Count(pickLine => pickLine.WZ_Units == 10m && pickLine.WZ_F3_NKAllocatedPackType == "UNT"));

			var pickLinesForOrder3 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine3.PK)
				.ToArray();

			AssertEquals("Expecting 1 pick line for order 3", 1, pickLinesForOrder3.Length);
			AssertEquals("Expecting 4 UNT pick line for order 3", 1,
				pickLinesForOrder3.Count(pickLine => pickLine.WZ_Units == 4m && pickLine.WZ_F3_NKAllocatedPackType == "UNT"));

			var pickLinesForOrder41 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine41.PK)
				.ToArray();

			AssertEquals("Expecting 1 pick line for order 4 line 1", 1, pickLinesForOrder41.Length);
			AssertEquals("Expecting 6 UNT pick line for order 4 line 1", 1,
				pickLinesForOrder41.Count(pickLine => pickLine.WZ_Units == 6m && pickLine.WZ_F3_NKAllocatedPackType == "UNT"));

			var pickLinesForOrder42 = pickLines
				.Where(pickLine => pickLine.WZ_WE_TransactionLine == orderLine42.PK)
				.ToArray();

			AssertEquals("Expecting 1 pick line for order 4 line 2", 1, pickLinesForOrder42.Length);
			AssertEquals("Expecting 2 UNT pick line for order 4 line 2", 1,
				pickLinesForOrder42.Count(pickLine => pickLine.WZ_Units == 2m && pickLine.WZ_F3_NKAllocatedPackType == "UNT"));
		}

