			pick.AutoAllocateItemsWithMock();
			newFactory.Save();

			order = newFactory.Load<WhsOrder>(order.PK);
			orderLine = newFactory.Load<WhsOrderLine>(orderLine.PK);
			AssertEquals(0m, orderLine.WE_ShortfallQuantityCached);
			AssertEquals("Still has one component line.", 1, orderLine.ChildComponentLines.Count);
			AssertEquals("A new Pick Line created.", 2, orderLine.ChildComponentLines.First().PickLines.Count);
			var receives = newFactory.Load<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Still has one receive.", 1, receives.Length);
