			AssertEquals("Only allocated 8 wheels.", 8m, orderLine1.ChildComponentLines.First().PickLines[0].WZ_Units);
			AssertEquals(6m, orderLine1.WE_ShortfallQuantityCached);

			AssertEquals("Added component orderline should exist.", 1, orderLine2.ChildComponentLines.Count);
			AssertEquals("Should be allocated.", 1, orderLine2.ChildComponentLines.First().PickLines.Count);
			AssertEquals("Only allocated 3 components.", 3m, orderLine2.ChildComponentLines.First().PickLines[0].WZ_Units);
			AssertEquals(9m, orderLine2.WE_ShortfallQuantityCached);

			var createdReceive = Factory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertCreatedReceive(createdReceive, order1);

			var createdReceiveLine1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == bike.PK);
			AssertCreatedReceiveLine(createdReceiveLine1, bike, 4m);
			var createdPickLines1 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine1.PK));
			AssertEquals("Should be committed to relevant Order Line through PickLine.", 1, createdPickLines1.Length);
