			AssertCreatedPickLine(relatedPickLine1, createdReceiveLine1, orderLine1, 4m);
			AssertEquals("Links created.", 1, createdReceiveLine1.BOMComponentLinks.Count());
			var link1 = createdReceiveLine1.BOMComponentLinks.First();
			AssertCreatedLink(link1, createdReceiveLine1, (WhsOrderLine)order1.AllLines.Single(l => l.WE_OP == wheel.PK), 8m);

			var createdReceiveLine2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == kit2.PK);
			AssertCreatedReceiveLine(createdReceiveLine2, kit2, 1m);
			var createdPickLines2 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine2.PK));
			AssertEquals("Should be committed to relevant Order Line through PickLine.", 1, createdPickLines1.Length);
			var relatedPickLine2 = createdPickLines2[0];
			AssertCreatedPickLine(relatedPickLine2, createdReceiveLine2, orderLine2, 1m);
			AssertEquals("Links created.", 1, createdReceiveLine2.BOMComponentLinks.Count());
			var link2 = createdReceiveLine2.BOMComponentLinks.First();
			AssertCreatedLink(link2, createdReceiveLine2, (WhsOrderLine)order2.AllLines.Single(l => l.WE_OP == component2.PK), 3m);

			var receive2 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R2");
			Helper.CreateWhsReceiveInventoryLine(receive2, wheel, 12m, data.Whs1.FindLocation("A-1"));
			receive2.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive2);
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			pick = newFactory.Load<WhsPick>(pick.PK);
			pick.AutoAllocateItemsWithMock();
			newFactory.Save();

			order1 = newFactory.Load<WhsOrder>(order1.PK);
			order2 = newFactory.Load<WhsOrder>(order2.PK);
			orderLine1 = newFactory.Load<WhsOrderLine>(orderLine1.PK);
			orderLine2 = newFactory.Load<WhsOrderLine>(orderLine2.PK);
			AssertEquals(0m, orderLine1.WE_ShortfallQuantityCached);
			AssertEquals("Still has one component line.", 1, orderLine1.ChildComponentLines.Count);
			AssertEquals("A new Pick Line created.", 2, orderLine1.ChildComponentLines.First().PickLines.Count);
			var receives = newFactory.Load<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Still has one receive.", 1, receives.Length);
			createdReceive = receives[0];
			AssertCreatedReceive(createdReceive, order1);
			AssertEquals("Still has two receive lines.", 2, createdReceive.Lines.Count);

			// bike has been allocated more stocks
			createdReceiveLine1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == bike.PK);
			AssertCreatedReceiveLine(createdReceiveLine1, bike, 10m);
			createdPickLines1 = newFactory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine1.PK));
			AssertEquals("A new Pick Line created.", 2, createdPickLines1.Length);
			var bikePickLine1 = createdPickLines1.Single(pl => pl.WZ_Units == 4m);
			var bikePickLine2 = createdPickLines1.Single(pl => pl.WZ_Units == 6m);
			AssertCreatedPickLine(bikePickLine1, createdReceiveLine1, orderLine1, 4m);
			AssertCreatedPickLine(bikePickLine2, createdReceiveLine1, orderLine1, 6m);
			AssertEquals(1, createdReceiveLine1.BOMComponentLinks.Count());
			link1 = createdReceiveLine1.BOMComponentLinks.First();
			AssertCreatedLink(link1, createdReceiveLine1, (WhsOrderLine)order1.AllLines.Single(l => l.WE_OP == wheel.PK), 20m);

			// kit2 remains the same
			createdReceiveLine2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == kit2.PK);
			AssertCreatedReceiveLine(createdReceiveLine2, kit2, 1m);
			createdPickLines2 = newFactory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine2.PK));
			AssertEquals("Nothing more allocated.", 1, createdPickLines2.Length);
			var kit2PickLine = createdPickLines2.Single();
			AssertCreatedPickLine(kit2PickLine, createdReceiveLine2, orderLine2, 1m);
			AssertEquals(1, createdReceiveLine2.BOMComponentLinks.Count());
			link2 = createdReceiveLine2.BOMComponentLinks.First();
			AssertCreatedLink(link2, createdReceiveLine2, (WhsOrderLine)order2.AllLines.Single(l => l.WE_OP == component2.PK), 3m);
		}

