			AssertCreatedLink(link2, createdReceiveLine2, (WhsOrderLine)order.AllLines.Single(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 40m), 40m);
			AssertCreatedLink(link3, createdReceiveLine3, (WhsOrderLine)order.AllLines.Single(l => l.WE_OP == component.PK), 20m);
		}

