			var orderLine1 = Helper.CreateWhsOrderLine(order1, bike, 2m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", pickOption: WhsPickOption.Codes.Manual);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, kit, 3m);
			var order3 = Helper.CreateWhsOrder(org2, data.Whs1, "O3", pickOption: WhsPickOption.Codes.Manual);
			var orderLine3 = Helper.CreateWhsOrderLine(order3, kit2, 4m);

			pick.AddOrders(new[] { order1, order2, order3 });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			Factory.Save();
			AssertEquals("Added component orderline should exist.", 1, orderLine1.ChildComponentLines.Count);
			AssertEquals("Added component orderline should exist.", 1, orderLine2.ChildComponentLines.Count);
			AssertEquals("Added component orderline should exist.", 2, orderLine3.ChildComponentLines.Count);
			AssertEquals("Should be allocated.", 1, orderLine1.ChildComponentLines.First().PickLines.Count);
			AssertEquals("Should be allocated.", 1, orderLine2.ChildComponentLines.First().PickLines.Count);
			var componentLines_orderLine3 = orderLine3.ChildComponentLines.ToArray();
			AssertEquals("Should be allocated.", 1, componentLines_orderLine3[0].PickLines.Count);
			AssertEquals("Should be allocated.", 1, componentLines_orderLine3[1].PickLines.Count);

			var createdReceives = Factory.Load<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals(2, createdReceives.Length);
			var createdReceive1 = createdReceives.Single(r => r.WD_OH_Client == data.Org1.PK);
			AssertCreatedReceive(createdReceive1, order1);
			var createdReceiveLine1 = createdReceive1.Lines.Cast<WhsReceiveLine>().Single(l => l.WE_OP == bike.PK);
			AssertCreatedReceiveLine(createdReceiveLine1, bike, 2m);
			var createdPickLines1 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine1.PK));
			AssertEquals("Should be committed to relevant Order Line through PickLine.", 1, createdPickLines1.Length);
			var relatedPickLine1 = createdPickLines1[0];
			AssertCreatedPickLine(relatedPickLine1, createdReceiveLine1, orderLine1, 2m);
			AssertEquals("Links created.", 1, createdReceiveLine1.BOMComponentLinks.Count());
			var link1 = createdReceiveLine1.BOMComponentLinks.First();
			AssertCreatedLink(link1, createdReceiveLine1, (WhsOrderLine)order1.AllLines.Single(l => l.WE_OP == wheel.PK), 4m);

			var createdReceiveLine2 = createdReceive1.Lines.Cast<WhsReceiveLine>().Single(l => l.WE_OP == kit.PK);
			AssertCreatedReceiveLine(createdReceiveLine2, kit, 3m);
			var createdPickLines2 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine2.PK));
			AssertEquals("Should be committed to relevant Order Line through PickLine.", 1, createdPickLines2.Length);
			var relatedPickLine2 = createdPickLines2[0];
			AssertCreatedPickLine(relatedPickLine2, createdReceiveLine2, orderLine2, 3m);
			AssertEquals("Links created.", 1, createdReceiveLine2.BOMComponentLinks.Count());
			var link2 = createdReceiveLine2.BOMComponentLinks.First();
			AssertCreatedLink(link2, createdReceiveLine2, (WhsOrderLine)order2.AllLines.Single(l => l.WE_OP == component.PK), 6m);

			var createdReceive2 = createdReceives.Single(r => r.WD_OH_Client == org2.PK);
			AssertCreatedReceive(createdReceive2, order3);
			var createdReceiveLine3 = createdReceive2.Lines[0];
			AssertCreatedReceiveLine(createdReceiveLine3, kit2, 4m);
			var createdPickLines3 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine3.PK));
			AssertEquals("Should be committed to relevant Order Line through PickLine.", 1, createdPickLines3.Length);
			var relatedPickLine3 = createdPickLines3[0];
			AssertCreatedPickLine(relatedPickLine3, createdReceiveLine3, orderLine3, 4m);
			AssertEquals("Links created.", 2, createdReceiveLine3.BOMComponentLinks.Count());
			var componentOrderLine3 = (WhsOrderLine)order3.AllLines.Single(l => l.WE_OP == component2.PK);
			var componentOrderLine4 = (WhsOrderLine)order3.AllLines.Single(l => l.WE_OP == component3.PK);
			var link3 = createdReceiveLine3.BOMComponentLinks.Single(l => l.WIP_WE_ComponentLine == componentOrderLine3.PK);
			var link4 = createdReceiveLine3.BOMComponentLinks.Single(l => l.WIP_WE_ComponentLine == componentOrderLine4.PK);
			AssertCreatedLink(link3, createdReceiveLine3, componentOrderLine3, 8m);
			AssertCreatedLink(link4, createdReceiveLine3, componentOrderLine4, 8m);
		}

