		public void TestAutoAllocateItems_PickByBom_StockExpired()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(bike, frame, 1m, Constants.PkgUnit.Unit);

			Helper.SetClientAttributeType(data.Org1, AttributeNumber.ExpiryDate, true);
			Helper.SetProductAttributeUse(data.Org1, frame, AttributeNumber.ExpiryDate, true);
			Factory.Save();

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, frame, 10m, ZDate.Today.AddDays(10), ZDate.Empty, "", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, frame, 5m, ZDate.Today.AddDays(-85), ZDate.Empty, "", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, wheel, 30m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine = Helper.CreateWhsOrderLine(order, bike, 15m);

			var pick = (WhsPick)GetNewBusinessObject();
			pick.Orders.AddRange(new[] { order });
			Factory.Save();

			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals("Added component orderlines should exist.", 2, orderLine.ChildComponentLines.Count);
			var wheelOrderLine = order.Lines.Single(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 30m);
			var frameOrderLine = order.Lines.Cast<WhsOrderLine>().Single(l => l.WE_OP == frame.PK && l.WE_TransactionQuantity == 15m);
			AssertEquals("frameOrderLine should be under allocated.", 10m, frameOrderLine.PickLineQuantity);
			if (frameOrderLine.PickLines.Count > 0)
			{
				frameOrderLine.PickLines.Single().Delete();
			}
			Factory.Save();

			var receive2 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R2");
			Helper.CreateWhsReceiveInventoryLine(receive2, frame, 10m, ZDate.Today.AddDays(10), ZDate.Empty, "", "", "", "");
			receive2.AllocateLocationsWithMock();
			receive2.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive2 should be finalised.", true, receive2.IsFinalised);
			Factory.Save();

			pick.ClearInventoryCache();
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals("2 component orderline should exist.", 2, orderLine.ChildComponentLines.Count);
			var wheelLineAfterReAllocation = orderLine.ChildComponentLines.Cast<WhsOrderLine>().SingleOrDefault(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 30m);
			AssertEquals("Correct Wheel component orderline should exist.", true, wheelLineAfterReAllocation != null);
			AssertEquals("Correct Wheel component orderline should be allocated.", 30m, wheelLineAfterReAllocation.PickLineQuantity);

			var frameLineAfterReAllocation = orderLine.ChildComponentLines.Cast<WhsOrderLine>().SingleOrDefault(l => l.WE_OP == frame.PK && l.WE_TransactionQuantity == 15m);
			AssertEquals("Correct Frame component orderline should exist.", true, frameLineAfterReAllocation != null);
			AssertEquals("Correct Frame component orderline should be allocated.", 15m, frameLineAfterReAllocation.PickLineQuantity);
		}

