			AssertEquals("Receive3 should be finalised.", true, receive3.IsFinalised);
			Factory.Save();

			pick.ClearInventoryCache();
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			AssertEquals("2 component orderline should exist.", 2, orderLine.ChildComponentLines.Count);
			AssertEquals("Correct Wheel component orderline should exist.", true, orderLine.ChildComponentLines.SingleOrDefault(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 70m) != null);
			AssertEquals("Correct Frame component orderline should exist.", true, orderLine.ChildComponentLines.SingleOrDefault(l => l.WE_OP == frame.PK && l.WE_TransactionQuantity == 35m) != null);

			var receive4 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R4");
