		#region TestAutoAllocateItems_RunsShortfallValidation

		[GuiTest]
		public void TestAutoAllocateItems_RunsShortfallValidation()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 9m);
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 9m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_IsAwaitingReplenishment = true;
			AssertEquals("Precondition.", 10m, orderLine1.WE_ShortfallQuantityCached);
			AssertEquals("Precondition.", 10m, orderLine2.WE_ShortfallQuantityCached);

			pick.AutoAllocateItems();
			AssertEquals("Should have updated pick status.", PickStatus.Codes.Created, pick.WP_PickStatus);
			AssertEquals("Should have cleared shortfall quantity cached.", 1m, orderLine1.WE_ShortfallQuantityCached);
			AssertEquals("Should have cleared shortfall quantity cached.", 1m, orderLine2.WE_ShortfallQuantityCached);
			AssertHasWarning("Should have re-run Shortfall validation.", orderLine1.WE_ShortfallQuantityCachedInfo, "Shortfall: Only 9 unit(s) have been selected for release");
			AssertHasWarning("Should have re-run Shortfall validation.", orderLine2.WE_ShortfallQuantityCachedInfo, "Shortfall: Only 9 unit(s) have been selected for release");
			AssertHasWarning("Should have re-run Shortfall validation.", order.WD_TotalUnitsInfo, "One or more Order Lines are in Shortfall.");

			var receive3 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", data.Part1, 5m);
			var receive4 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", data.Part2, 5m);
			Factory.Save();

			var factory2 = new BusinessObjectFactory();
			var pickInNewFactory = factory2.Load<WhsPick>(pick.PK);
			var orderInNewFactory = factory2.Load<WhsOrder>(order.PK);
			var orderLine1InNewFactory = factory2.Load<WhsOrderLine>(orderLine1.PK);
			var orderLine2InNewFactory = factory2.Load<WhsOrderLine>(orderLine2.PK);

			orderInNewFactory.RunPreSaveValidation();
			AssertEquals("Precondition.", 1m, orderLine1InNewFactory.WE_ShortfallQuantityCached);
			AssertEquals("Precondition.", 1m, orderLine2InNewFactory.WE_ShortfallQuantityCached);
			AssertHasWarning("Precondition.", orderLine1InNewFactory.WE_ShortfallQuantityCachedInfo, "Shortfall: Only 9 unit(s) have been selected for release");
			AssertHasWarning("Precondition.", orderLine2InNewFactory.WE_ShortfallQuantityCachedInfo, "Shortfall: Only 9 unit(s) have been selected for release");
			AssertHasWarning("Precondition.", orderInNewFactory.WD_TotalUnitsInfo, "One or more Order Lines are in Shortfall.");

			pickInNewFactory.AutoAllocateItems();
			AssertEquals("Should have cleared shortfall quantity cached.", 0m, orderLine1InNewFactory.WE_ShortfallQuantityCached);
			AssertEquals("Should have cleared shortfall quantity cached.", 0m, orderLine2InNewFactory.WE_ShortfallQuantityCached);
			AssertNoWarnings("Should have re-run Shortfall validation.", orderLine1InNewFactory.WE_ShortfallQuantityCachedInfo);
			AssertNoWarnings("Should have re-run Shortfall validation.", orderLine2InNewFactory.WE_ShortfallQuantityCachedInfo);
			AssertNoWarning("Should have re-run Shortfall validation.", orderInNewFactory.WD_TotalUnitsInfo, "One or more Order Lines are in Shortfall.");
		}

