		#region TestAutoAllocateItems_AllocationRulesEnabled

		public void TestAutoAllocateItems_AllocationRulesEnabled() => TestAutoAllocateItems_AllocationRulesEnabled(passInNotifications: false);

		public void TestAutoAllocateItems_AllocationRulesEnabled_NotificationsPassedIn() => TestAutoAllocateItems_AllocationRulesEnabled(passInNotifications: true);

		void TestAutoAllocateItems_AllocationRulesEnabled(bool passInNotifications)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_IsAwaitingReplenishment = true;
			var availInv = pick.OrderedInventories[0].AvailableInventories[0];

			IPickStrategy pickStrategy = null;

			var notifications = passInNotifications ? new Mock<INotifications>(MockBehavior.Strict).Object : pick.NotificationSubscriber;
			var allocationEngineMock = new Mock<IAllocationEngineManager>(MockBehavior.Strict);
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(
						It.Is<WhsPick>(p => p == pick),
						It.Is<INotifications>(n => n == notifications),
						It.IsNotNull<IPickStrategy>(),
						It.Is<IEnumerable<WhsPickOrderedInventory>>(ordInv => pick.OrderedInventories.Cast<WhsPickOrderedInventory>().All(i => ordInv.Contains(i)))))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) =>
				{
					AssertEquals("Should have set auto allocating items semaphore.", true, pick.IsAutoAllocatingItemsSemaphore.IsSuspended);

					AssertEquals("Precondition.", 10m, ps.GetAutoAllocateQuantity(10m, availInv));
					receive1.Inventory[0].WI_TotalUnits = 3m;
					AssertEquals("UnPicked quantity should be cached.", 10m, ps.GetAutoAllocateQuantity(10m, availInv));
					pickStrategy = ps;

					return AllocationResult.AllocatedStock;
				})
				.Verifiable();

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			{
				if (!passInNotifications)
				{
					pick.AutoAllocateItems();
				}
				else
				{
					pick.AutoAllocateItems(notifications);
				}
			}

			allocationEngineMock.VerifyAll();
			AssertEquals("Should have un-set auto allocating items semaphore.", false, pick.IsAutoAllocatingItemsSemaphore.IsSuspended);
			AssertEquals("Should have un-set shortfall semaphore.", false, order.IsCalculatingShortfallForAllLinesSemaphore.IsSuspended);
			AssertEquals("Should have updated pick status.", PickStatus.Codes.Created, pick.WP_PickStatus);
			AssertEquals("UnPicked quantity should no longer be cached.", 3m, pickStrategy.GetAutoAllocateQuantity(10m, availInv));
		}

		public void TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies() => TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies(usWarehouse: false, bondedWarehouse: false);
		public void TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies_US() => TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies(usWarehouse: true, bondedWarehouse: false);
		public void TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies_Bonded() => TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies(usWarehouse: false, bondedWarehouse: false);
		public void TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies_USBonded() => TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies(usWarehouse: true, bondedWarehouse: true);

		void TestAutoAllocateItems_AllocationRulesEnabled_PickStrategies(bool usWarehouse, bool bondedWarehouse)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			if (usWarehouse)
			{
				data.Whs1.WarehouseAddress.OA_RL_NKRelatedPortCode = "USLAX";
			}

			if (bondedWarehouse)
			{
				Helper.EnableWarehouseForBond(data.Whs1, true);
			}

			Factory.Save();

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			var availInv = pick.OrderedInventories[0].AvailableInventories[0];

			var pickStrategies = new List<IPickStrategy>();

			var allocationEngineMock = new Mock<IAllocationEngineManager>(MockBehavior.Strict);
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(
						It.Is<WhsPick>(p => p == pick),
						It.Is<INotifications>(n => n == pick.NotificationSubscriber),
						It.IsNotNull<IPickStrategy>(),
						It.Is<IEnumerable<WhsPickOrderedInventory>>(ordInv => pick.OrderedInventories.Cast<WhsPickOrderedInventory>().All(i => ordInv.Contains(i)))))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) =>
				{
					AssertType(usWarehouse && bondedWarehouse ? typeof(PickStrategyUS) : typeof(PickStrategy), ps);
					AssertNotEquals("Should use new pick strategy.", pick.CurrentPickStrategy, ps);
					pickStrategies.Add(ps);
					return AllocationResult.AllocatedStock;
				})
				.Verifiable();

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			{
				pick.AutoAllocateItems();
				pick.AutoAllocateItems();
			}

			AssertEquals("Precondition: Two pick strategies used.", 2, pickStrategies.Count);
			AssertNotEquals("Should have created and consumed a new pick strategy.", pickStrategies[0], pickStrategies[1]);
			allocationEngineMock.VerifyAll();
		}

		public void TestAutoAllocateItems_AllocationRulesEnabled_WaitingReplenishment_None() => TestAutoAllocateItems_AllocationRulesEnabled_WaitingReplenishment(WhsOrderFulfillmentRuleList.Codes.None);

		public void TestAutoAllocateItems_AllocationRulesEnabled_WaitingReplenishment_All() => TestAutoAllocateItems_AllocationRulesEnabled_WaitingReplenishment(WhsOrderFulfillmentRuleList.Codes.All);

		void TestAutoAllocateItems_AllocationRulesEnabled_WaitingReplenishment(string fulfillmentRule)
		{
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", ZDateTimeOffset.Today.AddDays(-1), data.Part1, 3m, pickFaceLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", ZDateTimeOffset.Today.AddDays(-4), data.Part1, 3m, bulkLocation, "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
			order.WD_WhsOrderFulfillmentRule = fulfillmentRule;
			Helper.CreateWhsOrderLine(order, data.Part1, 6m);

			var pick = Helper.CreatePickNew(order);
			var availInv = pick.OrderedInventories[0].AvailableInventories[0];

			var allocationEngineMock = new Mock<IAllocationEngineManager>(MockBehavior.Strict);
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(
						It.Is<WhsPick>(p => p == pick),
						It.Is<INotifications>(n => n == pick.NotificationSubscriber),
						It.IsNotNull<IPickStrategy>(),
						It.Is<IEnumerable<WhsPickOrderedInventory>>(ordInv => pick.OrderedInventories.Cast<WhsPickOrderedInventory>().All(i => ordInv.Contains(i)))))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) =>
				{
					AssertEquals("Should have set is auto allocating items semaphore.", true, pick.IsAutoAllocatingItemsSemaphore.IsSuspended);
					AssertType<PickStrategy>(ps);
					return AllocationResult.AllocatedStock;
				})
				.Verifiable();

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			{
				pick.AutoAllocateItems();
			}

			allocationEngineMock.VerifyAll();
			AssertEquals("Pick should be waiting for replenishment.", true, pick.WP_IsAwaitingReplenishment);
			if (fulfillmentRule == WhsOrderFulfillmentRuleList.Codes.All)
			{
				AssertEquals("Pick status should be BIL.", PickStatus.Codes.Building, pick.WP_PickStatus);
			}
			else
			{
				AssertEquals("Pick status should be NEW.", PickStatus.Codes.Created, pick.WP_PickStatus);
			}
		}

