		#region TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter

		public void TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter() => TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter(passesInNotifications: false);

		public void TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter_PassesInNotifications() => TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter(passesInNotifications: true);

		void TestAutoAllocateItems_AllocationRulesEnabled_WithDateFilter(bool passesInNotifications)
		{
			var lastYear = ZDateTime.Now.Year - 1;

			var data = new TestDataSimpleEnvironment(Factory);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", new ZDateTimeOffset(lastYear, 01, 01), data.Part1, 12m);
			receive1.WD_FinalisedDate = new ZDateTimeOffset(lastYear, 01, 01);

			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", new ZDateTimeOffset(lastYear, 03, 03), data.Part1, 18m);
			receive2.WD_FinalisedDate = new ZDateTimeOffset(lastYear, 03, 03);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 20);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var anotherFactory = new BusinessObjectFactory();
			var loadedPick = anotherFactory.Load<WhsPick>(pick.PK);

			var notifications = passesInNotifications ? new Mock<INotifications>(MockBehavior.Strict).Object : loadedPick.NotificationSubscriber;
			var allocationEngineMock = new Mock<IAllocationEngineManager>(MockBehavior.Strict);
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(
						It.Is<WhsPick>(p => p == loadedPick),
						It.Is<INotifications>(n => n == notifications),
						It.IsNotNull<IPickStrategy>(),
						It.Is<IEnumerable<WhsPickOrderedInventory>>(ordInv => loadedPick.OrderedInventories.Cast<WhsPickOrderedInventory>().All(i => ordInv.Contains(i)))))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) =>
				{
					// should only contain the inventory before the date we filtered by
					AssertContainsExactElementsInAnyOrder(new[] { receive1.Inventory[0].PK }, loadedPick.AllInventories.Select(i => i.PK));

					var inventoryViaAvailInv = loadedPick
						.OrderedInventories
						.Cast<WhsPickOrderedInventory>()
						.SelectMany(oi => oi.AvailableInventories)
						.Cast<WhsPickAvailableInventory>()
						.SelectMany(ai => ai.Inventory)
						.Cast<WhsInventoryView>()
						.Select(i => i.PK);
					AssertContainsExactElementsInAnyOrder(new[] { receive1.Inventory[0].PK }, inventoryViaAvailInv);
					return AllocationResult.AllocatedStock;
				})
				.Verifiable();

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			{
				if (!passesInNotifications)
				{
					loadedPick.AutoAllocateItems(new ZDateTime(lastYear, 02, 02).ToLocalBranchTimeOffset());
				}
				else
				{
					loadedPick.AutoAllocateItems(new ZDateTime(lastYear, 02, 02).ToLocalBranchTimeOffset(), notifications: notifications);
				}
			}

			allocationEngineMock.VerifyAll();
		}

		#endregion

		#region TestAutoAllocateItems_AllocationRulesEnabled_PickByBOM

		public void TestAutoAllocateItems_AllocationRulesEnabled_PickByBOM()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;

			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, wheel, 70m, data.Whs1.FindLocation("A-1"));
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption: WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, bike, 2m);

			var pick = Helper.CreatePickNew(order);
			Factory.Save();
			AssertEquals("Precondition: Component orderlines should *not* exist.", false, orderLine.ChildComponentLines.Count > 0);

			var hitCount = 0;

			var allocationEngineMock = new Mock<IAllocationEngineManager>(MockBehavior.Strict);
			allocationEngineMock.
				Setup(ae =>
					ae.Allocate(
						It.Is<WhsPick>(p => p == pick),
						It.Is<INotifications>(n => n == pick.NotificationSubscriber),
						It.IsNotNull<IPickStrategy>(),
						It.Is<IEnumerable<WhsPickOrderedInventory>>(ordInv => pick.OrderedInventories.Cast<WhsPickOrderedInventory>().All(i => ordInv.Contains(i)))))
				.Returns<WhsPick, INotifications, IPickStrategy, IEnumerable<WhsPickOrderedInventory>>((p, n, ps, ordInv) =>
				{
					if (hitCount == 0)
					{
						AssertEquals("Component orderlines should *not* exist.", false, orderLine.ChildComponentLines.Count > 0);
					}
					else
					{
						AssertEquals("Component orderline should exist.", 1, orderLine.ChildComponentLines.Count);

						var wheelOrderedInv = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(oi => oi.SupplierPartPK == wheel.PK);
						AssertEquals("Should have made ordered inv for the component.", 4m, wheelOrderedInv.QuantityOrdered);
						AssertEquals("Should have made available inv for the component.", true, wheelOrderedInv.AvailableInventories[0].AvailableForAllocationAlgorithm);
						AssertEquals("Should have made available inv for the component.", 70m, wheelOrderedInv.AvailableInventories[0].QuantityUnPicked);
					}

					hitCount++;
					return AllocationResult.AllocatedStock;
				})
				.Verifiable();

			using (ObjectFactory.Substitute(allocationEngineMock.Object))
			{
				pick.AutoAllocateItems();
			}

			AssertEquals("Should have hit AllocateItems twice.", 2, hitCount);
			allocationEngineMock.VerifyAll();
		}

