		#region TestSortItemsForManualPicking

		public void TestSortItemsForManualPicking()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.SetClientAttributeType(data.Org1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, data.Part1, AttributeNumber.One, true);
			Helper.SetProductAttributeUse(data.Org1, data.Part2, AttributeNumber.One, true);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventory1 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, ZDate.Empty, ZDate.Empty, "SN:1", "", "", "");
			var inventory2 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, ZDate.Empty, ZDate.Empty, "SN:2", "", "", "");
			var inventory3 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, ZDate.Empty, ZDate.Empty, "SN:3", "", "", "");
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 1m, ZDate.Empty, ZDate.Empty, "PA1", "", "", "");

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order, data.Part2, 5m);
			var pick = Helper.CreatePickNew(order);

			Factory.Save();

			var otherFactory = new BusinessObjectFactory();
			var reloadedPick = otherFactory.Load<WhsPick>(order.Pick.PK);

			// Get data to check sorting
			var orderedInventory1 = reloadedPick.OrderedInventories[0];
			var orderedInventory2 = reloadedPick.OrderedInventories[1];

			var availableInventory1 = reloadedPick.OrderedInventories[0].AvailableInventories[0]; //PartAttrib1 = "SN:1"
			var availableInventory2 = reloadedPick.OrderedInventories[0].AvailableInventories[1]; //PartAttrib1 = "SN:2"
			var availableInventory3 = reloadedPick.OrderedInventories[0].AvailableInventories[2]; //PartAttrib1 = "SN:3"

			// mess order of OrderedInventories to see if sorting is working
			reloadedPick.OrderedInventories.Sort("ProductCode", ListSortDirection.Descending);
			AssertEquals("Precondition: Elements are sorted differently.", orderedInventory2,
				reloadedPick.OrderedInventories[0]);
			AssertEquals("Precondition: Elements are sorted differently.", orderedInventory1,
				reloadedPick.OrderedInventories[1]);

			orderedInventory1.AvailableInventories.RemoveAll();
			orderedInventory1.AvailableInventories.Add(availableInventory3);
			orderedInventory1.AvailableInventories.Add(availableInventory1);
			orderedInventory1.AvailableInventories.Add(availableInventory2);

			reloadedPick.SortItemsForManualPicking();
			AssertEquals("OrderedInventories should have been sorted", orderedInventory1, reloadedPick.OrderedInventories[0]);
			AssertEquals("OrderedInventories should have been sorted", orderedInventory2, reloadedPick.OrderedInventories[1]);

			AssertEquals("PickLinesAvailable should have been sorted by PartAttrib1", availableInventory1,
				reloadedPick.OrderedInventories[0].AvailableInventories[0]);
			AssertEquals("PickLinesAvailable should have been sorted by PartAttrib1", availableInventory2,
				reloadedPick.OrderedInventories[0].AvailableInventories[1]);
			AssertEquals("PickLinesAvailable should have been sorted by PartAttrib1", availableInventory3,
				reloadedPick.OrderedInventories[0].AvailableInventories[2]);

			data.Org1.MiscServ.OM_IMPartAttrib1Type = PartAttributeTypeList.Codes.VIN;
			Factory.Save();
			// mess order of lines to see if sorting is working
			reloadedPick.OrderedInventories.Sort("ProductCode", ListSortDirection.Descending);
			AssertEquals("Precondition: Elements are sorted differently.", orderedInventory2,
				reloadedPick.OrderedInventories[0]);
			AssertEquals("Precondition: Elements are sorted differently.", orderedInventory1,
				reloadedPick.OrderedInventories[1]);

			orderedInventory1.AvailableInventories.RemoveAll();
			orderedInventory1.AvailableInventories.Add(availableInventory3);
			orderedInventory1.AvailableInventories.Add(availableInventory1);
			orderedInventory1.AvailableInventories.Add(availableInventory2);

			// hack to prevent sorting by part attribute 1
			availableInventory1.Inventory[0].WI_PartAttrib1 = "";
			availableInventory2.Inventory[0].WI_PartAttrib1 = "";
			availableInventory3.Inventory[0].WI_PartAttrib1 = "";
			reloadedPick.SortItemsForManualPicking();
			AssertEquals("OrderedInventories should have been sorted", orderedInventory1, reloadedPick.OrderedInventories[0]);
			AssertEquals("OrderedInventories should have been sorted", orderedInventory2, reloadedPick.OrderedInventories[1]);

			AssertEquals("PickLinesAvailable shouldn't have been sorted", availableInventory3,
				reloadedPick.OrderedInventories[0].AvailableInventories[0]);
			AssertEquals("PickLinesAvailable shouldn't have been sorted", availableInventory1,
				reloadedPick.OrderedInventories[0].AvailableInventories[1]);
			AssertEquals("PickLinesAvailable shouldn't have been sorted", availableInventory2,
				reloadedPick.OrderedInventories[0].AvailableInventories[2]);
		}

