		#region TestCancelPick

		public void TestCancelPick_CancelPick()
		{
			TestCancelPickCore((pick) => pick.CancelPick());
		}

		public void TestCancelPick_CancelCancellablePick()
		{
			TestCancelPickCore((pick) => pick.CancelCancellablePick());
		}

		public void TestCancelPickCore(Func<WhsPick, bool> cancelPick)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "OR1", Notify);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 20m);

			order.WD_PackagesSent = 12;
			order.WD_PalletsSent = 2;
			order.WD_TotalWeight = 3.3m;
			order.WD_TotalCubic = 2.2m;

			data.Part1.OP_Weight += 2m; // increase weight, to check that cancel will not reduce more that was allocated.
			AssertEquals("Precondition data.Part1.OP_Weight = 4", 4m, data.Part1.OP_Weight);
			data.Part1.OP_Cubic += 0.2m; // increase volume, to check that cancel will not reduce more that was allocated.
			AssertEquals("Precondition data.Part1.OP_Weight = 0.22", 0.22m, data.Part1.OP_Cubic);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.NotReady;

			// use another factory here to test all data is reloaded correctly
			var otherFactory = new BusinessObjectFactory();
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			var orderInOtherFactory = otherFactory.Load<WhsOrder>(order.PK);
			AssertEquals("Precondition - Order should be picked.", true, order.IsAttachedToPickButNotFinalised);
			AssertEquals("Precondition - Order should have Weight Sent = 20 * 4.", 80m, order.WD_WeightSent);
			AssertEquals("Precondition - Order should have Weight Sent User Entered = 20 * 4.", 80m,
				order.WD_WeightSentUserEntered);
			AssertEquals("Precondition - Order should have Cubic Sent = 2.2 * 20.", 4.4m, order.WD_CubicSent);
			AssertEquals("Precondition - Order line should have quantity transacted.", 20m, orderLine.SumOfUnitsMet);

			var inventories = Helper.LoadInventory();
			AssertEquals(20m, inventories.UnitsCommitted);

			var inventoriesInOtherFactory = new WhsTestHelperFunctions(otherFactory).LoadInventory();
			AssertEquals(20m, inventoriesInOtherFactory.UnitsCommitted);

			// cancel pick and assert result
			pickInOtherFactory.IsAlterPick = true;
			var weightSentHitCount = 0;
			orderInOtherFactory.WD_WeightSentInfo.AdditionalValidation += () => weightSentHitCount++;
			AssertEquals("Should have succeeded cancelling.", true, cancelPick(pickInOtherFactory));
			AssertEquals("Pick should have Cancelled Status", true, pickInOtherFactory.IsCancelled);
			AssertEquals("Pick Task Planning Status should be cleared", string.Empty, pickInOtherFactory.WP_TaskPlanningStatus);
			AssertNull("Pick should be null", orderInOtherFactory.Pick);
			AssertEquals("Order finalised date should be empty", true, orderInOtherFactory.WD_FinalisedDate.IsEmpty);
			AssertEquals("Order should have Entered Status", DocketStatus.Codes.Entered, orderInOtherFactory.WD_DocketStatus);
			AssertEquals("Order Units Sent should be cleared", 0m, orderInOtherFactory.WD_UnitsSent);
			AssertEquals("Order Cubic Sent should be cleared", 0m, orderInOtherFactory.WD_CubicSent);
			AssertEquals("Order Weight Sent should be cleared", 0m, orderInOtherFactory.WD_WeightSent);
			AssertEquals("Order Weight Sent User Entered should be cleared", 0m, orderInOtherFactory.WD_WeightSentUserEntered);
			AssertEquals("Order Gross Weight Sent should be cleared", 0m, orderInOtherFactory.GrossWeightSent);
			AssertEquals("Order Packs Sent should be cleared", 0, orderInOtherFactory.WD_PackagesSent);
			AssertEquals("Order Pallets Sent should be cleared", (short)0, orderInOtherFactory.WD_PalletsSent);
			AssertEquals("Order Total Cubic should not be cleared", 2.2m, orderInOtherFactory.WD_TotalCubic);
			AssertEquals("Order Total Weight should not be cleared", 3.3m, orderInOtherFactory.WD_TotalWeight);
			AssertEquals("Since Order was detaching from Pick, should not have been trying to set Weight Sent through other properties.", 1, weightSentHitCount);

			foreach (WhsOrderLine line in orderInOtherFactory.Lines)
			{
				AssertEquals("Order line units met should be zero", 0.0m, line.SumOfUnitsMet);
				AssertEquals("Order line sum of units met should be zero", 0.0m, line.SumOfUnitsMet);
				AssertEquals("Order line should not have release lines", 0, line.ReleaseLines.Count);
			}

			AssertEquals(0m, inventoriesInOtherFactory.UnitsCommitted);
		}

