		public void TestCancelPick_WaitingReplenishment_Core(Func<WhsPick, bool> cancelPick)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var transferLine = Helper.CreateWhsTransferLine(transfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			transferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, transfer.IsFinalised);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition: pick is waiting replenishment.", true, pick.WP_IsAwaitingReplenishment);
			Factory.Save();

			pick.IsAlterPick = true;
			AssertEquals("Should have succeeded cancelling.", true, cancelPick(pick));
			AssertEquals("Pick should have Cancelled Status", true, pick.IsCancelled);
			AssertEquals("Pick should have cleared the WaitingReplenishment flag.", false, pick.WP_IsAwaitingReplenishment);
			AssertNull("Pick should be null", order.Pick);
			AssertNoExceptionThrown(Factory.Save);
		}

