		#region TestCancelPick_UnfinalisedDockDoorTransfer_FinalisationFails

		public void TestCancelPick_UnfinalisedDockDoorTransfer_FinalisationFails()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			var originalInventory = receive.Lines[0];
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
