			var pick = Helper.CreatePickNew(order);

			var pickLine = orderLine.PickLines.Single();
			var dockDoorTransferLine = Helper.PickAndMakeInTransitTransfer(pickLine, ZDateTimeOffset.Now);
			var dockDoorTransfer = dockDoorTransferLine.Docket;
			Factory.Save();

			var recorder = new PickedStockAdjustersFactory().GetNewAdjuster(data.Whs1, data.Org1, ReduceStockReason.Lost);
			((IReducibleItem)pickLine).ReduceStock(pickLine.WZ_Units, recorder);
			AssertIsFinalisedPrecondition(dockDoorTransferLine);
			AssertEquals("Precondition: Transfer is unfinalised.", false, dockDoorTransfer.IsFinalised);

			dockDoorTransfer.WD_WW_Whs = ZGuid.Empty;

			AssertEquals("Should *not* have succeeded cancelling.", false, pick.CancelPick());
			AssertEquals("Precondition: Pick *NOT* Cancelled.", false, pick.IsCancelled);
			AssertHasError(pick.StatusDescInfo, "Unable to Cancel Pick because of the following Errors when attempting to finalize all In-Transit Transfers:\r\nError - WD_WW_Whs: Please enter a Warehouse.");
		}

