		#region TestCancelPick_NoPickLinesAttachedToCanceledPick

		/// <summary>
		/// This test re-creates the use case whereby a bad cancel pick has left picklines still attached to an Order on the Pick.
		/// </summary>
		[TestDate(2005, 10, 8, 11, 42, 30)]
		public void TestCancelPick_NoPickLinesAttachedToCanceledPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var factory2 = new BusinessObjectFactory();
			var factory3 = new BusinessObjectFactory();
			var helperInFactory2 = new WhsTestHelperFunctions(factory2);

			WhsReceive receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 100m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			// create 2 Orders in different Factories and allocate the same inventory to both

			// order 1
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "OR1", data.Part1, 100m,
				WhsPickOption.Codes.Manual);
			var pick2 = Helper.CreatePickNew(order1);

			pick2.AutoAllocateItemsWithMock();
			var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(pick2);
			AssertEquals("Precondition - Auto-Allocation failed.", 100m, totalPickLineQuantity);

			// order 2
			var order2InFactory2 =
				helperInFactory2.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "OR2", data.Part1, 50m,
					WhsPickOption.Codes.Manual);
			var pick2InFactory2 = helperInFactory2.CreatePickNew(order2InFactory2);
			pick2InFactory2.AutoAllocateItemsWithMock();

			var totalPickLineQuantityInFactory2 = Helper.GetTotalPickLineQuantity(pick2InFactory2);
			AssertEquals("Precondition - Auto-Allocation failed.", 50m, totalPickLineQuantityInFactory2);

			// save order 1, then attempt to validate order 2 (order 2 should be in error)
			pick2.RunPreSaveValidation();
			AssertEquals("Precondition - Pick should have no errors.", false, pick2.HasErrors());
			Factory.Save();

			pick2InFactory2.RunPreSaveValidation();
			AssertEquals("Pick from another factory should have committed all stock, so no more should be left for this pick.",
				true, pick2InFactory2.HasErrors());
			// (Order 2 is unsaved to allow the Pick1 to be finalised)

			// finalise order 1 and pick in a new factory.
			var order1InFactory3 = factory3.Load<WhsOrder>(order1.PK);
			order1InFactory3.Pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order1InFactory3);
			order1InFactory3.Pick.FinalisePick();
			AssertEquals("Should be able to finalise since Pick2 is not saved to DB yet.", true,
				order1InFactory3.Pick.IsFinalised);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, order1InFactory3.Pick.WP_FinalizedDateUtc);

			factory3.Save();

			// Since we could not finalise or save the second order and pick we should be able to cancel it.
			AssertEquals("Should have succeeded cancelling.", true, pick2InFactory2.CancelPick());
			AssertEquals("Should be able to cancel the Pick.", true, pick2InFactory2.IsCancelled);
			AssertEquals("No pick lines should be attached to canceled pick.", 0, pick2InFactory2.GetAllPickLines().Count());
			factory2.Save();
		}

