		#region TestCancelPick_ClearsPackagesFromCartonizedPicks

		public void TestCancelPick_ClearsPackagesFromCartonizedPicks()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;
			var org = data.Org1;
			var part = Helper.CreateProduct(org, "PR1");

			var whsGroup = Helper.CreateWhsCartonGroup("1", "WhsOrg");
			var whsSize = Helper.CreateWhsCartonSize("WH", 10, 20, 40, 80, 160, 320, new ZByte(100), Constants.Length.Metres,
				Constants.Weight.Kilograms);
			whsGroup.CartonSizes.Add(whsSize);
			data.Whs1.WarehouseAddress.Header.MiscServ.OM_WCG_CartonGroup = whsGroup.PK;

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", part, 5);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", arrivalDate: receive1.WD_ArrivalDate, part, 5);
			var splitCaseRefType = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Metres, 3,
				Constants.Weight.Kilograms, UOMPackTypesList.Codes.SplitCase);
			part.OP_StockKeepingUnit = splitCaseRefType.F3_Code;
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, part, 10);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;

			AssertEquals(DocketStatus.Codes.AttachedToPick, order.WD_DocketStatus);
			AssertEquals("Precondition", true, pick.WP_CartoniseSplitCases);
			Factory.Save();

			pick.AllocatePackageLabels();
			AssertEquals("Precondition - Cartonised", true, pick.WP_IsCartonised);
			AssertEquals("Precondition - some packages created", 1, order.PackageJob.Packages.Count);

			AssertEquals("Should have succeeded cancelling.", true, pick.CancelPick());
			CombineAssertions(() =>
			{
				AssertEquals(false, pick.WP_IsCartonised);
				AssertNull(order.PackageJob);
				AssertEquals(0, pick.Orders.Count);
				AssertEquals(PickStatus.Codes.Cancelled, pick.WP_PickStatus);
				AssertEquals(DocketStatus.Codes.Entered, order.WD_DocketStatus);
				AssertEquals("Should *not* have saved.", true, pick.HasChanges);
			});

			var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);
			AssertEquals("Should still be Cartonised in the database.", true, pickInFactory2.WP_IsCartonised);
			AssertEquals("Should still have allocated stock in the database.", 10m, pickInFactory2.OrderedInventories[0].AvailableInventories[0].QuantityCommitted);
			AssertEquals("Should still have a package in the database.", 1, pickInFactory2.Orders.Cast<WhsOrder>().Single().PackageJob.Packages.Count);
		}

