		#region TestCancelPick_FailsFactorySaveIfThereAreOrdersLeft_WaitingReplenishment

		public void TestCancelPick_FailsFactorySaveIfThereAreOrdersLeft_WaitingReplenishment()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var transferLine = Helper.CreateWhsTransferLine(transfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			transferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, transfer.IsFinalised);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;

			var dodgyOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition: pick is waiting replenishment.", true, pick.WP_IsAwaitingReplenishment);
			Factory.Save();

			pick.Orders.CountChanged += (sender, args) =>
			{
				pick.Orders.Add(dodgyOrder); // this is to make pick.Orders.Count > 0 when we detaching orders during cancellation
			};

			var cancelResult = true;
			AssertNoExceptionThrown("No exception is thrown.", () => cancelResult = pick.CancelCancellablePick());
			AssertEquals("Pick is not cancelled.", false, cancelResult);
			AssertEquals("Pick is not cancelled.", false, pick.IsCancelled);
			AssertEquals("Pick should *not* have cleared the WaitingReplenishment flag.", true, pick.WP_IsAwaitingReplenishment);
			Helper.AssertZCannotSaveExceptionThrown("Cannot save Pick P00000001 as an error occurred during the Cancel Pick operation. Please reload the Pick.", Factory.Save);

			var newFactory = new BusinessObjectFactory();
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
			Assert(pickInNewFactory.CancelCancellablePick());
			Assert("Pick is cancelled.", pickInNewFactory.IsCancelled);
			AssertEquals("Pick should have cleared the WaitingReplenishment flag.", false, pickInNewFactory.WP_IsAwaitingReplenishment);
			AssertNoExceptionThrown("Factory saved successfully.", () => newFactory.Save());
		}

