		#region TestIsCancellable

		#region TestIsCancellable

		public void TestIsCancellable()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "2", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order1, order2);

			var trolley = Helper.CreateTrolley("TR1");
			var trolleyJob = Helper.CreateWhsPickTrolleyJob(trolley.PK, "BLD");
			var package1 = order1.PackageJob.Packages.AddNew();
			var trolleySlot1 = Helper.CreateWhsPickTrolleySlot(trolleyJob.PK, package1.PK, 1);
			var package2 = order2.PackageJob.Packages.AddNew();
			var trolleySlot2 = Helper.CreateWhsPickTrolleySlot(trolleyJob.PK, package2.PK, 2);
			Factory.Save();

			var errorMessage = pick.GetIsCancellableErrorMessage();
			var isCancellable = errorMessage.IsEmpty;
			AssertEquals("IsCancellable should be false", false, isCancellable);
			AssertEquals("ErrorMessage doesn't match",
				"You cannot cancel pick because this pick has a package with an active Trolley job or was picked by Trolley.",
				errorMessage);

			trolleyJob.WTJ_Status = "FIN";
			Factory.Save();

			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("Still Pick has packages with trolley job, should not be cancellable", false, isCancellable);
			AssertEquals("ErrorMessage doesn't match",
				"You cannot cancel pick because this pick has a package with an active Trolley job or was picked by Trolley.",
				errorMessage);

			((BusinessObject)trolleySlot1).Delete();
			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("Still another package has trolley job, should not be cancellable", false, isCancellable);
			AssertEquals("ErrorMessage doesn't match",
				"You cannot cancel pick because this pick has a package with an active Trolley job or was picked by Trolley.",
				errorMessage);

			((BusinessObject)trolleySlot2).Delete();
			Factory.Save();
			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("IsCancellable should be true", true, isCancellable);
			AssertEquals("Pick should be cancellable and errorMessage should be empty", ZString.Empty, errorMessage);
		}

		public void TestIsCancellable_TaskPlanningStatus()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var errorMessage = pick.GetIsCancellableErrorMessage();
			var isCancellable = errorMessage.IsEmpty;
			AssertEquals("Precondition", true, isCancellable);
			AssertEquals("Pick should be cancellable and errorMessage should be empty", ZString.Empty, errorMessage);

			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.Ready;
			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("IsCancellable should be false", false, isCancellable);
			AssertEquals("ErrorMessage should match",
				"You cannot cancel pick because this pick is Ready For Planning or Planned.",
				errorMessage);

			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.NotReady;
			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("IsCancellable should be true", true, isCancellable);
			AssertEquals("Pick should be cancellable and errorMessage should be empty", ZString.Empty, errorMessage);

			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.Planned;
			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("IsCancellable should be false", false, isCancellable);
			AssertEquals("ErrorMessage should match",
				"You cannot cancel pick because this pick is Ready For Planning or Planned.",
				errorMessage);
		}

