		#region TestIsCancellable_PartiallyOrFullyPicked

		public void TestIsCancellable_PartiallyOrFullyPicked()
		{
			TestIsCancellable_PartiallyOrFullyPicked_Core(usingInTransitTransfer: false);
		}

		public void TestIsCancellable_PartiallyOrFullyPicked_WithInTransitTransfer()
		{
			TestIsCancellable_PartiallyOrFullyPicked_Core(usingInTransitTransfer: true);
		}

		void TestIsCancellable_PartiallyOrFullyPicked_Core(bool usingInTransitTransfer)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(pick);
			var errorMessage = pick.GetIsCancellableErrorMessage();
			var isCancellable = errorMessage.IsEmpty;

			AssertEquals("Precondition", 10m, totalPickLineQuantity);
			AssertEquals("Allocated picks can be cancelled.", true, isCancellable);
			AssertEquals("Allocated picks should have no errors when cancelling.", "", errorMessage);

			var pickLine = pick.GetAllPickLines().Single();

			if (usingInTransitTransfer)
			{
				Helper.PickAndMakeInTransitTransfer(pickLine, ZDateTimeOffset.Now);
			}
			else
			{
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;

				using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
				{
					Factory.Save();
					AssertEquals("Precondition: Picked Directly.", ZGuid.Empty,
						order.Lines[0].PickLines.Single().WZ_WE_OriginalPickedInventoryLine);
				}
			}

			errorMessage = pick.GetIsCancellableErrorMessage();
			isCancellable = errorMessage.IsEmpty;
			AssertEquals("Partially or fully picked picks cannot be cancelled.", false, isCancellable);
			AssertEquals("Partially or fully picked picks cannot be cancelled. Should show error.",
				OrderErrorTypes.CannotPerformThisOperationBecauseOrderIsPartiallyOrFullyPicked.Message, errorMessage);
		}

