		#region TestIsCancellable_UnfinalisedDockDoorTransferLines

		public void TestIsCancellable_UnfinalisedDockDoorTransferLines()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 20m, data.Whs1.FindLocation("A-1"), "");
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var order1Line = Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order1);

			// NOTE: This should be prevented earlier, but we do the check here to prevent any cancellation code running.
			// Unfinalised transfer lines shouldn't exist if no stock was picked
			var dodgyTransfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			dodgyTransfer.WD_WP_ParentPickForTransfer = pick.PK;

			var dodgyTransferLine = Helper.CreateWhsTransferLine(dodgyTransfer, data.Part1, 10m, data.Whs1.FindLocation("A-1"), data.Whs1.FindLocation("A-2"));
			dodgyTransferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition.", false, dodgyTransferLine.IsFinalised);
			AssertEquals("Precondition.", false, dodgyTransfer.IsFinalised);

			AssertEquals("Should have shown an error message.",
				"You cannot cancel the pick because there are un-finalized Outbound Dock Door Transfer lines.",
				pick.GetIsCancellableErrorMessage());

			dodgyTransferLine.Delete();
			AssertEquals("Pick should be cancellable and errorMessage should be empty", ZString.Empty, pick.GetIsCancellableErrorMessage());
		}

