		#region TestCancelPick_DeleteReceivesForUnpickedPickOnSaleOrders

		public void TestCancelPick_DeleteReceivesForUnpickedPickOnSaleOrders()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);

			var kit = Helper.CreateProduct(data.Org1, "KIT");
			kit.OP_IsComponentPickedOnSalesOrder = true;
			var component = Helper.CreateProduct(data.Org1, "COMPONENT");
			Helper.CreateProductBOM(kit, component, 2m, Constants.PkgUnit.Unit);

			var org2 = Helper.CreateClient("ORG2");
			var kit2 = Helper.CreateProduct(org2, "KIT2");
			kit2.OP_IsComponentPickedOnSalesOrder = true;
			var component2 = Helper.CreateProduct(org2, "COMPONENT2");
			var component3 = Helper.CreateProduct(org2, "COMPONENT3");
			Helper.CreateProductBOM(kit2, component2, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(kit2, component3, 2m, Constants.PkgUnit.Unit);

			var receive1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive1, wheel, 70m, data.Whs1.FindLocation("A-1"));
			Helper.CreateWhsReceiveInventoryLine(receive1, component, 70m, data.Whs1.FindLocation("A-1"));
			receive1.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive1.IsFinalised);

			var receive2 = Helper.CreateWhsReceive(org2, data.Whs1, "R2");
			Helper.CreateWhsReceiveInventoryLine(receive2, component2, 70m, data.Whs1.FindLocation("A-1"));
			Helper.CreateWhsReceiveInventoryLine(receive2, component3, 70m, data.Whs1.FindLocation("A-1"));
			receive2.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive2.IsFinalised);

			var pick = Factory.New<WhsPick>();
			pick.WP_WW_Whs = data.Whs1.PK;
			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultInboundDockDoor;
			pick.WP_PickOption = WhsPickOption.Codes.Manual;
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption: WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order1, bike, 2m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", pickOption: WhsPickOption.Codes.Manual);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, kit, 3m);
			var order3 = Helper.CreateWhsOrder(org2, data.Whs1, "O3", pickOption: WhsPickOption.Codes.Manual);
			var orderLine3 = Helper.CreateWhsOrderLine(order3, kit2, 4m);

			pick.AddOrders(new[] { order1, order2, order3 });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			Factory.Save();

			var createdReceives = Factory.Load<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			var createdReceive1 = createdReceives.Single(r => r.WD_OH_Client == data.Org1.PK);
			var createdReceiveLine1 = createdReceive1.Lines.Cast<WhsReceiveLine>().Single(l => l.WE_OP == bike.PK);
			var createdPickLines1 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine1.PK))[0];
			var link1 = createdReceiveLine1.BOMComponentLinks.First();
			AssertEquals("Precondition", false, createdReceive1.IsDeleted);
			AssertEquals("Precondition", false, createdReceiveLine1.IsDeleted);
			AssertEquals("Precondition", false, createdPickLines1.IsDeleted);
			AssertEquals("Precondition", false, link1.IsDeleted);
			AssertEquals("Precondition: Kit and Component Lines all have Pick Lines allocated.", true, order1.Lines.All(l => l.PickLines.Count > 0));

			var createdReceiveLine2 = createdReceive1.Lines.Cast<WhsReceiveLine>().Single(l => l.WE_OP == kit.PK);
			var createdPickLines2 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine2.PK))[0];
			var link2 = createdReceiveLine2.BOMComponentLinks.First();
			AssertEquals("Precondition", false, createdReceiveLine2.IsDeleted);
			AssertEquals("Precondition", false, createdPickLines2.IsDeleted);
			AssertEquals("Precondition", false, link2.IsDeleted);
			AssertEquals("Precondition: Kit and Component Lines all have Pick Lines allocated.", true, order2.Lines.All(l => l.PickLines.Count > 0));

			var createdReceive2 = createdReceives.Single(r => r.WD_OH_Client == org2.PK);
			var createdReceiveLine3 = createdReceive2.Lines[0];
			var createdPickLines3 = Factory.Load<WhsPickLine>(new ZQuery(WhsPickLineSchema.WZ_WE_InventoryLine, createdReceiveLine3.PK))[0];
			var componentOrderLine3 = (WhsOrderLine)order3.AllLines.Single(l => l.WE_OP == component2.PK);
			var componentOrderLine4 = (WhsOrderLine)order3.AllLines.Single(l => l.WE_OP == component3.PK);
			var link3 = createdReceiveLine3.BOMComponentLinks.Single(l => l.WIP_WE_ComponentLine == componentOrderLine3.PK);
			var link4 = createdReceiveLine3.BOMComponentLinks.Single(l => l.WIP_WE_ComponentLine == componentOrderLine4.PK);
			AssertEquals("Precondition", false, createdReceive2.IsDeleted);
			AssertEquals("Precondition", false, createdReceiveLine3.IsDeleted);
			AssertEquals("Precondition", false, createdPickLines3.IsDeleted);
			AssertEquals("Precondition", false, link3.IsDeleted);
			AssertEquals("Precondition", false, link4.IsDeleted);
			AssertEquals("Precondition: Kit and Component Lines all have Pick Lines allocated.", true, order3.Lines.All(l => l.PickLines.Count > 0));

			var pickCancelled = pick.CancelPick();
			AssertEquals(true, pickCancelled);
			Factory.Save();

			AssertEquals(true, createdReceive1.IsDeleted);
			AssertEquals(true, createdReceiveLine1.IsDeleted);
			AssertEquals(true, createdPickLines1.IsDeleted);
			AssertEquals(true, link1.IsDeleted);
			AssertEquals(true, createdReceiveLine2.IsDeleted);
			AssertEquals(true, createdPickLines2.IsDeleted);
			AssertEquals(true, link2.IsDeleted);
			AssertEquals(true, createdReceive2.IsDeleted);
			AssertEquals(true, createdReceiveLine3.IsDeleted);
			AssertEquals(true, createdPickLines3.IsDeleted);
			AssertEquals(true, link3.IsDeleted);
			AssertEquals(true, link4.IsDeleted);
			AssertEquals("Precondition: All Pick Lines on order1 were deleted.", true, order1.Lines.All(l => l.PickLines.Count == 0));
			AssertEquals("Precondition: All Pick Lines on order2 were deleted.", true, order2.Lines.All(l => l.PickLines.Count == 0));
			AssertEquals("Precondition: All Pick Lines on order3 were deleted.", true, order3.Lines.All(l => l.PickLines.Count == 0));
		}

