			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "External-Ref");
			order1.WD_DocketSubType = OrderType.Codes.Customs;
			Helper.CreateWhsOrderLine(order1, data.Part1, 25m, "BEK11-1", "DummyOutward-1", "");
			Helper.CreateWhsOrderLine(order1, data.Part2, 100m, "BEK11-2", "DummyOutward-2", "");
			Helper.CreateWhsOrderLine(order1, data.Part1, 75m, "BEK11-1", "DummyOutward-1", "");

			Helper.CreatePickNew(FINALISE_ORDERS, FINALISE_PICK, order1);
			Factory.Save();

			// create an adjustment but do *not* save it
			var adjustment = AdjustIn(order1);
			AssertAdjustment(order1, adjustment, 0);
			AssertIsFinalisedPrecondition(adjustment);
			AssertEquals("Precondition - Adjustment should not be saved.", false, adjustment.IsInDatabase);

			// create another order and order the same stock as was on the previous order / adjustment
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "External-Ref");
			order2.WD_ExternalReferenceSplit = 1;
			order2.WD_DocketSubType = OrderType.Codes.Customs;
			var line1 = Helper.CreateWhsOrderLine(order2, data.Part1, 25m, "BEK11-1", "DummyOutward-1", "");
			var line2 = Helper.CreateWhsOrderLine(order2, data.Part2, 100m, "BEK11-2", "DummyOutward-2", "");
			var line3 = Helper.CreateWhsOrderLine(order2, data.Part1, 75m, "BEK11-1", "DummyOutward-1", "");
			Factory.Save();

			// attempt to pick the order, should be able to see stock from the non-saved adjustment (as it is passed in to PickOrders())
			var pick = Factory.New<WhsPick>();
			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				pick.PickOrdersForBond(order2, adjustment.Lines.SelectMany(line => line.Inventory.Cast<WhsInventoryView>()));
			}
			order2.FinaliseDocketWithoutUserConfirmation();
			order2.Pick.FinalisePick();
			AssertIsFinalisedPrecondition(order2);
			AssertIsFinalisedPrecondition(order2.Pick);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, order2.Pick.WP_FinalizedDateUtc);

			AssertEquals(line1.SumOfUnitsMet, 25m);
			AssertEquals(line2.SumOfUnitsMet, 100m);
			AssertEquals(line3.SumOfUnitsMet, 75m);
		}

		static WhsAdjustment AdjustIn(WhsOrder order)
		{
			var mostRecentAdjustment = GetMostRecentAdjustment(order);
			var newAdjustmentSplit = (byte)((mostRecentAdjustment != null) ? mostRecentAdjustment.WD_ExternalReferenceSplit + 1 : 0);

			var adjustment = order.Factory.New<WhsAdjustment>();
			adjustment.WD_DocketSubType = AdjustmentType.Codes.Customs;
			adjustment.WD_WW_Whs = order.WD_WW_Whs;
			adjustment.WD_OH_Client = order.WD_OH_Client;
			adjustment.WD_ExternalReference = order.WD_ExternalReference;
			adjustment.WD_ExternalReferenceSplit = newAdjustmentSplit;

			AdjustInOrderLines(order, adjustment);

			using (((IBusinessObjectInternals)adjustment).ResumeValidationForAllDescendantsTemporarily())
			{
				adjustment.FinaliseDocketWithoutUserConfirmation();
			}
			adjustment.IsUniqueExternalReferenceCreatedOnSave = false; // don't auto add DocketID as we now use ExtRef + Split to locate the latest adjustment.

			return adjustment;
		}

		static WhsAdjustment GetMostRecentAdjustment(WhsDocket docket)
		{
			var existingAdjustmentsQuery = new ZQuery();
			existingAdjustmentsQuery.AddToFilter(WhsDocketSchema.WD_DocketType, DocketType.Codes.Adjustment);
			existingAdjustmentsQuery.AddToFilter(WhsDocketSchema.WD_ExternalReference, docket.WD_ExternalReference);
			existingAdjustmentsQuery.AddToFilter(WhsDocketSchema.WD_OH_Client, docket.WD_OH_Client);
			existingAdjustmentsQuery.OrderBy = WhsDocketSchema.Constants.WD_ExternalReferenceSplit + OrderByClause.Descending;

			return docket.Factory.LoadTop1<WhsAdjustment>(existingAdjustmentsQuery);
		}

		static void AdjustInOrderLines(WhsOrder order, WhsAdjustment newAdjustment)
		{
			// we must return inventory on actual picklines so that we adjust what was PICKED, *not* what was ORDERED
			// (attribs could be empty on orderlines but specified on picklines.inventory)
			foreach (var line in order.Lines)
			{
				foreach (var pickLine in line.PickLines)
				{
					var inventory = pickLine.Inventory;
					var newLine = newAdjustment.CreateDocketLineFromInventory(inventory);
					newLine.WE_TransactionQuantity = pickLine.WZ_Units;
					newLine.WE_ReasonCode = "AMD";
					newLine.WE_OriginalInventoryStatus = InventoryStatus.Codes.Available;
				}
			}
		}

		static void AssertAdjustment(WhsOrder order, WhsAdjustment adjustment, byte expectedAdjustmentSplitNo)
		{
			// header
			AssertEquals(order.Warehouse, adjustment.Warehouse);
			AssertEquals(order.Client, adjustment.Client);
			AssertEquals(order.WD_ExternalReference, adjustment.WD_ExternalReference);
			AssertEquals(expectedAdjustmentSplitNo, adjustment.WD_ExternalReferenceSplit);
			AssertEquals(AdjustmentType.Codes.Customs, adjustment.WD_DocketSubType);
			AssertEquals("Adjustment should be Finalised.", true, adjustment.IsFinalised);

			// lines
			var multiplier = 1; // -1 adjusts out received stock
			AssertEquals(order.Lines.Count, adjustment.Lines.Count);

			var expectedInventoryStatus = InventoryStatus.Codes.Available;

			foreach (var line in order.Lines)
			{
				var entryKeyAndNo = line.WE_BondedEntryKey.Split('-');
				var expectedEntryKey = entryKeyAndNo[0];
				var expectedEntryLineNo = ZShort.Parse(entryKeyAndNo[1]);

				// bit ugly but simpler than passing a delegate to AssertAdjustment
				var inventory = ((WhsOrderLine)line).PickLines[0].Inventory;

				AssertEquals(1,
					(from adjLine in adjustment.Lines
					 where
							 // critical
							 adjLine.WE_TransactionQuantity == line.WE_TransactionQuantity * multiplier
						&& adjLine.WE_OP == line.WE_OP
						&& adjLine.WE_BondedEntryKey == line.WE_BondedEntryKey
						&& adjLine.CustomsData.WB_EntryKey == expectedEntryKey
						&& adjLine.CustomsData.WB_EntryLineNo == expectedEntryLineNo
						&& adjLine.WE_PartAttrib1 == inventory.WI_PartAttrib1
						&& adjLine.WE_PartAttrib2 == inventory.WI_PartAttrib2
						&& adjLine.WE_PartAttrib3 == inventory.WI_PartAttrib3
						&& adjLine.WE_SerialNumber == inventory.WI_SerialNumber

						// less important
						&& adjLine.WE_ReasonCode == "AMD"
						&& adjLine.WE_OriginalInventoryStatus == expectedInventoryStatus
						&& adjLine.WE_WHC_NKOriginalInventoryHeldCode == string.Empty
					 select adjLine).Count());
			}
		}

