		#region TestPickOrdersForBond_WithAdditionalInventoryToMakeAvailableForPick

		public void TestPickOrdersForBond_WithAdditionalInventoryToMakeAvailableForPick()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateMultiWarehouseClientProductInventory();
			data.Whs1.WW_IsBondedWarehouse = true;
			data.Whs1.WW_IsVirtualWarehouse = true;
			data.Whs1.Areas[0].WA_AreaType = AreaTypes.Codes.Bonded;
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "RX", data.Part2, 100m, "BEK11-1"); // create same entry key in new receive

			// create an order in the DB for *all* stock for BEK11-1 and BEK11-2
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "External-Ref");
			order.WD_DocketSubType = OrderType.Codes.Customs;
			var line1 = Helper.CreateWhsOrderLine(order, data.Part1, 25m, "BEK11-1", "DummyOutward-1", "");
			var line2 = Helper.CreateWhsOrderLine(order, data.Part2, 100m, "BEK11-2", "DummyOutward-2", "");
			var line3 = Helper.CreateWhsOrderLine(order, data.Part1, 75m, "BEK11-1", "DummyOutward-1", "");

			Helper.CreatePickNew(order);
			Factory.Save();
			AssertEquals("Precondition", line1.SumOfUnitsMet, 25m);
			AssertEquals("Precondition", line2.SumOfUnitsMet, 100m);
			AssertEquals("Precondition", line3.SumOfUnitsMet, 75m);

			// store inventory from the order
			var additionalInventory = order.Lines.Cast<WhsOrderLine>().SelectMany(ol => ol.PickLines).Select(pl => pl.Inventory)
				.ToArray();

			// cancel the pick, but DON'T save changes to the DB (inventory is therefore not available to DBOnlyQueries)
			order.Pick.CancelPick();
			AssertNull("Precondition", order.Pick);
			AssertEquals("Precondition - cancelled pick should not be saved to DB.", true, order.HasChanges);

			// remove all order lines and add new ones, but be sure to order enough stock such that we require the inventory from the previously cancelled pick
			order.Lines.DeleteAll();
			var newLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 20m, "BEK11-1", "DummyOutward-1", "");
			var newLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 90m, "BEK11-1", "DummyOutward-2", "");
			var newLine3 = Helper.CreateWhsOrderLine(order, data.Part1, 75m, "BEK11-1", "DummyOutward-1", "");

			// attempt to re-pick the order, should be able to see stock from the non-saved cancelled pick (as it is passed in to PickOrders())
			var pick = Factory.New<WhsPick>();
			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				pick.PickOrdersForBond(order, additionalInventory);
			}
			AssertEquals(newLine1.SumOfUnitsMet, 20m);
			AssertEquals(newLine2.SumOfUnitsMet, 90m);
			AssertEquals(newLine3.SumOfUnitsMet, 75m);
		}

