		public void TestPick()
		{
			var part = new OrgSupplierPart[2];
			var receiveLine1 = new WhsInventoryView[2];
			var receiveLine2 = new WhsInventoryView[2];
			var orderLine = new WhsOrderLine[2];

			WhsWarehouse whs1 = Helper.CreateWarehouse("1");
			WhsRow row1 = Helper.CreateRowAndGenerateLocations(whs1, "A", 2, 2);

			// warehouse2 is used for multi-warehouse testing
			// that is, ensure stock is not picked from the wrong warehouse
			WhsWarehouse whs2 = Helper.CreateWarehouse("2");
			WhsRow row2 = Helper.CreateRowAndGenerateLocations(whs2, "A", 2, 2);

			OrgHeader org = Helper.CreateClient();
			part[0] = Helper.CreateProduct(org, "AA1");
			part[1] = Helper.CreateProduct(org, "AA2");

			// create receive docket for inventory
			WhsReceive receive1 = Helper.CreateWhsReceive(org, whs1, "1", Notify);
			receiveLine1[0] = Helper.CreateWhsReceiveInventoryLine(receive1, part[0], 20);
			receiveLine1[1] = Helper.CreateWhsReceiveInventoryLine(receive1, part[1], 20);

			// create inventory
			receive1.AllocateLocationsWithMock();
			receive1.FinaliseDocket();

			AssertEquals("Inventory must be created for Receive1", receive1.Inventory.Count, 2);
			AssertEquals("Putaway must be Finalised", true, receive1.IsFinalised);

			// create receive docket for inventory in 2nd warehouse
			WhsReceive receive2 = Helper.CreateWhsReceive(org, whs2, "2", Notify);
			receiveLine2[0] = Helper.CreateWhsReceiveInventoryLine(receive2, part[0], 20);
			receiveLine2[1] = Helper.CreateWhsReceiveInventoryLine(receive2, part[1], 20);

			// create inventory
			receive2.AllocateLocationsWithMock();
			receive2.FinaliseDocket();

			AssertEquals("Inventory must be created for Receive2", receive2.Inventory.Count, 2);
			AssertEquals("Putaway must be Finalised", true, receive1.IsFinalised);

			// construct an order
			WhsOrder order1 = Helper.CreateWhsOrder(org, whs1, "1", Notify);
			order1.ConsigneePK = org.PK;
			order1.ConsigneeAddressPK = org.MainAddress.PK;
			order1.WD_RequiredDate = ZDateTimeOffset.Now;
			AssertNull("Precondition: Order has no pick", order1.Pick);
			Factory.Save();

			// test for "no order lines" notification
			// construct Pick bizo
			bool exceptionThrown = false;
			WhsPick pick1 = Helper.CreatePick_OLD();
			try
			{
				using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
				{
					pick1.CreatePick_OBSOLETE(order1);
				}
			}
			catch (PickFailedException)
			{
				exceptionThrown = true;
			}
			Assert("Pick should have 'no order lines' notification", pick1.HasRowErrors);
			AssertEquals("Exception not thrown", true, exceptionThrown);
			AssertNull("Pick should be null", order1.Pick);

			// create some order lines for pick proper test
			orderLine[0] = Helper.CreateWhsOrderLine(order1, part[0], 10);
			orderLine[1] = Helper.CreateWhsOrderLine(order1, part[1], 30);

			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				// create the pick
				pick1.CreatePick_OBSOLETE(order1);
			}

			AssertEquals("Order Pick must be set", pick1.PK, order1.WD_WP);
			AssertEquals("There should be 2 pick lines", 2, pick1.GetAllPickLines().Count());
			Assert("PickLine1 has picked from correct location",
				FindInvLine(receive1, part[0].PK, FindPickLine(pick1, part[0].PK).Inventory.WI_WL) != null);
			Assert("PickLine2 has picked from correct location",
				FindInvLine(receive1, part[1].PK, FindPickLine(pick1, part[1].PK).Inventory.WI_WL) != null);
			AssertEquals("OrderLine1 UnitsMet must be set", 10.0m, orderLine[0].SumOfUnitsMet);
			AssertEquals("OrderLine2 UnitsMet must be set", 20.0m, orderLine[1].SumOfUnitsMet);
			AssertEquals("Inventory1 Committed must be set", 10.0m,
				FindInvLine(receive1, part[0].PK, FindPickLine(pick1, part[0].PK).Inventory.WI_WL)
					.CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Inventory2 Committed must be set", 20.0m,
				FindInvLine(receive1, part[1].PK, FindPickLine(pick1, part[1].PK).Inventory.WI_WL)
					.CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Should be no bonded attributes", null,
				WhsBondedWarehouseAttribute.LoadFromParentID(Factory, orderLine[0]));
			AssertEquals("Should be no bonded attributes", null,
				WhsBondedWarehouseAttribute.LoadFromParentID(Factory, orderLine[1]));

			// create shortfall on order + pick
			pick1.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(ordInv => ordInv.SupplierPartPK == part[0].PK)
				.AvailableInventories[0].PickLineQuantity -= 5m;
			pick1.FinaliseOrder(order1);
			pick1.FinalisePick();

			Assert("Pick is finalised", pick1.IsFinalised);
			AssertEquals("Inventory1 updated", 0m,
				FindInvLine(receive1, part[0].PK, FindPickLine(pick1, part[0].PK).Inventory.WI_WL)
					.CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Inventory2 updated", 0m,
				FindInvLine(receive1, part[1].PK, FindPickLine(pick1, part[1].PK).Inventory.WI_WL)
					.CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Inventory1 updated", 15m,
				FindInvLine(receive1, part[0].PK, FindPickLine(pick1, part[0].PK).Inventory.WI_WL).WI_TotalUnits);
			AssertEquals("Inventory2 updated", 0m,
				FindInvLine(receive1, part[1].PK, FindPickLine(pick1, part[1].PK).Inventory.WI_WL).WI_TotalUnits);

			Factory.Save(); // needed for DBOnly queries below
			var inventories0 = Helper.LoadInventory(org, part[0], whs1);
			var inventories1 = Helper.LoadInventory(org, part[1], whs1);
			AssertEquals("WhsInventoryQuery0 Committed", 0m, inventories0.UnitsCommitted);
			AssertEquals("WhsInventoryQuery0 Available", 15m, inventories0.UnitsAvailable);
			AssertEquals("WhsInventoryQuery0 Total", 15m, inventories0.UnitsTotal);
			AssertEquals("WhsInventoryQuery Committed", 0m, inventories1.UnitsCommitted);
			AssertEquals("WhsInventoryQuery Available", 0m, inventories1.UnitsAvailable);
			AssertEquals("WhsInventoryQuery Total", 0m, inventories1.UnitsTotal);
		}

		public void TestPickOnlyFromValidLocationsAndInventory()
		{
			var whs1 = Helper.CreateWarehouse("1", "A", 4, 1);
