		public void TestPickingWithAttributes()
		{
			var whs = Helper.CreateWarehouse("1", "A");
			var org = Helper.CreateClient();
			var part = Helper.CreateProduct(org, "A1");

			SetClientAttributesType(org);
			SetProductAttributesUse(org, part);

			var receive = Helper.CreateWhsReceive(org, whs, "1", Notify);
			var receiveLine1 = Helper.CreateWhsReceiveInventoryLine(receive, part, 10);
			var receiveLine2 = Helper.CreateWhsReceiveInventoryLine(receive, part, 20);
			var receiveLine3 = Helper.CreateWhsReceiveInventoryLine(receive, part, 30);
			SetLineAttributes(receiveLine1, "PA11", "PA21", "PA31", ZDate.Today.AddMonths(1), ZDate.Today.AddMonths(-1));
			SetLineAttributes(receiveLine2, "PA12", "PA22", "PA32", ZDate.Today.AddMonths(2), ZDate.Today.AddMonths(-2));
			SetLineAttributes(receiveLine3, "PA13", "PA23", "PA33", ZDate.Today.AddMonths(3), ZDate.Today.AddMonths(-3));

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Assert(receive.IsFinalised);

			var order = Helper.CreateWhsOrder(org, whs, "1", Notify);
			var orderLine1 = Helper.CreateWhsOrderLine(order, part, 10);
			var orderLine2 = Helper.CreateWhsOrderLine(order, part, 20);
			var orderLine3 = Helper.CreateWhsOrderLine(order, part, 30);
			SetLineAttributes(orderLine1, "PA11", "PA21", "PA31", ZDate.Today.AddMonths(1), ZDate.Today.AddMonths(-1));
			// line 2 attributes are left blank, pick engine should still find them
			SetLineAttributes(orderLine3, "PA13", "PA23", "PA33", ZDate.Today.AddMonths(3), ZDate.Today.AddMonths(-3));
			Factory.Save();

			Pick = Helper.CreatePick_OLD(order);
			Assert(order.IsAttachedToPickButNotFinalised);

			AssertEquals(orderLine1.SumOfUnitsMet, orderLine1.WE_TransactionQuantity);
			AssertEquals(orderLine1.WE_PartAttrib1, orderLine1.ReleaseLines[0].PartAttribute1);
			AssertEquals(orderLine1.WE_PartAttrib2, orderLine1.ReleaseLines[0].PartAttribute2);
			AssertEquals(orderLine1.WE_PartAttrib3, orderLine1.ReleaseLines[0].PartAttribute3);
			AssertEquals(orderLine1.WE_ExpiryDate, orderLine1.ReleaseLines[0].ExpiryDate);
			AssertEquals(orderLine1.WE_PackingDate, orderLine1.ReleaseLines[0].PackingDate);

			AssertEquals(receiveLine2.WI_PartAttrib1, orderLine2.ReleaseLines[0].PartAttribute1);
			AssertEquals(receiveLine2.WI_PartAttrib2, orderLine2.ReleaseLines[0].PartAttribute2);
			AssertEquals(receiveLine2.WI_PartAttrib3, orderLine2.ReleaseLines[0].PartAttribute3);
			AssertEquals(receiveLine2.WI_ExpiryDate, orderLine2.ReleaseLines[0].ExpiryDate);
			AssertEquals(receiveLine2.WI_PackingDate, orderLine2.ReleaseLines[0].PackingDate);

			AssertEquals(orderLine3.SumOfUnitsMet, orderLine3.WE_TransactionQuantity);
			AssertEquals(orderLine3.WE_PartAttrib1, orderLine3.ReleaseLines[0].PartAttribute1);
			AssertEquals(orderLine3.WE_PartAttrib2, orderLine3.ReleaseLines[0].PartAttribute2);
			AssertEquals(orderLine3.WE_PartAttrib3, orderLine3.ReleaseLines[0].PartAttribute3);
			AssertEquals(orderLine3.WE_ExpiryDate, orderLine3.ReleaseLines[0].ExpiryDate);
			AssertEquals(orderLine3.WE_PackingDate, orderLine3.ReleaseLines[0].PackingDate);
		}

		public void TestPicksFIFO()
		{
			var whs = Helper.CreateWarehouse("1", "A");
			var org = Helper.CreateClient();
			var part = Helper.CreateProduct(org, "A1");

			var receive1 = Helper.CreateWhsReceive(org, whs, "1", Notify);
			receive1.WD_ArrivalDate = ZDateTimeOffset.Now;
			Helper.CreateWhsReceiveInventoryLine(receive1, part, 10);
			receive1.AllocateLocationsWithMock();
			receive1.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive1);

			// make this one have an earlier arrival date so the pick should pick this line
			var receive2 = Helper.CreateWhsReceive(org, whs, "2", Notify);
			receive2.WD_ArrivalDate = ZDateTimeOffset.Now.AddDays(-1);
			var receiveLine21 = Helper.CreateWhsReceiveInventoryLine(receive2, part, 10);
			receive2.AllocateLocationsWithMock();
			receive2.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive2);

			var order = Helper.CreateWhsOrder(org, whs, "1", Notify);
			Helper.CreateWhsOrderLine(order, part, 10);
			Factory.Save();

			Helper.CreatePickNew(order);
			Assert("Precondtion - Order could not be picked", order.IsAttachedToPickButNotFinalised);

			AssertEquals("Wrong inventory picked", 10m, receiveLine21.CommittedQuantityIncludingUnfinalisedReceipt);
		}

