		#region TestPickBlowsUpWithTableValueParemeterValueUniqueness

		public void TestPickBlowsUpWithTableValueParameterValueUniqueness()
		{
			// This test is to reproduce issue from CS00371721. Sometimes TVP are used when loading AllInventories.
			// When TVP parameters are used, the inputs need to be unique, however our code previously did not consider 'text case'
			// when passing in 'unique' values and this test addresses that bug.
			using (var settings = TestEntityFrameworkSettings.Get())
			{
				settings.TVPRule = new TVPRule("1");

				var data = new TestDataSimpleEnvironment(Factory);
				var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				for (int i = 0; i < 5; i++)
				{
					Helper.CreateWhsOrderLine(order1, data.Part1, 1, ZDate.Empty, ZDate.Empty, "TEST" + i, "TEST" + i,
						"TEST" + i, "", "");
					Helper.CreateWhsOrderLine(order1, data.Part1, 1, ZDate.Empty, ZDate.Empty, "test" + i, "test" + i,
						"test" + i, "", "");
				}

				AssertNoExceptionThrown(() => Helper.CreatePickNew(order1));
			}
		}

