		#region TestMultiOrderPick_CancelPackageLabelsAndManuallyDeAllocateAndAllocate_UsePackageView

		public void TestMultiOrderPick_CancelPackageLabelsAndManuallyDeAllocateAndAllocate_UsePackageView()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;

			var packType = data.Part1.Lookups.PackTypes.Single(p => p.F3_Code == data.Part1.OP_StockKeepingUnit);
			packType.F3_UOMType = UOMPackTypesList.Codes.SplitCase;

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 100m);

			var part3 = Helper.CreateProduct(data.Org1, "P3");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", part3, 1m, null, "PLT-123");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", part3, 1m, null, "PLT-456");
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			Helper.CreateWhsOrderLine(order1, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order1, part3, 1m);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			Helper.CreateWhsOrderLine(order2, data.Part1, 3m);
			Helper.CreateWhsOrderLine(order2, data.Part2, 4m);
			Helper.CreateWhsOrderLine(order2, part3, 1m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.WP_CartoniseSplitCases = true;
			pick.Orders.Add(order1);
			pick.Orders.Add(order2);

			pick.PickOrdersWithAllocationMock();
			AssertEquals("Precondition: Order is picked.", true, order1.IsAttachedToPickButNotFinalised);
			AssertEquals("Precondition: Order is picked.", true, order2.IsAttachedToPickButNotFinalised);

			// simulate Cartonisation, pack everything for each order in a BOX per order.
			var package1 = order1.PackageJob.Packages.AddNew("BOX");
			var package2 = order2.PackageJob.Packages.AddNew("BOX");

			foreach (var releaseLine in order1.PackableItemParents.Typed)
			{
				package1.Pack(releaseLine, releaseLine.Quantity);
				AssertEquals("Precondition: Release Line is Packed.", true, releaseLine.IsPacked);
			}

			foreach (var releaseLine in order2.PackableItemParents.Typed)
			{
				package2.Pack(releaseLine, releaseLine.Quantity);
				AssertEquals("Precondition: Release Line is Packed.", true, releaseLine.IsPacked);
			}

			pick.WP_IsCartonised = true;
			Factory.Save();

			// simulate Loading the Package View
			var poke = new[] { order1.PackageJob, order2.PackageJob }
				.SelectMany(pj => pj.GetAllPackagesOnJob().SelectMany(p => p.PackedItems.Typed)).ToArray();
			pick.CancelPackageLabelAllocations();

			AssertEquals("Precondition - all packages removed.", 0,
				new[] { order1.PackageJob, order2.PackageJob }.SelectMany(pj => pj.GetAllPackagesOnJob()).Count());

			var availableInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.SelectMany(o => o.AvailableInventories.Cast<WhsPickAvailableInventory>()).ToArray();
			var availableInventory1 = availableInventories.Single(avl => avl.PalletID == "PLT-123");
			var availableInventory2 = availableInventories.Single(avl => avl.ProductCode == "P1");
			var availableInventory3 = availableInventories.Single(avl => avl.ProductCode == "P2");
			var availableInventory4 = availableInventories.Single(avl => avl.PalletID == "PLT-456");

			// simulate Manual De-allocation & Allocation
			// we need to deallocate part3 first as its across two orders, followed by any other product on that same order. Exception will get thrown but we need to handle it properly.
			foreach (var availableInventory in new[]
				{ availableInventory1, availableInventory2, availableInventory3, availableInventory4 })
			{
				Assert("Precondition: Stock was allocated", availableInventory.PickLineQuantity > 0);
				availableInventory.PickLineQuantity = 0m;
				AssertEquals("Precondition: De-allocation successful", 0m, availableInventory.PickLineQuantity);
			}

			//var allOrderLines = new[] { order1, order2 }.SelectMany(o => o.Lines.Cast<WhsOrderLine>()).ToArray();
			//AssertEquals("Precondition - all release lines deleted.", 0, allOrderLines.Select(l => l.ReleaseLines.Count()).Sum());

			foreach (WhsPickAvailableInventory availableInventory in pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.SelectMany(o => o.AvailableInventories))
			{
				availableInventory.Allocate = true;
			}

			// simulate Saving the Form, there should be no errors from Release Lines on the Picking Slip form
			pick.RunPreSaveValidation();
			AssertNoErrors(pick);
			Factory.Save();
		}

