		#region TestOuterPackages

		public void TestOuterPackages()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var inventory = receive.Inventory[0];

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 5m);
			Factory.Save();

			var pick1 = Helper.CreatePickNew(order1);
			var pick2 = Helper.CreatePickNew();
			AssertEquals("Precondition", 0, pick1.OuterPackages.Count);
			AssertEquals("Precondition", 0, pick2.OuterPackages.Count);

			var outer = order1.PackageJob.Packages.AddNew();
			AssertEquals(1, pick1.OuterPackages.Count);
			AssertEquals(0, pick2.OuterPackages.Count);

			outer.Packages.AddNew();
			AssertEquals("Precondition", 1, outer.Packages.Count);
			AssertEquals("Should not include inners", 1, pick1.OuterPackages.Count);

			pick1.Orders.Add(order2);
			order2.PackageJob.Packages.AddNew();
			AssertEquals(2, pick1.OuterPackages.Count);
			AssertEquals(0, pick2.OuterPackages.Count);

			pick1.Orders.Remove(order1);
			AssertEquals(1, pick1.OuterPackages.Count);
			AssertEquals(0, pick2.OuterPackages.Count);
		}

