		#region TestOverrideFulfillmentRuleForOrders

		public void TestOverrideFulfillmentRuleForOrders()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			var order_WithoutShortfall = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", data.Notify);
			order_WithoutShortfall.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithoutShortfall, data.Part1, 10m);

			var order_WithShortfallAndNoneFullfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2", data.Notify);
			order_WithShortfallAndNoneFullfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.None;
			Helper.CreateWhsOrderLine(order_WithShortfallAndNoneFullfillment, data.Part1, 1000m);

			var order_WithShortfallAndAllFulfillment = Helper.CreateWhsOrder(data.Org1, data.Whs1, "3", data.Notify);
			order_WithShortfallAndAllFulfillment.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;
			Helper.CreateWhsOrderLine(order_WithShortfallAndAllFulfillment, data.Part1, 1000m);
			Factory.Save();

			Pick.Orders.AddRange(new[] { order_WithoutShortfall, order_WithShortfallAndNoneFullfillment,
				order_WithShortfallAndAllFulfillment });
			Pick.PickOrdersWithAllocationMock();
			AssertEquals("Precondition", PickStatus.Codes.Building, Pick.WP_PickStatus);

			Pick.OverrideFulfillmentRuleForOrders(new WhsOrder[] { order_WithShortfallAndAllFulfillment }, Notify);
			AssertEquals(WhsOrderFulfillmentRuleList.Codes.All, order_WithoutShortfall.WD_WhsOrderFulfillmentRule);
			AssertEquals(WhsOrderFulfillmentRuleList.Codes.None,
				order_WithShortfallAndNoneFullfillment.WD_WhsOrderFulfillmentRule);
			AssertEquals(WhsOrderFulfillmentRuleList.Codes.None,
				order_WithShortfallAndAllFulfillment.WD_WhsOrderFulfillmentRule);
			AssertEquals(PickStatus.Codes.Created, Pick.WP_PickStatus);
		}

