		#region TestSuspendBuildingAllReleaseLinesForPick

		public void TestSuspendBuildingAllReleaseLinesForPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 10m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine11 = Helper.CreateWhsOrderLine(order1, data.Part1, 4m);
			var orderLine12 = Helper.CreateWhsOrderLine(order1, data.Part2, 4m);
			var pick1 = Helper.CreatePickNew(order1);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine21 = Helper.CreateWhsOrderLine(order2, data.Part1, 6m);
			var orderLine22 = Helper.CreateWhsOrderLine(order2, data.Part2, 6m);
			var pick2 = Helper.CreatePickNew(order2);
			AssertEquals("Precondition: Release Lines not built.", false, orderLine11.IsReleaseLineCollectionBuilt);
			AssertEquals("Precondition: Release Lines not built.", false, orderLine12.IsReleaseLineCollectionBuilt);
			AssertEquals("Precondition: Release Lines not built.", false, orderLine21.IsReleaseLineCollectionBuilt);
			AssertEquals("Precondition: Release Lines not built.", false, orderLine22.IsReleaseLineCollectionBuilt);

			var poke1 = orderLine11.ReleaseLines;
			AssertEquals("All Release Lines on Pick should be built.", true, orderLine11.IsReleaseLineCollectionBuilt);
			AssertEquals("All Release Lines on Pick should be built.", true, orderLine12.IsReleaseLineCollectionBuilt);
			AssertEquals("Release Lines on other Pick should not be built.", false, orderLine21.IsReleaseLineCollectionBuilt);
			AssertEquals("Release Lines on other Pick should not be built.", false, orderLine22.IsReleaseLineCollectionBuilt);

			using (pick2.SuspendBuildingAllReleaseLinesForPick())
			{
				var poke2 = orderLine21.ReleaseLines;
				AssertEquals("Only poked collection should be built when building all release lines is suspended.", true,
					orderLine21.IsReleaseLineCollectionBuilt);
				AssertEquals("Only poked collection should be built when building all release lines is suspended.", false,
					orderLine22.IsReleaseLineCollectionBuilt);
				AssertEquals(nameof(pick2.IsBuildingAllReleaseLinesForPickSuspended), true,
					pick2.IsBuildingAllReleaseLinesForPickSuspended);
			}

			AssertEquals(nameof(pick2.IsBuildingAllReleaseLinesForPickSuspended), false,
				pick2.IsBuildingAllReleaseLinesForPickSuspended);
		}

