		#region TestFinaliseSelectedOrders

		public void TestFinaliseSelectedOrders()
		{
			TestDataForInventory data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();

			WhsOrder order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", Notify);
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m);

			WhsOrder order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", Notify);
			Helper.CreateWhsOrderLine(order2, data.Part1, 10m);

			WhsOrder order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3", Notify);
			Helper.CreateWhsOrderLine(order3, data.Part1, 10m);

			WhsOrder order4 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O4", Notify);
			Helper.CreateWhsOrderLine(order4, data.Part1, 10m);

			Pick = Helper.CreatePickNew(new WhsOrder[4] { order1, order2, order3, order4 });

			order1.WD_IsOrderSelectedForFinalisation = ZBool.True;
			order3.WD_IsOrderSelectedForFinalisation = ZBool.True;
			order4.WD_IsOrderSelectedForFinalisation = ZBool.True;

			order3.WD_RequiredDate =
				ZDateTimeOffset.Empty; // cause finalise validation error so order3 does not get finalised, to cover not clearing WD_IsOrderSelected if finalise fails

			AssertEquals("Precondition: Order1 should not be finalised", false, order1.IsFinalised);
			AssertEquals("Precondition: Order2 should not be finalised", false, order2.IsFinalised);
			AssertEquals("Precondition: Order3 should not be finalised", false, order3.IsFinalised);
			AssertEquals("Precondition: Order4 should not be finalised", false, order4.IsFinalised);

			Pick.FinaliseSelectedOrders();

			AssertEquals("Order1 should be finalised", true, order1.IsFinalised);
			AssertEquals("Order2 should not be finalised because it is not selected for finalise", false, order2.IsFinalised);
			AssertEquals("Order3 should not be finalised due to validation error", false, order3.IsFinalised);
			AssertEquals("Order4 should be finalised", true, order4.IsFinalised);

			AssertEquals(false, order1.WD_IsOrderSelectedForFinalisation);
			AssertEquals(false, order2.WD_IsOrderSelectedForFinalisation);
			AssertEquals(true, order3.WD_IsOrderSelectedForFinalisation);
			AssertEquals(false, order4.WD_IsOrderSelectedForFinalisation);

			AssertEquals("Pick HasErrors", true, pick.HasErrors);
		}

