		#region TestFinaliseAllOrders_WithAlreadyFinalisedOrders

		[TestDate(2020, 02, 02)]
		public void TestFinaliseAllOrders_WithAlreadyFinalisedOrders()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 1m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 1m);
			Factory.Save();

			// create pick
			var pick = Helper.CreatePickNew(order1, order2);
			Assert("Order1 should not be finalised", !order1.IsFinalised);
			Assert("Order2 should not be finalised", !order2.IsFinalised);

			order1.FinaliseDocketWithoutUserConfirmation();
			Assert("Order1 should be finalised", order1.IsFinalised);
			Assert("Order2 should not be finalised", !order2.IsFinalised);
			AssertEquals("Order1 should be finalised", new ZDateTime(2020, 02, 02), order1.WD_FinalisedDate.Date);
			AssertEquals("Order2 should not be finalised", ZDateTimeOffset.Empty, order2.WD_FinalisedDate);

			TestDateAttribute.AddDays(3);
			pick.FinaliseAllOrders();
			Assert("Order1 should be finalised", order1.IsFinalised);
			Assert("Order2 should be finalised", order2.IsFinalised);
			AssertEquals("Order1 finalised date should not have changed.", new ZDateTime(2020, 02, 02), order1.WD_FinalisedDate.Date);
			AssertEquals("Order2 should be finalised.", new ZDateTime(2020, 02, 05), order2.WD_FinalisedDate.Date);
		}

