			AssertEquals(false, order2.WD_IsOrderSelectedForFinalisation);
			AssertEquals(false, order3.WD_IsOrderSelectedForFinalisation);

			order1.WD_FinalisedDate = ZDateTimeOffset.Now;
			pick.SetSelectColumnForAllOrders(true);

			AssertEquals(false, order1.WD_IsOrderSelectedForFinalisation);
			AssertEquals(true, order2.WD_IsOrderSelectedForFinalisation);
			AssertEquals(true, order3.WD_IsOrderSelectedForFinalisation);

			order2.WD_DocketStatus = DocketStatus.Codes.Entered;
			order2.WD_DocketStatus = DocketStatus.Codes.Cancelled;
			pick.SetSelectColumnForAllOrders(false);

			AssertEquals(false, order1.WD_IsOrderSelectedForFinalisation);
			AssertEquals(true, order2.WD_IsOrderSelectedForFinalisation);
			AssertEquals(false, order3.WD_IsOrderSelectedForFinalisation);
		}

