		#region TestFinalisePick_WithReducedUnits

		[TestDate(2010, 4, 7, 11, 12, 13)]
		public void TestFinalisePick_WithReducedUnits()
		{
			var whs1 = Helper.CreateWarehouse("1", "A1", 2, 2);
			var whs2 = Helper.CreateWarehouse("2", "A2", 2, 2);

			var client1 = Helper.CreateClient("TEST1", "TEST1");
			var client2 = Helper.CreateClient("TEST2", "TEST2");
			var part1 = Helper.CreateProduct(client1, "1");
			var part2 = Helper.CreateProduct(client1, "2");
			var part3 = Helper.CreateProduct(client2, "3");

			// create inventory
			var receive1 = Helper.CreateWhsReceive(client1.PK, whs1.PK, "111", Notify);
			var receive2 = Helper.CreateWhsReceive(client1.PK, whs2.PK, "122", Notify);
			var receive3 = Helper.CreateWhsReceive(client2.PK, whs1.PK, "213", Notify);

			var receiveLine1 = Helper.CreateWhsReceiveInventoryLine(receive1, part1.PK, 100);
			Helper.CreateWhsReceiveInventoryLine(receive2, part2.PK, 100);
			Helper.CreateWhsReceiveInventoryLine(receive3, part3.PK, 100);

			receive1.AllocateLocationsWithMock();
			receive2.AllocateLocationsWithMock();
			receive3.AllocateLocationsWithMock();
			receive1.FinaliseDocket();
			receive2.FinaliseDocket();
			receive3.FinaliseDocket();

			// create order / pick
			var order1 = Helper.CreateWhsOrder(client1.PK, whs1.PK, client2.PK, "111", Notify);
			Helper.CreateWhsOrderLine(order1, part1.PK, 100);
			Factory.Save();

			Pick.WP_WW_Whs = whs1.PK;
			Pick.WP_PickStatus = PickStatus.Codes.Created;

			// set the order to be picked
			var ordersToPick = new WhsOrder[1];
			ordersToPick[0] = order1;

			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				// test for "no order lines" notification
				Pick.CreatePick_OBSOLETE(ordersToPick);
			}

			Factory.Save(); // needed for DBOnly query below
			var inventoryCollection = Helper.LoadInventory(client1, part1, whs1).Inventory;
			AssertEquals("Should have no units available", 0m, GetAvailableUnits(inventoryCollection));
			AssertEquals("Should have 100 units committed", 100m, GetCommittedUnits(inventoryCollection));

			// reduce units on pick + order
			Pick.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 20m;
			Pick.FinaliseOrder(order1);
			Pick.FinalisePick();
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, Pick.WP_FinalizedDateUtc);

			Factory.Save(); // needed for DBOnly query below
			AssertEquals("Should have no units available", 80m, GetAvailableUnits(inventoryCollection));
			AssertEquals("Should have no units committed", 0m, GetCommittedUnits(inventoryCollection));

			var invForLineFilter = new ZQuery(WhsInventoryViewSchema.WI_WE_InDocketLine, receiveLine1.InDocketLine.PK);
			var invForLineList = new WhsInventoryViewCollection(Factory, invForLineFilter);
			invForLineList.Load();
			decimal totalLineUnits = 0;
			foreach (WhsInventoryView inv in invForLineList)
			{
				totalLineUnits += inv.WI_InDocketLineUnits;
			}
			AssertEquals("InDocketLineUnits should not have changed", receiveLine1.InDocketLine.WE_TransactionQuantity,
				totalLineUnits);
		}

		ZDecimal GetAvailableUnits(IEnumerable<WhsInventoryView> inventoryCollection)
		{
			ZDecimal result = 0m;
			foreach (var inventory in inventoryCollection)
			{
				result += inventory.WI_TotalUnits - inventory.CommittedQuantityIncludingUnfinalisedReceipt;
			}
			return result;
		}

		ZDecimal GetCommittedUnits(IEnumerable<WhsInventoryView> inventoryCollection)
		{
			ZDecimal result = 0m;
			foreach (var inventory in inventoryCollection)
			{
				result += inventory.CommittedQuantityIncludingUnfinalisedReceipt;
			}
			return result;
		}

