		#region TestFinalisePick_WaitingReplenishment_FailsIfInTransitTransferFailsFinalisation

		public void TestFinalisePick_WaitingReplenishment_FailsIfInTransitTransferFailsFinalisation()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, pickFaceLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var replenTransfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var replenTransferLine = Helper.CreateWhsTransferLine(replenTransfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			replenTransferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, replenTransfer.IsFinalised);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition: partially alllocated.", 10m, orderLine.PickLineQuantity);
			AssertEquals("Precondition: pick is waiting replenishment.", true, pick.WP_IsAwaitingReplenishment);

			var pickLine = orderLine.PickLines.Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			Factory.Save();
			AssertEquals("Precondition: In-Transit Transfer created.", 1, pick.Transfers.Count);

			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order);

			var transfer = pick.Transfers.Single();
			var transferLine = transfer.Lines.Single();
			transferLine.WE_DocketLineStatusInfo.ValueChanged += (sender, e) => transferLine.AddRowError("Test"); // create finalisation error.
			pick.FinalisePick();
			AssertEquals("Pick should not be finalised.", false, pick.IsFinalised);
			AssertEquals("WP_FinalizedDateUtc is null", ZDateTime.Empty, pick.WP_FinalizedDateUtc);
			AssertEquals("Pick should *not* have cleared the WaitingReplenishment flag.", true, pick.WP_IsAwaitingReplenishment);
			AssertEquals("In-Transit transfer should not be finalised.", false, transfer.IsFinalised);
			AssertHasError(pick.StatusDescInfo, "Unable to Finalize Pick because of the following Errors when attempting to finalize all In-Transit Transfers:\r\nError - Docket Line: Test");
			AssertEquals("Should not have Finalised Event if Transfer finalisation failed.", 0, pick.Logs.Find(l => l.SL_SE_NKEvent == Events.ItemDocumentJobFinalisedCode).Count());
		}

