		#region TestFinalisePick_SetsPickedTime

		public void TestFinalisePick_SetsPickedTime()
		{
			var staff = Helper.CreateGlbStaff("AA", "Antman");
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", data.Part2, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition: OrderLine is Picked.", 20m, orderLine1.PickLineQuantity);
			AssertEquals("Precondition: OrderLine is Picked.", 10m, orderLine2.PickLineQuantity);
			AssertEquals("Precondition: OrderLine is Picked.", 2, orderLine1.PickLines.Count);
			AssertEquals("Precondition: OrderLine is Picked.", 1, orderLine2.PickLines.Count);

			var today = data.Whs1.GetWarehouseBranchDateTimeOffset(ZDateTime.Today);
			orderLine1.PickLines[0].WZ_GS_NKAssignedTo = "ZZ"; // assign Pick Line but don't pick

			var orderLinePickedTime = today.AddDays(-2);
			orderLine2.PickLines.Single().WZ_PickedDateTime = orderLinePickedTime; // pick Pick Line
			order.FinaliseDocket();
			AssertIsFinalisedPrecondition(order);
			AssertEquals("OrderLine is not Picked.", true, orderLine1.PickLines.All(pl => pl.WZ_PickedDateTime.IsEmpty));
			AssertEquals("Previously Picked OrderLine still has previous Picked Time.", true,
				orderLine2.PickLines.All(pl => pl.WZ_PickedDateTime == orderLinePickedTime));

			using (Env.SetTemporaryUserContext(staff.PK.ToGuid(), Env.CurrentBranchPK, Env.CurrentDepartmentPK))
			{
				Env.Security.WhsReleaseFinalise.IsAllowed = true; // allow user to finalise pick
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
			}

			var finalisedLog = pick.Logs.Find(l => l.SL_SE_NKEvent == Events.ItemDocumentJobFinalisedCode).Single();
			AssertEquals("OrderLine should be Picked when Pick is finalised.", 1,
				orderLine1.PickLines.Count(pl => pl.WZ_GS_NKAssignedTo == "ZZ" &&
													pl.WZ_PickedDateTime.Date == finalisedLog.SL_EventTime.Date)); // don't override picker
			AssertEquals("OrderLine should be Picked when Pick is finalised.", 1,
				orderLine1.PickLines.Count(pl => pl.WZ_GS_NKAssignedTo == "AA" &&
													pl.WZ_PickedDateTime.Date == finalisedLog.SL_EventTime.Date));
			AssertEquals("Previously Picked OrderLine still has previous Picked Time.", true,
				orderLine2.PickLines.All(pl => pl.WZ_PickedDateTime == orderLinePickedTime));

			var expectedFinalisedDate = new ZDateTimeOffset(finalisedLog.SL_EventTime, today.Offset).ToUtcDateTime();
			AssertEquals("WP_FinalizedDateUtc is correct", expectedFinalisedDate.ToString("yyyy-MM-dd HH:mm"), pick.WP_FinalizedDateUtc.ToString("yyyy-MM-dd HH:mm"));

			AssertEquals("WP_GS_NKFinalizedBy should be set on finalization.", "AA", pick.WP_GS_NKFinalizedBy);
		}

