		#region TestFinalisePick_FinalDoubleCheckOfQuantitiesAgainstLowLevelPersistentBusinessObjects

		public void TestFinalisePick_FinalDoubleCheckOfQuantitiesAgainstLowLevelPersistentBusinessObjects()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines(10m, 20m, 30m, 40m, 50m);

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			Helper.CreateWhsOrderLine(order1, data.Part1, 20m);
			Helper.CreateWhsOrderLine(order2, data.Part1, 30m);
			Helper.CreateWhsOrderLine(order2, data.Part1, 90m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order1);
			pick.Orders.Add(order2);

			pick.AutoAllocateItemsWithMock();
			var poke1 = order1.Lines.Cast<WhsPickableDocketLine>().Select(l => l.ReleaseLines.Count).ToArray();
			var poke2 = order2.Lines.Cast<WhsPickableDocketLine>().Select(l => l.ReleaseLines.Count).ToArray();

			pick.GetAllPickLines().Last().Delete();
			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order1);
			AssertIsFinalisedPrecondition(order2);

			try
			{
				pick.OrderedInventories.SuspendValidation();
				pick.FinalisePick();
				AssertEquals(true, pick.HasErrors);
				AssertHasRowError(pick, "Cannot Finalize this Pick because Quantity Met does not equal Quantity Picked");
				AssertEquals("WP_FinalizedDateUtc is null since finalisation failed", ZDateTime.Empty, pick.WP_FinalizedDateUtc);
			}
			finally
			{
				pick.OrderedInventories.ResumeValidation();
			}
		}

