		public void TestFinalisePick_FailsOnIncorrectCommittedStockQuantities()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var factory2 = new BusinessObjectFactory();
			var helperInFactory2 = new WhsTestHelperFunctions(factory2);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 100m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			// Create 2 Orders in different Factories and allocate the same inventory to both.

			// Order 1
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "OR1", data.Part1, 100m,
				WhsPickOption.Codes.Manual);
			var pick = Helper.CreatePickNew(order);
			pick.AutoAllocateItemsWithMock();
			var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(pick);
			AssertEquals("Precondition - Auto-Allocation failed.", 100m, totalPickLineQuantity);

			// Order 2
			var orderInFactory2 =
				helperInFactory2.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "OR2", data.Part1, 50m,
					WhsPickOption.Codes.Manual);
			var pickInFactory2 = helperInFactory2.CreatePickNew(orderInFactory2);
			pickInFactory2.AutoAllocateItemsWithMock();
			var totalPickLineQuantityInFactory2 = Helper.GetTotalPickLineQuantity(pickInFactory2);
			AssertEquals("Precondition - Auto-Allocation failed.", 50m, totalPickLineQuantityInFactory2);

			// save order 1, then attempt to validate order 2 (order 2 should be in error)
			pick.Validation.ValidateAll();
			AssertEquals("Pick should have no errors.", false, pick.HasErrors());
			Factory.Save();

			pickInFactory2.Validation.ValidateAll();
			AssertEquals("Stock is committed to another pick - this pick should therefore have failed validation.", true,
				pickInFactory2.HasErrors());

			pickInFactory2.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(orderInFactory2);
			pickInFactory2.FinalisePick();
			AssertEquals(
				"Since more stock was committed than available, should not allow finalize pick until the problem is resolved.",
				false, pickInFactory2.IsFinalised);
			AssertEquals(true, pickInFactory2.HasErrors());
			AssertEquals("WP_FinalizedDateUtc is null since finalisation failed", ZDateTime.Empty, pickInFactory2.WP_FinalizedDateUtc);
		}

