		#region TestFinalisePick_DeletesEmptyPackageJobs_AndUpdatesPackingReadOnly

		[TestDate(2017, 2, 7, 6, 21, 31)]
		public void TestFinalisePick_DeletesEmptyPackageJobs_AndUpdatesPackingReadOnly()
		{
			var loadPackageJob =
				new Func<WhsOrder, PkgPackageJob>(
					(o) => Factory.LoadFromUniqueKey<PkgPackageJob>(PkgPackageJobSchema.KJ_ParentID, o.PK));
			var data = new TestDataSimpleEnvironment(Factory);
			Factory.Save();

			// create 2 orders
			var orderNoPackages = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var orderWithPackages = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			orderNoPackages.WD_ExternalReference = "1";
			orderNoPackages.WD_ExternalReference = "2";
			AssertNull("Precondition - PackageJob should not exist.", loadPackageJob(orderNoPackages));
			AssertNull("Precondition - PackageJob should not exist.", loadPackageJob(orderWithPackages));

			// pick the orders
			var pick = Helper.CreatePickNew(orderNoPackages, orderWithPackages);
			AssertEquals("Precondition - Pick should have been created.", true, orderNoPackages.IsAttachedToPickButNotFinalised);
			AssertNotNull("Precondition - PackageJob should have been created.", loadPackageJob(orderNoPackages));
			AssertNotNull("Precondition - PackageJob should have been created.", loadPackageJob(orderWithPackages));

			// add a package to one of the orders
			orderWithPackages.PackageJob.Packages.AddNew("PLT");

			// finalise the orders
			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(orderNoPackages);
			AssertIsFinalisedPrecondition(orderWithPackages);
			Factory.Save(); // to prove non-deletion
			AssertNotNull("Precondition - PackageJob should still exist.", loadPackageJob(orderNoPackages));
			AssertNotNull("Precondition - PackageJob should still exist.", loadPackageJob(orderWithPackages));
			AssertEquals(false, loadPackageJob(orderNoPackages).ReadOnly);
			AssertEquals(false, loadPackageJob(orderWithPackages).ReadOnly);

			// finalise the pick
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(pick);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick.WP_FinalizedDateUtc);
			Factory.Save();
			AssertNull("The PackageJob was unused and should have been deleted on Finalise Pick.",
				loadPackageJob(orderNoPackages));
			AssertNotNull("The PackageJob was in use and should *not* have been deleted on Finalise Pick.",
				loadPackageJob(orderWithPackages));
			AssertEquals("Finalise Pick should have notified Packing to re-evaluate Packing ReadOnly.", true,
				loadPackageJob(orderWithPackages).ReadOnly);
		}

