		#region TestFinalisePick_DoesNotSaveIfPickLineQuantityModifiedInOtherFactory

		[TestDate(2017, 2, 7, 6, 21, 31)]
		public void TestFinalisePick_DoesNotSaveIfPickLineQuantityModifiedInOtherFactory()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 2);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Factory.Save();
			var inventory = receive.Inventory.ToList<WhsInventoryView>();
			AssertIsFinalisedPrecondition(receive);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			pick.IsAlterPick = true;
			var availableInventory = pick.OrderedInventories[0].AvailableInventories[0];
			AssertEquals("Precondition", 5m, availableInventory.PickLineQuantity);
			AssertEquals("Precondition", 5m, pick.OrderedInventories[0].PickLineQuantity);
			Factory.Save();

			AssertEquals("Should have 95 units available", 95m, GetAvailableUnits(inventory));
			AssertEquals("Should have 5 units committed", 5m, GetCommittedUnits(inventory));

			pick.FinaliseOrder(order);
			pick.FinalisePick();
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick.WP_FinalizedDateUtc);

			AssertEquals("Should have 95 units available", 95m, GetAvailableUnits(inventory));
			AssertEquals("Should have 0 units committed", 0m, GetCommittedUnits(inventory));

			var otherFactory = new BusinessObjectFactory();
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			// change the PickLineQuantity after the Pick is being finalised in another factory.
			pickInOtherFactory.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 2m;
			otherFactory.Save();
			AssertEquals("WP_FinalizedDateUtc is null since finalisation isn't saved", ZDateTime.Empty, pickInOtherFactory.WP_FinalizedDateUtc);

			var exceptionThrown = AssertExceptionThrown<ZSaveConcurrencyException>(Factory.Save);
			AssertContains("WP_FinalizedDateUtc", exceptionThrown.Message);
			AssertEquals(pick, exceptionThrown.BusinessObjects.Single());

			var otherFactory2 = new BusinessObjectFactory();
			var pickInOtherFactory2 = otherFactory.Load<WhsPick>(pick.PK);
			AssertEquals("WP_FinalizedDateUtc is null since save failed", ZDateTime.Empty, pickInOtherFactory2.WP_FinalizedDateUtc);
		}

		#endregion

		#region TestFinalisePick_DoesNotSaveIfDetachAnfdReAttachOrderInOtherFactory

		[TestDate(2017, 2, 7, 6, 21, 31)]
		public void TestFinalisePick_DoesNotSaveIfDetachAnfdReAttachOrderInOtherFactory()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 2);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Factory.Save();
			var inventory = receive.Inventory.ToList<WhsInventoryView>();
			AssertIsFinalisedPrecondition(receive);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order1, order2);
			pick.IsAlterPick = true;
			var availableInventory = pick.OrderedInventories[0].AvailableInventories[0];
			AssertEquals("Precondition", 15m, availableInventory.PickLineQuantity);
			AssertEquals("Precondition", 15m, pick.OrderedInventories[0].PickLineQuantity);
			Factory.Save();

			AssertEquals("Should have 85 units available", 85m, GetAvailableUnits(inventory));
			AssertEquals("Should have 15 units committed", 15m, GetCommittedUnits(inventory));

			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick.WP_FinalizedDateUtc);

			AssertEquals("Should have 85 units available", 85m, GetAvailableUnits(inventory));
			AssertEquals("Should have 0 units committed", 0m, GetCommittedUnits(inventory));

			var otherFactory = new BusinessObjectFactory();
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			var availableInventoryInOtherFactory = pickInOtherFactory.OrderedInventories[0].AvailableInventories[0];
			var order2InOtherFactory = otherFactory.Load<WhsOrder>(order2.PK);
			// detach order after the Pick is being finalised in another factory.
			pickInOtherFactory.Orders.Remove(order2InOtherFactory);
			AssertEquals("Precondition", 5m, availableInventoryInOtherFactory.PickLineQuantity);
			AssertEquals("Precondition", 5m, pickInOtherFactory.OrderedInventories[0].PickLineQuantity);
			otherFactory.Save();
			// re-attach
			var orderReAttached = otherFactory.Load<WhsOrder>(order2.PK);
			pickInOtherFactory.Orders.Add(orderReAttached);
			AssertEquals("Precondition", 5m, availableInventoryInOtherFactory.PickLineQuantity);
			AssertEquals("Precondition", 5m, pickInOtherFactory.OrderedInventories[0].PickLineQuantity);
			otherFactory.Save();

			var exceptionThrown = AssertExceptionThrown<ZSaveConcurrencyException>(Factory.Save);
			AssertContains("WP_FinalizedDateUtc", exceptionThrown.Message);
			AssertEquals(pick, exceptionThrown.BusinessObjects.Single());

			var otherFactory2 = new BusinessObjectFactory();
			var pickInOtherFactory2 = otherFactory.Load<WhsPick>(pick.PK);
			AssertEquals("WP_FinalizedDateUtc is null since save failed", ZDateTime.Empty, pickInOtherFactory2.WP_FinalizedDateUtc);
		}

