		#region TestFinalisePick_FinalisesInTransitTransfers

		public void TestFinalisePick_FinalisesInTransitTransfers()
		{
			var staff = Helper.CreateGlbStaff("AA", "Antman");
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var now = data.Whs1.GetWarehouseBranchDateTimeOffset(ZDateTime.Now);
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			var pickLine = orderLine.PickLines.Single();
			pickLine.WZ_PickedDateTime = now;
			Factory.Save();
			AssertEquals("Precondition: In-Transit Transfer created.", 1, pick.Transfers.Count);

			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order);

			using (Env.SetTemporaryUserContext(staff.PK.ToGuid(), Env.CurrentBranchPK, Env.CurrentDepartmentPK))
			{
				Env.Security.WhsReleaseFinalise.IsAllowed = true; // allow user to finalise pick
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
			}

			var finalisedLog = pick.Logs.Find(l => l.SL_SE_NKEvent == Events.ItemDocumentJobFinalisedCode).Single();

			var transfer = pick.Transfers.Single();
			AssertEquals("In-Transit transfer should be finalised.", true, transfer.IsFinalised);
			AssertEquals("Transfer Finalise Time should be Pick Finalisation Time.", ZDateTime.TruncateSeconds(finalisedLog.SL_EventTime), ZDateTime.TruncateSeconds(transfer.WD_FinalisedDate.ToZDateTime()));

			var transferLine = transfer.Lines.Single();
			AssertEquals("Transfer Finalise Time should be Pick Finalisation Time.", ZDateTime.TruncateSeconds(finalisedLog.SL_EventTime), ZDateTime.TruncateSeconds(transferLine.WE_FinalisedDate.ToZDateTime()));
			AssertEquals("Transfer Putaway Time should be Pick Finalisation Time.", transferLine.WE_FinalisedDate, ZDateTimeOffset.TruncateMilliseconds(transferLine.WE_PutawayTime));
			AssertEquals("Transfer Putaway By should be user who finalised the Pick.", "AA", transferLine.WE_GS_NKPutawayBy);

			var expectedFinalisedDate = new ZDateTimeOffset(finalisedLog.SL_EventTime, now.Offset).ToUtcDateTime();
			AssertEquals("WP_FinalizedDateUtc is correct", expectedFinalisedDate.ToString("yyyy-MM-dd HH:mm"), pick.WP_FinalizedDateUtc.ToString("yyyy-MM-dd HH:mm"));
			AssertNoExceptionThrown(() => Factory.Save());
		}

		#endregion

