		#region TestFinalisePick_SomeTransferLinesAlreadyFinalised

		[TestDate(2017, 2, 7, 6, 21, 31)]
		public void TestFinalisePick_SomeTransferLinesAlreadyFinalised()
		{
			var staff1 = Helper.CreateGlbStaff("AA", "Antman");
			var staff2 = Helper.CreateGlbStaff("BB", "Bob");
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			var pickLine = orderLine.PickLines.Single();

			using (Env.SetTemporaryUserContext(staff2.PK.ToGuid(), Env.CurrentBranchPK, Env.CurrentDepartmentPK))
			{
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			}

			Factory.Save();
			AssertEquals("Precondition: In-Transit Transfer created.", 1, pick.Transfers.Count);

			var transferLine = pick.Transfers.Single().Lines[0];
			transferLine.FinaliseDocketLine();
			AssertIsFinalisedPrecondition(transferLine);
			AssertEquals("Precondition: Transfer Line is putaway by staff 2.", staff2.GS_Code, transferLine.WE_GS_NKPutawayBy);

			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order);

			using (Env.SetTemporaryUserContext(staff1.PK.ToGuid(), Env.CurrentBranchPK, Env.CurrentDepartmentPK))
			{
				Env.Security.WhsReleaseFinalise.IsAllowed = true; // allow user to finalise pick
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
			}

			AssertEquals("Putaway By should not be updated for previously finalised Transfer Lines.", staff2.GS_Code, transferLine.WE_GS_NKPutawayBy);
			AssertNoExceptionThrown(() => Factory.Save());
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick.WP_FinalizedDateUtc);
		}

