		#region TestFinalisePick_SomeTransferLinesAlreadyFinalised_DestinationLocation

		[TestDate(2017, 2, 7, 6, 21, 31)]
		public void TestFinalisePick_SomeTransferLinesAlreadyFinalised_DestinationLocation()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var dockDoorLocationType = Helper.CreateLocationType("XYZ", "Test", false, 0, LocationClasses.Codes.DDL);
			var newRow = Helper.CreateRowAndGenerateLocations(data.Whs1, "D");
			var otherDDL = newRow.Locations[0];
			otherDDL.WLV_WLT_LocationType = dockDoorLocationType.PK;

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 1m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 1m);
			var orderLine3 = Helper.CreateWhsOrderLine(order, data.Part1, 1m);

			var pick = Helper.CreatePickNew(order);
			pick.WP_WL_DockDoor = otherDDL.PK;
			pick.GetAllPickLines().ForEach(pl => pl.WZ_PickedDateTime = ZDateTimeOffset.Now);
			Factory.Save();
			AssertEquals("Precondition: In-Transit Transfer created.", 1, pick.Transfers.Count);

			var transfer = pick.Transfers.Single();
			var transferLine1 = transfer.Lines[0];
			var transferLine2 = transfer.Lines[1];
			var transferLine3 = transfer.Lines[2];

			transferLine1.WE_WL = data.Whs1.WW_DefaultOutboundDockDoor;
			transferLine2.WE_WL = data.Whs1.WW_DefaultOutboundDockDoor;
			transferLine3.WE_WL = ZGuid.Empty;
			AssertEquals("Precondition: Destination Location is the default outbound dock door.", data.Whs1.WW_DefaultOutboundDockDoor, transferLine1.WE_WL);
			AssertEquals("Precondition: Destination Location is the default outbound dock door.", data.Whs1.WW_DefaultOutboundDockDoor, transferLine2.WE_WL);
			AssertEquals("Precondition: Empty Destination Location.", true, transferLine3.WE_WL.IsEmpty);

			transferLine1.FinaliseDocketLine();
			AssertIsFinalisedPrecondition(transferLine1);

			pick.WP_WL_DockDoor = otherDDL.PK;
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(order);
			AssertEquals("Pick is finalised (this would have failed prior to the fix in this shelf).", true, pick.IsFinalised);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick.WP_FinalizedDateUtc);
			AssertEquals("In-Transit transfer should be finalised.", true, transfer.IsFinalised);
			AssertEquals("Destination Location remains the default outbound dock door on the line that was already finalised (we didn't change it).", data.Whs1.WW_DefaultOutboundDockDoor, transferLine1.WE_WL);
			AssertEquals("Destination Location was set to the pick's outbound dock door.", otherDDL.PK, transferLine2.WE_WL);
			AssertEquals("Destination Location was set to the pick's outbound dock door.", otherDDL.PK, transferLine3.WE_WL);
		}

