		#region TestFinalisePick_SetDepartedStatusOnOrdersAndOrderLines

		public void TestFinalisePick_SetDepartedStatusOnOrdersAndOrderLines()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", data.Part2, 10m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderline1 = Helper.CreateWhsOrderLine(order1, data.Part1, 2m);
			var orderline2 = Helper.CreateWhsOrderLine(order1, data.Part1, 3m);
			var orderline3 = Helper.CreateWhsOrderLine(order1, data.Part1, 5m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine4 = Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			var pick = Helper.CreatePickByAttachingOrders(order1, order2);
			pick.AutoAllocateItemsWithMock();

			orderline1.PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Now;

			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3");
			var orderLine5 = Helper.CreateWhsOrderLine(order3, data.Part2, 10m);

			pick.AddOrders(new[] { order3 });

			AssertEquals("Precondition: Order1 status correct", DocketStatus.Codes.Picking, order1.WD_DocketStatus);
			AssertEquals("Precondition: Order2 status correct", DocketStatus.Codes.AttachedToPick, order2.WD_DocketStatus);
			AssertEquals("Precondition: Order3 status correct", DocketStatus.Codes.AttachedToPick, order3.WD_DocketStatus);
			AssertEquals("Precondition: Order3 has not picklines", 0, orderLine5.PickLines.Count);

			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(pick);

			AssertEquals("Order1 status correct", WhsOrderStatus.Codes.Departed, order1.WD_DocketStatus);
			AssertEquals("Order2 status correct", WhsOrderStatus.Codes.Departed, order2.WD_DocketStatus);
			AssertEquals("Order3 status correct", WhsOrderStatus.Codes.Departed, order3.WD_DocketStatus);

			AssertNoExceptionThrown(Factory.Save);
			var newFactory = new BusinessObjectFactory();
			var order1InDB = newFactory.Load<WhsDocket>(order1.PK);
			var order2InDB = newFactory.Load<WhsDocket>(order2.PK);
			var order3InDB = newFactory.Load<WhsDocket>(order3.PK);
			AssertEquals("Order1 status saved correctly", WhsOrderStatus.Codes.Departed, order1.WD_DocketStatus);
			AssertEquals("Order2 status saved correctly", WhsOrderStatus.Codes.Departed, order2.WD_DocketStatus);
			AssertEquals("Order3 status saved correctly", WhsOrderStatus.Codes.Departed, order3.WD_DocketStatus);
			var orderLine1InDB = order1InDB.Lines[0];
			var orderLine2InDB = order1InDB.Lines[1];
			var orderLine3InDB = order1InDB.Lines[2];
			var orderLine4InDB = order2InDB.Lines[0];
			var orderLine5InDB = order3InDB.Lines[0];
			AssertEquals("OrderLine1 status saved correctly", DocketLineStatus.Codes.Departed, orderLine1InDB.WE_DocketLineStatus);
			AssertEquals("OrderLine2 status saved correctly", DocketLineStatus.Codes.Departed, orderLine2InDB.WE_DocketLineStatus);
			AssertEquals("OrderLine3 status saved correctly", DocketLineStatus.Codes.Departed, orderLine3InDB.WE_DocketLineStatus);
			AssertEquals("OrderLine4 status saved correctly", DocketLineStatus.Codes.Departed, orderLine4InDB.WE_DocketLineStatus);
			AssertEquals("OrderLine5 status saved correctly", DocketLineStatus.Codes.Departed, orderLine5InDB.WE_DocketLineStatus);
		}

		public void TestFinalisePick_SetDepartedStatusOnOrdersAndOrderLines_PickByBOMOrder()
		{
			var data = new TestDataSimpleEnvironment(Helper.Factory, 2, 1);
			var staff = Helper.CreateGlbStaff("OP1", "Test1");
			Helper.Factory.Save();

			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			Helper.CreateProductBOM(bike, wheel, 2m, PkgUnit.Unit);
			Helper.CreateProductBOM(bike, frame, 1m, PkgUnit.Unit);

			var receive1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive1, wheel, 10m, data.Whs1.FindLocation("A-1"));
			Helper.CreateWhsReceiveInventoryLine(receive1, frame, 10m, data.Whs1.FindLocation("A-1"));
			receive1.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive1);

			var pick = Helper.Factory.New<WhsPick>();
			pick.WP_WW_Whs = data.Whs1.PK;
			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultInboundDockDoor;
			pick.WP_PickOption = WhsPickOption.Codes.Manual;
			Helper.Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", pickOption: WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, bike, 5m);

			pick.AddOrders(new[] { order });
			pick.AutoAllocateItemsWithMock(); // Mock rules with FIFO, we are testing the higher level BOM parts
			Helper.Factory.Save();

			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(pick);
			AssertNoExceptionThrown(Factory.Save);
			var newFactory = new BusinessObjectFactory();
			var orderInDB = newFactory.Load<WhsDocket>(order.PK);
			AssertEquals("Order status saved correctly", WhsOrderStatus.Codes.Departed, order.WD_DocketStatus);
			var orderLineInDB = (WhsOrderLine)orderInDB.Lines.Single(l => l.WE_OP == bike.PK);
			AssertEquals("OrderLine status saved correctly", DocketLineStatus.Codes.Departed, orderLineInDB.WE_DocketLineStatus);
			var wheelComponentLine = orderLineInDB.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var frameComponentLine = orderLineInDB.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			AssertEquals("Component lines status saved correctly", DocketLineStatus.Codes.Departed, wheelComponentLine.WE_DocketLineStatus);
			AssertEquals("Component lines status saved correctly", DocketLineStatus.Codes.Departed, frameComponentLine.WE_DocketLineStatus);
		}

