		#region TestFinalisePick_CreateBackOrders_FinaliseContinuouslyBackOrders

		[TestDate(2007, 3, 16, 9, 15, 13)]
		public void TestFinalisePick_CreateBackOrders_FinaliseContinuouslyBackOrders()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			data.Org1.MiscServ.OM_WhsGenerateBackOrdersOnShortfalls = ZBool.True;
			data.Org1.MiscServ.OM_WhsIsRecalculateOrderPricing = ZBool.True;

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", Notify);
			order.WD_TotalWeight = 10;
			order.WD_TotalCubic = 20;
			data.Part1.OP_Weight = 5;
			data.Part1.OP_Cubic = 10;
			var orderline = Helper.CreateWhsOrderLine(order, data.Part1, 300m);
			orderline.WE_UnitPriceAfterDiscount = 5m;

			var pick1 = Helper.CreatePickNew(order);
			pick1.FinaliseAllOrders();
			pick1.FinalisePick();
			AssertEquals("Order should be finalised", true, order.IsFinalised);
			AssertEquals("Pick should be finalised", true, pick1.IsFinalised);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick1.WP_FinalizedDateUtc);

			var factoryWhsOrders = Factory.Load<WhsOrder>(new ZQuery(WhsDocketSchema.WD_DocketType, DocketType.Codes.Order));
			var backOrder1 = order.RelatedBackOrder;
			AssertNotNull("Back Order should be created", backOrder1);
			AssertContainsExactElementsInAnyOrder("Base Order and BackOrder should stay in DB", new[] { order, backOrder1 },
				factoryWhsOrders);
			AssertPropertiesSetCorrectly(backOrder1, order.PK, order.WD_ExternalReference, 1, 200m, 1000m);
			AssertEquals(1000m, backOrder1.WD_TotalWeight);
			AssertEquals(2000m, backOrder1.WD_TotalCubic);

			var receive2 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive2, data.Part1, 100m);
			receive2.AllocateLocationsWithMock();
			receive2.FinaliseDocket();
			Factory.Save();
			AssertEquals("Receive should be finalised", true, receive2.IsFinalised);

			var pick2 = Helper.CreatePickNew(backOrder1);
			pick2.FinaliseAllOrders();
			pick2.FinalisePick();
			AssertEquals("BackOrder should be finalised", true, backOrder1.IsFinalised);
			AssertEquals("Pick should be finalised", true, pick2.IsFinalised);
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick2.WP_FinalizedDateUtc);

			factoryWhsOrders = Factory.Load<WhsOrder>(new ZQuery(WhsDocketSchema.WD_DocketType, DocketType.Codes.Order));
			var backOrder2 = backOrder1.RelatedBackOrder;
			AssertNotNull("Back Order should be created", backOrder2);
			AssertContainsExactElementsInAnyOrder("Base Order and both BackOrders should stay in DB",
				new[] { order, backOrder1, backOrder2 }, factoryWhsOrders);
			AssertPropertiesSetCorrectly(backOrder2, backOrder1.PK, backOrder1.WD_ExternalReference, 2, 100m, 500m);
			AssertEquals(500m, backOrder2.WD_TotalWeight);
			AssertEquals(1000m, backOrder2.WD_TotalCubic);
		}

