		#region TestFinalisePick_CreateBackOrders_WithCorrectExternalReferenceSplit

		[TestDate(2011, 4, 6, 8, 52, 53)]
		public void TestCreateBackOrder_WithCorrectExternalReferenceSplit()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Org1.MiscServ.OM_WhsGenerateBackOrdersOnShortfalls = true;
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);

			// Original Order
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 300m);
			Factory.Save();

			var pick1 = Helper.CreatePickNew(order);
			pick1.FinaliseAllOrders();
			pick1.FinalisePick();
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick1.WP_FinalizedDateUtc);
			AssertIsFinalisedPrecondition(order);

			// Create first Back Order
			var allOrders1 = Factory.Load<WhsOrder>(new ZQuery(WhsDocketSchema.WD_DocketType, DocketType.Codes.Order));
			var backOrder1 = order.RelatedBackOrder;
			AssertNotNull("Back Order should be created.", backOrder1);
			AssertPropertiesSetCorrectly(backOrder1, order.PK, order.WD_ExternalReference, 1, 200m);
			AssertContainsExactElementsInAnyOrder("Order and Back Order should be saved to DB.", new[] { order, backOrder1 },
				allOrders1);

			// Create second Back Order
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 100m);
			Factory.Save();

			var pick2 = Helper.CreatePickNew(backOrder1);
			pick2.FinaliseAllOrders();
			pick2.CreateBackOrder(backOrder1);
			AssertIsFinalisedPrecondition(backOrder1);

			var allOrders2 = Factory.Load<WhsOrder>(new ZQuery(WhsDocketSchema.WD_DocketType, DocketType.Codes.Order));
			var backOrder2 = backOrder1.RelatedBackOrder;
			AssertNotNull("Second Back Order should be created.", backOrder2);
			AssertPropertiesSetCorrectly(backOrder2, backOrder1.PK, backOrder1.WD_ExternalReference, 2, 100m);
			AssertContainsExactElementsInAnyOrder("Order and 2 Back Orders should be saved to DB.",
				new[] { order, backOrder1, backOrder2 }, allOrders2);

			// Re-finalise original Order
			var ordersCount = allOrders2.Length;
			order.FinaliseDocket();
			AssertIsFinalisedPrecondition(order);

			var allOrders3 = Factory.Load<WhsPickableDocket>(new ZQuery(WhsDocketSchema.WD_DocketType, DocketType.Codes.Order));
			var backOrder3 = order.RelatedBackOrder;
			AssertEquals("No new Back Orders should be created because backOrder1 was already finalised", backOrder1,
				backOrder3);
			AssertEquals("Orders count should stay as it was", ordersCount, allOrders3.Length);

			// try to cancel pick from first back order, then create back order again
			backOrder2.WD_DocketSubType = OrderType.Codes.Order;
			pick2.CancelPick();

			var pick2_2 = Helper.CreatePickNew(backOrder1);
			pick2_2.FinaliseAllOrders();
			pick2_2.FinalisePick();
			AssertEquals("WP_FinalizedDateUtc is correct", ZDateTime.UtcNow, pick2_2.WP_FinalizedDateUtc);
			AssertIsFinalisedPrecondition(backOrder1);

			var allOrders4 =
				Factory.Load<WhsPickableDocket>(new ZQuery(WhsDocketSchema.WD_DocketType, CodeLists.DocketType.Codes.Order));
			var backOrder4 = backOrder1.RelatedBackOrder;
			AssertNotNull("Third Back Order should be created.", backOrder4);
			AssertPropertiesSetCorrectly(backOrder4, backOrder1.PK, backOrder1.WD_ExternalReference, 3,
				100m); // should get a new WD_ExternalReferenceSplit
			AssertContainsExactElementsInAnyOrder("Order and 3 Back Orders should be saved to DB.", allOrders4,
				new[] { order, backOrder1, backOrder2, backOrder4 });
		}

