		#region TestFinalisePick_SplitByInventoryAllocated
		void TestSplitByInventoryAllocatedCore(Action<WhsOrder, WhsPick> saveAction)
		{
			var client = Helper.CreateClient("Client");
			var product = Helper.CreateProduct("P1", client);
			var whs = Helper.CreateWarehouse("Whs", "A", 3, 1);
			whs.WW_IsVirtualWarehouse = true;
			Factory.Save();

			var locationA1 = whs.FindLocation("A-1");
			var bondedArea = Helper.CreateArea(whs, "C", AreaTypes.Codes.Bonded);
			locationA1.WLV_WA_PickingArea = bondedArea.PK;

			var receive = Helper.CreateWhsReceive(client, whs);
			var inventoryLine1 = Helper.CreateWhsReceiveInventoryLine(receive, product, 3m);
			var inventoryLine2 = Helper.CreateWhsReceiveInventoryLine(receive, product, 7m);

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(client, whs);
			order.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine = Helper.CreateWhsOrderLine(order, product, 10m);
			orderLine.WE_LineNo = 1;
			orderLine.CustomsData.WB_EntryKey = "123";

			var pick = Helper.CreatePickNew(order);
			saveAction(order, pick);
			AssertEquals("After pick is finalised, Order Lines should be split.", 2, order.Lines.Count);

			var orderLine1 = order.Lines[0];
			var orderLine2 = order.Lines[1];

			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine1, inventoryLine2, 7m, 1);
			AssertSplitPickLineForInventory(orderLine2, inventoryLine1, 3m, 2);
		}

		public void TestDataRefresh_WhenFinalisePickWithDifferentFactories_SplitByInventoryAllocated()
		{
			var processAction = new Action<WhsOrder, WhsPick>((order, pick) =>
			{
				Factory.Save();

				// start from new factory
				var newFactory = new BusinessObjectFactory();
				var pickFromNewFactory = newFactory.Load<WhsPick>(pick.PK);
				pickFromNewFactory.FinaliseAllOrders();

				newFactory.Save();

				AssertEquals("Precondition", 1, order.Lines.Count);

				pickFromNewFactory.FinalisePick();
				AssertIsFinalisedPrecondition(pickFromNewFactory);
				newFactory.Save();
			});
			TestSplitByInventoryAllocatedCore(processAction);
		}

		void TestSplitByInventoryAllocated_MultiOrderPickCore(Action<WhsOrder, WhsOrder, WhsOrder, WhsPick> saveAction)
		{
			var client = Helper.CreateClient("Client");
			var product1 = Helper.CreateProduct("P1", client);
			var product2 = Helper.CreateProduct("P2", client);
			var product3 = Helper.CreateProduct("P3", client);
			var whs = Helper.CreateWarehouse("Whs", "A", 3, 1);
			whs.WW_IsVirtualWarehouse = true;
			Factory.Save();

			var locationA1 = whs.FindLocation("A-1");
			var bondedArea = Helper.CreateArea(whs, "C", AreaTypes.Codes.Bonded);
			locationA1.WLV_WA_PickingArea = bondedArea.PK;

			var receive = Helper.CreateWhsReceive(client, whs);
			var inventoryLine1 = Helper.CreateWhsReceiveInventoryLine(receive, product1, 3m);
			var inventoryLine2 = Helper.CreateWhsReceiveInventoryLine(receive, product1, 7m);

			var inventoryLine3 = Helper.CreateWhsReceiveInventoryLine(receive, product2, 3m);
			var inventoryLine4 = Helper.CreateWhsReceiveInventoryLine(receive, product2, 4m);
			var inventoryLine5 = Helper.CreateWhsReceiveInventoryLine(receive, product2, 5m);

			var inventoryLine6 = Helper.CreateWhsReceiveInventoryLine(receive, product3, 5m);

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(client, whs, "O1");
			order1.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine1 = Helper.CreateWhsOrderLine(order1, product1, 10m);
			orderLine1.WE_LineNo = 1;
			orderLine1.CustomsData.WB_EntryKey = "123";

			var order2 = Helper.CreateWhsOrder(client, whs, "O2");
			order2.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine2 = Helper.CreateWhsOrderLine(order2, product2, 12m);
			orderLine2.WE_LineNo = 2;
			orderLine2.CustomsData.WB_EntryKey = "456";

			var order3 = Helper.CreateWhsOrder(client, whs, "O3");
			order3.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine3 = Helper.CreateWhsOrderLine(order3, product3, 5m);
			orderLine3.WE_LineNo = 3;
			orderLine3.CustomsData.WB_EntryKey = "789";

			var pick = Helper.CreatePickNew(order1, order2, order3);
			saveAction(order1, order2, order3, pick);
			AssertEquals("After pick is finalised, Order Lines should be split.", 2, order1.Lines.Count);
			var orderLine11 = order1.Lines[0];
			var orderLine12 = order1.Lines[1];
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 7m, orderLine11.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 7m, orderLine11.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine12.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine12.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine11, inventoryLine2, 7m, 1);
			AssertSplitPickLineForInventory(orderLine12, inventoryLine1, 3m, 2);

			AssertEquals("After pick is finalised, Order Lines should be split.", 3, order2.Lines.Count);
			var orderLine21 = order2.Lines[0];
			var orderLine22 = order2.Lines[1];
			var orderLine23 = order2.Lines[2];

			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 5m, orderLine21.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 5m, orderLine21.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine22.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine22.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 4m, orderLine23.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 4m, orderLine23.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine21, inventoryLine5, 5m, 2);
			AssertSplitPickLineForInventory(orderLine22, inventoryLine3, 3m, 1);
			AssertSplitPickLineForInventory(orderLine23, inventoryLine4, 4m, 3);

			AssertEquals("After pick is finalised, Order Lines should be unchanged if single inventory.", 1, order3.Lines.Count);
			var orderLine31 = order3.Lines[0];

			AssertSplitPickLineForInventory(orderLine31, inventoryLine6, 5m, 3);
		}

