		void TestSplitByInventoryAllocated_CopiesAllAttributesIncludingCustomsDataCore(Action<WhsOrder, WhsPick, ZDate, ZDate> saveAction)
		{
			var client = Helper.CreateClient("Client");
			var product = Helper.CreateProduct("P1", client);
			var whs = Helper.CreateWarehouse("Whs", "A", 3, 1);
			whs.WW_IsVirtualWarehouse = true;
			Factory.Save();

			Helper.SetClientAllAttributeType(client, true);
			Helper.SetClientAttributeType(client, AttributeNumber.Serial, false);
			Helper.SetProductAllAttributeUse(client, product, true, useSerialNumber: false);

			var locationA1 = whs.FindLocation("A-1");
			var bondedArea = Helper.CreateArea(whs, "C", AreaTypes.Codes.Bonded);
			locationA1.WLV_WA_PickingArea = bondedArea.PK;

			var expiryDate = ZDate.Today.AddDays(1);
			var packingDate = ZDate.Today.AddDays(-1);

			var receive = Helper.CreateWhsReceive(client, whs);
			var inventoryLine1 = Helper.CreateWhsReceiveInventoryLine(receive, product, 3m);
			inventoryLine1.WI_PartAttrib1 = "AAA";
			inventoryLine1.WI_PartAttrib2 = "BBB";
			inventoryLine1.WI_PartAttrib3 = "CCC";
			inventoryLine1.WI_ExpiryDate = expiryDate;
			inventoryLine1.WI_PackingDate = packingDate;

			var inventoryLine2 = Helper.CreateWhsReceiveInventoryLine(receive, product, 7m);
			inventoryLine2.WI_PartAttrib1 = "AAA";
			inventoryLine2.WI_PartAttrib2 = "BBB";
			inventoryLine2.WI_PartAttrib3 = "CCC";
			inventoryLine2.WI_ExpiryDate = expiryDate;
			inventoryLine2.WI_PackingDate = packingDate;

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(client, whs);
			order.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine = Helper.CreateWhsOrderLine(order, product, 10m);
			orderLine.WE_LineNo = 1;
			orderLine.WE_PartAttrib1 = "AAA";
			orderLine.WE_PartAttrib2 = "BBB";
			orderLine.WE_PartAttrib3 = "CCC";
			orderLine.WE_ExpiryDate = expiryDate;
			orderLine.WE_PackingDate = packingDate;

			var customsData = orderLine.CustomsData;
			customsData.WB_EntryLineNo = 100;
			customsData.WB_EntryKey = "ABC123";
			customsData.WB_AddInfo = "DEF456";
			customsData.WB_BondedWhsQty = 123;
			customsData.WB_BondedWhsUnitOfQty = "G";
			customsData.WB_CustomsQty = 456;
			customsData.WB_CustomsUnitOfQty = "KG";

			var pick = Helper.CreatePickNew(order);
			saveAction(order, pick, expiryDate, packingDate);
			AssertEquals("After pick is finalised, Order Lines should be split.", 2, order.Lines.Count);
			var orderLine1 = order.Lines[0];
			var orderLine2 = order.Lines[1];

			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine1, inventoryLine2, 7m, 1);
			AssertOrderLineAttributesIncludingCustomsData_WhenTestSplitByInventoryAllocated(orderLine1, expiryDate, packingDate);
			AssertSplitPickLineForInventory(orderLine2, inventoryLine1, 3m, 2);
			AssertOrderLineAttributesIncludingCustomsData_WhenTestSplitByInventoryAllocated(orderLine2, expiryDate, packingDate);
		}

		void AssertOrderLineAttributesIncludingCustomsData_WhenTestSplitByInventoryAllocated(WhsDocketLine orderLineToAssert, ZDate expiryDate, ZDate packingDate)
		{
			AssertEquals("AAA", orderLineToAssert.WE_PartAttrib1);
			AssertEquals("BBB", orderLineToAssert.WE_PartAttrib2);
			AssertEquals("CCC", orderLineToAssert.WE_PartAttrib3);
			AssertEquals(expiryDate, orderLineToAssert.WE_ExpiryDate);
			AssertEquals(packingDate, orderLineToAssert.WE_PackingDate);

			var customsDataToAssert = orderLineToAssert.CustomsData;
			AssertEquals((short)100, customsDataToAssert.WB_EntryLineNo);
			AssertEquals("ABC123", customsDataToAssert.WB_EntryKey);
			AssertEquals("DEF456", customsDataToAssert.WB_AddInfo);
			AssertEquals(123m, customsDataToAssert.WB_BondedWhsQty);
			AssertEquals("G", customsDataToAssert.WB_BondedWhsUnitOfQty);
			AssertEquals(456m, customsDataToAssert.WB_CustomsQty);
			AssertEquals("KG", customsDataToAssert.WB_CustomsUnitOfQty);
		}

