			var product = Helper.CreateProduct("P1", client);
			var whs = Helper.CreateWarehouse("Whs", "A", 3, 1);
			whs.WW_IsVirtualWarehouse = true;
			Factory.Save();

			var locationA1 = whs.FindLocation("A-1");
			var bondedArea = Helper.CreateArea(whs, "C", AreaTypes.Codes.Bonded);
			locationA1.WLV_WA_PickingArea = bondedArea.PK;

			var receive = Helper.CreateWhsReceive(client, whs);
			var inventoryLine1 = Helper.CreateWhsReceiveInventoryLine(receive, product, 3m);
			var inventoryLine2 = Helper.CreateWhsReceiveInventoryLine(receive, product, 7m);

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(client, whs);
			order.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine = Helper.CreateWhsOrderLine(order, product, 10m);
			orderLine.WE_LineNo = 1;
			orderLine.CustomsData.WB_EntryKey = "123";

			var pick = Helper.CreatePickNew(order);

			var pickLine = orderLine.PickLines.Single(l => l.WZ_WE_InventoryLine == inventoryLine2.PK);
			pickLine.WZ_Units -= 3m;

			Factory.Save();
			saveAction(order, pick);

			AssertEquals("After pick is finalised, Order Lines should be split.", 2, order.Lines.Count);
			var orderLine1 = order.Lines[0];
			var orderLine2 = order.Lines[1];

			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 7m, orderLine1.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine2.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine1, inventoryLine2, 4m, 1);
			AssertSplitPickLineForInventory(orderLine2, inventoryLine1, 3m, 2);
		}

