		void TestSplitByInventoryAllocated_PrioritiseLowestQuantityCore(Action<WhsOrder, WhsPick> saveAction)
		{
			var client = Helper.CreateClient("Client");
			var product = Helper.CreateProduct("P1", client);
			var whs = Helper.CreateWarehouse("Whs", "A", 3, 1);
			whs.WW_IsVirtualWarehouse = true;
			Factory.Save();

			var locationA1 = whs.FindLocation("A-1");
			var bondedArea = Helper.CreateArea(whs, "C", AreaTypes.Codes.Bonded);
			locationA1.WLV_WA_PickingArea = bondedArea.PK;

			var receive = Helper.CreateWhsReceive(client, whs);
			var inventoryLine1_1m = Helper.CreateWhsReceiveInventoryLine(receive, product, 1m);
			var inventoryLine2_4m = Helper.CreateWhsReceiveInventoryLine(receive, product, 4m);
			var inventoryLine3_2m = Helper.CreateWhsReceiveInventoryLine(receive, product, 2m);
			var inventoryLine4_3m = Helper.CreateWhsReceiveInventoryLine(receive, product, 3m);

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(client, whs);
			order.WD_DocketSubType = OrderType.Codes.Customs;
			var orderLine = Helper.CreateWhsOrderLine(order, product, 10m);
			orderLine.WE_LineNo = 1;
			orderLine.CustomsData.WB_EntryKey = "123";

			var pick = Helper.CreatePickNew(order);

			saveAction(order, pick);

			AssertEquals("After pick is finalised, Order Lines should be split.", 4, order.Lines.Count);
			var orderLine1 = order.Lines[0];
			var orderLine2 = order.Lines[1];
			var orderLine3 = order.Lines[2];
			var orderLine4 = order.Lines[3];

			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 4m, orderLine1.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 4m, orderLine1.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 1m, orderLine2.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 1m, orderLine2.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 2m, orderLine3.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 2m, orderLine3.WE_PackQuantity);
			AssertEquals("the WE_TransactionQuantity of the split order line and pick line should be equal", 3m, orderLine4.WE_TransactionQuantity);
			AssertEquals("the WE_PackQuantity of the split order line and pick line should be equal", 3m, orderLine4.WE_PackQuantity);

			AssertSplitPickLineForInventory(orderLine1, inventoryLine2_4m, 4m, 1);
			AssertSplitPickLineForInventory(orderLine2, inventoryLine1_1m, 1m, 2);
			AssertSplitPickLineForInventory(orderLine3, inventoryLine3_2m, 2m, 3);
			AssertSplitPickLineForInventory(orderLine4, inventoryLine4_3m, 3m, 4);
		}

