		void AssertSplitPickLineForInventory(WhsDocketLine orderLine, WhsInventoryView inventoryLine, ZDecimal pickedUnits, short lineNumber)
		{
			AssertNotNull(orderLine);
			AssertEquals("OrderLine should have expected WE_LineNo.", lineNumber, orderLine.WE_LineNo);

			var pickLine = orderLine.PickLines.Single();
			AssertEquals("Pick Line should have expected WZ_Units.", pickedUnits, pickLine.WZ_Units);
			AssertEquals("Pick Line should have expected WZ_WE_InventoryLine.", inventoryLine.PK, pickLine.WZ_WE_InventoryLine);
		}

