		#region AssertPropertiesSetCorrectly

		protected void AssertPropertiesSetCorrectly(WhsPickableDocket backOrder, ZGuid expectedParentPK,
			ZString expectedExternalReference, ZByte expectedExternalReferenceSplit, ZDecimal expectedUnits,
			decimal expectedExtendedLinePrice = 0m)
		{
			AssertEquals("ParentPK", expectedParentPK, backOrder.WD_WD_ParentDocket);
			AssertEquals("External Reference", expectedExternalReference, backOrder.WD_ExternalReference);
			AssertEquals("External Reference Split", expectedExternalReferenceSplit, backOrder.WD_ExternalReferenceSplit);
			AssertEquals("BackOrder Docket Status", DocketStatus.Codes.Entered, backOrder.WD_DocketStatus);
			AssertEquals("BackOrder Docket Type", OrderType.Codes.BackOrder, backOrder.WD_DocketSubType);

			AssertEquals("WE_TransactionQuantity", expectedUnits, backOrder.Lines[0].WE_TransactionQuantity);
			AssertEquals("WE_ExtendedLinePrice", expectedExtendedLinePrice, backOrder.Lines[0].WE_ExtendedLinePrice);

			//check if release related data was cleared
			AssertEquals("WD_TransportReference", "", backOrder.WD_TransportReference);
			AssertEquals("WD_VehicleNo", "", backOrder.VehicleNo);
			AssertEquals("WD_ShipperCODAmount", 0m, backOrder.WD_ShipperCODAmount);
			AssertEquals("WD_CODPayMethod", "", backOrder.WD_CODPayMethod);
			AssertEquals("Containers count", 0, backOrder.Containers.Count);
		}

