		public void TestPickFinaliseStatus_IsFinalisable()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Factory.Save();
			AssertPickFinaliseStatusIsFinalisable(data, "1", isVirtualWarehouse: true, isAllowedWhsReleaseFinalise: true,
				docketSubType: OrderType.Codes.Order, expectedIsFinalisable: true);
			AssertPickFinaliseStatusIsFinalisable(data, "2", isVirtualWarehouse: true, isAllowedWhsReleaseFinalise: false,
				docketSubType: OrderType.Codes.Order, expectedIsFinalisable: false);
			AssertPickFinaliseStatusIsFinalisable(data, "3", isVirtualWarehouse: false, isAllowedWhsReleaseFinalise: false,
				docketSubType: OrderType.Codes.Order, expectedIsFinalisable: false);
			AssertPickFinaliseStatusIsFinalisable(data, "4", isVirtualWarehouse: false, isAllowedWhsReleaseFinalise: true,
				docketSubType: OrderType.Codes.Order, expectedIsFinalisable: true);

			AssertPickFinaliseStatusIsFinalisable(data, "5", isVirtualWarehouse: true, isAllowedWhsReleaseFinalise: true,
				docketSubType: OrderType.Codes.Customs, expectedIsFinalisable: true);
			AssertPickFinaliseStatusIsFinalisable(data, "6", isVirtualWarehouse: true, isAllowedWhsReleaseFinalise: false,
				docketSubType: OrderType.Codes.Customs, expectedIsFinalisable: true);
			AssertPickFinaliseStatusIsFinalisable(data, "7", isVirtualWarehouse: false, isAllowedWhsReleaseFinalise: false,
				docketSubType: OrderType.Codes.Customs, expectedIsFinalisable: false);
			AssertPickFinaliseStatusIsFinalisable(data, "8", isVirtualWarehouse: false, isAllowedWhsReleaseFinalise: true,
				docketSubType: OrderType.Codes.Customs, expectedIsFinalisable: true);
		}

		void AssertPickFinaliseStatusIsFinalisable(TestDataSimpleEnvironment data, string reference, bool isVirtualWarehouse,
			bool isAllowedWhsReleaseFinalise, string docketSubType, bool expectedIsFinalisable)
		{
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, reference, data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, reference, data.Part1, 1m);
			var pick = Helper.CreatePickNew(order);

			data.Whs1.WW_IsVirtualWarehouse = isVirtualWarehouse;
			Env.Security.WhsReleaseFinalise.IsAllowed = isAllowedWhsReleaseFinalise;
			if (docketSubType == OrderType.Codes.Customs)
			{
				order.Lines[0].CustomsData.WB_EntryKey = "123";
				Helper.EnableWarehouseForBond(data.Whs1, true);
			}
			order.WD_DocketSubType = docketSubType;

			pick.FinaliseOrder(order);

			AssertIsFinalisedPrecondition(order);
			var finalisePickStatus = pick.GetFinalisableStatus();
			AssertEquals("Pick.FinalisablePickStatus.IsFinalisable:", expectedIsFinalisable, finalisePickStatus.IsFinalisable);
		}

		public void TestPickFinaliseStatusIsFinalisable_IsImportingForChangeOfInventory()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Factory.Save();

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 1m);
			var pick = Helper.CreatePickNew(order);

			data.Whs1.WW_IsVirtualWarehouse = false;
			Env.Security.WhsReleaseFinalise.IsAllowed = false;
			order.Lines[0].CustomsData.WB_EntryKey = "123";
			Helper.EnableWarehouseForBond(data.Whs1, true);
			order.WD_DocketSubType = OrderType.Codes.Customs;

			pick.FinaliseOrder(order);

			AssertIsFinalisedPrecondition(order);
			var finalisePickStatus = pick.GetFinalisableStatus();
			AssertEquals(false, order.IsImportingForChangeOfInventory);
			AssertEquals("Pick.FinalisablePickStatus.IsFinalisable:", false, finalisePickStatus.IsFinalisable);
			AssertEquals("No error.", "", finalisePickStatus.ErrorMessage);
			using (order.MarkAsImportingForChangeOfInventory())
			{
				AssertEquals("Precondition", true, order.IsImportingForChangeOfInventory);
				AssertEquals("Pick.FinalisablePickStatus.IsFinalisable:", true, finalisePickStatus.IsFinalisable);
			}
		}

		public void TestPickFinaliseStatus_CannotFinaliseBecauseCartoniseSplitCasesAndLabelsHaveNotBeenCreatedYet()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			order.FinaliseDocket();

			pick.WP_CartoniseSplitCases = true;
			pick.WP_PickPalletsByLabel = false;
			pick.WP_PickCasesByLabel = false;

			// have labels been created?
			pick.WP_IsCartonised = false;

			var status = pick.GetFinalisableStatus();
			AssertEquals("Pick is not finalisable", false, status.IsFinalisable);
			AssertEquals("Correct error message is given", status.ErrorMessage, "Cannot Finalize this pick, because it requires Package Labels and no Package Labels have been allocated.");
		}

