		[TestDate(2022, 11, 15)]
		public void TestPickFinalise_CanFinaliseStatus_SetLoadsGateOutTime()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var load1 = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation, jobID: "L1");

			var yesterday = ZDateTimeOffset.Today.AddDays(-1);
			load1.WLO_StartTime = yesterday;
			load1.WLO_TransportationUnitNumber = "4543";
			load1.WLO_CompleteTime = yesterday;
			load1.WLO_GateOutTime = yesterday;
			order1.WD_WLO_PlannedLoad = load1.PK;

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", data.Notify);
			Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			var load2 = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation, jobID: "L2");

			load2.WLO_StartTime = yesterday;
			load2.WLO_TransportationUnitNumber = "453";
			load2.WLO_CompleteTime = yesterday;
			order2.WD_WLO_PlannedLoad = load2.PK;

			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3", data.Notify);
			Helper.CreateWhsOrderLine(order3, data.Part1, 10m);
			var load3 = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation, jobID: "L3");

			load3.WLO_StartTime = yesterday;
			load3.WLO_TransportationUnitNumber = "43";
			load3.WLO_CompleteTime = yesterday;
			order3.WD_WLO_PlannedLoad = load3.PK;
			Factory.Save();

			var pick = Helper.CreatePickNew(new[] { order1, order2, order3 });
			AssertEquals("Precondition: Load1 GateOutTime is correct", yesterday, load1.WLO_GateOutTime);
			AssertEquals("Precondition: Load2 GateOutTime is empty", ZDateTimeOffset.Empty, load2.WLO_GateOutTime);
			AssertEquals("Precondition: Load3 GateOutTime is empty", ZDateTimeOffset.Empty, load3.WLO_GateOutTime);

			AssertEquals("Precondition", false, pick.IsFinalised);
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertIsFinalisedPrecondition(pick);

			AssertEquals("Load1 GateOutTime is correct.", yesterday, load1.WLO_GateOutTime);
			AssertEquals("Load2 GateOutTime is correct.", ZDateTimeOffset.Today, load2.WLO_GateOutTime);
			AssertEquals("Load3 GateOutTime is correct.", ZDateTimeOffset.Today, load3.WLO_GateOutTime);
			AssertEquals("Pick should be finalised since all orders have completed loading.", true, pick.IsFinalised);
		}

		[TestDate(2023, 2, 17)]
		public void TestPickFinalise_DoesnotSetLoadsGateOutTime_WhenOtherPicksFromLoadAreNotFinalisaed()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", data.Notify);
			Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3", data.Notify);
			Helper.CreateWhsOrderLine(order3, data.Part1, 10m);
			var load = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation, jobID: "L1");

			var yesterday = ZDateTimeOffset.Today.AddDays(-1);
			load.WLO_StartTime = yesterday;
			load.WLO_TransportationUnitNumber = "4543";
			load.WLO_CompleteTime = yesterday;
			order1.WD_WLO_PlannedLoad = load.PK;
			order2.WD_WLO_PlannedLoad = load.PK;
			order3.WD_WLO_PlannedLoad = load.PK;
			Factory.Save();
			var pick1 = Helper.CreatePickNew(new[] { order1 });
			var pick2 = Helper.CreatePickNew(new[] { order2 });
			AssertEquals("Precondition: pick1 is not finalised", false, pick1.IsFinalised);
			AssertEquals("Precondition: pick2 is not finalised", false, pick2.IsFinalised);

			pick1.FinaliseAllOrders();
			pick1.FinalisePick();
			Factory.Save();
			AssertIsFinalisedPrecondition(pick1);
			AssertEquals("load's GateOutTime should not be set because pick2 and order3 is not Finalised.", ZDateTimeOffset.Empty, load.WLO_GateOutTime);

			var newFactory1 = new BusinessObjectFactory();
			var pick2InNewFactory = newFactory1.Load<WhsPick>(pick2.PK);
			pick2InNewFactory.FinaliseAllOrders();
			pick2InNewFactory.FinalisePick();
			newFactory1.Save();
			AssertIsFinalisedPrecondition(pick2InNewFactory);
			AssertEquals("load's GateOutTime should not be set because order3 has no Pick.", ZDateTimeOffset.Empty, load.WLO_GateOutTime);

			var pick3 = Helper.CreatePickNew(new[] { order3 });
			Factory.Save();

			var newFactory2 = new BusinessObjectFactory();
			var pick3InNewFactory2 = newFactory2.Load<WhsPick>(pick3.PK);
			pick3InNewFactory2.FinaliseAllOrders();
			pick3InNewFactory2.FinalisePick();
			newFactory2.Save();

			var loadInNewFactory = newFactory2.Load<WhsLoad>(load.PK);
			AssertEquals("load's GateOutTime is set since all picks are finalised.", ZDateTimeOffset.Today, loadInNewFactory.WLO_GateOutTime);
		}

		public void TestPickFinalise_AddFreightLoadedEventToOrdersWithoutLoad()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", data.Notify);
			Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", data.Notify);
			Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3", data.Notify);
			Helper.CreateWhsOrderLine(order3, data.Part1, 10m);
			var order4 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O4", data.Notify);
			Helper.CreateWhsOrderLine(order4, data.Part1, 10m);

			var load = Helper.CreateWhsLoad(data.Org1, data.Whs1.DefaultOutboundDockDoorLocation);
			order1.WD_WLO_PlannedLoad = load.PK;
			order3.WD_WLO_PlannedLoad = load.PK;
			load.WLO_StartTime = ZDateTimeOffset.Today;
			load.WLO_TransportationUnitNumber = "4543";
			load.WLO_GateOutTime = ZDateTimeOffset.Today;
			load.WLO_CompleteTime = ZDateTimeOffset.Today;

			var pick = Helper.CreatePickNew(new[] { order1, order2, order3, order4 });
			var packageJob1 = order3.PackageJob;
			var package1 = packageJob1.Packages.AddNew(Constants.PkgUnit.Box, 1);
			var packageJob2 = order4.PackageJob;
			var package2 = packageJob2.Packages.AddNew(Constants.PkgUnit.Box, 1);
			Helper.CreateLoadPkgPackagePivot(package1.PK, load);
			Helper.CreateLoadPkgPackagePivot(package2.PK, load);
			Factory.Save();

			AssertEquals("Precondition", false, pick.IsFinalised);
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			Factory.Save();

			AssertIsFinalisedPrecondition(pick);
			AssertEquals("Freight load event should not be added", 0, Helper.FindLogs(order1.Logs, Events.FreightLoaded).Length);
			AssertEquals("Freight load event added successfully", 1, Helper.FindLogs(order2.Logs, Events.FreightLoaded).Length);
			AssertEquals("Event not added because order3 has both WD_WLO_PlannedLoad and Pivot set", 0, Helper.FindLogs(order3.Logs, Events.FreightLoaded).Length);
			AssertEquals("Event not added because order4 is attached through Pivot", 0, Helper.FindLogs(order4.Logs, Events.FreightLoaded).Length);
		}

