			order1.WD_PackingAfterPickingRequired = true;
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 15m);
			order2.WD_PackingAfterPickingRequired = true;

			Factory.Save();

			var pick = Helper.CreatePickNew(new[] { order1, order2 });
			pick.AutoAllocateItemsWithMock();
			pick.FinaliseAllOrders();

			var packageJob1 = order1.PackageJob;
			var packageItem1 = packageJob1.PackableItemParents[0];
			var pallet1 = packageJob1.Packages.AddNew("PLT");
			pallet1.Pack(packageItem1.PackableItemParent, 6m);
			var box1OnPallet1 = pallet1.Packages.AddNew("BOX");
			box1OnPallet1.Pack(packageItem1.PackableItemParent, 4m);
			pallet1.KP_ClosedTimeUtc = ZDateTime.UtcNow;

			var packageJob2 = order2.PackageJob;
			var packageItem2 = packageJob2.PackableItemParents[0];
