		#region TestPickFinalise_GetOrdersWithUnfinishedTotes

		public void TestPickFinalise_GetOrdersWithUnfinishedTotes_NoPickPackParamsCreated()
		{
			TestPickFinalise_GetOrdersWithUnfinishedTotesCore(createPickPackParams: false);
		}

		public void TestPickFinalise_GetOrdersWithUnfinishedTotes_PickPackParamsCreated_AllowPickFinaliseWithUnpackedTote()
		{
			TestPickFinalise_GetOrdersWithUnfinishedTotesCore(createPickPackParams: true, allowPickFinaliseWithUnpackedTote: true);
		}

		public void TestPickFinalise_GetOrdersWithUnfinishedTotes_PickPackParamsCreated_DisallowPickFinaliseWithUnpackedTote()
		{
			TestPickFinalise_GetOrdersWithUnfinishedTotesCore(createPickPackParams: true, allowPickFinaliseWithUnpackedTote: false);
		}

		void TestPickFinalise_GetOrdersWithUnfinishedTotesCore(bool createPickPackParams, bool allowPickFinaliseWithUnpackedTote = false)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 20m);
			Factory.Save();

			if (createPickPackParams)
			{
				var pickPackParams = Helper.CreatePickPackParameter(data.Org1, data.Whs1);
				pickPackParams.WPP_AllowPickFinalizationWithUnpackedTotes = allowPickFinaliseWithUnpackedTote;
				Factory.Save();
			}

			var orderWithTote1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O3", data.Part1, 10m);
			var orderWithoutTote = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 20m);
			var orderWithTote2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);

			var pick = Helper.CreatePickNew(orderWithTote1, orderWithoutTote, orderWithTote2);
			orderWithTote1.PackageJob.Packages.AddNew().SetIsTote(true);
			orderWithTote2.PackageJob.Packages.AddNew().SetIsTote(true);

			orderWithTote1.Lines[0].PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			orderWithoutTote.Lines[0].PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			orderWithTote2.Lines[0].PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			orderWithTote1.FinaliseDocket();
			orderWithoutTote.FinaliseDocket();
			orderWithTote2.FinaliseDocket();
			Factory.Save();
			Assert("Precondition.", orderWithTote1.IsFinalised);
			Assert("Precondition.", orderWithoutTote.IsFinalised);
			Assert("Precondition.", orderWithTote2.IsFinalised);

			if (!allowPickFinaliseWithUnpackedTote)
			{
				pick.FinalisePickFailure += Pick_FinalisePickFailure;
			}
			pick.FinalisePick();

			AssertEquals(allowPickFinaliseWithUnpackedTote, pick.IsFinalised);

			void Pick_FinalisePickFailure(object sender, WhsPick.FinalisePickEventArgs e)
			{
				AssertEquals("Cannot Finalize this pick as the following Orders have not finished Packing Totes:\r\nO1\r\nO3", e.ErrorMessage);
			}
		}

		#endregion

		#region TestPickFinalise_GetNonStagedOrdersUsingConsolidation

		public void TestPickFinalise_GetNonStagedOrdersUsingConsolidation()
		{
			var packingHelper = new PackingTestHelper(Factory);
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var conLocationType = Factory.NewWithValidTestData<WhsLocationType>();
			conLocationType.WLT_LocationClass = LocationClasses.Codes.CON;
			var firstLocation = data.Whs1.FindLocation("A-1");
			var conLocation = data.Whs1.FindLocation("A-3");
			conLocation.WLV_WLT_LocationType = conLocationType.PK;
			var dockDoorLocation = data.Whs1.FindLocation("DOCKDOOR");
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			AssertEquals("Precondition: Receive Line Location.", firstLocation.PK, receive.Lines[0].WE_WL);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			order.WD_UseDirectedPackingConsolidation = true;
			var pick = Helper.CreatePickNew(order);
			var pickLine = pick.GetAllPickLines().Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
			pickLine.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;
			Factory.Save();

			var transfer = pick.Transfers[0];
			AssertNotNull("Precondition: Transfer Created.", transfer);
			var transferLine = pick.Transfers[0].Lines[0];
			var transferPickLine = pick.Transfers[0].Lines[0].PickLines[0];
			AssertEquals("Precondition: Transfer to Dock Door.", dockDoorLocation.PK, transferLine.WE_WL);

			transferLine.WE_WL = conLocation.PK;
			AssertEquals("Precondition: Changed to Transfer to CON Location.", conLocation.PK, transferLine.WE_WL);

			var pkgJob = PkgPackageJob.LoadOrCreatePackageJob(order);
			var pkg = packingHelper.CreatePackage(pkgJob, "PKG1", 1, PkgUnit.Box);
			packingHelper.CreatePackageDivot(pkg, pickLine);

			var handlingUnit = packingHelper.CreatePkgHandlingUnit(data.Whs1.WW_GB_RelatedCompanyBranch, "3PL");
			var handlingUnitPackageJob = PkgPackageJob.LoadOrCreatePackageJob(handlingUnit);
			var handlingUnitPackage = packingHelper.CreatePackage(handlingUnitPackageJob, "HU1", 1, PkgUnit.Package);
			packingHelper.PackHandlingUnit(handlingUnitPackage, pkg, handlingUnitPackage);
			Factory.Save();

			var service = new WhsPackingConsolidationService();
			var errorMessage = service.CreateDockDoorTransfer(handlingUnitPackage.PK);

			AssertEquals(true, errorMessage.IsNullOrEmpty());
			AssertEquals("New Transfer Line to Dock Door created.", 2, transfer.Lines.Count);

			order.FinaliseDocket();
			Factory.Save();
			Assert("Precondition.", order.IsFinalised);

			var pickInDB1 = new BusinessObjectFactory().Load<WhsPick>(pick.PK);
			pickInDB1.FinaliseSelectedOrders();
			pickInDB1.FinalisePickFailure += (s, e) =>
			{
				AssertEquals("Cannot Finalize this pick as the following Orders are using directed Consolidation and are not yet Staged:\r\nO1", e.ErrorMessage);
			};
			pickInDB1.FinalisePick();

			Assert("Should not finalise pick", !pickInDB1.IsFinalised);

			var newTransferLine = (WhsTransferLine)transfer.Lines.Single(l => l.PK != transferLine.PK);
			newTransferLine.FinaliseDocketLine();
			AssertEquals("Precondition - should be Staged.", InventoryStatus.Codes.Staged, newTransferLine.WE_CurrentInventoryStatus);
			Factory.Save();

			AssertEquals("Precondition: WarehouseOrderStatus", WhsOrderStatus.Codes.Staged, new BusinessObjectFactory().Load<WhsOrder>(order.PK).WarehouseOrderStatus);

			var pickInDB2 = new BusinessObjectFactory().Load<WhsPick>(pick.PK);
			pickInDB2.FinaliseSelectedOrders();
			pickInDB2.FinalisePickFailure += (s, e) =>
			{
				Fail("This event should not be called when there is no error in finalise pick.");
			};
			pickInDB2.FinalisePick();

			Assert("Should be able to finalise pick when there is no error.", pickInDB2.IsFinalised);
		}

		#endregion

