		public void TestFinalizePick_PartiallyPicked_TriggersPrompt_PressYesFinalizesPick()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventoryManyLines();
			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", Notify);
			var orderLine1 = Helper.CreateWhsOrderLine(order1, data.Part1, 10m);
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", Notify);
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 10m);
			var pick = Helper.CreatePickNew(order1, order2);
			pick.FinaliseAllOrders();

			var pickLines = pick.GetAllPickLines().ToArray();
			AssertEquals("Precondition: Two pick lines.", 2, pickLines.Length);
			pickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Now;

			pick.NotificationManager.Push(Notify);
			Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;

			AssertEquals("Precondition", false, pick.IsFinalised);

			pick.FinalisePick();

			var lastQueryEventArgs = (DefaultableQueryUserEventArgs)Notify.LastQueryUserEventArgs;
			AssertEquals("Caption on query matches", "Continue?", lastQueryEventArgs.Caption);
			AssertEquals("Message on query matches", "Not all allocated lines have been picked, please confirm that you want to finalize the pick which will automatically mark any un-picked lines as picked.", lastQueryEventArgs.Message);
			AssertEquals("Response is as set", true, lastQueryEventArgs.Response);
			AssertEquals("Postcondition", true, pick.IsFinalised);
		}

