		#region TestPickFinalise_PickByBOM_MultiplekitOrderLinesWithDifferentComponentQtyOnSameComponentProduct

		public void TestPickFinalise_PickByBOM_MultiplekitOrderLinesWithDifferentComponentQtyOnSameComponentProduct()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var unitForBike = bike.PartUnits.AddNew();
			unitForBike.OF_PackType = "UNT";
			unitForBike.OF_ParentPackType = "PLT";
			unitForBike.OF_QuantityInParent = 10;
			var bikeParams = Helper.CreateProductParamsByWhsAndClient(bike, data.Org1, data.Whs1);
			bikeParams.W3_OH = data.Org1.PK;
			bikeParams.W3_WW = data.Whs1.PK;
			bikeParams.W3_F3_NKReleasedPackType = "PLT";

			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var unitForWheel = wheel.PartUnits.AddNew();
			unitForWheel.OF_PackType = "UNT";
			unitForWheel.OF_ParentPackType = "PLT";
			unitForWheel.OF_QuantityInParent = 13;
			var wheelParams1 = Helper.CreateProductParamsByWhsAndClient(wheel, data.Org1, data.Whs1);
			wheelParams1.W3_OH = data.Org1.PK;
			wheelParams1.W3_WW = data.Whs1.PK;
			wheelParams1.W3_F3_NKReleasedPackType = "PLT";
			var frame = Helper.CreateProduct(data.Org1, "FRAME");

			Helper.CreateProductBOM(bike, wheel, 1m, PkgUnit.Unit);
			Helper.CreateProductBOM(bike, frame, 2m, PkgUnit.Unit);

			var moto = Helper.CreateProduct(data.Org1, "MOTO");
			moto.OP_IsComponentPickedOnSalesOrder = true;
			Helper.CreateProductBOM(moto, wheel, 2m, PkgUnit.Unit);
			Helper.CreateProductBOM(moto, frame, 1m, PkgUnit.Unit);

			var inventoryLocation = data.Whs1.FindLocation("A-1");
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			var inventory2 = Helper.CreateWhsReceiveInventoryLine(receive, wheel, 100m, inventoryLocation);
			var inventory3 = Helper.CreateWhsReceiveInventoryLine(receive, frame, 100m, inventoryLocation);
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertEquals("Receive should be finalised.", true, receive.IsFinalised);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 3m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, moto, 4m);
			var pick = Helper.CreatePickNew(order);
			pick.FinaliseAllOrders();
			Factory.Save();

			var componentLines1 = orderLine1.ChildComponentLines.ToArray();
			var wheelOrderLine1 = componentLines1[0];
			wheelOrderLine1.PickLines.ForEach(pl => pl.WZ_PickedDateTime = ZDateTimeOffset.Now);
			var frameOrderLine1 = componentLines1[1];
			frameOrderLine1.PickLines.ForEach(pl => pl.WZ_PickedDateTime = ZDateTimeOffset.Now);

			var componentLines2 = orderLine2.ChildComponentLines.ToArray();
			var wheelOrderLine2 = componentLines2[0];
			wheelOrderLine2.PickLines.ForEach(pl => pl.WZ_PickedDateTime = ZDateTimeOffset.Now);
			var frameOrderLine2 = componentLines2[1];
			frameOrderLine2.PickLines.ForEach(pl => pl.WZ_PickedDateTime = ZDateTimeOffset.Now);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			pick = newFactory.Load<WhsPick>(pick.PK);
			pick.FinalisePick();
			Factory.Save();

			var createdReceive = newFactory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			var createdReceiveLines = createdReceive.Lines;

			AssertNull("No last query", Notify.LastQueryUserEventArgs);
			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals(2, createdReceiveLines.Count);
			AssertEquals(true, createdReceiveLines.Single(l => l.ProductCode.Equals("BIKE")).IsFinalised);
			AssertEquals(true, createdReceiveLines.Single(l => l.ProductCode.Equals("MOTO")).IsFinalised);
		}

