			wheelPickLine2 = newFactory.Load<WhsPickLine>(wheelPickLine2.PK);
			kitPickLine = newFactory.Load<WhsPickLine>(kitPickLine.PK);

			AssertEquals(true, wheelPickLine1.IsPicked);
			AssertEquals(12m, wheelPickLine1.WZ_Units);
			AssertEquals(true, wheelTransferLine1.IsFinalised);
			AssertEquals(createdReceive.WD_FinalisedDate, wheelPickLine1.WZ_PickedDateTime);
			AssertEquals(data.Whs1.WW_DefaultOutboundDockDoor, wheelTransferLine1.WE_WL);

			AssertEquals(true, wheelPickLine2.IsPicked);
			AssertEquals(8m, wheelPickLine2.WZ_Units);
			AssertEquals(true, wheelTransferLine2.IsFinalised);
			AssertEquals(createdReceive.WD_FinalisedDate, wheelPickLine2.WZ_PickedDateTime);
			AssertEquals(data.Whs1.WW_DefaultOutboundDockDoor, wheelTransferLine2.WE_WL);

			AssertEquals(true, kitPickLine.IsPicked);
			AssertEquals(10m, kitPickLine.WZ_Units);
			AssertEquals(createdReceive.WD_FinalisedDate, kitPickLine.WZ_PickedDateTime);
			AssertEquals("Was directly picked.", true, kitPickLine.WZ_WE_OriginalPickedInventoryLine.IsEmpty);
			AssertEquals(location.PK, createdReceiveLine.WE_WL);

			AssertEquals("2 for components, we won't generate kit transfer lines for simplicity.", 2, pick.Transfers.Single().Lines.Count);
		}

