			AssertEquals("Precondition: component order lines created.", 1, orderLine2.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single();
			var wheelPickLine1 = wheelOrderLine1.PickLines.Single();
			var kitPickLine1 = orderLine1.PickLines.Single();

			var wheelOrderLine2 = orderLine2.ChildComponentLines.Single();
			var wheelPickLine2 = wheelOrderLine2.PickLines.Single();
			var kitPickLine2 = orderLine2.PickLines.Single();

			// mock fully shorting so orderLine2 will have component order line without pick line
			wheelPickLine2.Delete();
			kitPickLine2.InventoryLine.Delete();
			kitPickLine2.Delete();

			pick.FinaliseAllOrders();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var dockDoorLocation = newFactory.Load<WhsLocation>(data.Whs1.DefaultOutboundDockDoorLocation.PK);
			pick = newFactory.Load<WhsPick>(pick.PK);
			var createdReceive = newFactory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			var createdReceiveLine = createdReceive.Lines.Single();

			AssertEquals("Precondition", false, pick.IsFinalised);
			AssertEquals("Precondition", false, createdReceive.IsFinalised);
			AssertEquals("Precondition", false, createdReceiveLine.IsFinalised);

			pick.NotificationManager.Push(Notify);
			Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;

			pick.FinalisePick();
			newFactory.Save();

			var lastQueryEventArgs = (DefaultableQueryUserEventArgs)Notify.LastQueryUserEventArgs;
			AssertEquals("Caption on query matches", "Continue?", lastQueryEventArgs.Caption);
			AssertEquals("Message on query matches", "Not all allocated lines have been picked, please confirm that you want to finalize the pick which will automatically mark any un-picked lines as picked.", lastQueryEventArgs.Message);
			AssertEquals("Response is as set", true, lastQueryEventArgs.Response);

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals(true, createdReceiveLine.IsFinalised);

			AssertEquals(true, wheelPickLine1.IsPicked);
			AssertEquals(true, kitPickLine1.IsPicked);
			AssertEquals(0, pick.Transfers.Count);
		}

