		#region TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted

		public void TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted_TheOtherComponentsWerePickedAndHaveTransferLines()
		{
			TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted_Core(areRemainingComponentsPicked: true);
		}

		public void TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted_TheOtherComponentsWereNotPickedAndHaveNoTransferLines()
		{
			TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted_Core(areRemainingComponentsPicked: false);
		}

		void TestPickFinalise_PickByBOM_HandleOverPickedComponents_OneComponentsWereFullyShorted_Core(bool areRemainingComponentsPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");
			var location3 = data.Whs1.FindLocation("A-3");
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			var horn = Helper.CreateProduct(data.Org1, "HORN");
			Helper.CreateProductBOM(bike, wheel, 2m, "UNT");
			Helper.CreateProductBOM(bike, frame, 1m, "UNT");
			Helper.CreateProductBOM(bike, horn, 1m, "UNT");

			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 100m, location1, palletID: "");
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", frame, 100m, location2, palletID: "");
			var receive3 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", horn, 100m, location3, palletID: "");
			var hornReceiveLine = receive3.Lines[0];
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 10m);
			var pick = Helper.CreatePickNew(order);

			AssertEquals("Precondition: component order lines created.", 3, orderLine1.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine1 = wheelOrderLine1.PickLines.Single();
			var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine1 = frameOrderLine1.PickLines.Single();
			var hornOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == horn.PK);
			var hornPickLine1 = hornOrderLine1.PickLines.Single();
			var kitPickLine1 = orderLine1.PickLines.Single();

			// mock fully shorting wheels so all frames will be over-picked
			wheelPickLine1.Delete();
			kitPickLine1.InventoryLine.Delete();
			kitPickLine1.Delete();

			if (areRemainingComponentsPicked)
			{
				framePickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now;
				hornPickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(10);
			}

			Factory.Save();

			AssertEquals(areRemainingComponentsPicked, framePickLine1.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, hornPickLine1.IsPickedFromPutawayLocation);

			if (areRemainingComponentsPicked)
			{
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, framePickLine1.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, hornPickLine1.InventoryLine.WE_CurrentInventoryStatus);
			}

			pick.FinaliseAllOrders();
			Factory.Save();

			var createdReceive = Factory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Precondition: Kit Receive Line was deleted through shorting.", 0, createdReceive.Lines.Count);

			AssertEquals("Precondition", false, pick.IsFinalised);
			AssertEquals("Precondition", false, createdReceive.IsFinalised);

			if (!areRemainingComponentsPicked)
			{
				pick.NotificationManager.Push(Notify);
				Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;
			}

			pick.FinalisePick();
			Factory.Save();

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals("New Lines for the over-picked components.", 2, createdReceive.Lines.Count);

			var line1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == frame.PK);
			var frameRceiveLine1 = framePickLine1.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line1, frame.PK, 10m, location2.PK, frameRceiveLine1.WE_AdjustmentArrivalDate, frameRceiveLine1);

			var line2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == horn.PK);
			AssertOverPickedComponentReceiveLine(line2, horn.PK, 10m, location3.PK, hornReceiveLine.WE_AdjustmentArrivalDate, hornReceiveLine);
		}

		void AssertOverPickedComponentReceiveLine(WhsReceiveLine line, ZGuid productPK, decimal qty, ZGuid locationPK, ZDateTimeOffset arrivalDate, WhsDocketLine originalInventoryLine = null, bool isKitLine = false)
		{
			AssertEquals(productPK, line.WE_OP);
			AssertEquals(qty, line.WE_TransactionQuantity);
			AssertEquals(qty, line.WE_ClientOrderedUnits);
			AssertEquals(isKitLine ? 0m : qty, line.WE_StockOnHand);
			AssertEquals(locationPK, line.WE_WL);
			AssertEquals(InventoryStatus.Codes.Available, line.WE_CurrentInventoryStatus);
			AssertEquals(InventoryStatus.Codes.Available, line.WE_OriginalInventoryStatus);
			AssertEquals(arrivalDate, line.WE_AdjustmentArrivalDate);
			AssertEquals(DocketStatus.Codes.Finalised, line.WE_DocketLineStatus);

			if (originalInventoryLine != null)
			{
				AssertEquals(originalInventoryLine.WE_F3_NKPackType, line.WE_F3_NKPackType);
				AssertEquals(originalInventoryLine.WE_PartAttrib1, line.WE_PartAttrib1);
				AssertEquals(originalInventoryLine.WE_PartAttrib2, line.WE_PartAttrib2);
				AssertEquals(originalInventoryLine.WE_PartAttrib3, line.WE_PartAttrib3);
				AssertEquals(originalInventoryLine.WE_SerialNumber, line.WE_SerialNumber);
				AssertEquals(originalInventoryLine.WE_PackingDate, line.WE_PackingDate);
				AssertEquals(originalInventoryLine.WE_ExpiryDate, line.WE_ExpiryDate);
			}
		}

