		public void TestPickFinalise_PickByBOM_HandleOverPickedComponents_TwoComponentsWerePartiallyShorted_TheOtherComponentsWereNotPickedAndHaveNoTransferLines()
		{
			TestPickFinalise_PickByBOM_HandleOverPickedComponents_TwoComponentsWerePartiallyShorted_Core(areRemainingComponentsPicked: false);
		}

		void TestPickFinalise_PickByBOM_HandleOverPickedComponents_TwoComponentsWerePartiallyShorted_Core(bool areRemainingComponentsPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");
			var location3 = data.Whs1.FindLocation("A-3");
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			var horn = Helper.CreateProduct(data.Org1, "HORN");
			Helper.CreateProductBOM(bike, wheel, 2m, "UNT");
			Helper.CreateProductBOM(bike, frame, 1m, "UNT");
			Helper.CreateProductBOM(bike, horn, 1m, "UNT");

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 6m, areRemainingComponentsPicked ? location1 : location2, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", wheel, 4m, location2, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", frame, 3m, location2, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", frame, 2m, areRemainingComponentsPicked ? location3 : location2, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R5", horn, 5m, areRemainingComponentsPicked ? location3 : location2, palletID: "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 5m);
			var pick = Helper.CreatePickNew(order);

			AssertEquals("Precondition: component order lines created.", 3, orderLine1.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine1 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 4m);
			var wheelPickLine2 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 6m);
			var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine1 = frameOrderLine1.PickLines.Single(pl => pl.WZ_Units == 3m);
			var framePickLine2 = frameOrderLine1.PickLines.Single(pl => pl.WZ_Units == 2m);
			var hornOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == horn.PK);
			var hornPickLine1 = hornOrderLine1.PickLines.Single();
			var kitPickLine1 = orderLine1.PickLines.Single();
			var kitReceiveLine = kitPickLine1.InventoryLine;

			// mock partially shorting wheels and frames
			DeletePickLineAndRecreateLinks(wheelPickLine1, wheelOrderLine1.PK, kitReceiveLine.PK, 6m);
			DeletePickLineAndRecreateLinks(framePickLine1, frameOrderLine1.PK, kitReceiveLine.PK, 2m);

			kitReceiveLine.WE_ClientOrderedUnits = 2m;
			kitReceiveLine.WE_StockOnHand = 2m;
			kitPickLine1.WZ_Units = 2m;

			if (areRemainingComponentsPicked)
			{
				wheelPickLine2.WZ_PickedDateTime = ZDateTimeOffset.Now;
				framePickLine2.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(10);
				hornPickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(20);
			}

			Factory.Save();

			AssertEquals(areRemainingComponentsPicked, wheelPickLine2.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, framePickLine2.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, hornPickLine1.IsPickedFromPutawayLocation);

			if (areRemainingComponentsPicked)
			{
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, wheelPickLine2.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, framePickLine2.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, hornPickLine1.InventoryLine.WE_CurrentInventoryStatus);
			}

			pick.FinaliseAllOrders();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			pick = newFactory.Load<WhsPick>(pick.PK);
			var createdReceive = newFactory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Precondition: Kit Receive Line.", 1, createdReceive.Lines.Count);
			AssertEquals("Precondition: Kit Receive Line.", 2m, createdReceive.Lines[0].WE_TransactionQuantity);
			AssertEquals("Precondition", false, pick.IsFinalised);
			AssertEquals("Precondition", false, createdReceive.IsFinalised);

			if (!areRemainingComponentsPicked)
			{
				pick.NotificationManager.Push(Notify);
				Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;
			}

			pick.FinalisePick();
			newFactory.Save();

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals("New Lines for the over-picked components.", 3, createdReceive.Lines.Count);

			wheelPickLine2 = newFactory.Load<WhsPickLine>(wheelPickLine2.PK);
			hornPickLine1 = newFactory.Load<WhsPickLine>(hornPickLine1.PK);

			var line0 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == bike.PK);
			AssertOverPickedComponentReceiveLine(line0, bike.PK, 2m, areRemainingComponentsPicked ? location3.PK : location2.PK, createdReceive.WD_ArrivalDate, isKitLine: true);

			var line1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == wheel.PK);
			var wheelReceiveLine2 = wheelPickLine2.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line1, wheel.PK, 2m, areRemainingComponentsPicked ? location1.PK : location2.PK, wheelReceiveLine2.WE_AdjustmentArrivalDate, wheelReceiveLine2);

			var line2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == horn.PK);
			var hornReceiveLine1 = hornPickLine1.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line2, horn.PK, 3m, areRemainingComponentsPicked ? location3.PK : location2.PK, hornReceiveLine1.WE_AdjustmentArrivalDate, hornReceiveLine1);
		}

