		void TestPickFinalise_PickByBOM_HandleOverPickedComponents_RetainAttributes_Core(bool areRemainingComponentsPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var location = data.Whs1.FindLocation("A");

			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			var horn = Helper.CreateProduct(data.Org1, "HORN");
			Helper.CreateProductBOM(bike, wheel, 2m, "UNT");
			Helper.CreateProductBOM(bike, frame, 1m, "UNT");
			Helper.CreateProductBOM(bike, horn, 1m, "UNT");

			Helper.SetClientAllAttributeType(data.Org1, false);
			Helper.SetProductAllAttributeUse(data.Org1, frame, use: true, useSerialNumber: false);
			Factory.Save();

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 20m, location, palletID: "");
			var frameReceive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R3");
			var expireDate = new ZDate(2024, 7, 7);
			var packingDate = new ZDate(2024, 7, 6);
			var frameReceiveLine = Helper.CreateWhsReceiveLine(frameReceive, frame, 10m, location, palletID: "", expireDate, packingDate, "A1", "A2", "A3", "BEK-1");
			frameReceiveLine.WE_F3_NKPackType = "PLT";
			frameReceive.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(frameReceive);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", horn, 9m, location, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R5", horn, 1m, location, palletID: "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			AssertEquals("Precondition: component order lines created.", 3, orderLine1.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine1 = wheelOrderLine1.PickLines.Single();
			var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine1 = frameOrderLine1.PickLines.Single();
			var hornOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == horn.PK);
			var hornPickLine1 = hornOrderLine1.PickLines.Single(pl => pl.WZ_Units == 9m);
			var hornPickLine2 = hornOrderLine1.PickLines.Single(pl => pl.WZ_Units == 1m);
			var kitPickLine1 = orderLine1.PickLines.Single();
			var kitReceiveLine1 = kitPickLine1.InventoryLine;

			// mock partially shorting horns
			DeletePickLineAndRecreateLinks(hornPickLine2, hornOrderLine1.PK, kitReceiveLine1.PK, 9m);

			kitReceiveLine1.WE_ClientOrderedUnits = 9m;
			kitReceiveLine1.WE_StockOnHand = 9m;
			kitPickLine1.WZ_Units = 9m;

			if (areRemainingComponentsPicked)
			{
				wheelPickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now;
				framePickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(10);
				hornPickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(20);
			}

			Factory.Save();

			AssertEquals(areRemainingComponentsPicked, framePickLine1.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, hornPickLine1.IsPickedFromPutawayLocation);

			if (areRemainingComponentsPicked)
			{
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, framePickLine1.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, hornPickLine1.InventoryLine.WE_CurrentInventoryStatus);
			}
			pick.FinaliseAllOrders();
			Factory.Save();

			AssertEquals("Precondition", false, pick.IsFinalised);

			if (!areRemainingComponentsPicked)
			{
				pick.NotificationManager.Push(Notify);
				Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;
			}

			var newFactory = new BusinessObjectFactory();
			pick = newFactory.Load<WhsPick>(pick.PK);
			var createdReceive = newFactory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));

			AssertEquals("Precondition", 1, createdReceive.Lines.Count);
			AssertEquals("Precondition", false, createdReceive.IsFinalised);

			pick.FinalisePick();
			newFactory.Save();

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals("New Lines for the over-picked components.", 3, createdReceive.Lines.Count);

			kitPickLine1 = newFactory.Load<WhsPickLine>(kitPickLine1.PK);
			framePickLine1 = newFactory.Load<WhsPickLine>(framePickLine1.PK);
			wheelPickLine1 = newFactory.Load<WhsPickLine>(wheelPickLine1.PK);

			var line0 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == bike.PK);
			AssertOverPickedComponentReceiveLine(line0, bike.PK, 9m, location.PK, createdReceive.WD_ArrivalDate, kitPickLine1.InventoryLineForAvailableInventory, isKitLine: true);

			var line1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == frame.PK);
			var frameReceiveLine1 = framePickLine1.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line1, frame.PK, 1m, location.PK, frameReceiveLine1.WE_AdjustmentArrivalDate, frameReceiveLine1);

			var line2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == wheel.PK);
			var wheelReceiveLine1 = wheelPickLine1.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line2, wheel.PK, 2m, location.PK, wheelReceiveLine1.WE_AdjustmentArrivalDate, wheelReceiveLine1);
		}

