		void TestPickFinalise_PickByBOM_HandleOverPickedComponents_MultipleOrderLinesOnSingleOrder_Core(bool areRemainingComponentsPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");
			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			Helper.CreateProductBOM(bike, wheel, 2m, "UNT");
			Helper.CreateProductBOM(bike, frame, 1m, "UNT");

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 6m, location1, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", wheel, 4m, location2, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", frame, 5m, location2, palletID: "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 3m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, bike, 2m);
			var pick = Helper.CreatePickNew(order);

			AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelOrderLine2 = orderLine2.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine1 = wheelOrderLine1.PickLines.Single();
			var wheelPickLine2 = wheelOrderLine2.PickLines.Single();
			var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var frameOrderLine2 = orderLine2.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine1 = frameOrderLine1.PickLines.Single();
			var framePickLine2 = frameOrderLine2.PickLines.Single();
			var kitPickLine1 = orderLine1.PickLines.Single();
			var kitPickLine2 = orderLine2.PickLines.Single();
			var kitReceiveLine1 = kitPickLine1.InventoryLine;
			var kitReceiveLine2 = kitPickLine2.InventoryLine;

			// mock fully shorting frames so all wheels will be over-picked
			framePickLine1.Delete();
			framePickLine2.Delete();
			kitPickLine1.InventoryLine.Delete();
			kitPickLine1.Delete();
			kitPickLine2.InventoryLine.Delete();
			kitPickLine2.Delete();

			if (areRemainingComponentsPicked)
			{
				wheelPickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now;
				wheelPickLine2.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(10);
			}

			Factory.Save();

			AssertEquals(areRemainingComponentsPicked, wheelPickLine1.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, wheelPickLine2.IsPickedFromPutawayLocation);

			if (areRemainingComponentsPicked)
			{
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, wheelPickLine1.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, wheelPickLine2.InventoryLine.WE_CurrentInventoryStatus);
			}

			pick.FinaliseAllOrders();
			Factory.Save();

			var createdReceive = Factory.LoadTop1<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Precondition: Kit Receive Lines are all deleted.", 0, createdReceive.Lines.Count);
			AssertEquals("Precondition", false, pick.IsFinalised);
			AssertEquals("Precondition", false, createdReceive.IsFinalised);

			if (!areRemainingComponentsPicked)
			{
				pick.NotificationManager.Push(Notify);
				Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;
			}

			pick.FinalisePick();
			Factory.Save();

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive.IsFinalised);
			AssertEquals("New Lines for the over-picked components.", 2, createdReceive.Lines.Count);

			var line1 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 6m);
			var wheelReceiveLine1 = wheelPickLine1.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line1, wheel.PK, 6m, location1.PK, wheelReceiveLine1.WE_AdjustmentArrivalDate, wheelReceiveLine1);

			var line2 = (WhsReceiveLine)createdReceive.Lines.Single(l => l.WE_OP == wheel.PK && l.WE_TransactionQuantity == 4m);
			var wheelReceiveLine2 = wheelPickLine2.InventoryLineForAvailableInventory;
			AssertOverPickedComponentReceiveLine(line2, wheel.PK, 4m, location2.PK, wheelReceiveLine2.WE_AdjustmentArrivalDate, wheelReceiveLine2);
		}

