		public void TestPickFinalise_PickByBOM_HandleOverPickedComponents_OrdersOnMultipleClients_RemaingComponentAreNotPicked()
		{
			TestPickFinalise_PickByBOM_HandleOverPickedComponents_OrdersOnMultipleClients_Core(areRemainingComponentsPicked: false);
		}

		void TestPickFinalise_PickByBOM_HandleOverPickedComponents_OrdersOnMultipleClients_Core(bool areRemainingComponentsPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var org2 = Helper.CreateClient("ORG2");
			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");

			var bike = Helper.CreateProduct(data.Org1, "BIKE");
			bike.OP_IsComponentPickedOnSalesOrder = true;
			var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
			var frame = Helper.CreateProduct(data.Org1, "FRAME");
			Helper.CreateProductBOM(bike, wheel, 2m, "UNT");
			Helper.CreateProductBOM(bike, frame, 1m, "UNT");

			Helper.CreateProductClientRelationShip(org2, bike);
			Helper.CreateProductClientRelationShip(org2, wheel);
			Helper.CreateProductClientRelationShip(org2, frame);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 6m, location1, palletID: "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", wheel, 4m, areRemainingComponentsPicked ? location2 : location1, palletID: "");
			var frameReceive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", frame, 5m, areRemainingComponentsPicked ? location2 : location1, palletID: "");

			Helper.CreateWhsReceiveWithInventory(org2, data.Whs1, "R4", wheel, 6m, location1, palletID: "");
			Helper.CreateWhsReceiveWithInventory(org2, data.Whs1, "R5", wheel, 4m, areRemainingComponentsPicked ? location2 : location1, palletID: "");
			var frameReceive2 = Helper.CreateWhsReceiveWithInventory(org2, data.Whs1, "R6", frame, 5m, areRemainingComponentsPicked ? location2 : location1, palletID: "");

			Factory.Save();

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine1 = Helper.CreateWhsOrderLine(order1, bike, 5m);
			var order2 = Helper.CreateWhsOrder(org2, data.Whs1, "O2");
			var orderLine2 = Helper.CreateWhsOrderLine(order2, bike, 5m);
			var pick = Helper.CreatePickNew(order1, order2);

			AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);
			AssertEquals("Precondition: component order lines created.", 2, orderLine2.ChildComponentLines.Count);

			var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine1_1 = wheelOrderLine1.PickLines.Single(l => l.WZ_Units == 6m);
			var wheelPickLine1_2 = wheelOrderLine1.PickLines.Single(l => l.WZ_Units == 4m);

			var wheelOrderLine2 = orderLine2.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
			var wheelPickLine2_1 = wheelOrderLine2.PickLines.Single(l => l.WZ_Units == 6m);
			var wheelPickLine2_2 = wheelOrderLine2.PickLines.Single(l => l.WZ_Units == 4m);

			var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine1 = frameOrderLine1.PickLines.Single();

			var frameOrderLine2 = orderLine2.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
			var framePickLine2 = frameOrderLine2.PickLines.Single();

			var kitPickLine1 = orderLine1.PickLines.Single();
			var kitPickLine2 = orderLine2.PickLines.Single();
			var kitReceiveLine1 = kitPickLine1.InventoryLine;
			var kitReceiveLine2 = kitPickLine2.InventoryLine;

			// mock partially shorting wheels so some frames will be over-picked
			DeletePickLineAndRecreateLinks(wheelPickLine1_1, wheelOrderLine1.PK, kitReceiveLine1.PK, 4m);
			DeletePickLineAndRecreateLinks(wheelPickLine2_2, wheelOrderLine2.PK, kitReceiveLine2.PK, 6m);

			kitReceiveLine1.WE_ClientOrderedUnits = 2m;
			kitReceiveLine1.WE_StockOnHand = 2m;
			kitPickLine1.WZ_Units = 2m;

			kitReceiveLine2.WE_ClientOrderedUnits = 3m;
			kitReceiveLine2.WE_StockOnHand = 3m;
			kitPickLine2.WZ_Units = 3m;

			if (areRemainingComponentsPicked)
			{
				wheelPickLine1_2.WZ_PickedDateTime = ZDateTimeOffset.Now;
				wheelPickLine2_1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(10);
				framePickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(20);
				framePickLine2.WZ_PickedDateTime = ZDateTimeOffset.Now.AddMinutes(30);
			}

			Factory.Save();

			AssertEquals(areRemainingComponentsPicked, wheelPickLine1_2.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, wheelPickLine2_1.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, framePickLine1.IsPickedFromPutawayLocation);
			AssertEquals(areRemainingComponentsPicked, framePickLine2.IsPickedFromPutawayLocation);

			if (areRemainingComponentsPicked)
			{
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, wheelPickLine1_2.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, wheelPickLine2_1.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, framePickLine1.InventoryLine.WE_CurrentInventoryStatus);
				AssertEquals("In-Transit Transfer Line was created.", InventoryStatus.Codes.InTransit, framePickLine2.InventoryLine.WE_CurrentInventoryStatus);
			}

			pick.FinaliseAllOrders();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			pick = newFactory.Load<WhsPick>(pick.PK);
			var createdReceive = newFactory.Load<WhsReceive>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForReceive, pick.PK));
			AssertEquals("Precondition", 2, createdReceive.Length);

			var createdReceive1 = createdReceive.Single(r => r.WD_OH_Client == data.Org1.PK);
			AssertEquals("Precondition", 1, createdReceive1.Lines.Count);
			AssertEquals("Precondition", false, createdReceive1.IsFinalised);

			var createdReceive2 = createdReceive.Single(r => r.WD_OH_Client == org2.PK);
			AssertEquals("Precondition", 1, createdReceive2.Lines.Count);
			AssertEquals("Precondition", false, createdReceive2.IsFinalised);

			AssertEquals("Precondition", false, pick.IsFinalised);

			if (!areRemainingComponentsPicked)
			{
				pick.NotificationManager.Push(Notify);
				Notify.PreQueryUser += (sender, e) => ((DefaultableQueryUserEventArgs)e).Response = true;
			}

			pick.FinalisePick();
			newFactory.Save();

			AssertEquals(true, pick.IsFinalised);
			AssertEquals(true, createdReceive1.IsFinalised);
			AssertEquals(true, createdReceive2.IsFinalised);
			AssertEquals("New Lines for the over-picked components.", 2, createdReceive1.Lines.Count);
			AssertEquals("New Lines for the over-picked components.", 2, createdReceive2.Lines.Count);

			wheelPickLine1_2 = newFactory.Load<WhsPickLine>(wheelPickLine1_2.PK);
			wheelPickLine2_1 = newFactory.Load<WhsPickLine>(wheelPickLine2_1.PK);

			var locationPK = areRemainingComponentsPicked ? location2.PK : location1.PK;
			var line1_1 = (WhsReceiveLine)createdReceive1.Lines.Single(l => l.WE_OP == bike.PK);
			AssertOverPickedComponentReceiveLine(line1_1, bike.PK, 2m, locationPK, createdReceive1.WD_ArrivalDate, isKitLine: true);

			var line1_2 = (WhsReceiveLine)createdReceive1.Lines.Single(l => l.WE_OP == frame.PK);
			var frameReceiveLine1 = frameReceive1.Lines[0];
			AssertOverPickedComponentReceiveLine(line1_2, frame.PK, 3m, locationPK, frameReceiveLine1.WE_AdjustmentArrivalDate, frameReceiveLine1); // WE_AdjustmentArrivalDate must always match with the original inventory.

			var line2_1 = (WhsReceiveLine)createdReceive2.Lines.Single(l => l.WE_OP == bike.PK);
			AssertOverPickedComponentReceiveLine(line2_1, bike.PK, 3m, locationPK, createdReceive2.WD_ArrivalDate, isKitLine: true);

			var line2_2 = (WhsReceiveLine)createdReceive2.Lines.Single(l => l.WE_OP == frame.PK);
			var frameReceiveLine2 = frameReceive2.Lines[0];
			AssertOverPickedComponentReceiveLine(line2_2, frame.PK, 2m, locationPK, frameReceiveLine2.WE_AdjustmentArrivalDate, frameReceiveLine2); // WE_AdjustmentArrivalDate must always match with the original inventory.
		}

		void DeletePickLineAndRecreateLinks(WhsPickLine lineToDelete, ZGuid componentOrderLinePK, ZGuid kitReceiveLinePK, ZDecimal linkQuantity)
		{
			lineToDelete.Delete();
			var link = Factory.LoadTop1<WhsBOMInventoryPivot>(new ZQuery(WhsBOMInventoryPivotSchema.WIP_WE_ComponentLine, componentOrderLinePK));
			link.Delete();
			var newLink = Factory.New<WhsBOMInventoryPivot>();
			newLink.WIP_ComponentQuantity = linkQuantity;
			newLink.WIP_WE_ComponentLine = componentOrderLinePK;
			newLink.WIP_WE_InventoryLine = kitReceiveLinePK;
		}

		#endregion

		#region TestPickFinalise_DbHits_GetOrdersWithUnfinishedTotes

		public void TestPickFinalise_DbHits_GetOrdersWithUnfinishedTotes()
		{
			const int numberOfOrders = 10;
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 50m, data.Whs1.DefaultLocation, "111");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 50m, data.Whs1.DefaultLocation, "222");
			Factory.Save();

			var randomList = Enumerable.Range(0, numberOfOrders).OrderBy(x => Guid.NewGuid()).ToArray(); // to test order by in error massage

			var orders = new WhsOrder[numberOfOrders];
			for (var i = 0; i < numberOfOrders; i++)
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + randomList[i], data.Part1, 10m);
				orders[i] = order;
			}

			var pick = Helper.CreatePickNew(orders);

			foreach (var order in orders)
			{
				order.PackageJob.Packages.AddNew().SetIsTote(true);
				order.Lines[0].PickLines[0].WZ_PickedDateTime = ZDateTimeOffset.Today;
			}

			pick.AutoAllocateItemsWithMock();
			pick.FinaliseAllOrders();
			Factory.Save();

			AssertEquals("Precondition", false, pick.IsFinalised);

			var newFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
			var expectedHits = new Dictionary<string, int>
			{
				{ GenAddOnColumnSchema.Constants.TableName, 1 },
				{ PkgPackageSchema.Constants.TableName, 1 },
				{ PkgPackageJobSchema.Constants.TableName, 1 },
				{ WhsDocketSchema.Constants.TableName, 1 },
				{ WhsLoadOrderSchema.Constants.TableName, 1 },
				{ WhsPickSchema.Constants.TableName, 1 },
				{ OrgHeaderSchema.Constants.TableName, 1 },
			};

			using (AssertDbHitsWithUsefulQueryInformation(expectedHits, newFactory))
			{
				var status = pickInNewFactory.GetFinalisableStatus();
				CombineAssertions(() =>
				{
					AssertEquals("Pick is not finalisable", false, status.IsFinalisable);
					AssertEquals("Pick Finalisable error message", status.ErrorMessage, @"Cannot Finalize this pick as the following Orders have not finished Packing Totes:
O0
O1
O2
O3
O4
O5
O6
O7
O8
O9");
				});
			}
		}

		#endregion

