		#region TestPickFinalise_DbHits_GetNonStagedOrdersUsingConsolidation

		public void TestPickFinalise_DbHits_GetNonStagedOrdersUsingConsolidation()
		{
			const int numberOfOrders = 10;
			var packingHelper = new PackingTestHelper(Factory);
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var conLocationType = Factory.NewWithValidTestData<WhsLocationType>();
			conLocationType.WLT_LocationClass = LocationClasses.Codes.CON;
			var conLocation = data.Whs1.FindLocation("A-3");
			conLocation.WLV_WLT_LocationType = conLocationType.PK;
			var dockDoorLocation = data.Whs1.FindLocation("DOCKDOOR");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 50m, data.Whs1.DefaultLocation, "111");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 50m, data.Whs1.DefaultLocation, "222");
			Factory.Save();

			var randomList = Enumerable.Range(0, numberOfOrders).OrderBy(x => Guid.NewGuid()).ToArray(); // to test order by in error massage

			var orders = new WhsOrder[numberOfOrders];
			for (var i = 0; i < numberOfOrders; i++)
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + randomList[i], data.Part1, 10m);
				order.WD_UseDirectedPackingConsolidation = true;
				orders[i] = order;
			}

			var pick = Helper.CreatePickNew(orders);
			var handlingUnit = packingHelper.CreatePkgHandlingUnit(data.Whs1.WW_GB_RelatedCompanyBranch, "3PL");
			var handlingUnitPackageJob = PkgPackageJob.LoadOrCreatePackageJob(handlingUnit);
			var handlingUnitPackage = packingHelper.CreatePackage(handlingUnitPackageJob, $"HU1", 1, PkgUnit.Package);

			for (var i = 0; i < numberOfOrders; i++)
			{
				var order = orders[i];
				var pickLine = order.Lines[0].PickLines[0];
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;
				pickLine.WZ_GS_NKAssignedTo = GlbStaff.CurrentUser.GS_Code;
				Factory.Save();

				var pkgJob = PkgPackageJob.LoadOrCreatePackageJob(order);
				var pkg = packingHelper.CreatePackage(pkgJob, $"PKG{i}", 1, PkgUnit.Box);
				packingHelper.CreatePackageDivot(pkg, pickLine);

				packingHelper.PackHandlingUnit(handlingUnitPackage, pkg, handlingUnitPackage);
				Factory.Save();
			}

			var transfer = pick.Transfers[0];
			AssertNotNull("Precondition: Transfer Created.", transfer);
			foreach (var transferLine in pick.Transfers[0].Lines)
			{
				var transferPickLine = transferLine.PickLines[0];
				AssertEquals("Precondition: Transfer to Dock Door.", dockDoorLocation.PK, transferLine.WE_WL);

				transferLine.WE_WL = conLocation.PK;
				AssertEquals("Precondition: Changed to Transfer to CON Location.", conLocation.PK, transferLine.WE_WL);
			}
			Factory.Save();

			var service = new WhsPackingConsolidationService();
			var errorMessage = service.CreateDockDoorTransfer(handlingUnitPackage.PK);

			Assert("Should not have error.", errorMessage.IsNullOrEmpty());
			AssertEquals("New Transfer Lines to Dock Door created.", 20, transfer.Lines.Count);

			pick.AutoAllocateItemsWithMock();
			pick.FinaliseAllOrders();
			Factory.Save();

			AssertEquals("Precondition", false, pick.IsFinalised);

			var newFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
			var expectedHits = new Dictionary<string, int>
			{
				{ WhsDocketSchema.Constants.TableName, 1 },
				{ WhsLoadOrderSchema.Constants.TableName, 1 },
				{ WhsOrderStatusViewSchema.Constants.TableName, 1 },
				{ WhsPickSchema.Constants.TableName, 1 },
			};

			using (AssertDbHitsWithUsefulQueryInformation(expectedHits, newFactory))
			{
				var status = pickInNewFactory.GetFinalisableStatus();
				CombineAssertions(() =>
				{
					AssertEquals("Pick is not finalisable", false, status.IsFinalisable);
					AssertEquals("Pick Finalisable error message is given", status.ErrorMessage, @"Cannot Finalize this pick as the following Orders are using directed Consolidation and are not yet Staged:
O0
O1
O2
O3
O4
O5
O6
O7
O8
O9");
				});
			}
		}

