		#region TestCreateAutomatedStocktakes

		#region TestCreateAutomatedStocktakes_ForDifferentLocations

		public void TestCreateAutomatedStocktakes_Location()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 5);
			var locationWithNoMTC = data.Whs1.FindLocation("A-1-1");
			var locationWithMTCLessThanCTC = data.Whs1.FindLocation("A-1-2");
			var locationWithMTCEqualsCTC = data.Whs1.FindLocation("A-1-3");
			var locationWithMTCGreaterThanCTC = data.Whs1.FindLocation("A-1-4");
			var locationNotUsedInPickMTCEqualsCTC = data.Whs1.FindLocation("A-1-5");
			SetTouchCount(locationWithMTCLessThanCTC, 10, 11);
			SetTouchCount(locationWithMTCEqualsCTC, 11, 10);
			SetTouchCount(locationWithMTCGreaterThanCTC, 12, 10);
			SetTouchCount(locationNotUsedInPickMTCEqualsCTC, 20, 20);

			// create receive, orders and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, locationWithNoMTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 15m, locationWithNoMTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 5m, locationWithMTCLessThanCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 5m, locationWithMTCEqualsCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 5m, locationWithMTCGreaterThanCTC);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var orderWithDifferentProducts = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				var orderWithSameProduct = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
				Helper.CreateWhsOrderLine(orderWithDifferentProducts, data.Part1, 20m);
				Helper.CreateWhsOrderLine(orderWithDifferentProducts, data.Part2, 10m);
				Helper.CreateWhsOrderLine(orderWithSameProduct, data.Part2, 10m);

				var pick = Helper.CreatePickNew(orderWithDifferentProducts, orderWithSameProduct);
				pick.AutoAllocateItemsWithMock();
				pick.FinaliseAllOrders();

				// test touch counts finalise pick -- before saving
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertTouchCounts("Precondition", locationWithMTCLessThanCTC, 10, 11);
				AssertTouchCounts("Precondition", locationWithMTCEqualsCTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCGreaterThanCTC, 12, 10);
				AssertTouchCounts("Precondition", locationNotUsedInPickMTCEqualsCTC, 20, 20);
				AssertEquals("Precondition - No Stocktakes should be created.", 0, GetAutoCreatedStocktakes().Count());

				// test touch counts finalise pick -- after saving
				Factory.Save();
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertTouchCounts("Precondition", locationWithMTCLessThanCTC, 10, 0);
				AssertTouchCounts("Precondition", locationWithMTCEqualsCTC, 11, 0);
				AssertTouchCounts("Precondition", locationWithMTCGreaterThanCTC, 12, 11);
				AssertTouchCounts("Precondition", locationNotUsedInPickMTCEqualsCTC, 20, 20);

				// test automatically-created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - Two Automated stocktakes should be created.", 2, automatedStocktakes.Count());
				var stocktakeForMTCLessThanCTC = automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCLessThanCTC.PK);
				var stocktakeForMTCEqualsCTC = automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCEqualsCTC.PK);

				AssertAutomatedStocktake(stocktakeForMTCLessThanCTC, data.Org1, data.Whs1, locationWithMTCLessThanCTC, "ATC");
				AssertAutomatedStocktake(stocktakeForMTCEqualsCTC, data.Org1, data.Whs1, locationWithMTCEqualsCTC, "ATC");

				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTC.Lines.Single(), data.Org1, data.Part2,
					locationWithMTCLessThanCTC);
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTC.Lines.Single(), data.Org1, data.Part1,
					locationWithMTCEqualsCTC);
			}
		}

		public void TestCreateAutomatedStocktakes_Location_InTransit()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 5);
			var locationWithNoMTC = data.Whs1.FindLocation("A-1-1");
			var locationWithMTCEqualsCTC = data.Whs1.FindLocation("A-1-2");
			SetTouchCount(locationWithMTCEqualsCTC, 11, 10);

			// create receive, orders and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 20m, locationWithNoMTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, locationWithMTCEqualsCTC);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var orderWithDifferentProducts = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				var orderWithSameProduct = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
				Helper.CreateWhsOrderLine(orderWithDifferentProducts, data.Part1, 5m);
				Helper.CreateWhsOrderLine(orderWithDifferentProducts, data.Part2, 10m);
				Helper.CreateWhsOrderLine(orderWithSameProduct, data.Part2, 10m);

				var pick = Helper.CreatePickNew(orderWithDifferentProducts, orderWithSameProduct);
				pick.AutoAllocateItemsWithMock();

				foreach (var pickLine in pick.GetAllPickLines().ToArray())
				{
					Helper.PickAndMakeInTransitTransfer(pickLine, ZDateTimeOffset.Now);
				}

				pick.FinaliseAllOrders();

				// test touch counts finalise pick -- before saving
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertTouchCounts("Precondition", locationWithMTCEqualsCTC, 11, 10);
				AssertEquals("Precondition - No Stocktakes should be created.", 0, GetAutoCreatedStocktakes().Count());

				// test touch counts finalise pick -- after saving
				Factory.Save();
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertTouchCounts("Precondition", locationWithMTCEqualsCTC, 11, 0);

				// test automatically-created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - One Automated stocktake should be created.", 1, automatedStocktakes.Count());

				var stocktakeForMTCEqualsCTC = automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCEqualsCTC.PK);
				AssertAutomatedStocktake(stocktakeForMTCEqualsCTC, data.Org1, data.Whs1, locationWithMTCEqualsCTC, "ATC");
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTC.Lines.Single(), data.Org1, data.Part1, locationWithMTCEqualsCTC, 5m);
			}
		}

