		#region TestCreateAutomatedStocktakes_ForDifferentProductsInLocation

		public void TestCreateAutomatedStocktakes_ForDifferentProductsInLocation()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			Factory.Save();

			var locationWithMTCLessThanCTC = data.Whs1.FindLocation("A-1-1");
			var locationWithMTCEqualsCTC = data.Whs1.FindLocation("A-1-2");
			SetTouchCount(locationWithMTCLessThanCTC, 10, 11);
			SetTouchCount(locationWithMTCEqualsCTC, 11, 11);

			// create receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 15m, locationWithMTCLessThanCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 20m, locationWithMTCLessThanCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 5m, locationWithMTCEqualsCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 10m, locationWithMTCEqualsCTC);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				Helper.CreateWhsOrderLine(order, data.Part1, 20m);
				Helper.CreateWhsOrderLine(order, data.Part2, 25m);

				var pick = Helper.CreatePickNew(order);
				AssertEquals("Precondition", 2, pick.OrderedInventories.Count);
				var orderedInventoryForPart1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.SupplierPart.PK == data.Part1.PK);
				var orderedInventoryForPart2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.SupplierPart.PK == data.Part2.PK);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryForPart1, locationWithMTCLessThanCTC, true, false,
					15m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryForPart1, locationWithMTCEqualsCTC, true, false, 5m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryForPart2, locationWithMTCLessThanCTC, true, false,
					20m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryForPart2, locationWithMTCEqualsCTC, true, false, 5m);

				pick.FinaliseAllOrders();

				// test touch counts finalising the pick -- after saving
				pick.FinalisePick();
				Factory.Save();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Precondition", locationWithMTCLessThanCTC, 10, 0);
				AssertTouchCounts("Precondition", locationWithMTCEqualsCTC, 11, 0);

				// test automatically created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - Two stocktakes should exist.", 2, automatedStocktakes.Count());
				var stocktakeForMTCLessThanCTC = automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCLessThanCTC.PK);
				var stocktakeForMTCEqualsCTC = automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCEqualsCTC.PK);

				AssertAutomatedStocktake(stocktakeForMTCLessThanCTC, data.Org1, data.Whs1, locationWithMTCLessThanCTC, "ATC");
				AssertAutomatedStocktake(stocktakeForMTCEqualsCTC, data.Org1, data.Whs1, locationWithMTCEqualsCTC, "ATC");

				AssertEquals("Precondition - stocktakeForMTCLessThanCTC stocktake should have two lines for each product.", 2,
					stocktakeForMTCLessThanCTC.Lines.Count);
				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTC.Lines.Single(l => l.WU_OP == data.Part1.PK), data.Org1,
					data.Part1, locationWithMTCLessThanCTC);
				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTC.Lines.Single(l => l.WU_OP == data.Part2.PK), data.Org1,
					data.Part2, locationWithMTCLessThanCTC);

				AssertEquals("Precondition - stocktakeForMTCEqualsCTC stocktake should have two lines for each product.", 2,
					stocktakeForMTCEqualsCTC.Lines.Count);
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTC.Lines.Single(l => l.WU_OP == data.Part1.PK), data.Org1,
					data.Part1, locationWithMTCEqualsCTC);
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTC.Lines.Single(l => l.WU_OP == data.Part2.PK), data.Org1,
					data.Part2, locationWithMTCEqualsCTC, 5m);
			}
		}

