		#region TestCreateAutomatedStocktakes_ForDifferentClientsInLocation

		public void TestCreateAutomatedStocktakes_ForDifferentClientsInLocation()
		{
			// setup data
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			var org2 = Helper.CreateClient("2");
			Helper.CreateProductClientRelationShip(org2, data.Part1, OrgPartRelation.RelationshipTypes.Owner);
			Factory.Save();

			var locationWithMTCLessThanCTC = data.Whs1.FindLocation("A-1-1");
			var locationWithMTCEqualsCTC = data.Whs1.FindLocation("A-1-2");
			SetTouchCount(locationWithMTCLessThanCTC, 10, 11);
			SetTouchCount(locationWithMTCEqualsCTC, 11, 11);

			// Create receives, orders and pick
			var receiveOrg1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var receiveOrg2 = Helper.CreateWhsReceive(org2, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receiveOrg1, data.Part1, 5m, locationWithMTCLessThanCTC);
			Helper.CreateWhsReceiveInventoryLine(receiveOrg1, data.Part1, 10m, locationWithMTCEqualsCTC);
			Helper.CreateWhsReceiveInventoryLine(receiveOrg2, data.Part1, 15m, locationWithMTCLessThanCTC);
			Helper.CreateWhsReceiveInventoryLine(receiveOrg2, data.Part1, 20m, locationWithMTCEqualsCTC);
			receiveOrg1.FinaliseDocket();
			receiveOrg2.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receiveOrg1);
			AssertIsFinalisedPrecondition(receiveOrg2);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var orderForOrg1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				var orderForOrg2 = Helper.CreateWhsOrder(org2, data.Whs1, "1");
				Helper.CreateWhsOrderLine(orderForOrg1, data.Part1, 8m);
				Helper.CreateWhsOrderLine(orderForOrg2, data.Part1, 25m);

				var pick = Helper.CreatePickNew(orderForOrg1, orderForOrg2);
				AssertEquals("Precondition", 2, pick.OrderedInventories.Count);
				var orderedIOnventoryForOrg1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.Client.PK == data.Org1.PK);
				var orderedIOnventoryForOrg2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.Client.PK == org2.PK);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedIOnventoryForOrg1, locationWithMTCLessThanCTC, true, false,
					5m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedIOnventoryForOrg1, locationWithMTCEqualsCTC, true, false, 3m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedIOnventoryForOrg2, locationWithMTCLessThanCTC, true, false,
					15m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedIOnventoryForOrg2, locationWithMTCEqualsCTC, true, false,
					10m);
				pick.FinaliseAllOrders();

				// test touch counts after finalising the pick -- after saving
				pick.FinalisePick();
				Factory.Save();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts(locationWithMTCLessThanCTC, 10, 0);
				AssertTouchCounts(locationWithMTCEqualsCTC, 11, 0);

				// test automatically created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - Four Automated stocktakes should be created.", 4, automatedStocktakes.Count());
				var stocktakeForMTCLessThanCTCForOrg1 =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCLessThanCTC.PK &&
													s.WS_OH_Client == data.Org1.PK);
				var stocktakeForMTCEqualsCTCForOrg1 =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCEqualsCTC.PK && s.WS_OH_Client == data.Org1.PK);
				var stocktakeForMTCLessThanCTCForOrg2 =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCLessThanCTC.PK && s.WS_OH_Client == org2.PK);
				var stocktakeForMTCEqualsCTCForOrg2 =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithMTCEqualsCTC.PK && s.WS_OH_Client == org2.PK);

				AssertAutomatedStocktake(stocktakeForMTCLessThanCTCForOrg1, data.Org1, data.Whs1, locationWithMTCLessThanCTC, "ATC");
				AssertAutomatedStocktake(stocktakeForMTCEqualsCTCForOrg1, data.Org1, data.Whs1, locationWithMTCEqualsCTC, "ATC");
				AssertAutomatedStocktake(stocktakeForMTCLessThanCTCForOrg2, org2, data.Whs1, locationWithMTCLessThanCTC, "ATC");
				AssertAutomatedStocktake(stocktakeForMTCEqualsCTCForOrg2, org2, data.Whs1, locationWithMTCEqualsCTC, "ATC");

				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTCForOrg1.Lines.Single(), data.Org1, data.Part1,
					locationWithMTCLessThanCTC);
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTCForOrg1.Lines.Single(), data.Org1, data.Part1,
					locationWithMTCEqualsCTC, 7m);
				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTCForOrg2.Lines.Single(), org2, data.Part1,
					locationWithMTCLessThanCTC);
				AssertAutomatedStocktakeLine(stocktakeForMTCEqualsCTCForOrg2.Lines.Single(), org2, data.Part1,
					locationWithMTCEqualsCTC, 10m);
			}
		}

