		#region TestCreateAutomatedStocktakes_AllocatedAvailableInventory

		public void TestCreateAutomatedStocktakes_AllocatedAvailableInventory()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			var locationWithAllocatedInventory = data.Whs1.FindLocation("A-1-1");
			var locationWithoutAllocatedInventory = data.Whs1.FindLocation("A-1-2");
			SetTouchCount(locationWithAllocatedInventory, 2, 1);
			SetTouchCount(locationWithoutAllocatedInventory, 2, 1);

			// Create receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1, locationWithAllocatedInventory);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1, locationWithoutAllocatedInventory);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
				Helper.CreateWhsOrderLine(order, data.Part1, 1m);

				var pick = Helper.CreatePickNew(order);
				AssertEquals("Precondtion", 2, pick.OrderedInventories[0].AvailableInventories.Count);
				var allocatedLine = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>()
					.Single(l => l.LocationPK == locationWithAllocatedInventory.PK);
				allocatedLine.Allocate = true;
				pick.FinaliseAllOrders();

				// test touch counts after finalising and saving the pick
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				Factory.Save();
				AssertTouchCounts("Touch count should have ticked over.", locationWithAllocatedInventory, 2, 0);
				AssertTouchCounts("Touch count should not be changed.", locationWithoutAllocatedInventory, 2, 1);

				// test automatically created stocktake
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertAutomatedStocktake(automatedStocktakes.Single(), data.Org1, data.Whs1, locationWithAllocatedInventory, "ATC");
				AssertAutomatedStocktakeLine(automatedStocktakes.Single().Lines.Single(), data.Org1, data.Part1,
					locationWithAllocatedInventory);
			}
		}

