		[TestDate(2012, 08, 20)]
		public void TestCreateAutomatedStocktakes_WithExistingInventory()
		{
			// setup data
			var today = ZDate.Today;
			var data = new TestDataSimpleEnvironment(Factory, 1, 3);
			var org2 = Helper.CreateClient("O2", "ORG2");
			Helper.SetProductAllAttributeUse(data.Org1, data.Part1, true);
			Helper.SetClientAllAttributeType(data.Org1, false);
			Helper.CreateProductClientRelationShip(org2, data.Part1);

			var locationWithMTC1 = data.Whs1.FindLocation("A-1-1");
			var locationWithMTC2 = data.Whs1.FindLocation("A-1-2");
			var locationWithNoMTC = data.Whs1.FindLocation("A-1-3");
			SetTouchCount(locationWithMTC1, 2, 1);
			SetTouchCount(locationWithMTC2, 3, 2);

			// create receives, orders and pick

			var receiveForOrg1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, locationWithMTC1, today.AddDays(1),
				today.AddDays(-1), "1", "2", "3", "5");
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, locationWithMTC1, today.AddDays(2),
				today.AddDays(-2), "2", "3", "4", "6");
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, locationWithMTC1, today.AddDays(3),
				today.AddDays(-3), "3", "4", "5", "7");
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part2, 15m, locationWithMTC1);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, locationWithNoMTC, today.AddDays(3),
				today.AddDays(-3), "6", "7", "8", "8");

			var receiveForOrg2 = Helper.CreateWhsReceive(org2, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg2, data.Part1, 10m, locationWithMTC1);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg2, data.Part1, 10m, locationWithMTC2);

			receiveForOrg1.FinaliseDocket();
			receiveForOrg2.FinaliseDocket();
			AssertIsFinalisedPrecondition(receiveForOrg1);
			AssertIsFinalisedPrecondition(receiveForOrg2);

			var orderForOrg1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			var orderForOrg2 = Helper.CreateWhsOrder(org2, data.Whs1, "2");
			Helper.CreateWhsOrderLine(orderForOrg1, data.Part1, 2m);
			Helper.CreateWhsOrderLine(orderForOrg2, data.Part1, 15m);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var pick = Helper.CreatePickNew(orderForOrg1, orderForOrg2);
				var avlLinesForOrg1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(o => o.Client.PK == data.Org1.PK).AvailableInventories.Cast<WhsPickAvailableInventory>();
				var avlLinesForOrg2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(o => o.Client.PK == org2.PK)
					.AvailableInventories.Cast<WhsPickAvailableInventory>();
				avlLinesForOrg1.Single(l => l.Location == locationWithMTC1 && l.PartAttrib1 == "1").Allocate = true;
				avlLinesForOrg1.Single(l => l.Location == locationWithMTC1 && l.PartAttrib1 == "2").Allocate = true;
				avlLinesForOrg2.Single(l => l.Location == locationWithMTC1).Allocate = true;
				avlLinesForOrg2.Single(l => l.Location == locationWithMTC2).Allocate = true;
				pick.FinaliseAllOrders();

				// test touch counts after finalising and saving the pick
				pick.FinalisePick();
				Factory.Save();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Touch counts should be ticked over.", locationWithMTC1, 2, 0);
				AssertTouchCounts("Touch counts should be ticked over.", locationWithMTC2, 3, 0);
				AssertTouchCounts("Touched counts should not be changed.", locationWithNoMTC, 0, 0);

				// test automatically created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Three stocktakes should be created.", 3, automatedStocktakes.Count());
				var stocktakeForOrg1AndLocationWithMTC1 =
					automatedStocktakes.Single(s => s.WS_OH_Client == data.Org1.PK && s.WS_WL_Location == locationWithMTC1.PK);
				var stocktakeForOrg2AndLocationWithMTC1 =
					automatedStocktakes.Single(s => s.WS_OH_Client == org2.PK && s.WS_WL_Location == locationWithMTC1.PK);
				var stocktakeForOrg2AndLocationWithMTC2 =
					automatedStocktakes.Single(s => s.WS_OH_Client == org2.PK && s.WS_WL_Location == locationWithMTC2.PK);

				AssertAutomatedStocktake(stocktakeForOrg1AndLocationWithMTC1, data.Org1, data.Whs1, locationWithMTC1, "ATC");
				AssertAutomatedStocktake(stocktakeForOrg2AndLocationWithMTC1, org2, data.Whs1, locationWithMTC1, "ATC");
				AssertAutomatedStocktake(stocktakeForOrg2AndLocationWithMTC2, org2, data.Whs1, locationWithMTC2, "ATC");

				AssertEquals(4, stocktakeForOrg1AndLocationWithMTC1.Lines.Count);
				AssertAutomatedStocktakeLine(
					stocktakeForOrg1AndLocationWithMTC1.Lines.Single(l => l.WU_OP == data.Part1.PK && l.PartAttrib1 == "1"), data.Org1,
					data.Part1, locationWithMTC1, 0m);
				AssertAutomatedStocktakeLine(
					stocktakeForOrg1AndLocationWithMTC1.Lines.Single(l => l.WU_OP == data.Part1.PK && l.PartAttrib1 == "2"), data.Org1,
					data.Part1, locationWithMTC1, 0m);
				AssertAutomatedStocktakeLine(
					stocktakeForOrg1AndLocationWithMTC1.Lines.Single(l => l.WU_OP == data.Part1.PK && l.PartAttrib1 == "3"), data.Org1,
					data.Part1, locationWithMTC1, 1m);
				AssertAutomatedStocktakeLine(stocktakeForOrg1AndLocationWithMTC1.Lines.Single(l => l.WU_OP == data.Part2.PK),
					data.Org1, data.Part2, locationWithMTC1, 15m);

				AssertAutomatedStocktakeLine(stocktakeForOrg2AndLocationWithMTC1.Lines.Single(), org2, data.Part1, locationWithMTC1,
					0m);
				AssertAutomatedStocktakeLine(stocktakeForOrg2AndLocationWithMTC2.Lines.Single(), org2, data.Part1, locationWithMTC2,
					5m);
			}
		}

