		#region TestCreateAutomatedStocktakes_SetPickedDateTimeBeforeFinalisePick

		public void TestCreateAutomatedStocktakes_SetPickedDateTimeBeforeFinalisePick()
		{
			// setup location, client and client product relationship for the new client
			var data = new TestDataSimpleEnvironment(Factory);
			var location = data.Whs1.FindLocation("A");
			SetTouchCount(location, 2, 1);

			// create receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, location);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				Helper.CreateWhsOrderLine(order1, data.Part1, 5m);
				var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "2");
				Helper.CreateWhsOrderLine(order2, data.Part1, 5m);

				var finalisedPick = Helper.CreatePickNew(order1);

				var availableInventory = finalisedPick.OrderedInventories[0].AvailableInventories[0];
				var pickLine = availableInventory.PickLines.ElementAt(0);
				availableInventory.PickLineQuantity = 3m;
				pickLine.WZ_PickedDateTime = ZDateTimeOffset.Today;

				finalisedPick.AutoAllocateItemsWithMock();

				// this is specifically testing Picked PickLines in the DB on an unfinalised Pick
				using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
				{
					Factory.Save();
				}

				AssertEquals("Precondition", 2, availableInventory.PickLines.Count());
				AssertEquals("Precondition - PickLine1 should be picked", true, availableInventory.PickLines.ElementAt(0).IsPicked);
				AssertEquals("Precondition - PickLine2 should not be picked", false, availableInventory.PickLines.ElementAt(1).IsPicked);
				AssertEquals("Precondition", 2m, availableInventory.PickLines.ElementAt(1).WZ_Units);

				finalisedPick.FinaliseAllOrders();
				finalisedPick.FinalisePick();
				Factory.Save();

				AssertIsFinalisedPrecondition(order1);
				AssertIsFinalisedPrecondition(finalisedPick);
				AssertTouchCounts("Touch count should have ticked over.", location, 2, 0);

				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals(1, automatedStocktakes.Count());
				var stocktake = automatedStocktakes.First();
				AssertAutomatedStocktake(stocktake, data.Org1, data.Whs1, location, StocktakeTypeCodeList.Codes.AutomaticTouchCount);
				AssertEquals("Precondition - There should be one line for Part1.", 1, stocktake.Lines.Count);
				AssertAutomatedStocktakeLine(stocktake.Lines.Single(), data.Org1, data.Part1, location, 5m);
			}
		}

