		#region TestCreateAutomatedStocktakes_NotCreatedForLocationsThatAlreadyHaveOpenStocktakes

		public void TestCreateAutomatedStocktakes_NotCreatedForLocationsThatAlreadyHaveOpenStocktakes()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 3);
			var locationWithOpenedStocktake = data.Whs1.FindLocation("A-1-1");
			var locationWithClosedStocktake = data.Whs1.FindLocation("A-1-2");
			var locationWithNotOpenedStocktake = data.Whs1.FindLocation("A-1-3");
			SetTouchCount(locationWithOpenedStocktake, 2, 1);
			SetTouchCount(locationWithClosedStocktake, 3, 2);
			SetTouchCount(locationWithNotOpenedStocktake, 4, 3);

			// create stocktakes
			var openedStocktake = Helper.CreateWhsStocktake(data.Org1, data.Whs1, StocktakeStatus.Codes.Loaded);
			var closedStocktake = Helper.CreateWhsStocktake(data.Org1, data.Whs1, StocktakeStatus.Codes.Finalised);
			Helper.CreateWhsStocktakeLine(openedStocktake, data.Org1, data.Part1, locationWithOpenedStocktake,
				StocktakeLineStatus.Codes.Open, InventoryStatus.Codes.Available);
			Helper.CreateWhsStocktakeLine(openedStocktake, data.Org1, data.Part1, locationWithOpenedStocktake,
				StocktakeLineStatus.Codes.Closed, InventoryStatus.Codes.Available);
			Helper.CreateWhsStocktakeLine(closedStocktake, data.Org1, data.Part1, locationWithClosedStocktake,
				StocktakeLineStatus.Codes.Closed, InventoryStatus.Codes.Available);

			// create receive, pick and order
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, locationWithOpenedStocktake);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, locationWithClosedStocktake);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, locationWithNotOpenedStocktake);
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			Helper.CreateWhsOrderLine(order, data.Part1, 3m);

			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var pick = Helper.CreatePickNew(order);
				pick.AutoAllocateItemsWithMock();
				pick.FinaliseAllOrders();

				// test touch counts after saving finalised pick
				pick.FinalisePick();
				Factory.Save();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts(locationWithOpenedStocktake, 2, 0);
				AssertTouchCounts(locationWithClosedStocktake, 3, 0);
				AssertTouchCounts(locationWithNotOpenedStocktake, 4, 0);

				// test automatically created stocktakes
				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - Two stocktakes should be created for each locations which doesn't have a stocktake.", 2,
					automatedStocktakes.Count());
				var stocktakeForLocationWithClosedStocktake =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithClosedStocktake.PK);
				var stocktakeForLocationWithNoOpenedStocktake =
					automatedStocktakes.Single(s => s.WS_WL_Location == locationWithNotOpenedStocktake.PK);

				AssertAutomatedStocktake(stocktakeForLocationWithClosedStocktake, data.Org1, data.Whs1, locationWithClosedStocktake,
					"ATC");
				AssertAutomatedStocktake(stocktakeForLocationWithNoOpenedStocktake, data.Org1, data.Whs1,
					locationWithNotOpenedStocktake, "ATC");

				AssertAutomatedStocktakeLine(stocktakeForLocationWithClosedStocktake.Lines.Single(), data.Org1, data.Part1,
					locationWithClosedStocktake, 0m);
				AssertAutomatedStocktakeLine(stocktakeForLocationWithNoOpenedStocktake.Lines.Single(), data.Org1, data.Part1,
					locationWithNotOpenedStocktake, 0m);
			}
		}

