		#region TestCreateAutomatedStocktakes_Attributes

		public void TestCreateAutomatedStocktakes_Attributes()
		{
			// setup locations
			var year = ZDate.Today.Year;
			var data = new TestDataSimpleEnvironment(Factory, 1, 3);
			data.Whs1.WW_VerifyEmptyLocations = true;
			Helper.SetClientAllAttributeType(data.Org1, true);
			Helper.SetProductAllAttributeUse(data.Org1, data.Part1, true, useSerialNumber: true);

			var emptyLocationAndVerifiedEmpty = data.Whs1.FindLocation("A-1-1");

			// setup receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventory = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, emptyLocationAndVerifiedEmpty);
			Helper.SetDocketLineAttributes(inventory.InDocketLine, new ZDate(year + 1, 1, 1), new ZDate(year + 1, 1, 2), "PA1", "PA2", "PA3", "SN1");

			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", Notify);
			Helper.CreateWhsOrderLine(order, data.Part1, 1m);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var pick = Helper.CreatePickNew(order);
				pick.FinaliseAllOrders();
				var orderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single();
				var availableInventory = orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>().Single();
				availableInventory.VerifiedNonEmpty = true;

				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				Factory.Save();

				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals(1, automatedStocktakes.Count());
				AssertEquals(1, automatedStocktakes.First().Lines.Count);

				var stocktakeLine = automatedStocktakes.First().Lines.Single();
				AssertEquals(nameof(stocktakeLine.WU_IsManuallyAdded), false, stocktakeLine.WU_IsManuallyAdded);
				AssertEquals(nameof(stocktakeLine.WU_OP), data.Part1.PK, stocktakeLine.WU_OP);
				AssertEquals(nameof(stocktakeLine.WU_PartAttrib1), "PA1", stocktakeLine.WU_PartAttrib1);
				AssertEquals(nameof(stocktakeLine.WU_PartAttrib2), "PA2", stocktakeLine.WU_PartAttrib2);
				AssertEquals(nameof(stocktakeLine.WU_PartAttrib3), "PA3", stocktakeLine.WU_PartAttrib3);
				AssertEquals(nameof(stocktakeLine.WU_ExpiryDate), new ZDate(year + 1, 1, 1), stocktakeLine.WU_ExpiryDate);
				AssertEquals(nameof(stocktakeLine.WU_PackingDate), new ZDate(year + 1, 1, 2), stocktakeLine.WU_PackingDate);
				AssertEquals(nameof(stocktakeLine.WU_SerialNumber), "SN1", stocktakeLine.WU_SerialNumber);
			}
		}

