		#region TestCreateAutomatedStocktakes_ForAllClientsInTouchedLocation

		public void TestCreateAutomatedStocktakes_ForAllClientsInTouchedLocation()
		{
			// setup location, client and client product relationship for the new client
			var data = new TestDataSimpleEnvironment(Factory);
			var location = data.Whs1.FindLocation("A");
			SetTouchCount(location, 2, 1);
			var org2 = Helper.CreateClient("O2");
			Helper.CreateProductClientRelationShip(org2, data.Part1);
			Helper.CreateProductClientRelationShip(org2, data.Part2);

			// create receive, order and pick
			var receiveForOrg1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var receiveForOrg2 = Helper.CreateWhsReceive(org2, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, location);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg2, data.Part1, 2m, location);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg2, data.Part2, 3m, location);
			receiveForOrg1.FinaliseDocket();
			receiveForOrg2.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receiveForOrg1);
			AssertIsFinalisedPrecondition(receiveForOrg2);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var orderForOrg1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				var orderForOrg2 = Helper.CreateWhsOrder(org2, data.Whs1, "1");
				Helper.CreateWhsOrderLine(orderForOrg1, data.Part1, 1m); // Order everything for Part1 of Org1
				Helper.CreateWhsOrderLine(orderForOrg2, data.Part1, 1m); // 1 item left for Part1 of Org2

				var finalisedPick = Helper.CreatePickNew(orderForOrg1);
				var nonFinalisedPick = Helper.CreatePickNew(orderForOrg2); // To create committed inventory
				finalisedPick.FinaliseAllOrders();
				AssertIsFinalisedPrecondition(orderForOrg1);
				AssertEquals("Precondition", false, orderForOrg2.IsFinalised);

				// test touch counts after finalising and saving the pick
				finalisedPick.FinalisePick();
				Factory.Save();
				AssertIsFinalisedPrecondition(finalisedPick);
				AssertTouchCounts("Touch count should have ticked over.", location, 2, 0);

				var automatedStocktakes = GetAutoCreatedStocktakes();
				AssertEquals("Precondition - Two stocktakes should be created for each client in the location.", 2,
					automatedStocktakes.Count());
				var stocktakeForOrg1 = automatedStocktakes.Single(s => s.Client.PK == data.Org1.PK);
				var stocktakeForOrg2 = automatedStocktakes.Single(s => s.Client.PK == org2.PK);
				AssertAutomatedStocktake(stocktakeForOrg1, data.Org1, data.Whs1, location,
					StocktakeTypeCodeList.Codes.AutomaticTouchCount);
				AssertAutomatedStocktake(stocktakeForOrg2, org2, data.Whs1, location,
					StocktakeTypeCodeList.Codes.AutomaticTouchCount);
				AssertEquals("Precondition - There should be one line for Part1.", 1, stocktakeForOrg1.Lines.Count);
				AssertEquals("Precondition - There should be two lines, each line for Part1 and Part2.", 2,
					stocktakeForOrg2.Lines.Count);
				AssertAutomatedStocktakeLine(stocktakeForOrg1.Lines.Single(), data.Org1, data.Part1, location);
				AssertAutomatedStocktakeLine(stocktakeForOrg2.Lines.Single(l => l.WU_OP == data.Part1.PK), org2, data.Part1,
					location, 2m);
				AssertAutomatedStocktakeLine(stocktakeForOrg2.Lines.Single(l => l.WU_OP == data.Part2.PK), org2, data.Part2,
					location, 3m);
			}
		}

