				AssertAutomatedStocktake(automatedStocktakes.Single(), org2, data.Whs1, location,
					StocktakeTypeCodeList.Codes.AutomaticTouchCount);
				AssertAutomatedStocktakeLine(automatedStocktakes.Single().Lines.Single(), org2, data.Part1, location, 2m);
			}
