		#region TestCreateAutomatedStocktakes_OnSave

		public void TestCreateAutomatedStocktakes_OnSave()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 3);
			var locationWithMTC = data.Whs1.FindLocation("A-1-1");
			var locationWithMTCNotAllocatedToFinalisedPick = data.Whs1.FindLocation("A-1-2");
			var locationWithNoMTC = data.Whs1.FindLocation("A-1-3");
			SetTouchCount(locationWithMTC, 11, 10);
			SetTouchCount(locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
			SetTouchCount(locationWithNoMTC, 0, 0);

			// create receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 3m, locationWithMTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, locationWithMTCNotAllocatedToFinalisedPick);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 15m, locationWithNoMTC);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
				Helper.CreateWhsOrderLine(order, data.Part1, 5m);
				Helper.CreateWhsOrderLine(order, data.Part2, 10m);

				var packageJob = PkgPackageJob.LoadOrCreatePackageJob(order);
				packageJob.Packages.AddNew();

				var pick = Helper.CreatePickNew(order);

				// allocate available inventory lines
				AssertEquals("Precondition - There should be two ordered inventory lines fro each product.", 2,
					pick.OrderedInventories.Count);
				var availableInventoryLinesForPart1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(o => o.SupplierPart.PK == data.Part1.PK).AvailableInventories.Cast<WhsPickAvailableInventory>();
				var availableInventoryLinesForPart2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(o => o.SupplierPart.PK == data.Part2.PK).AvailableInventories.Cast<WhsPickAvailableInventory>();
				AssertEquals("Precondition - There should be two available inventory lines", 2,
					availableInventoryLinesForPart1.Count());
				var avlInvLineForLocationNotAllocatedToFinalisedPick =
					availableInventoryLinesForPart1.Single(l => l.LocationPK == locationWithMTCNotAllocatedToFinalisedPick.PK);
				var avlInvLineForLocationWithNoMTC = availableInventoryLinesForPart2.Single();
				avlInvLineForLocationNotAllocatedToFinalisedPick.Allocate = true;
				avlInvLineForLocationWithNoMTC.Allocate = true;
				avlInvLineForLocationNotAllocatedToFinalisedPick.PickLineQuantity = 2m;
				avlInvLineForLocationWithNoMTC.PickLineQuantity = 10m;
				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - No Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				// allocate available inventory from a different location
				avlInvLineForLocationNotAllocatedToFinalisedPick.Allocate = false;
				var avlInvLineForLocationWithMTC = availableInventoryLinesForPart1.Single(l => l.LocationPK == locationWithMTC.PK);
				avlInvLineForLocationWithMTC.Allocate = true;
				avlInvLineForLocationWithMTC.PickLineQuantity = 2m;
				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - No Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				// increase allocated quantity
				avlInvLineForLocationWithMTC.PickLineQuantity = 10m;
				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - No Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				// reduce allocated quantity
				avlInvLineForLocationWithMTC.PickLineQuantity = 5m;
				avlInvLineForLocationWithMTC.Allocate = true;
				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - No Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				pick.FinaliseAllOrders();
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);

				// test touch counts before saving
				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - No Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				// save failure -- ensure no stocktake created
				var dodgyOrg = Factory.New<OrgHeader>();
				dodgyOrg.OH_Code = "abc";
				dodgyOrg.OH_ScreeningStatus = "abc";
				AssertExceptionThrown("Precondition - That org has no relevance to this test other than to ensure saving will fail due to invalid column.", typeof(ZSaveException), () => Factory.Save());
				dodgyOrg.Delete(); // cleanup

				AssertTouchCounts("Precondition", locationWithMTC, 11, 10);
				AssertTouchCounts("Precondition", locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Precondition", locationWithNoMTC, 0, 0);
				AssertEquals("Precondition - One Stocktakes should exist.", 0, GetAutoCreatedStocktakes().Count());

				// test touch counts after saving
				Factory.Save();
				AssertTouchCounts("Touch count should have ticked over on save.", locationWithMTC, 11, 0);
				AssertTouchCounts("Location is not used in finalised pick, Touch Count should not have changed.",
					locationWithMTCNotAllocatedToFinalisedPick, 11, 10);
				AssertTouchCounts("Location does not use touch count, Touch Count should not have changed on save.",
					locationWithNoMTC, 0, 0);

				// test the automatically-created stocktake
				var stocktakeForMTCLessThanCTC = GetAutoCreatedStocktakes().Single(s => !s.IsDeleted);
				AssertAutomatedStocktake(stocktakeForMTCLessThanCTC, data.Org1, data.Whs1, locationWithMTC, "ATC");
				AssertAutomatedStocktakeLine(stocktakeForMTCLessThanCTC.Lines.Single(), data.Org1, data.Part1, locationWithMTC);
			}
		}

		#endregion

