			dockDoorLocation1.WLV_WLT_LocationType = dockDoorLocationType.PK;
			var nonDockDoorLocation = data.Whs1.FindLocation("A-1-2");

			var puttingAwayReceive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
