			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m, nonDockDoorLocation, "PLT2");
			Factory.Save();

			AssertEquals("Precondition: Putting-Away receive is not finalised", false, puttingAwayReceive.IsFinalised);
			AssertIsFinalisedPrecondition(receive);

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1, "TR1", Notify);
			transfer.WD_IsPutawayTransfer = true;
