			transferLine1.PickedTime = ZDateTimeOffset.Now;

			AssertEquals($"Precondition: InventoryStatus of Transfer Line should be {InventoryStatus.Codes.PuttingAway}.", InventoryStatus.Codes.PuttingAway, transferLine1.WE_CurrentInventoryStatus);
			AssertEquals($"Precondition: InventoryStatus of Inventory should be {InventoryStatus.Codes.Received}.", InventoryStatus.Codes.Received, inventory.WI_InventoryStatus);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
				var pick = Helper.CreatePickNew(order);

				pick.FinaliseAllOrders();
				var orderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single();
				AssertEquals("Precondition", 1, orderedInventory.AvailableInventories.Count);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventory, nonDockDoorLocation, true, true, 10m);

				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				AssertEquals("Precondition - No Stocktakes should be created.", 0, GetAutoCreatedStocktakes().Count());

				Factory.Save();

				// test automatically-created stocktakes
