			var emptyLocationNotUseCTCWithNonZeroCTC = data.Whs1.FindLocation("A-1-3");
			var nonEmptyLocationUseCTC = data.Whs1.FindLocation("A-1-4");
			var nonEmptyLocationNotUseCTC = data.Whs1.FindLocation("A-1-5");
			var nonEmptyLocationNotUseCTCWithNonZeroCTC = data.Whs1.FindLocation("A-1-6");
			var allocatedVerifiedNonEmptyLocationUseCTC = data.Whs1.FindLocation("A-1-7");
			var notAllocatedEmptyLocationUseCTC = data.Whs1.FindLocation("A-1-8");
			SetTouchCount(emptyLocationUseCTC, 2, 1);
			SetTouchCount(emptyLocationNotUseCTC, 0, 0);
			SetTouchCount(emptyLocationNotUseCTCWithNonZeroCTC, 0, 2);
			SetTouchCount(nonEmptyLocationUseCTC, 3, 1);
			SetTouchCount(nonEmptyLocationNotUseCTC, 0, 0);
			SetTouchCount(nonEmptyLocationNotUseCTCWithNonZeroCTC, 0, 2);
			SetTouchCount(allocatedVerifiedNonEmptyLocationUseCTC, 2, 0);
			SetTouchCount(notAllocatedEmptyLocationUseCTC, 3, 1);

			// create receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, emptyLocationUseCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, emptyLocationNotUseCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, emptyLocationNotUseCTCWithNonZeroCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, nonEmptyLocationUseCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, nonEmptyLocationNotUseCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, nonEmptyLocationNotUseCTCWithNonZeroCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, allocatedVerifiedNonEmptyLocationUseCTC);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 20m, notAllocatedEmptyLocationUseCTC);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
				Helper.CreateWhsOrderLine(order, data.Part1, 80m);

				var pick = Helper.CreatePickNew(order);
				var orderedInventoryLine = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single();
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, emptyLocationUseCTC, true, false, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, emptyLocationNotUseCTC, true, false, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, emptyLocationNotUseCTCWithNonZeroCTC, true,
					false, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, nonEmptyLocationUseCTC, true, false, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, nonEmptyLocationNotUseCTC, true, false, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, nonEmptyLocationNotUseCTCWithNonZeroCTC, true,
					true, 10m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, allocatedVerifiedNonEmptyLocationUseCTC, true,
					true, 20m);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventoryLine, notAllocatedEmptyLocationUseCTC, false, false,
					0m);
				pick.FinaliseAllOrders();

				// finalise pick -- before saving
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts(emptyLocationUseCTC, 2, 1);
				AssertTouchCounts(emptyLocationNotUseCTC, 0, 0);
				AssertTouchCounts(emptyLocationNotUseCTCWithNonZeroCTC, 0, 2);
				AssertTouchCounts(nonEmptyLocationUseCTC, 3, 1);
				AssertTouchCounts(nonEmptyLocationNotUseCTC, 0, 0);
				AssertTouchCounts(nonEmptyLocationNotUseCTCWithNonZeroCTC, 0, 2);
				AssertTouchCounts(allocatedVerifiedNonEmptyLocationUseCTC, 2, 0);
				AssertTouchCounts(notAllocatedEmptyLocationUseCTC, 3, 1);

				// finalise pick -- after saving
				Factory.Save();
				AssertTouchCounts("Since location is confirmed empty current touch should be reset.", emptyLocationUseCTC, 2, 0);
				AssertTouchCounts("Empty location doesn't use current touch count.", emptyLocationNotUseCTC, 0, 0);
				AssertTouchCounts("Empty location doesn't use current touch count.", emptyLocationNotUseCTCWithNonZeroCTC, 0, 2);
				AssertTouchCounts("Since location is not empty current touch count should not be changed.", nonEmptyLocationUseCTC,
					3, 2);
				AssertTouchCounts("Non empty location doesn't use current touch count.", nonEmptyLocationNotUseCTC, 0, 0);
				AssertTouchCounts("Non empty location doesn't use current touch count.", nonEmptyLocationNotUseCTCWithNonZeroCTC, 0,
					2);
				AssertTouchCounts("Since location is verified non-empty current touch count is incremented.",
					allocatedVerifiedNonEmptyLocationUseCTC, 2, 1);
				AssertTouchCounts("Since location is not allocated it should not change current touch count.",
					notAllocatedEmptyLocationUseCTC, 3, 1);
			}
		}

		WhsPickAvailableInventory AllocateAndVerifiedEmptyAvailableInventoryLines(
			WhsPickOrderedInventory orderedInventoryLine, WhsLocation location, bool isAllocate, bool isVerifiedNonEmpty,
			decimal pickedQty)
		{
			var result = orderedInventoryLine.AvailableInventories.Cast<WhsPickAvailableInventory>()
				.Single(l => l.LocationPK == location.PK);
			if (isAllocate)
			{
				result.PickLineQuantity = pickedQty;
			}
			result.VerifiedNonEmpty = isVerifiedNonEmpty;

			return result;
		}

