		#region TestCreateAutomatedStocktakes_ResettingCurrentTouchCount_ForSameLocationDifferentProducts

		public void TestCreateAutomatedStocktakes_ResettingCurrentTouchCount_ForSameLocationDifferentProducts()
		{
			// setup locations and touch counts
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			data.Whs1.WW_VerifyEmptyLocations = true;
			var org2 = Helper.CreateClient("O2");
			Helper.CreateProductClientRelationShip(org2, data.Part1);
			var locationHasTwoProducts = data.Whs1.FindLocation("A-1-1");
			var locationHasTwoClients = data.Whs1.FindLocation("A-1-2");
			SetTouchCount(locationHasTwoProducts, 3, 1);
			SetTouchCount(locationHasTwoClients, 4, 2);

			// create receives, orders and pick
			var receiveForOrg1 = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var receiveForOrg2 = Helper.CreateWhsReceive(org2, data.Whs1, "R2", Notify);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 1m, locationHasTwoProducts);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part2, 2m, locationHasTwoProducts);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg1, data.Part1, 3m, locationHasTwoClients);
			Helper.CreateWhsReceiveInventoryLine(receiveForOrg2, data.Part1, 4m, locationHasTwoClients);
			receiveForOrg1.FinaliseDocket();
			receiveForOrg2.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receiveForOrg1);
			AssertIsFinalisedPrecondition(receiveForOrg2);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var orderForOrg1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
				var orderForOrg2 = Helper.CreateWhsOrder(org2, data.Whs1, "O2", WhsPickOption.Codes.Manual);
				Helper.CreateWhsOrderLine(orderForOrg1, data.Part1, 4m);
				Helper.CreateWhsOrderLine(orderForOrg1, data.Part2, 1m);
				Helper.CreateWhsOrderLine(orderForOrg2, data.Part1, 2m);

				var pick = Helper.CreatePickNew(orderForOrg1, orderForOrg2);
				AssertEquals("Precondition", 3, pick.OrderedInventories.Count);
				var orderedInvLineForOrg1Part1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.Client.PK == data.Org1.PK && l.SupplierPart.PK == data.Part1.PK);
				var orderedInvLineForOrg1Part2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.Client.PK == data.Org1.PK && l.SupplierPart.PK == data.Part2.PK);
				var orderedInvLineForOrg2Part1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
					.Single(l => l.Client.PK == org2.PK && l.SupplierPart.PK == data.Part1.PK);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInvLineForOrg1Part1, locationHasTwoProducts, true, false,
					1m); // location is empty for client org1 and part1
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInvLineForOrg1Part1, locationHasTwoClients, true, false,
					3m); // location is empty for client org1 and part1
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInvLineForOrg1Part2, locationHasTwoProducts, true, true,
					1m); // location is not empty for client org1 and part2
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInvLineForOrg2Part1, locationHasTwoClients, true, true,
					2m); // location is not empty for client org2 and part1

				pick.FinaliseAllOrders();
				AssertIsFinalisedPrecondition(orderForOrg1);
				AssertIsFinalisedPrecondition(orderForOrg2);

				// finalise pick -- before saving
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Precondtion", locationHasTwoProducts, 3, 1);
				AssertTouchCounts("Precondtion", locationHasTwoClients, 4, 2);

				// finalise pick -- after saving
				Factory.Save();
				AssertTouchCounts("Touch counts should not be reset since for one product location is not empty.",
					locationHasTwoProducts, 3, 2);
				AssertTouchCounts("Touch counts should not be reset since for one client location is not empty.",
					locationHasTwoClients, 4, 3);
			}
		}

