		#region TestCreateAutomatedStocktakes_DbHits

		[StressTest]
		public void TestCreateAutomatedStocktakes_DbHits()
		{
			// setup locations
			var data = new TestDataSimpleEnvironment(Factory, 1, 100);
			data.Whs1.WW_VerifyEmptyLocations = true;

			// setup receive, order and pick
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			foreach (var location in data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations)
			{
				SetTouchCount(location, 2, 1);
				Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, location);
			}
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
				Helper.CreateWhsOrderLine(order, data.Part1, 100m);

				var pick = Helper.CreatePickNew(order);
				pick.FinaliseAllOrders();
				AssertIsFinalisedPrecondition(order);
				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var pickInAnotherFactory = newFactory.Load<WhsPick>(pick.PK);
				pickInAnotherFactory.FinalisePick();
				AssertIsFinalisedPrecondition(pickInAnotherFactory);

				var dbHitsBeforePickSaving = newFactory.GetTableHitCount(WhsStocktakeLineSchema.Constants.TableName);
				newFactory.Save();
				AssertEquals(dbHitsBeforePickSaving + 1, newFactory.GetTableHitCount(WhsStocktakeLineSchema.Constants.TableName));
			}
		}

