		#region TestCreateAutomatedStocktakes_OnlyIncreaseTouchCountForFreshlyFinalisedPicks

		public void TestCreateAutomatedStocktakes_OnlyIncreaseTouchCountForFreshlyFinalisedPicks()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			SetTouchCount(data.Whs1.DefaultLocation, 5, 0);
			data.Whs1.WW_VerifyEmptyLocations = true;

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var finalisedOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
				var finalisedPick = Helper.CreatePickByAttachingOrders(finalisedOrder);
				var totalPickLineQuantity = Helper.GetTotalPickLineQuantity(finalisedPick);
				finalisedPick.FinaliseAllOrders();
				finalisedPick.FinalisePick();
				AssertEquals("Precondition - pick should not be saved to DB.", false, finalisedPick.IsInDatabase);
				AssertEquals("Precondition", 10m, totalPickLineQuantity);
				AssertIsFinalisedPrecondition(finalisedOrder);
				AssertIsFinalisedPrecondition(finalisedPick);

				Factory.Save();
				AssertTouchCounts("Pick was finalised location should have been touched once.", data.Whs1.DefaultLocation, 5, 1);

				var notFinalisedOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
				var notFinalisedPick = Helper.CreatePickNew(notFinalisedOrder);
				var totalQuantitynotFinalisedPicked = Helper.GetTotalPickLineQuantity(notFinalisedPick);

				AssertEquals("Precondition", 10m, totalQuantitynotFinalisedPicked);

				Factory.Save();
				AssertTouchCounts("Should not have touched location again since the new pick was not finalised.",
					data.Whs1.DefaultLocation, 5, 1);
			}
		}

