		public void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_VerifiedNonEmpty()
		{
			TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolderCore(verifiedNonEmpty: true);
		}

		public void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_NotVerifiedNonEmpty()
		{
			TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolderCore(verifiedNonEmpty: false);
		}

		void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolderCore(bool verifiedNonEmpty)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_VerifyEmptyLocations = true;
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var pick = Helper.CreatePickNew(order);
				var orderedInventories = pick.OrderedInventories;
				var pickAvailableInventory = orderedInventories[0].AvailableInventories[0];
				pickAvailableInventory.VerifiedNonEmpty = verifiedNonEmpty;
				AssertEquals("Precondition: Only one OrderedInventories.", 1, orderedInventories.Count);
				AssertEquals("Precondition: Only one AvailableInventories.", 1, orderedInventories[0].AvailableInventories.Count);

				var assertionHit = false;
				var receiveLine = receive.Lines[0];
				receiveLine.Location.WLV_MaximumPickCountBeforeAutomatedStocktake = 1;
				receiveLine.Location.WLV_FinalisedPickCountInfo.ValueChanged += (s, e) =>
				{
					// poke to have cache lazy calculated
					_ = pickAvailableInventory.VerifiedNonEmpty;

					assertionHit = true;
					AssertEquals(verifiedNonEmpty, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(data.Org1.PK, data.Part1.PK, receiveLine.WE_WL));
					pickAvailableInventory.VerifiedNonEmpty = !verifiedNonEmpty;
					AssertEquals("Should use cache and not return changed value.", verifiedNonEmpty, pickAvailableInventory.VerifiedNonEmpty);
					AssertEquals("VerifiedNonEmptyCacheManager should not be null and not return changed value.", verifiedNonEmpty, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(data.Org1.PK, data.Part1.PK, receiveLine.WE_WL));
				};

				pick.FinaliseAllOrders();
				pick.FinalisePick();
				Factory.Save();
				AssertEquals(true, assertionHit);
				AssertNull("Should not use cache and return changed value.", pick.VerifiedNonEmptyCacheManager);
			}
		}

		public void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_MultiLines()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var whs = data.Whs1;
			whs.WW_VerifyEmptyLocations = true;

			var client1 = Helper.CreateClient("C1");
			var client2 = Helper.CreateClient("C2");
			var product1 = Helper.CreateProduct("P1", client1);
			var product2 = Helper.CreateProduct("P2", client2);
			product2.RelatedOrganisations.AddOwner(client1);
			var location1 = whs.FindLocation("A-1");
			var location2 = whs.FindLocation("A-2");
			var orders = new List<WhsPickableDocket>();

			Helper.CreateWhsReceiveWithInventory(client1, whs, "R1", product1, 1m, location1, "");
			Helper.CreateWhsReceiveWithInventory(client1, whs, "R2", product2, 1m, location1, "");
			Helper.CreateWhsReceiveWithInventory(client1, whs, "R3", product1, 1m, location2, "");
			Helper.CreateWhsReceiveWithInventory(client2, whs, "R4", product2, 1m, location1, "");

			orders.Add(Helper.CreateWhsOrderWithOrderLine(client1, whs, "O1", product1, 1m));
			orders.Add(Helper.CreateWhsOrderWithOrderLine(client1, whs, "O2", product2, 1m));
			orders.Add(Helper.CreateWhsOrderWithOrderLine(client1, whs, "O3", product1, 1m));
			orders.Add(Helper.CreateWhsOrderWithOrderLine(client2, whs, "O4", product2, 1m));
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var pick = Helper.CreatePickNew(orders.ToArray());
				var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
				orderedInventories.Single(oi => oi.ClientPK == client1.PK && oi.SupplierPartPK == product1.PK && oi.AvailableInventories.Cast<WhsPickAvailableInventory>().Any(al => al.LocationPK == location1.PK))
					.AvailableInventories[0].VerifiedNonEmpty = true;
				orderedInventories.Single(oi => oi.ClientPK == client2.PK && oi.SupplierPartPK == product2.PK && oi.AvailableInventories.Cast<WhsPickAvailableInventory>().Any(al => al.LocationPK == location1.PK))
					.AvailableInventories[0].VerifiedNonEmpty = true;

				var assertionHit = true;
				location1.WLV_MaximumPickCountBeforeAutomatedStocktake = 1;
				location1.WLV_FinalisedPickCountInfo.ValueChanged += (s, e) =>
				{
					assertionHit = true;
					AssertEquals(true, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(client1.PK, product1.PK, location1.PK));
					AssertEquals(false, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(client1.PK, product2.PK, location1.PK));
					AssertEquals(false, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(client1.PK, product1.PK, location2.PK));
					AssertEquals(true, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(client2.PK, product2.PK, location1.PK));
					AssertEquals("Should not have error is not exists in cache.", false, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(ZGuid.NewZGuid(), ZGuid.NewZGuid(), ZGuid.NewZGuid()));
				};

				pick.FinaliseAllOrders();
				pick.FinalisePick();
				Factory.Save();
				AssertEquals(true, assertionHit);
			}
		}

