		public void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_UseOriginalInventoryLocation_PutawayLocation()
		{
			TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_UseOriginalInventoryLocationCore(putawayLocation: true);
		}

		void TestCreateAutomatedStocktakes_VerifiedNonEmptyCacheHolder_UseOriginalInventoryLocationCore(bool putawayLocation)
		{
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			data.Whs1.WW_VerifyEmptyLocations = true;
			var location = data.Whs1.FindLocation("A-1-1");

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, location);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m, location);
			receive.FinaliseDocket();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
				Helper.CreateWhsOrderLine(order, data.Part1, 20m);
				Factory.Save();

				var pick = Helper.CreatePickNew(order);
				var orderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single();
				AssertEquals("Precondition: AvailableInventories", 1, orderedInventory.AvailableInventories.Count);
				AllocateAndVerifiedEmptyAvailableInventoryLines(orderedInventory, location, true, true, 20m);

				var pickLines = pick.GetAllPickLines();
				AssertEquals("Precondition: PickLines", 2, pickLines.Count());
				if (putawayLocation)
				{
					foreach (var pickline in pickLines)
					{
						pickline.WZ_PickedDateTime = ZDateTimeOffset.Now;
					}
				}
				Factory.Save();

				var assertionHit = false;
				location.WLV_MaximumPickCountBeforeAutomatedStocktake = 1;
				location.WLV_FinalisedPickCountInfo.ValueChanged += (s, e) =>
				{
					assertionHit = true;
					AssertEquals(true, pick.VerifiedNonEmptyCacheManager.GetVerifiedNonEmpty(data.Org1.PK, data.Part1.PK, location.PK));
					if (putawayLocation)
					{
						AssertEquals(true, pick.GetAllPickLines().All(pl => pl.WZ_WE_OriginalPickedInventoryLine.IsValid));
					}
					else
					{
						AssertEquals(true, pick.GetAllPickLines().All(pl => !pl.WZ_WE_OriginalPickedInventoryLine.IsValid));
					}
				};

				pick.FinaliseAllOrders();
				AssertIsFinalisedPrecondition(order);
				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);
				Factory.Save();

				Assert(assertionHit);
			}
		}

