		#region TestCreateAutomatedStocktakes_InventoryStatus

		public void TestCreateAutomatedStocktakes_InventoryStatus()
		{
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			var location = data.Whs1.FindLocation("A-1-1");
			SetTouchCount(location, 2, 1);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			var inventoryAVL = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, location);
			var inventoryHEL = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1.PK, 5m, location.PK, "", "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Damaged);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 1m, WhsPickOption.Codes.Manual);

				var pick = Helper.CreatePickNew(order);
				pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single().Allocate = true;
				pick.FinaliseAllOrders();
				pick.FinalisePick();

				Factory.Save();

				AssertIsFinalisedPrecondition(order);
				AssertIsFinalisedPrecondition(pick);
				AssertTouchCounts("Precondition", location, 2, 0);
				AssertEquals("Precondition: Inventory status is HEL but should create StocktakeLine with status DAM.", InventoryStatus.Codes.Held, inventoryHEL.WI_InventoryStatus);

				// test automatically created stocktake
				var stocktake = GetAutoCreatedStocktakes().Single();
				AssertAutomatedStocktake(stocktake, data.Org1, data.Whs1, location, "ATC");

				var stocktakelineAVL = stocktake.Lines.Single(s => s.WU_InventoryStatus == inventoryAVL.WI_InventoryStatus);
				var stocktakelineDAM = stocktake.Lines.Single(s => s.WU_InventoryStatus == InventoryHoldCodes.Codes.Damaged);
				AssertAutomatedStocktakeLine(stocktakelineAVL, data.Org1, data.Part1, location); // Picked
				AssertAutomatedStocktakeLine(stocktakelineDAM, data.Org1, data.Part1, location, 5m, "DAM");
			}
		}

