		#region TestCreateAutomatedStocktakes_InventoryStatus_MatchWithHeldLine

		public void TestCreateAutomatedStocktakes_InventoryStatus_MatchWithHeldLine()
		{
			var data = new TestDataSimpleEnvironment(Factory, 1, 2);
			var location = data.Whs1.FindLocation("A-1-1");
			SetTouchCount(location, 2, 1);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R0", data.Part1, 1m);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1.PK, 5m, location.PK, "", "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Damaged);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			using (WarehouseDataRegistry.Instance.InventoryAccuracyManagementMethod.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "WST"))
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "1", data.Part1, 1m, WhsPickOption.Codes.Manual);

				var pick = Helper.CreatePickNew(order);
				var availableInventory = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single();

				MakeItHeld(availableInventory.Inventory[0].InDocketLine);

				var groupedAvailableInventoryLines = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().GroupBy(a => a.Location);
				new WhsAutoStocktakeTaskCreator().CreateInventoryAccuracyManagementTasksForAutoTouchCount(groupedAvailableInventoryLines, data.Whs1);

				// test automatically created stocktake
				var stocktake = GetAutoCreatedStocktakes().Single();
				AssertAutomatedStocktake(stocktake, data.Org1, data.Whs1, location, "ATC");

				var stocktakelineAVL = stocktake.Lines.Single(s => s.WU_InventoryStatus != InventoryHoldCodes.Codes.Damaged);
				var stocktakelineDAM = stocktake.Lines.Single(s => s.WU_InventoryStatus == InventoryHoldCodes.Codes.Damaged);
				AssertAutomatedStocktakeLine(stocktakelineAVL, data.Org1, data.Part1, location, 1); // Picked
				AssertAutomatedStocktakeLine(stocktakelineDAM, data.Org1, data.Part1, location, 5m, "DAM");
			}

			void MakeItHeld(WhsDocketLine docketline)
			{
				var status = docketline.WE_DocketLineStatus;
				docketline.WE_DocketLineStatus = DocketLineStatus.Codes.Entered; // cannot change Finalised
				docketline.WE_FinalisedDate = ZDateTimeOffset.Empty; // cannot change Finalised
				docketline.WE_OriginalInventoryStatus = InventoryStatus.Codes.Held;
				docketline.WE_DocketLineStatus = status;
			}
		}

