		IEnumerable<WhsStocktake> GetAutoCreatedStocktakes()
		{
			return Factory.Load<WhsStocktake>(new ZQuery(WhsStocktakeSchema.WS_StocktakeType, new[] { StocktakeTypeCodeList.Codes.AutomaticTouchCount, StocktakeTypeCodeList.Codes.AutomaticZeroConfirmation }));
		}

		void AssertAutomatedStocktake(WhsStocktake stocktake, OrgHeader client, WhsWarehouse warehouse, WhsLocation location,
			string stocktakeType)
		{
			AssertEquals("Invalid client.", client, stocktake.Client);
			AssertEquals("Invalid warehouse.", warehouse, stocktake.Warehouse);
			AssertEquals("Invalid location.", location.PK, stocktake.WS_WL_Location);
			AssertEquals("Invalid stocktake type.", stocktakeType, stocktake.WS_StocktakeType);
			AssertEquals("Invalid stocktake status.", true, stocktake.IsLoaded);
		}

		void AssertAutomatedStocktakeLine(WhsStocktakeLine line, OrgHeader client, OrgSupplierPart part, WhsLocation location,
			decimal systemCount = 0m, string inventoryStatus = "AVL")
		{
			AssertEquals("Invalid client.", client, line.Client);
			AssertEquals("Invalid product.", part, line.SupplierPart);
			AssertEquals("Invalid location.", location, line.Location);
			AssertEquals("Invalid inventory status.", inventoryStatus, line.WU_InventoryStatus);
			AssertEquals("Invalid system count.", systemCount, line.WU_SystemUnits);
			AssertEquals("Invalid current count.", 0m, line.CurrentCount);
			AssertEquals("Line is not manually added.", false, line.WU_IsManuallyAdded);
		}

		void AssertTouchCounts(WhsLocation location, int expectedMaximumTouchCount, int expectedCurrentTouchCount)
		{
			AssertTouchCounts("Invalid touch count.", location, expectedMaximumTouchCount, expectedCurrentTouchCount);
		}

		void AssertTouchCounts(string msg, WhsLocation location, int expectedMaximumTouchCount, int expectedCurrentTouchCount)
		{
			AssertEquals(msg, expectedMaximumTouchCount, location.WLV_MaximumPickCountBeforeAutomatedStocktake);
			AssertEquals(msg, expectedCurrentTouchCount, location.WLV_FinalisedPickCount);
		}

		void SetTouchCount(WhsLocation location, int maximumTouchCount, int currentTouchCount)
		{
			location.WLV_MaximumPickCountBeforeAutomatedStocktake = maximumTouchCount;
			location.WLV_FinalisedPickCount = currentTouchCount;
		}

