		public void TestCreateAutomatedCycleCount_SaveFailure()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var location = data.Whs1.FindLocation("A");
			SetTouchCount(location, 2, 1);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 1m, location);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			Helper.CreateWhsOrderLine(order, data.Part1, 1m);

			var finalisedPick = Helper.CreatePickNew(order);
			finalisedPick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order);

			finalisedPick.FinalisePick();

			BusinessObjectFactory.SavingEventHandler handler = f =>
			{
				f.ServiceContainer.AddAfterOnSavingService(new ServiceThatThrowsException(f));
			};
			Factory.Saving += handler;

			Helper.AssertZCannotSaveExceptionThrown("Test", Factory.Save);
			AssertTouchCounts("Location touch count reverted to original value.", location, 2, 1);

			var newFactory = new BusinessObjectFactory();
			AssertEquals("No cycle counts created due to save failure.", false, newFactory.Load<WhsCycleCountLocation>(new ZQuery()).Length > 0);
		}

