		public void TestIsPrintingWithoutSeparatorLabels()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "W1");
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
