			using (pick.EnablePrintingWithoutSeparatorLabels())
			{
				AssertEquals("Printing Without Separator Labels should be enabled.", true, pick.IsPrintingWithoutSeparatorLabels);

				using (pick.EnablePrintingWithoutSeparatorLabels())
				{
					AssertEquals("Printing Without Separator Labels should be enabled.", true, pick.IsPrintingWithoutSeparatorLabels);
