				AssertEquals("Printing Without Separator Labels should be enabled.", true, pick.IsPrintingWithoutSeparatorLabels);
			}

			AssertEquals("Printing Without Separator Labels should not be disabled.", false, pick.IsPrintingWithoutSeparatorLabels);
		}

