		#region TestAllocatePackageSequence

		public void TestAllocatePackageSequence()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;
			var helper = new WhsTestHelperFunctions(Factory);
			var packingHelper = new PackingTestHelper(Factory);
			helper.CreateProductUnit(data.Part1, "CAS", 5);
			helper.CreateProductUnit(data.Part1, "PLT", 20);

			Factory.LoadFromUniqueKey<RefPackType>(RefPackTypeSchema.F3_Code, new ZString("UNT")).F3_UOMType = UOMPackTypesList.Codes.SplitCase;
			Factory.LoadFromUniqueKey<RefPackType>(RefPackTypeSchema.F3_Code, new ZString("CAS")).F3_UOMType = UOMPackTypesList.Codes.Case;
			Factory.LoadFromUniqueKey<RefPackType>(RefPackTypeSchema.F3_Code, new ZString("PLT")).F3_UOMType = UOMPackTypesList.Codes.Pallet;

			helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 56m);
			Factory.Save();

			var order1 = helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 28m);
			var order2 = helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 28m);

			var pick = helper.CreatePickNew(order1, order2);
			pick.WP_PickCasesByLabel = true;
			pick.WP_PickPalletsByLabel = true;
			Factory.Save();

			pick.AllocatePackageLabels();

			pick.AllocatePackageSequence();

			var sorter = new PackageComparerForLabelPrinting(pick);
			var packagesQueue = new Queue<PkgPackage>(pick.OuterPackages.Where(p => p.PackedItems.Count > 0).OrderBy(p => p, sorter));

			AssertEquals("should allocate the sequence with the sequence which sorted of PackageCompareForLabelPrinting", (short)1, packagesQueue.ElementAt(0).KP_Sequence);
			AssertEquals("should allocate the sequence with the sequence which sorted of PackageCompareForLabelPrinting", (short)2, packagesQueue.ElementAt(1).KP_Sequence);
			AssertEquals("should allocate the sequence with the sequence which sorted of PackageCompareForLabelPrinting", (short)3, packagesQueue.ElementAt(2).KP_Sequence);
			AssertEquals("should allocate the sequence with the sequence which sorted of PackageCompareForLabelPrinting", (short)4, packagesQueue.ElementAt(3).KP_Sequence);
		}

