		public void TestAllocatePackageLabels_AlreadyCartonisedInAnotherInstance()
		{
			TestAllocatePackageLabels_AlreadyCartonisedOrDeletedInAnotherInstance(p => p.WP_IsCartonised = true);
		}

		public void TestAllocatePackageLabels_AlreadyDeletedInAnotherInstance()
		{
			TestAllocatePackageLabels_AlreadyCartonisedOrDeletedInAnotherInstance(p =>
			{
				p.Orders.RemoveAll();
				p.Delete();
			});
