		void TestAllocatePackageLabels_AlreadyCartonisedOrDeletedInAnotherInstance(
			Action<WhsPick> actionOnPickInOtherFactoryThatShouldCauseError)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			pick.WP_PickCasesByLabel = false;
			pick.WP_PickPalletsByLabel = false;
			Factory.Save();

			var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);
			actionOnPickInOtherFactoryThatShouldCauseError(pickInFactory2);
			factory2.Save();

			var mock = new Mock<IAllocatePackageLabelsStrategy>();
			mock.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);

			pick.SetAllocatePackageLabelsStrategyForTest(mock.Object);
			pick.AllocatePackageLabels();
			mock.Verify(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>()), Times.Once());
			mock.Verify(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>()), Times.Never());
			mock.Verify(m => m.PickCasesByLabel(It.IsAny<WhsPick>()), Times.Never());
			mock.Verify(m => m.PickPalletsByLabel(It.IsAny<WhsPick>()), Times.Never());

			var notifications = (NotificationBuffer)pick.NotificationSubscriber;
			AssertEquals("Should have shown error", true, notifications.HasErrors);
			AssertEquals("Should have shown error",
				"This Pick has already had Package Labels allocated or been deleted in another instance.",
				notifications.Events[0].Message);
			AssertEquals("Should have released lock.", false, pick.IsCartonising);
		}

		public void TestAllocatePackageLabels_UnsavedWhsPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			pick.WP_PickCasesByLabel = true;
			pick.WP_PickPalletsByLabel = true;

			var strategyMock = new Mock<IAllocatePackageLabelsStrategy>();
			strategyMock.Setup(s => s.RunChecksPriorToCartonisingOrPickingByLabel(pick, true)).Returns(true);
			strategyMock.Setup(s => s.CartoniseSplitCases(pick, true)).Returns(CartonisationResult.Cartonised);
			strategyMock.Setup(s => s.PickCasesByLabel(pick)).Returns(true);
			strategyMock.Setup(s => s.PickPalletsByLabel(pick)).Returns(true);

			pick.SetAllocatePackageLabelsStrategyForTest(strategyMock.Object);
			pick.AllocatePackageLabels();

			var notifications = (NotificationBuffer)pick.NotificationSubscriber;
			AssertEquals("Should not have shown error", false, notifications.HasErrors);
			AssertEquals("Should have released lock.", false, pick.IsCartonising);

			strategyMock.Verify(s => s.RunChecksPriorToCartonisingOrPickingByLabel(pick, true));
			strategyMock.Verify(s => s.CartoniseSplitCases(pick, true));
			strategyMock.Verify(s => s.PickCasesByLabel(pick));
			strategyMock.Verify(s => s.PickPalletsByLabel(pick));
			strategyMock.VerifyNoOtherCalls();
		}

		public void TestAllocatePackageLabels_TakesLock()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			pick.WP_PickCasesByLabel = false;
			pick.WP_PickPalletsByLabel = false;
			Factory.Save();

			var assertionRan = false;
			var mock = new Mock<IAllocatePackageLabelsStrategy>();
			mock.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			mock.Setup(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(() =>
			{
				AssertEquals("Should be locked.", true, pick.IsCartonising);

				var notifications = (NotificationBuffer)pick.NotificationSubscriber;
				AssertEquals("Precondition", false, notifications.HasErrors);

				var factory2 = new BusinessObjectFactory { RefreshEnabled = false };
				var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);
				pickInFactory2.SetAllocatePackageLabelsStrategyForTest(mock.Object);
				pickInFactory2.AllocatePackageLabels();

				var notificationsForPickInFactory2 = (NotificationBuffer)pickInFactory2.NotificationSubscriber;
				AssertEquals("Should have shown error", true, notificationsForPickInFactory2.HasErrors);
				AssertEquals("Should have shown error", "This Pick is already having Package Labels allocated in another instance.",
					notificationsForPickInFactory2.Events[0].Message);

				assertionRan = true;
				return CartonisationResult.Cartonised;
			});

			pick.SetAllocatePackageLabelsStrategyForTest(mock.Object);
			pick.AllocatePackageLabels();
			AssertEquals(true, assertionRan);

			AssertEquals("Should have released lock.", false, pick.IsCartonising);
		}

		public void TestAttemptToSaveWhileIsCartonisedSetInAnotherInstance()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

