		public void TestCanAllocatePackageLabels()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var pick1 = Helper.CreatePickNew(order1);
			AssertEquals(false, pick1.CanAllocatePackageLabels);

			pick1.WP_CartoniseSplitCases = true;
			pick1.WP_PickCasesByLabel = false;
			pick1.WP_PickPalletsByLabel = false;
			AssertEquals(true, pick1.CanAllocatePackageLabels);

			pick1.WP_CartoniseSplitCases = false;
			pick1.WP_PickCasesByLabel = true;
			AssertEquals(true, pick1.CanAllocatePackageLabels);

			pick1.WP_PickCasesByLabel = false;
			pick1.WP_PickPalletsByLabel = true;
			AssertEquals(true, pick1.CanAllocatePackageLabels);

			order1.PackageJob.Packages.AddNew();
			AssertEquals(false, pick1.CanAllocatePackageLabels);
			order1.PackageJob.Packages.RemoveAllFromRelationship();
			AssertEquals(true, pick1.CanAllocatePackageLabels);

			pick1.WP_IsCartonised = true;
			AssertEquals(false, pick1.CanAllocatePackageLabels);
			pick1.WP_IsCartonised = false;
			AssertEquals(true, pick1.CanAllocatePackageLabels);

			var workOrder = Helper.CreateWhsDynamicWorkOrderWithLine(data.Org1, data.Whs1, "02", data.Part1, 5m);
			var pick2 = Helper.CreatePickNew(workOrder);
			pick2.WP_CartoniseSplitCases = false;
			pick2.WP_PickCasesByLabel = false;
			pick2.WP_PickPalletsByLabel = true;
			pick2.WP_IsCartonised = false;
			AssertEquals(true, pick2.IsWorkOrderPick);
			AssertEquals(false, pick2.CanAllocatePackageLabels);
		}

