		public void TestAllocatePackageLabels_TakesLock_OnlyForSinglePick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 5m);
			var pick1 = Helper.CreatePickNew(order1);
			var pick2 = Helper.CreatePickNew(order2);
			pick1.WP_CartoniseSplitCases = true;
			pick2.WP_CartoniseSplitCases = true;
			pick1.WP_PickCasesByLabel = false;
			pick2.WP_PickCasesByLabel = false;
			pick1.WP_PickPalletsByLabel = false;
			pick2.WP_PickPalletsByLabel = false;
			Factory.Save();

			var mock1 = new Mock<IAllocatePackageLabelsStrategy>();
			var mock2 = new Mock<IAllocatePackageLabelsStrategy>();

			mock1.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			mock2.Setup(m => m.RunChecksPriorToCartonisingOrPickingByLabel(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(true);
			mock1.Setup(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(() =>
			{
				pick2.AllocatePackageLabels();
				return CartonisationResult.Cartonised;
			});

			var cartonisationRanOnPick2 = false;
			mock2.Setup(m => m.CartoniseSplitCases(It.IsAny<WhsPick>(), It.IsAny<bool>())).Returns(() =>
			{
				cartonisationRanOnPick2 = true;
				return CartonisationResult.Cartonised;
			});

			pick1.SetAllocatePackageLabelsStrategyForTest(mock1.Object);
			pick2.SetAllocatePackageLabelsStrategyForTest(mock2.Object);
			pick1.AllocatePackageLabels();
			AssertEquals(true, cartonisationRanOnPick2);
		}

