		public void TestAllocatePackageLabels_EndToEnd()
		{
			// Simple test to ensure the strategy is correctly hooked up as it is mocked out in the more comprehensive tests
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;

			var refType1 = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Metres, 3,
				Constants.Weight.Kilograms, UOMPackTypesList.Codes.Case);
			data.Part1.OP_StockKeepingUnit = refType1.F3_Code;

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);

			var pick = Helper.CreatePickNew(order);
			AssertEquals("Precondition", 1, pick.OrderedInventories.Count);

			var part1OrderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.Single(o => o.SupplierPartPK == data.Part1.PK);
			AssertEquals("Precondition", 1, part1OrderedInventory.AvailableInventories.Count);
			AssertEquals("Precondition", 1, part1OrderedInventory.AvailableInventories[0].PickLines.Count());

			pick.WP_CartoniseSplitCases = true;
			Factory.Save();
			pick.AllocatePackageLabels();

			AssertEquals(1, part1OrderedInventory.AvailableInventories.Count);
			AssertEquals("Should have split the pick lines for Part 1.", 5,
				part1OrderedInventory.AvailableInventories[0].PickLines.Count());

			var packageJob = ((WhsOrder)pick.Orders[0]).PackageJob;
			AssertEquals("Should have created packages for Part1.", 5, packageJob.Packages.Count);
			AssertEquals("Should have generated IDs.", true,
				packageJob.Packages.All(p => p.KP_PackageID.StartsWith(string.Format("{0}-00", packageJob.ParentJob.JobNo))));

			// Dodgy reflection test, just in case...
			AssertType<AllocatePackageLabelsStrategy>(pick.GetType()
				.GetProperty("AllocatePackageLabelsStrategy",
					System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).GetValue(pick));
		}

