		public void TestAllocatePackageLabels_PackingCommencedEventCascadedToOrders()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;

			var refType1 = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Metres, 3,
				Constants.Weight.Kilograms, UOMPackTypesList.Codes.Case);
			data.Part1.OP_StockKeepingUnit = refType1.F3_Code;

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var trigger = order.WorkflowItems.Triggers.AddNew();
			trigger.TriggerConditions.TriggerEventCode = Events.PackingCommencedCode;
			trigger.P9_RespondToCascadedEvents = true;

			var packingCommencedEvent = Factory.Load<StmEvent>(new ZQuery(StmEventSchema.SE_Code, Events.PackingCommencedCode)).Single();
			packingCommencedEvent.SE_PropagateToParent = true;
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_PickNo = "P123";
			AssertEquals("Precondition", 1, pick.OrderedInventories.Count);

			var part1OrderedInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.Single(o => o.SupplierPartPK == data.Part1.PK);
			AssertEquals("Precondition", 1, part1OrderedInventory.AvailableInventories.Count);
			AssertEquals("Precondition", 1, part1OrderedInventory.AvailableInventories[0].PickLines.Count());

			pick.WP_CartoniseSplitCases = true;
			Factory.Save();

			Assert("Precondition: event is configured to propagate.", packingCommencedEvent.SE_PropagateToParent);
			Assert("Precondition: trigger is not yet 'triggered' with event.", trigger.P9_ActualDateForBinding.IsEmpty);

			pick.AllocatePackageLabels();

			AssertEquals("Pick is cartonized.", true, pick.WP_IsCartonised);

			var logQuery = new ZQuery(StmALogSchema.SL_Parent, pick.PK);
			logQuery.AddToFilter(StmALogSchema.SL_SE_NKEvent, Events.PackingCommencedCode);
			logQuery.AddToFilter(StmALogSchema.SL_Reference, "Pick Cartonized: P123|TYP=Cartonization");
			AssertEquals("Packing Commenced Event is added.", 1, pick.Logs.Find(logQuery).Length);

			Assert("Trigger event date time got updated.", !trigger.P9_ActualDateForBinding.IsEmpty);
		}

