		#region TestCancelPackageLabelAllocations

		public void TestCancelPackageLabelAllocations()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;

			var whsGroup = Helper.CreateWhsCartonGroup("1", "WhsOrg");
			var whsSize = Helper.CreateWhsCartonSize("WH", 10, 20, 40, 80, 160, 320, new ZByte(100), Constants.Length.Metres,
				Constants.Weight.Kilograms);
			whsGroup.CartonSizes.Add(whsSize);
			data.Whs1.WarehouseAddress.Header.MiscServ.OM_WCG_CartonGroup = whsGroup.PK;

			var part3 = Helper.CreateProduct(data.Org1, "P3");
			var splitCaseRefType = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Metres, 3,
				Constants.Weight.Kilograms, UOMPackTypesList.Codes.SplitCase);
			var caseRefType = PackingHelper.CreateRefPackType("2", "2", 3m, 6m, 12m, Constants.Length.Feet, 7,
				Constants.Weight.Pounds, UOMPackTypesList.Codes.Case);
			var palletRefType = PackingHelper.CreateRefPackType("3", "3", 3m, 6m, 12m, Constants.Length.Feet, 7,
				Constants.Weight.Pounds, UOMPackTypesList.Codes.Pallet);
			data.Part1.OP_StockKeepingUnit = splitCaseRefType.F3_Code;
			data.Part2.OP_StockKeepingUnit = caseRefType.F3_Code;
			part3.OP_StockKeepingUnit = palletRefType.F3_Code;

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, part3, 10m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order, data.Part2, 5m);
			Helper.CreateWhsOrderLine(order, part3, 5m);

			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			AssertEquals("Precondition", 3, pick.OrderedInventories.Count);
			AssertEquals("Precondition", 3, pick.GetAllPickLines().Count());
			AssertEquals("Precondition", true, pick.WP_CartoniseSplitCases);
			AssertEquals("Precondition", true, pick.WP_PickCasesByLabel);
			AssertEquals("Precondition", true, pick.WP_PickPalletsByLabel);
			Factory.Save();

			AssertEquals("Precondition: Cannot cancel package label allocations.", false, pick.CanCancelPackageLabelAllocations);
			pick.AllocatePackageLabels();
			AssertEquals("Precondition - Cartonised", true, pick.WP_IsCartonised);
			AssertEquals("Precondition - Cartonised", 1 + 5 + 5, order.PackageJob.Packages.Count);

			AssertEquals("Can cancel package label allocations.", true, pick.CanCancelPackageLabelAllocations);
			pick.CancelPackageLabelAllocations();
			AssertEquals("Should have cancelled Package Label Allocations", false, pick.WP_IsCartonised);
			AssertEquals("Should have cancelled Package Label Allocations", 0, order.PackageJob.Packages.Count);
			AssertEquals("Should *not* have saved", true, pick.HasChanges);
		}

		public void TestCancelPackageLabelAllocations_UnitConversions()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WW_IsPickByUOMEnabled = true;

			data.Part1.OP_Cubic = 1m; // Make it so max units is the defining parameter
			data.Part1.OP_Weight = 1m; // Make it so max units is the defining parameter

			var whsGroup = Helper.CreateWhsCartonGroup("1", "WhsOrg");
			var whsSize = Helper.CreateWhsCartonSize("WH", 10, 10, 10, 10, 100, 5, new ZByte(100), Constants.Length.Metres,
				Constants.Weight.Kilograms); // Make it so max units is the defining parameter
			whsGroup.CartonSizes.Add(whsSize);
			data.Whs1.WarehouseAddress.Header.MiscServ.OM_WCG_CartonGroup = whsGroup.PK;

			var part3 = Helper.CreateProduct(data.Org1, "P3");
			var splitCaseRefType = PackingHelper.CreateRefPackType("1", "1", 2m, 4m, 8m, Constants.Length.Centimetres, 3,
				Constants.Weight.Grams, UOMPackTypesList.Codes.SplitCase);
			var caseRefType = PackingHelper.CreateRefPackType("2", "2", 3m, 6m, 12m, Constants.Length.Feet, 7,
				Constants.Weight.Pounds, UOMPackTypesList.Codes.Case);
			var palletRefType = PackingHelper.CreateRefPackType("3", "3", 3m, 6m, 12m, Constants.Length.Feet, 7,
				Constants.Weight.Pounds, UOMPackTypesList.Codes.Pallet);
			var biggerSplitCaseRefType = PackingHelper.CreateRefPackType("4", "4", 2m, 4m, 8m, Constants.Length.Metres, 3,
				Constants.Weight.Kilograms, UOMPackTypesList.Codes.SplitCase);

			data.Part1.OP_StockKeepingUnit = splitCaseRefType.F3_Code;
			data.Part2.OP_StockKeepingUnit = caseRefType.F3_Code;
			part3.OP_StockKeepingUnit = palletRefType.F3_Code;

			data.Part1.PartUnits.RemoveAndDeleteAll();
			data.Part2.PartUnits.RemoveAndDeleteAll();
			part3.PartUnits.RemoveAndDeleteAll();
			Helper.CreateProductUnit(data.Part1, biggerSplitCaseRefType.F3_Code, 2m);

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, part3, 10m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();

			var packageSentValueChangedCount = 0;
			var totalPackTypeChangedCount = 0;
			var palletsSentChangedCount = 0;
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			// update to random values so that at the end of cartonisation should be overridden.
			order.WD_PackagesSent = 500;
			order.WD_F3_NKTotalPackType = "ABC";
			order.WD_PalletsSent = 100;

			order.WD_PackagesSentInfo.ValueChanged += (s, e) => packageSentValueChangedCount++;
			order.WD_F3_NKTotalPackTypeInfo.ValueChanged += (s, e) => totalPackTypeChangedCount++;
			order.WD_PalletsSentInfo.ValueChanged += (s, e) => palletsSentChangedCount++;

			Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			Helper.CreateWhsOrderLine(order, part3, 10m);

			var pick = Helper.CreatePickNew(order);
			pick.WP_CartoniseSplitCases = true;
			AssertEquals("Precondition", 3, pick.OrderedInventories.Count);
			AssertEquals("Precondition", true, pick.WP_CartoniseSplitCases);
			AssertEquals("Precondition", true, pick.WP_PickCasesByLabel);
			AssertEquals("Precondition", true, pick.WP_PickPalletsByLabel);
			AssertEquals("Precondition", 3, pick.GetAllPickLines().Count());

			var pickLines1 = pick.GetAllPickLines();
			AssertEquals("Precondition", 1,
				pickLines1.Count(pl => pl.WZ_Units == 10m && pl.WZ_F3_NKAllocatedPackType == biggerSplitCaseRefType.F3_Code));
			AssertEquals("Precondition", 1,
				pickLines1.Count(pl => pl.WZ_Units == 10m && pl.WZ_F3_NKAllocatedPackType == palletRefType.F3_Code));
			AssertEquals("Precondition", 1,
				pickLines1.Count(pl => pl.WZ_Units == 10m && pl.WZ_F3_NKAllocatedPackType == caseRefType.F3_Code));
			Factory.Save();

			pick.AllocatePackageLabels();
			AssertEquals("Precondition - Cartonised", true, pick.WP_IsCartonised);
			AssertEquals("Precondition - Cartonised", 2 + 10 + 10, order.PackageJob.Packages.Count);
			AssertEquals("Precondition - Cartonised", 2 + 10 + 10, pick.GetAllPickLines().Count());

			AssertEquals("Package Sent must be calculated only once.", 1, packageSentValueChangedCount);
			AssertEquals("Total pack type must be changed once.", 1, totalPackTypeChangedCount);
			AssertEquals("Pallets sent must be changed once.", 1, palletsSentChangedCount);

			AssertEquals("Package Sent must be updated.", 12, order.WD_PackagesSent);
			AssertEquals("Total pack type must be updated.", "", order.WD_F3_NKTotalPackType);
			AssertEquals("Pallets sent must be updated.", (ZShort)10, order.WD_PalletsSent);

			// after cartonisation biggerSplitCaseRefType will be replaced with splitCaseRefType
			var pickLines2 = pick.GetAllPickLines();
			AssertEquals("Precondition - Cartonised", 10,
				pickLines2.Count(pl => pl.WZ_Units == 1 && pl.WZ_F3_NKAllocatedPackType == caseRefType.F3_Code));
			AssertEquals("Precondition - Cartonised", 10,
				pickLines2.Count(pl => pl.WZ_Units == 1 && pl.WZ_F3_NKAllocatedPackType == palletRefType.F3_Code));
			AssertEquals("Precondition - Cartonised", 2,
				pickLines2.Count(pl => pl.WZ_F3_NKAllocatedPackType == splitCaseRefType.F3_Code));
			AssertEquals("Precondition - Cartonised", splitCaseRefType.F3_Code,
				pick.OrderedInventories[0].AvailableInventories[0].AvailableInventoriesSplitByUOM[0].PackQuantityUQ);

			// cancelling should revert all Package Label Allocations to how Pick by UOM splits the Pick Lines.
			pick.CancelPackageLabelAllocations();
			var pickLines3 = pick.GetAllPickLines();
			AssertEquals("Should have cancelled Package Label Allocations.", false, pick.WP_IsCartonised);
			AssertEquals("Should have cancelled Package Label Allocations.", 0, order.PackageJob.Packages.Count);
			AssertEquals("Should have cancelled Package Label Allocations.", 30m, pickLines3.Sum(pl => pl.WZ_Units));
			AssertEquals("Should have cancelled Package Label Allocations.", 10m,
				pickLines3.Where(pl => pl.WZ_F3_NKAllocatedPackType == biggerSplitCaseRefType.F3_Code).Sum(pl => pl.WZ_Units));
			AssertEquals("Should have cancelled Package Label Allocations.", 10m,
				pickLines3.Where(pl => pl.WZ_F3_NKAllocatedPackType == palletRefType.F3_Code).Sum(pl => pl.WZ_Units));
			AssertEquals("Should have cancelled Package Label Allocations.", 10m,
				pickLines3.Where(pl => pl.WZ_F3_NKAllocatedPackType == caseRefType.F3_Code).Sum(pl => pl.WZ_Units));
			AssertEquals("Precondition - Cartonised", biggerSplitCaseRefType.F3_Code,
				pick.OrderedInventories[0].AvailableInventories[0].AvailableInventoriesSplitByUOM[0].PackQuantityUQ);
			AssertEquals("Should *not* have saved", true, pick.HasChanges);
		}

