		#region TestIsLineInventoryAwaitingReplenishment

		public void TestIsLineInventoryAwaitingReplenishment()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);

			Helper.CreateProductUnit(data.Part1, Constants.PkgUnit.Pallet, 2m); // Part1 : 1PLT = 2 UNT
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", ZDateTimeOffset.Today.AddDays(-1), data.Part1, 3m, pickFaceLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", ZDateTimeOffset.Today.AddDays(-1), data.Part1, 2m, bulkLocation, "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 6m); // This will short fall since there is a pick face and can't pick the full pallet
			Factory.Save();
			var pick = Helper.CreatePickNew(order);

			AssertExceptionThrown<ArgumentNullException>(() => pick.IsLineInventoryAwaitingReplenishment(Factory.New<WhsOrder>().Lines.AddNew()));

			var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var orderedInventory = orderedInventories.Single();
			AssertEquals("Precondition", 0m, orderedInventory.PickLineQuantity);
			AssertEquals("Precondition", 6m, orderedInventory.QuantityShort);
			AssertEquals("Precondition", true, orderedInventory.IsWaitingReplenishment());
			AssertEquals(true, pick.IsLineInventoryAwaitingReplenishment(orderLine));

			AllocateFIFOLegacyMock.AllocateOrderedInventoryWithLegacy(orderedInventory);
			AssertEquals("5 items should be picked.", 5m, orderedInventory.PickLineQuantity);
			AssertEquals("Ordered inventory shortfall since there are no enough stock to be allocated from pick face location.", 1m, orderedInventory.QuantityShort);
			AssertEquals("Ordered Inventory should not be waiting for replenishment.", false, orderedInventory.IsWaitingReplenishment());
			AssertEquals(false, pick.IsLineInventoryAwaitingReplenishment(orderLine));
		}

		public void TestIsLineInventoryAwaitingReplenishment_HeldInventoryOverride_WhenHeldInventoryOrder() =>
			TestIsLineInventoryAwaitingReplenishment_HeldInventoryOverride_Core(isHeldInventoryOrder: true, expectIsAwaitingReplenishment: false);
		public void TestIsLineInventoryAwaitingReplenishment_HeldInventoryOverride_WhenNotHeldInventoryOrder() =>
			TestIsLineInventoryAwaitingReplenishment_HeldInventoryOverride_Core(isHeldInventoryOrder: false, expectIsAwaitingReplenishment: true);

		void TestIsLineInventoryAwaitingReplenishment_HeldInventoryOverride_Core(bool isHeldInventoryOrder, bool expectIsAwaitingReplenishment)
		{
			using (WarehouseDataRegistry.Instance.EnableHeldGoodsForOrders.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, isHeldInventoryOrder))
			{
				var data = new TestDataSimpleEnvironment(Factory, 2, 1);

				var pickFaceLocation = data.Whs1.FindLocation("A-1");
				var bulkLocation = data.Whs1.FindLocation("A-2");
				Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);

				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
				Helper.CreateWhsReceiveLine(receive, data.Part1, 100m, pickFaceLocation, "");
				Helper.CreateWhsReceiveLine(receive, data.Part1, 100m, bulkLocation, "");
				Helper.CreateWhsReceiveLine(receive, data.Part1, 100m, pickFaceLocation, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Damaged);
				Helper.CreateWhsReceiveLine(receive, data.Part1, 100m, bulkLocation, "", InventoryStatus.Codes.Held, InventoryHoldCodes.Codes.Damaged);

				receive.FinaliseDocketWithoutUserConfirmation();
				Assert(receive.IsFinalised);
				Factory.Save();

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
				var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 100m); // This will short fall
				if (isHeldInventoryOrder)
				{
					orderLine.WE_WHC_NKOrderedHeldCode = InventoryHoldCodes.Codes.Damaged;
				}
				Factory.Save();
				var pick = Helper.CreatePickNew(order);

				AssertExceptionThrown<ArgumentNullException>(() => pick.IsLineInventoryAwaitingReplenishment(Factory.New<WhsOrder>().Lines.AddNew()));

				var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
				var orderedInventory = orderedInventories.Single();
				AssertEquals("Precondition", 0m, orderedInventory.PickLineQuantity);
				AssertEquals("Precondition", 100m, orderedInventory.QuantityShort);
				AssertEquals("Precondition", expectIsAwaitingReplenishment, orderedInventory.IsWaitingReplenishment());
				AssertEquals(expectIsAwaitingReplenishment, pick.IsLineInventoryAwaitingReplenishment(orderLine));
			}
		}

