		#region TestClearPickLinesCacheForInventory

		public void TestClearPickLinesCacheForInventory()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, data.Whs1.DefaultLocation, "PLT-1");
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part1, 10m, data.Whs1.DefaultLocation, "PLT-2");
			var receive3 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", data.Part2, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			var pick = Helper.CreatePickNew(order);
			AssertExceptionThrown<ArgumentNullException>(() => pick.ClearPickLinesCacheForInventory(Factory.New<WhsOrder>().Lines.AddNew(), ZGuid.Empty));

			var pickLine1 = orderLine1.PickLines.Single(pl => pl.InventoryLine.WE_PalletID == "PLT-1");
			var pickLine2 = orderLine1.PickLines.Single(pl => pl.InventoryLine.WE_PalletID == "PLT-2");
			var pickLine3 = orderLine2.PickLines.Single();
			var orderedInventory1 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(o => o.ProductCode == data.Part1.OP_PartNum);
			var orderedInventory2 = pick.OrderedInventories.Cast<WhsPickOrderedInventory>().Single(o => o.ProductCode == data.Part2.OP_PartNum);
			var availableInventory1 = orderedInventory1.AvailableInventories.Cast<WhsPickAvailableInventory>().Single(a => a.PalletID == "PLT-1");
			var availableInventory2 = orderedInventory1.AvailableInventories.Cast<WhsPickAvailableInventory>().Single(a => a.PalletID == "PLT-2");
			var availableInventory3 = orderedInventory2.AvailableInventories.Cast<WhsPickAvailableInventory>().Single();
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);

			var transferLine1 = Factory.New<WhsTransferLine>();
			var transferLine2 = Factory.New<WhsTransferLine>();
			var transferLine3 = Factory.New<WhsTransferLine>();
			var newPickLine1 = transferLine1.PickLines.AddNew();
			var newPickLine2 = transferLine2.PickLines.AddNew();
			var newPickLine3 = transferLine3.PickLines.AddNew();
			newPickLine1.WZ_WE_InventoryLine = pickLine1.WZ_WE_InventoryLine;
			newPickLine2.WZ_WE_InventoryLine = pickLine2.WZ_WE_InventoryLine;
			newPickLine3.WZ_WE_InventoryLine = pickLine3.WZ_WE_InventoryLine;
			pickLine1.WZ_WE_InventoryLine = transferLine1.PK;
			pickLine1.WZ_WE_OriginalPickedInventoryLine = receive1.Lines[0].PK;
			pickLine2.WZ_WE_InventoryLine = transferLine2.PK;
			pickLine2.WZ_WE_OriginalPickedInventoryLine = receive2.Lines[0].PK;
			pickLine3.WZ_WE_InventoryLine = transferLine3.PK;
			pickLine3.WZ_WE_OriginalPickedInventoryLine = receive3.Lines[0].PK;
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);

			pick.ClearPickLinesCacheForInventory(orderLine1, receive1.Lines[0].PK);
			AssertContainsExactElementsInAnyOrder(new[] { newPickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);

			pick.ClearPickLinesCacheForInventory(orderLine2, receive3.Lines[0].PK);
			AssertContainsExactElementsInAnyOrder(new[] { newPickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine1 }, availableInventory1.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine2 }, availableInventory2.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
			AssertContainsExactElementsInAnyOrder(new[] { newPickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesForPickingDetails);
			AssertContainsExactElementsInAnyOrder(new[] { pickLine3 }, availableInventory3.AvailableInventoriesSplitByPickedDetails[0].PickLinesOnOrder);
		}

