		#region TestSaveDoesNotFail_WhenDataRefreshCancelsAPick

		public void TestSaveDoesNotFail_WhenDataRefreshCancelsAPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var otherFactory = new BusinessObjectFactory(); // Data refresh enabled
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			pickInOtherFactory.CancelPick();
			AssertEquals("Preconditon: Pick Cancelled.", true, pickInOtherFactory.IsCancelled);
			AssertEquals("Preconditon: Pick Cancelled.", 0, pickInOtherFactory.Orders.Count);
			otherFactory.Save(); // Save cancelled pick

			AssertEquals("Preconditon: Pick Cancelled via data refresh.", true, pick.IsCancelled);
			AssertNoExceptionThrown("Saving the Order should succeed.",
				Factory.Save); // Emulate saving order from the other screen
		}

