		#region TestSaveFailsWhenOrdersAddedAfterPickCancellation

		public void TestSaveFailsWhenOrdersAddedAfterPickCancellation()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10);
			var pick = Helper.CreatePickNew(order1);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 9);
			Factory.Save();

			var otherFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var order2InOtherFactory = otherFactory.Load<WhsOrder>(order2.PK);
			order2InOtherFactory.WD_WP = pick.PK;
			order2InOtherFactory.WD_DocketStatus = DocketStatus.Codes.AttachedToPick;

			pick.CancelPick();
			Assert("Precondition: pick is cancelled", pick.IsCancelled);
			Factory.Save(); // saves pick cancellation

			var ex = AssertExceptionThrown<ZSaveConcurrencyException>(otherFactory.Save);
			AssertContains("Pick version should prevent saving.(before trigger catch the error)", "**CONCURRENCY Error Saving Record **", ex.Message);
		}

		#endregion

		#region TestSaveFailsWhenOrdersCountChangedDuringPickCancellation

		public void TestSaveFailsWhenOrdersCountChangedDuringPickCancellation()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10);
			var pick = Helper.CreatePickNew(order1);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 9);
			Factory.Save();
			pick.CancelPick();

			var otherFactory = new BusinessObjectFactory();
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			var order2InOtherFactory = otherFactory.Load<WhsOrder>(order2.PK);
			pickInOtherFactory.Orders.Add(order2InOtherFactory);
			otherFactory.Save();

			AssertEquals("Precondition: pick cancelled", PickStatus.Codes.Cancelled, pick.WP_PickStatus);
			AssertEquals("Precondition: In current factory we have no order attached to a pick (as it was cancelled).", 0,
				pick.Orders.Count);
			AssertEquals("Precondition: In second factory we have 2 orders attached to a pick.", 2,
				pickInOtherFactory.Orders.Count);
			Assert("Precondition: In second factory both orders are in a Attached To Pick state.",
				pickInOtherFactory.Orders.Cast<WhsDocket>().All(o => o.WD_DocketStatus == DocketStatus.Codes.AttachedToPick));

			var exceptionThrown = AssertExceptionThrown<ZSaveConcurrencyException>(Factory.Save);
			AssertContains("WP_CriticalChangesVersionID", exceptionThrown.Message);
			AssertEquals(pick, exceptionThrown.BusinessObjects.Single());
		}

		#endregion

		#region TestSaveFailsWhenOrdersAddedAfterPickFinalisation

		public void TestSaveFailsWhenOrdersAddedAfterPickFinalisation()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 9);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10);
			var pick = Helper.CreatePickNew(order1);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 9);
			Factory.Save();
			order1.FinaliseDocketAlwaysFinalisingPick();

			var otherFactory = new BusinessObjectFactory();
			var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
			var order2InOtherFactory = otherFactory.Load<WhsOrder>(order2.PK);
			pickInOtherFactory.Orders.Add(order2InOtherFactory);

			Factory.Save(); // saves pick finalisation

			try
			{
				otherFactory.Save(); // trying to save order addition to the pick
				Fail("Trigger should prevent saving this.");
			}
			catch (ZSaveException ex)
			{
				AssertEquals("Attempt to attach not finalised order to finalised pick.", ex.FriendlyMessage);
			}
		}

