		#region TestSavePickFails_RollsBackGrantedPermits

		public void TestSavePickFails_RollsBackGrantedPermits()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs = Helper.CreateFTZWarehouseInUS();

			var customsOrder = Helper.CreateWhsOrder(data.Org1, whs, "O1");
			customsOrder.WD_DocketSubType = OrderType.Codes.CustomsReleaseWithPermit;
			var nonCustomsOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, whs, "O2", data.Part1, 10m);
			nonCustomsOrder.WD_DocketSubType = OrderType.Codes.Order;
			Factory.Save();

			var orderLine = Helper.CreateWhsOrderLine(customsOrder, data.Part1, 5m);
			orderLine.CustomsData.WB_CustomsQty = 50m;
			orderLine.CustomsData.WB_Tariff = "1020304050";

			var responseForIsPermitAvailable =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Success, 1000m, "111");
			var responseForTryGetPermits =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Success, 1000m, "111");

			var permitService = new Mock<IPermitService>();
			permitService.Setup(p => p.IsPermitAvailable(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForIsPermitAvailable } });
			permitService.Setup(p => p.TryGetPermits(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForTryGetPermits } });

			ZString[] permitNumbers = null;
			permitService.Setup(p => p.RelinquishPermitTransactions(It.IsAny<IEnumerable<IPermitTransactionDetail>>())).Returns<IEnumerable<IPermitTransactionDetail>>(args =>
			{
				permitNumbers = args.Select(x => x.PermitTransactionRefNumber).ToArray();
				return SuccessOrFailure.Success;
			});

			using (ObjectFactory.Substitute(permitService.Object))
			{
				var pick = Helper.CreatePickNew(customsOrder, nonCustomsOrder);
				BusinessObjectFactory.SavingEventHandler handler = f =>
				{
					f.ServiceContainer.AddAfterOnSavingService(new ServiceThatThrowsException(f));
				};
				Factory.Saving += handler;

				Helper.AssertZCannotSaveExceptionThrown("Test", Factory.Save);
				Factory.Saving -= handler;

				permitService.VerifyAll();
				AssertContainsExactElementsInAnyOrder(
					new[] { WhsPermitWithdrawalRequestDetail.GetPermitTransactionRefNumber(orderLine) }, permitNumbers);
			}
		}

		// throw exception before committing transaction
		class ServiceThatThrowsException : IAfterOnSavingBOProcessingService
		{
			public ServiceThatThrowsException(BusinessObjectFactory factory)
			{
				Factory = factory;
			}

			readonly BusinessObjectFactory Factory;

			void IAfterOnSavingBOProcessingService.ProcessBusinesObjects(
				IEnumerable<BusinessObject> businessObjectsInOnSavingOrder)
			{
				Factory.ServiceContainer.RemoveAfterOnSavingService<ServiceThatThrowsException>();
				throw new ZCannotSaveException("Test", "Test", ExceptionType.BusinessFailure);
			}
		}

