		#region TestGetPermitsOnFinalisationIfFinalisingStraightAfterAttachPriorToSave

		public void TestGetPermitsOnFinalisationIfFinalisingStraightAfterAttachPriorToSave()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs = Helper.CreateFTZWarehouseInUS();

			var order = Helper.CreateWhsOrder(data.Org1, whs);
			order.WD_DocketID = "OrderID1";
			order.WD_DocketSubType = OrderType.Codes.CustomsReleaseWithPermit;
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			orderLine.CustomsData.WB_CustomsQty = 50m;
			orderLine.CustomsData.WB_Tariff = "1020304050";
			orderLine.CustomsData.WB_EntryKey = "111";
			orderLine.CustomsData.WB_EntryLineNo = 111;

			var responseForIsPermitAvailable =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Success, 1000m, "111");
			var responseForTryGetPermits =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Success, 1000m, "111");

			var permitService = new Mock<IPermitService>();
			permitService.Setup(p => p.IsPermitAvailable(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForIsPermitAvailable } });
			permitService.Setup(p => p.TryGetPermits(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForTryGetPermits } });
			permitService.Setup(p => p.ConfirmPermitTransactions(It.IsAny<IEnumerable<IPermitWithdrawalRequestDetail>>())).Returns(true);

			WhsPick pick;
			using (ObjectFactory.Substitute(permitService.Object))
			{
				pick = Helper.CreatePickNew(order);
				order.FinaliseDocketWithoutUserConfirmation();
				AssertIsFinalisedPrecondition(order);

				pick.FinalisePick();
				AssertIsFinalisedPrecondition(pick);

				AssertNoExceptionThrown("Save Pick With No Exception.", Factory.Save);
				permitService.Verify(p => p.IsPermitAvailable(It.IsAny<IEnumerable<IPermitWithdrawRequest>>()), Times.Once());
				permitService.Verify(p => p.TryGetPermits(It.IsAny<IEnumerable<IPermitWithdrawRequest>>()), Times.Once());
				permitService.Verify(p => p.ConfirmPermitTransactions(It.IsAny<IEnumerable<IPermitWithdrawalRequestDetail>>()), Times.Once());
			}

			AssertNoRowWarnings("Order Has No Warnings.", order);
			AssertNoRowWarnings("OrderLine Has No Warnings.", orderLine);

			pick.WP_PickNo = "P2";
			using (ObjectFactory.Substitute(permitService.Object))
			{
				AssertNoExceptionThrown("Save Pick With No Exception.", Factory.Save);
				permitService.Verify(p => p.IsPermitAvailable(It.IsAny<IEnumerable<IPermitWithdrawRequest>>()), Times.Once());
				permitService.Verify(p => p.TryGetPermits(It.IsAny<IEnumerable<IPermitWithdrawRequest>>()), Times.Once());
				permitService.Verify(p => p.ConfirmPermitTransactions(It.IsAny<IEnumerable<IPermitWithdrawalRequestDetail>>()), Times.Once());
			}
		}

