		[TestDate(2017, 9, 4)]
		void TestSavePickFails_WhenOrderLineHasNoPermitMatch_Core(bool isDetailedTrackingEnabled, string failureReason)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs = Helper.CreateFTZWarehouseInUS(isDetailedTrackingEnabled: isDetailedTrackingEnabled);

			var order = Helper.CreateWhsOrder(data.Org1, whs);
			order.WD_DocketSubType = OrderType.Codes.CustomsReleaseWithPermit;
			Factory.Save();

			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			orderLine.CustomsData.WB_CustomsQty = 50m;
			orderLine.CustomsData.WB_Tariff = "1020304050";

			var permitService = new Mock<IPermitService>();
			var responseForIsPermitAvailable =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Success, 0m, null, null);
			var responseForTryGetPermits =
				new WhsPermitWithdrawRequestResponseForTest(orderLine, SuccessOrFailure.Failure, 0m, null, failureReason);
			permitService.Setup(p => p.IsPermitAvailable(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForIsPermitAvailable } });
			permitService.Setup(p => p.TryGetPermits(It.IsAny<IEnumerable<IPermitWithdrawRequest>>())).Returns(
				new WhsPermitWithdrawRequestResponseResultForTest { Responses = new[] { responseForTryGetPermits } });

			using (ObjectFactory.Substitute(permitService.Object))
			{
				var pick = Helper.CreatePickNew(order);
				Helper.AssertZCannotSaveExceptionThrown($"Not every Order Line on this Pick could be matched to a weekly estimate. Errors below:\r\nNo weekly estimate found for Order Line 1 (5 UNT of Product P1) (Date: 04-Sep-17, {failureReason}).\r\n\r\nClose and reopen the form before making changes to the Order.", Factory.Save);
			}

			permitService.Verify(p => p.RelinquishPermitTransactions(It.IsAny<IEnumerable<IPermitTransactionDetail>>()), Times.Never());
			permitService.VerifyAll();
			AssertHasRowWarning("Order Has Warning.", order,
				"Not all Order Lines could be granted a weekly estimate for this Order.");
			AssertHasRowWarning("OrderLine Has Warning.", orderLine,
				$"No weekly estimate found for Order Line 1 (5 UNT of Product P1) (Date: 04-Sep-17, {failureReason}).");
		}

