		#region TestDoesNotGetPermitForWorkOrderPick

		public void TestDoesNotGetPermitForWorkOrderPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs = Helper.CreateFTZWarehouseInUS();

			var bomProduct = data.Part1;
			var componentProduct1 = Helper.CreateProduct(data.Org1, "C1");
			var bomPart1 = Helper.CreateProductBOM(bomProduct, componentProduct1, 1m, Constants.PkgUnit.Unit);

			var receive = Helper.CreateWhsReceive(data.Org1, whs);
			Helper.CreateWhsReceiveInventoryLine(receive, componentProduct1, 1m, whs.DefaultLocation);
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var workOrder = Helper.CreateWhsWorkOrder(data.Org1.PK, whs.PK, "W1", WorkOrderType.Codes.Assemble);
			Helper.CreateWhsWorkOrderLine(workOrder, bomProduct, 1m);

			var permitService = new Mock<IPermitService>();

			var pick = Helper.CreatePickNew(workOrder);

			using (ObjectFactory.Substitute(permitService.Object))
			{
