		#region TestFinalisePickDoesNotFail_WithConfirmPermitSuccess_PassesInAllocatedAmount

		public void TestFinalisePickDoesNotFail_WithConfirmPermitSuccess_PassesInAllocatedAmount()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs = Helper.CreateFTZWarehouseInUS();

			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, whs, "R1", data.Part1, 50m);
			Factory.Save();

			var customsOrder = Helper.CreateWhsOrder(data.Org1, whs, "Order1");
			customsOrder.WD_DocketSubType = OrderType.Codes.CustomsReleaseWithPermit;
			var orderLine1 = Helper.CreateWhsOrderLine(customsOrder, data.Part1, 40m);
			var orderLine2 = Helper.CreateWhsOrderLine(customsOrder, data.Part1, 20m);
			orderLine1.CustomsData.WB_CustomsQty = 50m;
			orderLine1.CustomsData.WB_Tariff = "1020304050";
			Factory.Save();

			WhsPick pick;
			using (PermitServiceTestHelper.MockServiceToGetPermits())
			{
				pick = Helper.CreatePickNew(customsOrder);
				AssertEquals("Precondition: Order Line is fully Picked.", 40m, orderLine1.PickLineQuantity);
				AssertEquals("Precondition: Order Line is partially Picked.", 10m, orderLine2.PickLineQuantity);
				AssertNoExceptionThrown("Save Pick With No Exception.", Factory.Save);
			}

			IPermitWithdrawalRequestDetail[] permitTransactions = null;

			var permitService = new Mock<IPermitService>();
			permitService.Setup(p => p.ConfirmPermitTransactions(It.IsAny<IEnumerable<IPermitWithdrawalRequestDetail>>())).Returns<IEnumerable<IPermitWithdrawalRequestDetail>>(args =>
			{
				permitTransactions = args.ToArray();
				return true;
			});
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			AssertEquals("Pick is finalised.", true, pick.IsFinalised);

			using (ObjectFactory.Substitute(permitService.Object))
			{
				AssertNoExceptionThrown("Save Pick With No Exception.", Factory.Save);
				AssertContainsExactElementsInAnyOrder(
					new[]
					{
						$"{WhsPermitWithdrawalRequestDetail.GetPermitTransactionRefNumber(orderLine1)}|40",
						$"{WhsPermitWithdrawalRequestDetail.GetPermitTransactionRefNumber(orderLine2)}|10"
					},
					permitTransactions.Select(p => $"{p.PermitTransactionRefNumber}|{p.Qty.ToStringTrimZeros()}"));
			}

			permitService.VerifyAll();
		}

