		#region ICustomLabelsConfigOrgProvider Members

		public void TestICustomLabelsConfigOrgProviderConfigOrg()
		{
			var pick = (WhsPick)GetNewBusinessObject();
			AssertEquals(null, ((ICustomLabelsConfigOrgProvider)pick).ConfigOrg);

			var org1 = Factory.New<OrgHeader>();
			var org2 = Factory.New<OrgHeader>();

			using (WarehouseDataRegistry.Instance.GroupOrderedInventoryByCustomAttributes.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				pick.CustomLabelsGridLayoutPersister_ConfigOrg = org1;
				AssertEquals(org1, pick.CustomLabelsGridLayoutPersister_ConfigOrg);
				AssertEquals(org1, ((ICustomLabelsConfigOrgProvider)pick).ConfigOrg);

				pick.CustomLabelsGridLayoutPersister_ConfigOrg = org2;
				AssertEquals(org2, pick.CustomLabelsGridLayoutPersister_ConfigOrg);
				AssertEquals(org2, ((ICustomLabelsConfigOrgProvider)pick).ConfigOrg);
			}

			// With registry off ConfigOrg should return null
			AssertEquals(org2, pick.CustomLabelsGridLayoutPersister_ConfigOrg);
			AssertEquals(null, ((ICustomLabelsConfigOrgProvider)pick).ConfigOrg);
		}

