						 documentCommand.SU_MenuName.StartsWith("Manifest by Product") ||
						 documentCommand.SU_MenuName.StartsWith("Order Copy") ||
						 documentCommand.SU_MenuName.StartsWith("Package Labels") ||
						 documentCommand.SU_MenuName.StartsWith("Packing Slip") ||
						 documentCommand.SU_MenuName.StartsWith("Picking Shortfall And Non Picked Items") ||
						 documentCommand.SU_MenuName.StartsWith("Pick Documents Pack");
