		#region TestDocumentSupporter_GetChildCollection

		public void TestDocumentSupporter_GetChildCollection()
		{
			#region SetUpData

			var data = new TestDataSimpleEnvironment(Factory);
			var part3 = Helper.CreateProduct(data.Org1, "part3");
			var part4 = Helper.CreateProduct(data.Org1, "part4");

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "r1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, part3, 10m);
			Helper.CreateWhsReceiveInventoryLine(receive, part4, 10m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();

			AssertEquals("Check receive is finalised", true, receive.IsFinalised);
			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var order1Line1 = Helper.CreateWhsOrderLine(order1, data.Part1, 5);
			var order1Line2 = Helper.CreateWhsOrderLine(order1, data.Part2, 5);
			var order1Line3 = Helper.CreateWhsOrderLine(order1, part3, 5);
			var order1Line4 = Helper.CreateWhsOrderLine(order1, part4, 5);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var order2Line1 = Helper.CreateWhsOrderLine(order2, data.Part1, 5);
			var order2Line2 = Helper.CreateWhsOrderLine(order2, data.Part2, 5);
			var order2Line3 = Helper.CreateWhsOrderLine(order2, part3, 5);
			var order2Line4 = Helper.CreateWhsOrderLine(order2, part4, 5);
			Factory.Save();

			var pick = Helper.CreatePickNew(order1, order2);

			// Package Job 1
			//    1x Box B1
			//    1x Box B2
			//       Part1
			//		 1x Box B4
			//          Part1
			//          Part2
			//          Part3
			//          Part4
			//    1x Box B3
			//       Part2
			//       Part3
			//       Part4

			// Package Job 2
			//    1x Box B1
			//    1x Box B2
			//       Part1

			var packageJob1 = PkgPackageJob.LoadOrCreatePackageJob(order1);
			var order1OuterPackWith0 = PackingHelper.CreatePackage(packageJob1, 1, Constants.PkgUnit.Box, "B1");

			var order1OuterPackWith1 = PackingHelper.CreatePackage(packageJob1, 1, Constants.PkgUnit.Box, "B2");
			order1OuterPackWith1.Pack(order1Line1.ReleaseLines[0], 1m);

			var order1OuterPackWith3 = PackingHelper.CreatePackage(packageJob1, 1, Constants.PkgUnit.Box, "B3");
			order1OuterPackWith3.Pack(order1Line2.ReleaseLines[0], 1);
			order1OuterPackWith3.Pack(order1Line3.ReleaseLines[0], 1);
			order1OuterPackWith3.Pack(order1Line4.ReleaseLines[0], 1);

			var order1InnerPackWith4 = PackingHelper.CreatePackage(order1OuterPackWith1, 1, Constants.PkgUnit.Box, "B4");
			order1InnerPackWith4.Pack(order1Line1.ReleaseLines[0], 1);
			order1InnerPackWith4.Pack(order1Line2.ReleaseLines[0], 1);
			order1InnerPackWith4.Pack(order1Line3.ReleaseLines[0], 1);
			order1InnerPackWith4.Pack(order1Line4.ReleaseLines[0], 1);

			var packageJob2 = PkgPackageJob.LoadOrCreatePackageJob(order2);
			var order2OuterPackWith0 = PackingHelper.CreatePackage(packageJob2, 1, Constants.PkgUnit.Box, "B1");

			var order2OuterPackWith1 = PackingHelper.CreatePackage(packageJob2, 1, Constants.PkgUnit.Box, "B2");
			order2OuterPackWith1.Pack(order2Line1.ReleaseLines[0], 1m);

			#endregion

			var packingCommand = Factory.New<DocumentCommand>();
			packingCommand.SU_MenuPath = "Packing/Some Label";

			var orderPackingCommand = Factory.New<DocumentCommand>();
			orderPackingCommand.SU_MenuPath = "Orders/Packing/Some Label";

			var order1Form = new OrderFormForTest(order1);
			pick.ParentForm = order1Form;
			var docSupporter = pick.DocumentSupporter;
			var order1PackingDocuments =
				docSupporter.GetChildCollection(orderPackingCommand, BusinessContext.Packing, null);
			AssertEquals("Selected Order 1", 1, order1PackingDocuments.Length);
			AssertEquals("Selected Order 1", order1.PackageJob, order1PackingDocuments[0]);

			var order2Form = new OrderFormForTest(order2);
			pick.ParentForm = order2Form;
			docSupporter = pick.DocumentSupporter;
			var order2PackingDocuments =
				docSupporter.GetChildCollection(orderPackingCommand, BusinessContext.Packing, null);
			AssertEquals("Selected Order 2", 1, order2PackingDocuments.Length);
			AssertEquals("Selected Order 2", order2.PackageJob, order2PackingDocuments[0]);

			var orderPackingDocuments = docSupporter.GetChildCollection(packingCommand, BusinessContext.Packing, null);
			AssertContainsExactElementsInAnyOrder("Packing from all Orders", pick.Orders.Cast<WhsOrder>().Select(o => o.PackageJob), orderPackingDocuments);
		}

		#endregion

