			var order2Line1 = Helper.CreateWhsOrderLine(order2, data.Part1, 5);
			var order2Line2 = Helper.CreateWhsOrderLine(order2, data.Part2, 5);

			var pick = Helper.CreatePickNew(order1, order2);

			var rootMenuCommand = Factory.New<DocumentCommand>();
			rootMenuCommand.SU_MenuPath = "Some Label";
			var tbGuiProviderMock = new Mock<ITransportBookingGUIProvider>();
			tbGuiProviderMock.Setup(tgp => tgp.GetBookingsToDeliver(pick.Orders.Cast<IDtbBookingParent>().ToArray(), rootMenuCommand)).Returns(Enumerable.Empty<IDtbBooking>());

			using (ObjectFactory.Substitute(tbGuiProviderMock.Object))
			{
				var docSupporter = pick.DocumentSupporter;
				var rootMenuDocuments = docSupporter.GetChildCollection(rootMenuCommand, BusinessContext.DtbBooking, null);
				AssertContainsExactElementsInAnyOrder("Should return no bookings.", Enumerable.Empty<IDtbBooking>(), rootMenuDocuments);
				AssertEquals(false, docSupporter.ShowReasonForNotPrinting(Constants.DataContext.DtbBooking, rootMenuCommand));

				var consol1 = Factory.New<IDtbBookingConsolidation>();
				consol1.KB_ParentID = order1.PK;
				consol1.KB_JobType = TransportConsolidationJobTypes.Codes.Booking;
				consol1.KB_ParentTableCode = WhsDocketSchema.Constants.Prefix;

				var booking1 = Factory.New<IDtbBooking>();
				booking1.KM_KB_Booking = consol1.PK;
				booking1.KM_JobID = "Booking 1";

				var consol2 = Factory.New<IDtbBookingConsolidation>();
				consol2.KB_ParentID = order2.PK;
				consol2.KB_JobType = TransportConsolidationJobTypes.Codes.Booking;
				consol2.KB_ParentTableCode = WhsDocketSchema.Constants.Prefix;

				var booking2 = Factory.New<IDtbBooking>();
				booking2.KM_KB_Booking = consol2.PK;
				booking2.KM_JobID = "Booking 2";
				Factory.Save();

				var bookings = new[] { booking1, booking2 };
				tbGuiProviderMock.Setup(tgp => tgp.GetBookingsToDeliver(pick.Orders.Cast<IDtbBookingParent>().ToArray(), rootMenuCommand)).Returns(bookings);

				rootMenuDocuments = docSupporter.GetChildCollection(rootMenuCommand, BusinessContext.DtbBooking, null);
				AssertContainsExactElementsInAnyOrder("Documents from both bookings", bookings, rootMenuDocuments);
				AssertEquals(true, docSupporter.ShowReasonForNotPrinting(Constants.DataContext.DtbBooking, rootMenuCommand));
			}
		}

