		#region TestIMasterAssignerMembers

		public void TestIMasterAssignerMembers()
		{
			var data = new TestDataSimpleEnvironment(Factory);

			// Create inventory

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1.PK, 40m, data.Whs1.DefaultLocation.PK, "", "",
				InventoryStatus.Codes.Putaway);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2.PK, 40m, data.Whs1.DefaultLocation.PK, "", "",
				InventoryStatus.Codes.Putaway);
			receive.FinaliseDocket();

			AssertIsFinalisedPrecondition(receive);

			// Create orders and attach them to pick

			var orderWithMultipleProducts = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", Notify);
			Helper.CreateWhsOrderLine(orderWithMultipleProducts, data.Part1, 10m);
			Helper.CreateWhsOrderLine(orderWithMultipleProducts, data.Part2, 20m);

			var orderWithSingleProducts = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2", Notify);
			Helper.CreateWhsOrderLine(orderWithSingleProducts, data.Part1, 10m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.PickOrdersWithAllocationMock(new WhsOrder[] { orderWithMultipleProducts, orderWithSingleProducts });

			var assigner = (IMasterStaffAssigner)pick;

			// All Assignable lines

			Helper.SetPickedDate(pick.OrderedInventories[0].AvailableInventories[0], ZDateTimeOffset.Empty);
			Helper.SetPickedDate(pick.OrderedInventories[1].AvailableInventories[0], ZDateTimeOffset.Empty);
			pick.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			pick.OrderedInventories[1].AvailableInventories[0].Allocate = true;

			AssertEquals(2, assigner.Lines.Count());
			AssertEquals("Since pick is Created, it can be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since no lines are assigned, lines should be assignable.", true, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// One line with empty picked date and non-empty picked date

			Helper.SetPickedDate(pick.OrderedInventories[0].AvailableInventories[0], ZDateTimeOffset.Now);
			AssertEquals("Since pick is Created, Pick can be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since one line is un-assigned, lines should be assignable.", true, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// All non-empty picked dates

			Helper.SetPickedDate(pick.OrderedInventories[1].AvailableInventories[0], ZDateTimeOffset.Now);
			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since all lines are assigned, lines should not be assignable.", false, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// All non-allocated Lines

			Helper.SetPickedDate(pick.OrderedInventories[0].AvailableInventories[0], ZDateTimeOffset.Empty);
			Helper.SetPickedDate(pick.OrderedInventories[1].AvailableInventories[0], ZDateTimeOffset.Empty);
			pick.OrderedInventories[0].AvailableInventories[0].Allocate = false;
			pick.OrderedInventories[1].AvailableInventories[0].Allocate = false;

			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since all lines are non-allocated, lines should not be assignable.", false,
				assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// One allocated and non allocated line

			pick.OrderedInventories[0].AvailableInventories[0].Allocate = true;

			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since one lines is allocated, lines should be assignable.", true, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// One allocated but PickLine is Picking and non allocated line

			pick.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			foreach (var pickLine in pick.OrderedInventories[0].AvailableInventories[0].PickLines)
			{
				pickLine.WZ_IsPicking = true;
			}

			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals(
				"Since one lines is allocated but PickLines are Picking and another one lines are non-allocated, lines should not assignable.",
				false, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// One allocated but PickLine is Picking and allocated line

			pick.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			pick.OrderedInventories[1].AvailableInventories[0].Allocate = true;

			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since one lines is allocated and PickLine is Picking, lines should be assignable.", true,
				assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// Set pick line not Picking
			foreach (var pickLine in pick.OrderedInventories[0].AvailableInventories[0].PickLines)
			{
				pickLine.WZ_IsPicking = false;
			}

			// All non-allocated and non-empty picked date

			Helper.SetPickedDate(pick.OrderedInventories[0].AvailableInventories[0], ZDateTimeOffset.Now);
			Helper.SetPickedDate(pick.OrderedInventories[1].AvailableInventories[0], ZDateTimeOffset.Now);
			pick.OrderedInventories[0].AvailableInventories[0].Allocate = false;
			pick.OrderedInventories[1].AvailableInventories[0].Allocate = false;

			AssertEquals("Since Pick is Created, Pick should be assignable.", true, assigner.IsJobAssignable);
			AssertEquals("Since all lines are non-allocated, lines should not be assignable.", false,
				assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// Pick is cancelled

			pick.WP_PickStatus = PickStatus.Codes.Cancelled;
			AssertEquals("since pick is Cancelled it can't be assigned.", false, assigner.IsJobAssignable);
			AssertEquals("Since pick is Cancelled, no lines can be assignable.", false, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);

			// Pick is finalised

			pick.WP_PickStatus = PickStatus.Codes.Finalised;
			AssertEquals("since pick is Finalised it can't be assigned.", false, assigner.IsJobAssignable);
			AssertEquals("Since pick is Finalised, no lines can be assignable.", false, assigner.CanAssignOrUnAssignAnyLines);
			AssertEquals(pick.Factory, assigner.Factory);
		}

