		#region TestFireEventWhenCompletePicklines

		[TestDate(2014, 12, 10, 7, 50, 00)]
		public void TestFireEventWhenCompletePicklines()
		{
			var data = new TestDataSimpleEnvironment(Factory, 20, 1);
			data.Whs1.WarehouseAddress.OA_City = "Sydney";

			var locations = data.Whs1.Rows.Single(r => r.WR_Name == "A").Locations;
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 700m, locations[0]);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 600m, locations[1]);
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part2, 50m, locations[2]);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			var order1 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine11 = Helper.CreateWhsOrderLine(order1, data.Part1, 500m);
			var orderLine12 = Helper.CreateWhsOrderLine(order1, data.Part2, 10m);

			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine21 = Helper.CreateWhsOrderLine(order2, data.Part1, 500m);

			var pick = Helper.CreatePickNew(order1, order2);
			var part1OrderdInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.Single(o => o.SupplierPart == data.Part1);
			var part1AvailableInventories = part1OrderdInventory.AvailableInventories.Cast<WhsPickAvailableInventory>();
			part1AvailableInventories.Single(o => o.Location == locations[0]).AvailableInventoriesSplitByPickedDetails
				.Cast<WhsPickAvailableInventorySplitByPickedDetails>().Single().PickedDate = ZDateTimeOffset.Today;
			part1AvailableInventories.Single(o => o.Location == locations[1]).AvailableInventoriesSplitByPickedDetails
				.Cast<WhsPickAvailableInventorySplitByPickedDetails>().Single().PickedDate = ZDateTimeOffset.Today;
			AssertPickCompletedEventCountAsExpected(pick, order1, order2, 0);

			var part2OrderdInventory = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.Single(o => o.SupplierPart == data.Part2);
			var part2AvailableInventories = part2OrderdInventory.AvailableInventories.Cast<WhsPickAvailableInventory>();
			part2AvailableInventories.Single().AvailableInventoriesSplitByPickedDetails
				.Cast<WhsPickAvailableInventorySplitByPickedDetails>().Single().PickedDate = ZDateTimeOffset.Today;
			AssertEquals("All locations (100%) should be marked as Picked if Pick was finalised", (ZByte)100,
				pick.WP_PercentageComplete);
			AssertPickCompletedEventCountAsExpected(pick, order1, order2, 1);

			var logForPickCompleteEvent = order1.Logs.Find(GetLogFilter(order1.PK, Events.ServiceCompleted.Code))[0];
			AssertEquals("Reference should be Pick.WP_PickNo", pick.WP_PickNo.ToString(),
				logForPickCompleteEvent.ReferenceFreeText);
			AssertEquals("Event time should equals to ZDateTime.Now", ZDateTime.Now, logForPickCompleteEvent.SL_EventTime);

			AssertEquals("Should have 2 Parameters.", 2, logForPickCompleteEvent.Parameters.Count);
			AssertEquals("Paramerer EventReferenceParameters.Codes.Type is not as expected.",
				Constants.EventReferenceParameterTypes.Pick,
				logForPickCompleteEvent.Parameters[CargoWise.EventReference.Constants.EventReferenceParameters.Codes.Type]);
			AssertEquals("Paramerer EventReferenceParameters.Codes.Location is not as expected.",
				data.Whs1.WarehouseAddress.OA_City,
				logForPickCompleteEvent.Parameters[CargoWise.EventReference.Constants.EventReferenceParameters.Codes.Location]);
		}

		void AssertPickCompletedEventCountAsExpected(WhsPick pick, WhsOrder order1, WhsOrder order2, int expectedCount)
		{
			AssertEquals(expectedCount.ToString() + " PickCompleted event should be created in Pick", expectedCount,
				pick.Logs.Find(GetLogFilter(pick.PK, Events.ServiceCompleted.Code)).Length);
			AssertEquals(expectedCount.ToString() + " PickCompleted event should be created in Order1", expectedCount,
				order1.Logs.Find(GetLogFilter(order1.PK, Events.ServiceCompleted.Code)).Length);
			AssertEquals(expectedCount.ToString() + " PickCompleted event should be created in Order2", expectedCount,
				order2.Logs.Find(GetLogFilter(order2.PK, Events.ServiceCompleted.Code)).Length);
		}

		ZQuery GetLogFilter(ZGuid pK, ZString code)
		{
			var logFilter = new ZQuery(StmALogSchema.SL_Parent, pK);
			logFilter.AddToFilter(StmALogSchema.SL_SE_NKEvent, code);

			return logFilter;
		}

