		#region TestTotals_RecalculateAfterRemovingOrders_PartialSuccess

		public void TestTotals_RecalculateAfterRemovingOrders_PartialSuccess()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			PackingRegistry.Instance.WeightUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "KG");
			PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "M3");
			Helper.SetProductWeightAndVolume(data.Part1, 1, "KG", 1, "M3");
			Helper.SetProductWeightAndVolume(data.Part2, 100, "G", 10, "D3");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part2, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order1, order2);

			var pickLine = order1.Lines[0].PickLines.Single();
			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Now;

			using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
			{
				Factory.Save();
			}

			pick.CalculateOrderTotals();
			AssertEquals("Precondition: Picked Directly.", ZGuid.Empty, order1.Lines[0].PickLines.Single().WZ_WE_OriginalPickedInventoryLine);
			AssertEquals("Precondition: NumberOfOrders should be 2.", 2, pick.NumberOfOrders);
			AssertEquals("Precondition: TotalWeight should be 11 KG.", 11m, pick.TotalWeight);
			AssertEquals("Precondition: TotalVolume should be 10.1 M3.", 10.1m, pick.TotalVolume);
			AssertEquals("Precondition: TotalLineQty should be 20.", 20m, pick.TotalLineQty);
			AssertEquals("Precondition: TotalComponentQty should be 0.", 0m, pick.TotalComponentQty);

			pick.RemoveOrders(new WhsPickableDocket[] { order1, order2 });

			AssertEquals("NumberOfOrders should be 1 because 1 order is picked.", 1, pick.NumberOfOrders);
			AssertEquals("TotalWeight should be 10 KG because 10 Part1 was picked.", 10m, pick.TotalWeight);
			AssertEquals("TotalVolume should be 10 M3 because 10 Part1 was picked.", 10m, pick.TotalVolume);
			AssertEquals("TotalLineQty should be 10 because 10 Part1 was picked.", 10m, pick.TotalLineQty);
			AssertEquals("TotalComponentQty should be 0.", 0m, pick.TotalComponentQty);
		}

