			const int numberOfOrders = 100;
			PackingRegistry.Instance.WeightUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "KG");
			PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "M3");

			var data = new TestDataSimpleEnvironment(Factory);
			Helper.SetProductWeightAndVolume(data.Part1, 1.5, "KG", 2, "M3");
			Helper.SetProductWeightAndVolume(data.Part2, 1.5, "KG", 2, "M3");
			for (var i = 0; i < numberOfOrders; i++)
			{
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1" + i, data.Part1, 1m);
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2" + i, data.Part2, 1m);
			}
			var orders = new WhsPickableDocket[numberOfOrders];
			for (var i = 0; i < numberOfOrders; i++)
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + i, i % 2 == 0 ? data.Part1 : data.Part2, 1m, WhsPickOption.Codes.Manual);
				orders[i] = order;
			}
			var pick = Helper.CreatePickNew(orders);
			pick.AutoAllocateItemsWithMock();
			Factory.Save();

			var otherFactory = new BusinessObjectFactory { RefreshEnabled = false };
			var expectedDBHits = new Dictionary<string, int>()
			{
				{ WhsDocketSchema.Constants.TableName, 2 },
				{ OrgSupplierPartSchema.Constants.TableName, 1 },
				{ OrgHeaderSchema.Constants.TableName, 1 },
				{ OrgMiscServSchema.Constants.TableName, 1 },
				{ WhsWarehouseSchema.Constants.TableName, 1 },
				{ WhsDocketLineSchema.Constants.TableName, 4 }, // Bulk load by fetch hints
				{ WhsPickSchema.Constants.TableName, 1 },
				{ WhsPickLineSchema.Constants.TableName, 2 }, // Bulk load by fetch hints for 16 times
			};

			using (AssertDbHitsWithUsefulQueryInformation(expectedDBHits, otherFactory))
			{
				var pickInOtherFactory = otherFactory.Load<WhsPick>(pick.PK);
				pickInOtherFactory.CalculateOrderTotals();
				AssertEquals("Order count should be 100", 100, pickInOtherFactory.NumberOfOrders);
				AssertEquals("Total weight should be 150", 150m, pickInOtherFactory.TotalWeight);
			}
		}

