		#region GetTestDataForTotals_DBHits

		(IEnumerable<WhsPickableDocket>, WhsPick) GetTestDataForTotals_DBHits()
		{
			var data = new TestDataSimpleEnvironment(Factory, 10, 10);

			for (int i = 0; i < 10; i++)
			{
				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R" + i);
				for (int j = 0; j < 20; j++)
				{
					Helper.CreateWhsReceiveInventoryLine(receive, j % 2 == 0 ? data.Part1 : data.Part2, 1m);
				}

				receive.AllocateLocationsWithMock();
				receive.FinaliseDocket();
				AssertIsFinalisedPrecondition(receive);
			}

			var orders = new List<WhsOrder>();
			for (int i = 0; i < 20; i++)
			{
				var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + i, i % 2 == 0 ? data.Part1 : data.Part2, 1m, WhsPickOption.Codes.Manual);
				orders.Add(order);
			}

			var pick = Factory.New<WhsPick>();
			pick.AddOrders(orders);
			pick.AutoAllocateItemsWithMock();
			Factory.Save();

			AssertContainsExactElementsInAnyOrder("Precondition: Should have attached orders.", orders, pick.Orders);

			return (orders, pick);
		}

