		public void TestTotals_WorkOrder_UpdateTotals()
		{
			var (data, pick) = GetTestDataForTotals_WorkOrder(type: WorkOrderType.Codes.Assemble, shortfall: false);

			var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var subPart1Inventory = orderedInventories.First(orderedInventory => orderedInventory.ProductCode == "SUBPART1").AvailableInventories[0];
			AssertEquals("Precondition: PickLineQuantity of SubPart1 should be 6.", 6m, subPart1Inventory.PickLineQuantity);

			subPart1Inventory.PickLineQuantity = 5;
			AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
			AssertEquals("TotalWeight should be 55 KG.", 55m, pick.TotalWeight);
			AssertEquals("TotalVolume should be 2.8 M3.", 2.8m, pick.TotalVolume);
			AssertEquals("TotalLineQty should be 0.", 0m, pick.TotalLineQty);
			AssertEquals("TotalComponentQty should be 8.", 8m, pick.TotalComponentQty);
		}

