		#region TestTotals_WorkOrder_UpdateTotals_Disassemble

		public void TestTotals_WorkOrder_UpdateTotals_Disassemble()
		{
			var (data, pick) = GetTestDataForTotals_WorkOrder(type: WorkOrderType.Codes.Disassemble, shortfall: false);

			var availableInventory = pick.OrderedInventories[0].AvailableInventories[0];
			AssertEquals("Precondition: PickLineQuantity of MainPart should be 3.", 3m, availableInventory.PickLineQuantity);

			availableInventory.PickLineQuantity = 1;
			AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
			AssertEquals("TotalWeight should be 30 KG.", 30m, pick.TotalWeight);
			AssertEquals("TotalVolume should be 1 M3.", 1m, pick.TotalVolume);
			AssertEquals("TotalLineQty should be 1.", 1m, pick.TotalLineQty);
			AssertEquals("TotalComponentQty should be 0.", 0m, pick.TotalComponentQty);
		}

