		#region GetTestDataForTotals_WorkOrder

		(TestDataSimpleEnvironment, WhsPick) GetTestDataForTotals_WorkOrder(ZString type, bool shortfall)
		{
			PackingRegistry.Instance.WeightUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "KG");
			PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "M3");

			var data = new TestDataSimpleEnvironment(Factory, 10, 10);
			var mainPart = data.Part1;
			var subPart1 = Helper.CreateProduct(data.Org1, "SubPart1");
			var subPart2 = Helper.CreateProduct(data.Org1, "SubPart2");
			Helper.CreateProductBOM(mainPart, subPart1, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(mainPart, subPart2, 1m, Constants.PkgUnit.Unit);
			Helper.SetProductWeightAndVolume(mainPart, 30, "KG", 1, "M3");
			Helper.SetProductWeightAndVolume(subPart1, 5, "KG", 0.5, "M3");
			Helper.SetProductWeightAndVolume(subPart2, 10, "KG", 0.1, "M3");

			if (type == WorkOrderType.Codes.Assemble)
			{
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", subPart1, shortfall ? 2m : 10m);
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", subPart2, shortfall ? 3m : 10m);
			}
			else
			{
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", mainPart, shortfall ? 2m : 10m);
			}
			Factory.Save();

			var workOrder = Helper.CreateWhsWorkOrder(data.Org1, data.Whs1, "O1", type);
			Helper.CreateWhsWorkOrderLine(workOrder, mainPart, 3m);
			var pick = Helper.CreatePickNew(workOrder);
			pick.AutoAllocateItemsWithMock();
			Factory.Save();
			AssertEquals("Precondition - Picking is created.", true, workOrder.IsAttachedToPickButNotFinalised);

			var totalWeight = pick.TotalWeight;
			if (type == WorkOrderType.Codes.Assemble)
			{
				if (shortfall)
				{
					AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
					AssertEquals("TotalWeight should be 40 KG.", 40m, pick.TotalWeight);
					AssertEquals("TotalVolume should be 1.3 M3.", 1.3m, pick.TotalVolume);
					AssertEquals("TotalLineQty should be 0.", 0m, pick.TotalLineQty);
					AssertEquals("TotalComponentQty should be 5.", 5m, pick.TotalComponentQty);
				}
				else
				{
					AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
					AssertEquals("TotalWeight should be 60 KG.", 60m, pick.TotalWeight);
					AssertEquals("TotalVolume should be 3.3 M3.", 3.3m, pick.TotalVolume);
					AssertEquals("TotalLineQty should be 0.", 0m, pick.TotalLineQty);
					AssertEquals("TotalComponentQty should be 9.", 9m, pick.TotalComponentQty);
				}
			}
			else
			{
				if (shortfall)
				{
					AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
					AssertEquals("TotalWeight should be 60 KG.", 60m, pick.TotalWeight);
					AssertEquals("TotalVolume should be 2 M3.", 2m, pick.TotalVolume);
					AssertEquals("TotalLineQty should be 2.", 2m, pick.TotalLineQty);
					AssertEquals("TotalComponentQty should be 0.", 0m, pick.TotalComponentQty);
				}
				else
				{
					AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
					AssertEquals("TotalWeight should be 90 KG.", 90m, pick.TotalWeight);
					AssertEquals("TotalVolume should be 3 M3.", 3m, pick.TotalVolume);
					AssertEquals("TotalLineQty should be 3.", 3m, pick.TotalLineQty);
					AssertEquals("TotalComponentQty should be 0.", 0m, pick.TotalComponentQty);
				}
			}

			return (data, pick);
		}

