		(WhsPickableDocket, WhsPick) GetTestDataForTotals_WorkOrder_DBHits(ZString type)
		{
			PackingRegistry.Instance.WeightUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "KG");
			PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "M3");

			var data = new TestDataSimpleEnvironment(Factory, 10, 10);
			var mainPart = data.Part1;
			var subPart1 = Helper.CreateProduct(data.Org1, "SubPart1");
			var subPart2 = Helper.CreateProduct(data.Org1, "SubPart2");
			Helper.CreateProductBOM(mainPart, subPart1, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(mainPart, subPart2, 1m, Constants.PkgUnit.Unit);

			for (int i = 0; i < 10; i++)
			{
				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R" + i);
				for (int j = 0; j < 20; j++)
				{
					Helper.CreateWhsReceiveInventoryLine(receive, j % 2 == 0 ? subPart1 : subPart2, 5m);
				}

				receive.AllocateLocationsWithMock();
				receive.FinaliseDocket();
				AssertIsFinalisedPrecondition(receive);
			}

			var order = Helper.CreateWhsWorkOrder(data.Org1, data.Whs1, "O1", type);
			for (int i = 0; i < 20; i++)
			{
				Helper.CreateWhsWorkOrderLine(order, mainPart, 1m);
			}

			var pick = Factory.New<WhsPick>();
			pick.AddOrders(new WhsPickableDocket[] { order });
			pick.AutoAllocateItemsWithMock();
			Factory.Save();

			AssertEquals("Precondition: Should have attached work order.", order.PK, pick.Orders[0].PK);

			return (order, pick);
		}

