		#region TestTotals_PickOnSaleOrder_UpdateTotals

		public void TestTotals_PickOnSaleOrder_UpdateTotals()
		{
			var (data, pick) = GetTestDataForTotals_PickOnSaleOrder(shortfall: false);

			var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var mainPartInventory = orderedInventories.First(orderedInventory => orderedInventory.ProductCode == "P1").AvailableInventories[0];
			AssertEquals("Precondition: PickLineQuantity of P1 should be 1.", 1m, mainPartInventory.PickLineQuantity);

			mainPartInventory.PickLineQuantity = 0;
			AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
			AssertEquals("TotalWeight should be 0*30 + 2*5 + 1*10 + 2*10 = 40.", 40m, pick.TotalWeight);
			AssertEquals("TotalVolume should be 0*1 + 2*0.5 + 1*0.1 + 2*0.1 = 1.3", 1.3m, pick.TotalVolume);
			AssertEquals("TotalLineQty should be 0(mainPart)+2(Part2)=2.", 2m, pick.TotalLineQty);
			AssertEquals("TotalComponentQty should be 2(subPart1)+1(subPart2)=3.", 3m, pick.TotalComponentQty);

			var part2Inventory = orderedInventories.First(orderedInventory => orderedInventory.ProductCode == "P2").AvailableInventories[0];
			AssertEquals("Precondition: PickLineQuantity of P2 should be 2.", 2m, part2Inventory.PickLineQuantity);

			part2Inventory.PickLineQuantity = 0;
			AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
			AssertEquals("TotalWeight should be 0*30 + 2*5 + 1*10 + 0*10 = 20.", 20m, pick.TotalWeight);
			AssertEquals("TotalVolume should be 0*1 + 2*0.5 + 1*0.1 + 0*0.1 = 1.1", 1.1m, pick.TotalVolume);
			AssertEquals("TotalLineQty should be 0(mainPart)+0(Part2)=0.", 0m, pick.TotalLineQty);
			AssertEquals("TotalComponentQty should be 2(subPart1)+1(subPart2)=3.", 3m, pick.TotalComponentQty);
		}

		#endregion

		#region GetTestDataForTotals_PickOnSaleOrder

		(TestDataSimpleEnvironment, WhsPick) GetTestDataForTotals_PickOnSaleOrder(bool shortfall)
		{
			PackingRegistry.Instance.WeightUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "KG");
			PackingRegistry.Instance.VolumeUnit.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "M3");

			var data = new TestDataSimpleEnvironment(Factory, 10, 10);
			var mainPart = data.Part1;
			var subPart1 = Helper.CreateProduct(data.Org1, "SubPart1");
			var subPart2 = Helper.CreateProduct(data.Org1, "SubPart2");
			Helper.CreateProductBOM(mainPart, subPart1, 2m, Constants.PkgUnit.Unit);
			Helper.CreateProductBOM(mainPart, subPart2, 1m, Constants.PkgUnit.Unit);
			Helper.SetProductWeightAndVolume(mainPart, 30, "KG", 1, "M3");
			Helper.SetProductWeightAndVolume(subPart1, 5, "KG", 0.5, "M3");
			Helper.SetProductWeightAndVolume(subPart2, 10, "KG", 0.1, "M3");
			Helper.SetProductWeightAndVolume(data.Part2, 10, "KG", 0.1, "M3");
			mainPart.OP_IsComponentPickedOnSalesOrder = true;
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", mainPart, 1m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", subPart1, shortfall ? 3m : 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", subPart2, shortfall ? 2m : 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", data.Part2, shortfall ? 1m : 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			Helper.CreateWhsOrderLine(order, mainPart, 2m);
			Helper.CreateWhsOrderLine(order, data.Part2, 2m);
			var pick = Helper.CreatePickNew(order);
			pick.AutoAllocateItemsWithMock();
			Factory.Save();
			AssertEquals("Precondition - Picking is created.", true, order.IsAttachedToPickButNotFinalised);

			var totalWeight = pick.TotalWeight;

			if (shortfall)
			{
				AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
				AssertEquals("TotalWeight should be 30 + 2*5 + 1*10 + 1*10 = 60.", 60m, pick.TotalWeight);
				AssertEquals("TotalVolume should be 1 + 2*0.5 + 1*0.1 + 1*0.1 = 2.2.", 2.2m, pick.TotalVolume);
				AssertEquals("TotalLineQty should be 1(mainPart)+1(Part2)=2.", 2m, pick.TotalLineQty);
				AssertEquals("TotalComponentQty should be 2(subPart1)+1(subPart2)=3.", 3m, pick.TotalComponentQty);
			}
			else
			{
				AssertEquals("NumberOfOrders should be 1.", 1, pick.NumberOfOrders);
				AssertEquals("TotalWeight should be 1*30 + 2*5 + 1*10 + 2*10 = 70.", 70m, pick.TotalWeight);
				AssertEquals("TotalVolume should be 1*1 + 2*0.5 + 1*0.1 + 2*0.1 = 2.3.", 2.3m, pick.TotalVolume);
				AssertEquals("TotalLineQty should be 1(mainPart)+2(Part2)=3, 1 normal order line.", 3m, pick.TotalLineQty);
				AssertEquals("TotalComponentQty should be 2(subPart1)+1(subPart2)=3.", 3m, pick.TotalComponentQty);
			}

			return (data, pick);
		}

