			var pickOnSaleOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O999", mainPart, 1m, WhsPickOption.Codes.Manual);
			var orders = new List<WhsOrder>();
			orders.Add(pickOnSaleOrder);
			for (int i = 0; i < 20; i++)
			{
				var normalOrder = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O" + i, subPart1, 1m, WhsPickOption.Codes.Manual);
				orders.Add(normalOrder);
			}

			var pick = Factory.New<WhsPick>();
			pick.AddOrders(orders);
			pick.AutoAllocateItemsWithMock();
			Factory.Save();

			AssertContainsExactElementsInAnyOrder("Precondition: Should have attached orders.", orders, pick.Orders);

			return (orders, pick);
		}

