		void AssertPickOnHoldIfShorfallOccursOnPickfaceLocation(bool autoPrintPickingSlip)
		{
			var data = new TestDataSimpleEnvironment(Factory, 3, 1);
			var ruleSet = AllocationRulesHelper.MakeNewRuleSetAndDeactivateSystemAllocationRuleSet(Factory);
			AllocationRulesHelper.AddFifoRule(ruleSet, 200, preventPickingPickFacesFromBulk: true);
			AllocationRulesHelper.AddPickFaceRules(ruleSet, 100);
			AllocationRulesHelper.AddFullPalletRule(ruleSet, 10);

			Helper.CreateProductUnit(data.Part1, Constants.PkgUnit.Pallet, 2m); // Part1: 1PLT = 2 UNT

			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			var bulkLocationForPartWithEnoughStock = data.Whs1.FindLocation("A-3");
			data.Whs1.WW_AutoPrintPackingSlip = autoPrintPickingSlip;

			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);

			var today = ZDateTimeOffset.Today;
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", today.AddDays(-1), data.Part1, 3m, pickFaceLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", today.AddDays(-4), data.Part1, 3m, bulkLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", today.AddDays(-1), data.Part2, 1m, bulkLocationForPartWithEnoughStock, "");

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1");
			Helper.CreateWhsOrderLine(order, data.Part1, 6m); // This will short fall since there is a pick face and can't pick the full pallet
			Helper.CreateWhsOrderLine(order, data.Part2, 1m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order);

			var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var orderedInventoryForShortfallPart = orderedInventories.Single(o => o.SupplierPart == data.Part1);
			var orderedInventoryForPartWithEnoughStock = orderedInventories.Single(o => o.SupplierPart == data.Part2);

			AssertEquals("Precondition", 0m, orderedInventoryForShortfallPart.PickLineQuantity);
			AssertEquals("Precondition", 0m, orderedInventoryForPartWithEnoughStock.PickLineQuantity);

			WhsPick.AutoPickEventArgs args = null;
			pick.AutoPickAttempt += (sender, e) => { args = e; };
			pick.PickOrders();

			AssertEquals(true, args.IsPickWaitingReplenishment);
			AssertEquals("Pick shortfalls since there are no enough stock to be allocated from pick face location.", true, pick.HasShortfallItems);
			AssertEquals("Precondition", true, pick.WP_IsAwaitingReplenishment);
			AssertEquals("5 items should be picked.", 5m, orderedInventoryForShortfallPart.PickLineQuantity);
			AssertEquals("1 item should be picked.", 1m, orderedInventoryForPartWithEnoughStock.PickLineQuantity);
			AssertEquals("1 item should be shortfall.", 1m, orderedInventoryForShortfallPart.QuantityShort);
			AssertEquals("No items should be shortfall.", 0m, orderedInventoryForPartWithEnoughStock.QuantityShort);

			// pickface location receives inventory
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R5", today.AddDays(-1), data.Part1, 1m, pickFaceLocation, "");
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
			AssertEquals("Precondition", true, pickInNewFactory.HasShortfallItems);
			AssertEquals("Precondition", true, pickInNewFactory.WP_IsAwaitingReplenishment);

			var orderedInventoriesInNewFactory = pickInNewFactory.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var orderedInventoryForShortfallPartInNewFactory = orderedInventoriesInNewFactory.Single(o => o.SupplierPart.PK == data.Part1.PK);
			var orderedInventoryForPartWithEnoughStockInNewFactory = orderedInventoriesInNewFactory.Single(o => o.SupplierPart.PK == data.Part2.PK);

			AssertEquals("Precondition", 5m, orderedInventoryForShortfallPartInNewFactory.PickLineQuantity);
			AssertEquals("Precondition", 1m, orderedInventoryForPartWithEnoughStockInNewFactory.PickLineQuantity);
			AssertEquals("Precondition", 1m, orderedInventoryForShortfallPartInNewFactory.QuantityShort);
			AssertEquals("Precondition", 0m, orderedInventoryForPartWithEnoughStockInNewFactory.QuantityShort);

			pickInNewFactory.AutoAllocateItems();

			AssertEquals("Since there are inventory available pick is not shortfall.", false, pickInNewFactory.HasShortfallItems);
			AssertEquals("Pick is not held anymore since all inventory is allocated without a shortfall.", PickStatus.Codes.Created, pickInNewFactory.WP_PickStatus);
			AssertEquals("6 items should be picked.", 6m, orderedInventoryForShortfallPartInNewFactory.PickLineQuantity);
			AssertEquals("1 item should be picked.", 1m, orderedInventoryForPartWithEnoughStockInNewFactory.PickLineQuantity);
			AssertEquals("No items should be shortfall.", 0m, orderedInventoryForShortfallPartInNewFactory.QuantityShort);
			AssertEquals("No items should be shortfall.", 0m, orderedInventoryForPartWithEnoughStockInNewFactory.QuantityShort);
		}

		#endregion

