		[GuiTest]
		public void TestPickDynamicProduct_PicksFullPalletFromBulk()
		{
			const decimal PalletSize = 5m;
			const decimal InitialBulkQuantity = 2 * PalletSize;
			const decimal InitialDynamicQuantity = 6m;
			const decimal OrderQuantity = 5m;

			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var ruleSet = AllocationRulesHelper.MakeNewRuleSetAndDeactivateSystemAllocationRuleSet(Factory);
			AllocationRulesHelper.AddFifoRule(ruleSet, 200, preventPickingPickFacesFromBulk: true);
