			Helper.CreateProductUnit(data.Part1, Constants.PkgUnit.Pallet, PalletSize); // Part1 : 1PLT = 5 UNT

			var bulkLocation = data.Whs1.FindLocation("A-1");
			var dynamicPickFaceLocation = data.Whs1.FindLocation("A-2");
			var dynamicArea = Helper.CreateArea(data.Whs1, "DYNAMIC");
			dynamicPickFaceLocation.WLV_WA_PickingArea = dynamicArea.PK;
			var dynamicLocationType = Helper.CreateLocationType("DLC", LocationClasses.Codes.DPF);
			dynamicPickFaceLocation.WLV_WLT_LocationType = dynamicLocationType.PK;

			var whsProduct = WhsProduct.GetWhsProduct(data.Part1);
			var productParams = whsProduct.ParamsByWhsAndClient.AddNew();
			productParams.W3_OH = data.Org1.PK;
			productParams.W3_WW = data.Whs1.PK;
			productParams.W3_WA_DynamicPickFaceArea = dynamicArea.PK;

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", ZDateTimeOffset.Today.AddDays(-1), data.Part1,
				InitialBulkQuantity, bulkLocation, "");
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", ZDateTimeOffset.Today.AddDays(-1), data.Part1,
				InitialDynamicQuantity, dynamicPickFaceLocation, "");
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "1", WhsPickOption.Codes.Manual);
			Helper.CreateWhsOrderLine(order, data.Part1, OrderQuantity);

			var pick = Helper.CreatePickNew(order);
			var orderedInventories = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var orderedInventory = orderedInventories.Single();
			var bulkInventory = orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>()
				.Single(inventory => inventory.LocationPK == bulkLocation.PK);
			var dynamicInventory = orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>()
				.Single(inventory => inventory.LocationPK == dynamicPickFaceLocation.PK);

			AssertEquals("Precondition", 0m, orderedInventory.PickLineQuantity);
			AssertEquals("Precondition", OrderQuantity, orderedInventory.QuantityShort);

			pick.AutoAllocateItems();
			CombineAssertions(() =>
			{
				AssertEquals("5 items should be picked.", OrderQuantity, orderedInventory.PickLineQuantity);
				AssertEquals("Pick should not be short", 0m, orderedInventory.QuantityShort);
				AssertEquals("1 pallet should remain in bulk", PalletSize, bulkInventory.QuantityUnPicked);
				AssertEquals("Dynamic location should still be full", InitialDynamicQuantity,
					dynamicInventory.QuantityUnPicked);
				AssertEquals("Pick should be created", PickStatus.Codes.Created, pick.WP_PickStatus);
			});
		}

