		#region TestIsCancellable_OrderWithPickByLabelJob

		public void TestIsCancellable_OrderWithPickByLabelJob()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			AssertEquals("Precondition", 1, pick.Orders.Count);
			AssertEquals("Precondition: order.HasAnyPackagesAssignedToAPickByLabelJob should be false", false,
				order.HasAnyPackageAssignedToAPickByLabelJob());

			var package = order.PackageJob.Packages.AddNew("PLT", "PACKAGE-1");
			var releaseLine = order.Lines[0].ReleaseLines[0];
			package.Pack(releaseLine, 5m);
			Factory.Save();

			WhsPickByLabelHelper.AddPackageToListOfPickByLabelForUser(Factory, data.Whs1.PK,
				data.Whs1.WW_DefaultOutboundDockDoor, GlbStaff.CurrentUser.GS_Code, package.PK);
			Factory.Save();

			AssertEquals("Precondition: order.HasAnyPackagesAssignedToAPickByLabelJob should be true", true,
				order.HasAnyPackageAssignedToAPickByLabelJob());

			var errorMessage = pick.GetIsCancellableErrorMessage();
			AssertEquals("HasAnyPackagesAssignedToAPickByLabelJob, should not be cancellable.", false,
				errorMessage.IsEmpty);
			AssertEquals("ErrorMessage doesn't match",
				"You cannot cancel pick because this pick has a package with an active Pick By Label job.",
				errorMessage);
		}

