		#region TestWP_FinalizedDateUtc_ZSaveConcurrencyException

		public void TestWP_FinalizedDateUtc_ZSaveConcurrencyException()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(finaliseOrders: true, finalisePick: true, pickableDockets: order);
			Factory.Save();
			AssertEquals("Precondition", true, pick.IsFinalised);

			// Load before change
			var pickInOtherFactory = new BusinessObjectFactory { RefreshEnabled = false }.Load<WhsPick>(pick.PK);
			// Any change in WP_FinalizedDateUtc in DB to not match with memory
			CargoWise.Database.TestFramework.ObjectModel.WhsPick.UpdateWhere(pick.PK.ToGuid())
				.Set(l => l.WP_FinalizedDateUtc, pick.WP_FinalizedDateUtc.AddDays(-1).ToDateTime()).Post(Db.Connection);
			pickInOtherFactory.WP_PickPalletsByLabel = true;
			AssertExceptionThrown<ZSaveConcurrencyException>(pickInOtherFactory.Factory.Save);
		}

