		#region TestWP_FinalizedDateUtc_ConcurrencyPolicy

		public void TestWP_FinalizedDateUtc_ConcurrencyPolicy()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(finaliseOrders: true, finalisePick: false, pickableDockets: order);
			Factory.Save();

			var pickNotFinalized = new BusinessObjectFactory { RefreshEnabled = false }.Load<WhsPick>(pick.PK);
			AssertEquals("Precondition", ConcurrencyPolicy.Strict,
				pickNotFinalized.WP_FinalizedDateUtcInfo.ConcurrencyPolicy);
			pickNotFinalized.FinalisePick();
			pickNotFinalized.Factory.Save();

			var pickFinalized = new BusinessObjectFactory { RefreshEnabled = false }.Load<WhsPick>(pick.PK);
			AssertEquals("WP_FinalizedDateUtc should be strict for finalize pick!", ConcurrencyPolicy.Strict,
				pickFinalized.WP_FinalizedDateUtcInfo.ConcurrencyPolicy);
		}

