		#region TestWP_CriticalChangesVersionID_ConcurrencyPolicy

		public void TestWP_CriticalChangesVersionID_ConcurrencyPolicy()
		{
			var pick = Factory.New<WhsPick>();
			AssertNotEquals("Precondition", PickStatus.Codes.Finalised, pick.WP_PickStatus);
			AssertEquals("Precondition", ConcurrencyPolicy.Ignore,
				pick.WP_CriticalChangesVersionIDInfo.ConcurrencyPolicy);

			pick.WP_PickStatus = PickStatus.Codes.PickSlip;
			AssertEquals(ConcurrencyPolicy.Ignore, pick.WP_CriticalChangesVersionIDInfo.ConcurrencyPolicy);

			pick.WP_PickStatus = PickStatus.Codes.Finalised;
			AssertEquals(ConcurrencyPolicy.Strict, pick.WP_CriticalChangesVersionIDInfo.ConcurrencyPolicy);

			pick.WP_PickStatus = PickStatus.Codes.Cancelled;
			AssertEquals(ConcurrencyPolicy.Strict, pick.WP_CriticalChangesVersionIDInfo.ConcurrencyPolicy);
		}

