		void TestWP_CriticalChangesVersionID_PickFinalizedCore(Action<WhsPick> action)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Factory.New<WhsPick>();
			pick.PickOrdersWithAllocationMock(order, saveFactory: false);
			pick.FinaliseAllOrders();
			AssertIsFinalisedPrecondition(order);

			Factory.Save();
			AssertEquals(ZGuid.Empty, pick.WP_CriticalChangesVersionID);

			pick.WP_PickStatus = PickStatus.Codes.PickSlip;
			Factory.Save();
			AssertNotEquals(ZGuid.Empty, pick.WP_CriticalChangesVersionID);

			var pickInOtherFactory = NewFactory().Load<WhsPick>(pick.PK);
			AssertEquals("Precondition", false, pickInOtherFactory.IsFinalised);
			AssertRowExistsInDb("Pick is not finalized, Should have version!",
				"WP_CriticalChangesVersionID is not null", pick.PK);

			action(pickInOtherFactory);
			pickInOtherFactory.Factory.Save();

			AssertEquals(ZGuid.Empty, pickInOtherFactory.WP_CriticalChangesVersionID);
			AssertRowExistsInDb("Pick is finalized or cancel, Should clear version to save sapce!",
				"WP_CriticalChangesVersionID is null", pick.PK);
		}

