			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			var pick = Helper.CreatePickNew(finaliseOrders: true, finalisePick: false, pickableDockets: order);
			Factory.Save();

			var pickforUser1 = new BusinessObjectFactory { RefreshEnabled = false }.Load<WhsPick>(pick.PK);
			var pickforUser2 = new BusinessObjectFactory { RefreshEnabled = false }.Load<WhsPick>(pick.PK);

			pickforUser1.WP_PickStatus = PickStatus.Codes.PickSlip;
			pickforUser1.Factory.Save();
			AssertEquals(true, pickforUser1.WP_CriticalChangesVersionID.IsValid);

			action(pickforUser2);
			AssertExceptionThrown<ZSaveConcurrencyException>(pickforUser2.Factory.Save);
			AssertRowExistsInDb("Should not be able to save Pick and keep version!",
				"WP_CriticalChangesVersionID is not null", pickforUser2.PK);
		}

