		static void AssertRowExistsInDb(string msg, string condition, ZGuid pk)
		{
			var count = (int)Db.Connection.ExecuteScalar(
				$"SELECT COUNT(*) FROM dbo.WhsPick WHERE WP_PK = '{pk}' and {condition}");
			AssertEquals(msg, 1, count);
		}

