		public void TestFinalisePickCalculatesOrderClassification_MultipleOrders()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "2", data.Part2, 10m);
			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "3", data.Part1, 10m);
			order1.WD_TotalWeightUnit = "KG";
			order1.WD_TotalCubicUnit = "M3";
			order1.WD_CubicSent = 2m;
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "4", data.Part2, 3m);
			order2.WD_TotalWeightUnit = "KG";
			order2.WD_TotalCubicUnit = "M3";
			order2.WD_CubicSent = 0.4m;
			var order3 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "5", data.Part2, 5m);
			order3.WD_TotalWeightUnit = "KG";
			order3.WD_TotalCubicUnit = "M3";
			order3.WD_CubicSent = 0.5m;

			var consignee = Helper.CreateClient("CONSIGNEE");
			order1.ConsigneeAddressPK = consignee.MainAddress.PK;
			order2.ConsigneeAddressPK = consignee.MainAddress.PK;
			order3.ConsigneeAddressPK = consignee.MainAddress.PK;
			Factory.Save();

			AssertEquals(string.Empty, order1.WD_OrderClassification);
			AssertEquals(string.Empty, order2.WD_OrderClassification);
			AssertEquals(string.Empty, order3.WD_OrderClassification);
			var pick = Helper.CreatePickNew(order1, order2, order3);
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			Factory.Save();
			AssertIsFinalisedPrecondition(pick);
			AssertIsFinalisedPrecondition(order1);
			AssertIsFinalisedPrecondition(order2);
