			AssertEquals(OrderClassification.Codes.Bulk, order1.WD_OrderClassification);
			AssertEquals(OrderClassification.Codes.ECommerce, order2.WD_OrderClassification);
			AssertEquals(OrderClassification.Codes.Unknown, order3.WD_OrderClassification);
		}

		public void TestFinalisePickCalculatesOrderClassification_DBHits()
