		public void TestRemoveOrders_ResetsWaitingReplenishmentStatus()
		{
			TestRemoveOrders_ResetsWaitingReplenishmentStatus_Core((pick, order) => pick.Orders.Remove(order));
		}

		public void TestRemoveOrders_ResetsWaitingReplenishmentStatus_BulkRemove()
		{
			TestRemoveOrders_ResetsWaitingReplenishmentStatus_Core((pick, order) => pick.RemoveOrders(new[] { order }));
		}

		void TestRemoveOrders_ResetsWaitingReplenishmentStatus_Core(Action<WhsPick, WhsOrder> removeOrder)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var transferLine = Helper.CreateWhsTransferLine(transfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			transferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, transfer.IsFinalised);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order);

			pick.PickOrdersWithAllocationMock();
			AssertEquals("Precondition: pick is waiting for replenishment.", true,
				pick.WP_IsAwaitingReplenishment);
			Factory.Save();

			pick.HasChanges =
				true; // removing orders does not set HasChanges to true, done manually in OrdersModuleButtonGrid
			removeOrder(pick, order);
			Factory.Save();

			Assert("Pick has no more orders.", pick.Orders.Count == 0);
			AssertEquals("Pick status is not waiting replenishment anymore.", false,
				pick.WP_IsAwaitingReplenishment);
		}

