		#region TestAutoAllocateItems_AllocationRulesEnabled_US_Bonded_EndToEnd

		[GuiTest]
		public void TestAutoAllocateItems_AllocationRulesEnabled_US_Bonded_EndToEnd()
		{
			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			CreateRule(ruleSet, "RULE1", "RULE1", 1, canPickSplitCase: false);
			CreateRule(ruleSet, "RULE2", "RULE2", 2);

			var data = new TestDataSimpleEnvironment(Factory);
			data.Whs1.WarehouseAddress.OA_RL_NKRelatedPortCode = "USLAX";
			var bondedArea = Helper.CreateArea(data.Whs1, "BOND", AreaTypes.Codes.Bonded);
			var location = data.Whs1.DefaultLocation;
			location.WLV_WA_PutawayArea = bondedArea.PK;
			Factory.Save();

			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1", Notify);
			receive.WD_DocketSubType = ReceiveType.Codes.Customs;
			var inventory1 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 30m, "KEY-1", "", 3m);
			var inventory2 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 40m, "KEY-1", "", 4m);
			var inventory3 = Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 50m, "KEY-1", "", 5m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();
			Factory.Save();
			AssertIsFinalisedPrecondition(receive);

			// if multiple packages can be picked, then the biggest packages should be used.
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 20m);
			var pick = Helper.CreatePickNew(order);
			AssertEquals("Order should be fulfilled.", 20m, orderLine.PickLineQuantity);
			AssertEquals("The biggest packages should be picked.", 0m,
				inventory1.CommittedQuantityIncludingUnfinalisedReceipt); // 0x3
			AssertEquals("The biggest packages should be picked.", 0m,
				inventory2.CommittedQuantityIncludingUnfinalisedReceipt); // 0x4
			AssertEquals("The biggest packages should be picked.", 20m,
				inventory3.CommittedQuantityIncludingUnfinalisedReceipt); // 4x5

			// system should be able to pick different quantities from different inventories to achieve fulfilment
			var order2 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
			var orderLine2 = Helper.CreateWhsOrderLine(order2, data.Part1, 17m);
			var pick2 = Helper.CreatePickNew(order2);
			AssertEquals("Order should be fulfilled.", 17m, orderLine2.PickLineQuantity);
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 3m,
				inventory1.CommittedQuantityIncludingUnfinalisedReceipt); // 1x3
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 4m,
				inventory2.CommittedQuantityIncludingUnfinalisedReceipt); // 1x4
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 30m,
				inventory3.CommittedQuantityIncludingUnfinalisedReceipt); // 2x5

			// system should be able to pick different quantities from different inventories to achieve fulfilment
			var order3 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O3");
			var orderLine3 = Helper.CreateWhsOrderLine(order3, data.Part1, 41m);
			var pick3 = Helper.CreatePickNew(order3);
			AssertEquals("Order should be fulfilled.", 41m, orderLine3.PickLineQuantity);
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 12m,
				inventory1.CommittedQuantityIncludingUnfinalisedReceipt); // 3x3
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 16m,
				inventory2.CommittedQuantityIncludingUnfinalisedReceipt); // 3x4
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 50m,
				inventory3.CommittedQuantityIncludingUnfinalisedReceipt); // 4x5

			// when order cannot be fulfilled it should achieve max possible allocation but not over-allocate
			var order4 = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O4");
			var orderLine4 = Helper.CreateWhsOrderLine(order4, data.Part1, 5m);
			var pick4 = Helper.CreatePickNew(order4);
			AssertEquals("Order should be fulfilled.", 4m, orderLine4.PickLineQuantity);
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 12m,
				inventory1.CommittedQuantityIncludingUnfinalisedReceipt); // 0x3
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 20m,
				inventory2.CommittedQuantityIncludingUnfinalisedReceipt); // 1x4
			AssertEquals("All three inventories should be picked to fulfil picking requirements.", 50m,
				inventory3.CommittedQuantityIncludingUnfinalisedReceipt); // 0x5
		}

		[GuiTest]
		[StressTest]
		public void TestAutoAllocateItems_AllocationRulesEnabled_EndToEnd_DBHits()
		{
			var data = new TestDataSimpleEnvironment(Factory, 10, 10);

			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			var rule = Factory.New<ProductionRule>();
			rule.PRL_PRS_RuleSet = ruleSet.PK;
			rule.PRL_Name = "RULE1";
			rule.PRL_Description = "RULE1";
			rule.PRL_Priority = 1;
			rule.PRL_RuleDefinition = $@"{{
    ""conditions"": [
    ],
    ""action"": {{
        ""$type"": ""AllocateStockActionState"",
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""ArrivalDate"",
				""direction"": ""descending""
			}}
        ],
		""allocateCases"": true,
		""allocatePallets"": true,
		""allocateSplitCase"": true,
		""canBreakUOMs"": true,
    }}
}}";

			var orderList = new List<WhsOrder>();
			for (int orderCount = 0; orderCount < 10; orderCount++)
			{
				var postfix = orderCount.ToString();
				var client = Helper.CreateClient("C" + postfix);
				var order = Helper.CreateWhsOrder(client, data.Whs1, "O" + postfix, WhsPickOption.Codes.Manual);
				for (int orderLineCount = 0; orderLineCount < 10; orderLineCount++)
				{
					var product = Helper.CreateProduct(client, "P" + postfix + orderLineCount.ToString());
					var location = Helper
						.CreateRowAndGenerateLocations(data.Whs1,
							"R" + orderCount.ToString() + orderLineCount.ToString(), 1, 1).Locations
						.Single();
					Helper.CreateWhsReceiveWithInventory(client, data.Whs1, "R" + postfix + orderLineCount.ToString(),
						ZDateTimeOffset.Today, product, 2, location, "", false);

					Helper.CreateWhsOrderLine(order, product, 1m);
				}

				orderList.Add(order);
			}

			var pick = Helper.CreatePickNew(orderList.ToArray());
			var orderedInventories = pick.OrderedInventories;
			Assert("Precondition: there are ordered inventories.", orderedInventories.Count > 0);
			foreach (WhsPickOrderedInventory orderedInv in orderedInventories)
			{
				AssertEquals("Precondition: not allocated.", 0m, orderedInv.PickLineQuantity);
