		void TestAutoAllocateItems_AllocationRulesEnabled_EndToEnd_UOMs(string uomType, bool breakUOMs,
			decimal expectedQuantity)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			Factory.LoadFromNaturalKey<RefPackType>(RefPackTypeSchema.F3_Code, "BOX").F3_UOMType =
				UOMPackTypesList.Codes.Case;

			data.Part1.PartUnits.RemoveAndDeleteAll();
			Helper.CreateProductUnit(data.Part1, "PLT", 10m);
			Helper.CreateProductUnit(data.Part1, "BOX", 5m);

			var today = ZDateTimeOffset.Today;
			var receive1 =
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", today.AddDays(-1), data.Part1, 16m);
			Factory.Save();

			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			var rule = Factory.New<ProductionRule>();
			rule.PRL_PRS_RuleSet = ruleSet.PK;
			rule.PRL_Name = "RULE1";
			rule.PRL_Description = "RULE1";
			rule.PRL_Priority = 1;
			rule.PRL_RuleDefinition = $@"{{
    ""conditions"": [
    ],
    ""action"": {{
        ""$type"": ""AllocateStockActionState"",
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""ArrivalDate"",
				""direction"": ""descending""
			}}
        ],
		""allocateCases"":{GetLowerCaseBoolString(uomType == UOMPackTypesList.Codes.Case)},
		""allocatePallets"":{GetLowerCaseBoolString(uomType == UOMPackTypesList.Codes.Pallet)},
		""allocateSplitCase"":{GetLowerCaseBoolString(uomType == UOMPackTypesList.Codes.SplitCase)},
		""canBreakUOMs"":{GetLowerCaseBoolString(breakUOMs)},
    }}
}}";
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 16m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);

			var availInv = pick.OrderedInventories[0].AvailableInventories.Cast<WhsPickAvailableInventory>().Single();

			pick.AutoAllocateItems();

			AssertEquals("Should have picked available inventory 1.", expectedQuantity, availInv.PickLineQuantity);

			string GetLowerCaseBoolString(bool value) => value ? "true" : "false";
		}

