		[GuiTest]
		public void TestAutoAllocateItems_AllocationRulesEnabled_Groups_EndToEnd()
			=> TestAutoAllocateItems_AllocationRulesEnabled_Groups_EndToEnd(
				groupMustAllocateWholeOrderLineBalance: false);

		[GuiTest]
		public void TestAutoAllocateItems_AllocationRulesEnabled_Groups_MustAllocateBalance_EndToEnd()
			=> TestAutoAllocateItems_AllocationRulesEnabled_Groups_EndToEnd(
				groupMustAllocateWholeOrderLineBalance: true);

		void TestAutoAllocateItems_AllocationRulesEnabled_Groups_EndToEnd(bool groupMustAllocateWholeOrderLineBalance)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			var location = data.Whs1.DefaultLocation;
			var today = ZDateTimeOffset.Today;
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", today.AddDays(-2),
				data.Part1, 10m, location, "");
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", today.AddDays(-2),
				data.Part1, 5m, location, "");
			var receive3 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", today.AddDays(-1),
				data.Part1, 10m, location, "");
			var receive4 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", today.AddDays(-1),
				data.Part1, 10m, location, "");
			var receive5 =
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R5", today, data.Part1, 20m, location, "");
			Factory.Save();

			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			var rule = Factory.New<ProductionRule>();
			rule.PRL_PRS_RuleSet = ruleSet.PK;
			rule.PRL_Name = "RULE1";
			rule.PRL_Description = "RULE1";
			rule.PRL_Priority = 1;

			var groupMustAllocateWholeOrderLineBalanceString =
				groupMustAllocateWholeOrderLineBalance ? "true" : "false";
			rule.PRL_RuleDefinition = $@"{{
    ""conditions"": [
    ],
    ""action"": {{
        ""$type"": ""AllocateGroupStockActionState"",
        ""GroupByCriteria"": [
			""ArrivalDate"",
        ],
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""ArrivalDate"",
				""direction"": ""ascending""
			}}
        ],
		""groupMustAllocateWholeOrderLineBalance"": {groupMustAllocateWholeOrderLineBalanceString},
		""allocateCases"": true,
		""allocatePallets"": true,
		""allocateSplitCase"": true,
		""canBreakUOMs"": true,
    }}
}}";
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine3 =
				Helper.CreateWhsOrderLine(order, data.Part2, 10m); // Can't allocate, ensure it doesn't interfere.
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			var orderedInv = pick.OrderedInventories.Cast<WhsPickOrderedInventory>()
				.Single(ordInv => ordInv.ProductCode == data.Part1.OP_PartNum);
			var availInvs = orderedInv.AvailableInventories.Cast<WhsPickAvailableInventory>();
			var availInv1 = availInvs.Single(ai => ai.ArrivalDate == today.AddDays(-2));
			var availInv2 = availInvs.Single(ai => ai.ArrivalDate == today.AddDays(-1));
			var availInv3 = availInvs.Single(ai => ai.ArrivalDate == today);

			pick.AutoAllocateItems();

			if (groupMustAllocateWholeOrderLineBalance)
			{
				AssertEquals("Should *not* have picked available inventory 1.", 0m, availInv1.PickLineQuantity);
				AssertEquals("Should *not* have picked available inventory 3.", 0m, availInv3.PickLineQuantity);
				AssertEquals("Should have picked available inventory 2.", 20m, availInv2.PickLineQuantity);
			}
			else
			{
				AssertEquals("Should have picked available inventory 1.", 15m, availInv1.PickLineQuantity);
				AssertEquals("Should have picked available inventory 2.", 5m, availInv2.PickLineQuantity);
				AssertEquals("Should *not* have picked available inventory 3.", 0m, availInv3.PickLineQuantity);
			}
		}

