		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			var location1 = data.Whs1.FindLocation("A-1");
			var location2 = data.Whs1.FindLocation("A-2");

			var today = ZDateTimeOffset.Today;
			var receive1 =
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", today, data.Part1, 10m, location2, "");
			var receive2 =
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", today, data.Part2, 10m, location1, "");
			var receive3 =
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", today, data.Part2, 10m, location2, "");
			Factory.Save();

			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			var rule1 = CreateRule(ruleSet, "RULE1", "RULE1", 1);
			rule1.PRL_RuleDefinition = $@"{{
    ""conditions"": [
        {{
          ""fieldPath"": ""Product"",
          ""operation"": ""equals"",
          ""value"": ""{data.Part1.RelatedOrganisations.Single().PK}""
        }}
    ],
    ""action"": {{
        ""$type"": ""AllocateGroupStockActionState"",
        ""GroupByCriteria"": [
			""Location"",
        ],
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""Location.PickPathSequence"",
				""direction"": ""ascending""
			}}
        ],
		""groupMustAllocateWholeOrderLineBalance"": false,
		""allocateCases"": true,
		""allocatePallets"": true,
		""allocateSplitCase"": true,
		""canBreakUOMs"": true,
    }}
}}";

			var rule2 = CreateRule(ruleSet, "RULE2", "RULE2", 20);
			rule2.PRL_RuleDefinition = $@"{{
    ""conditions"": [
    ],
    ""action"": {{
        ""$type"": ""AllocateGroupStockActionState"",
        ""GroupByCriteria"": [
			""Location"",
        ],
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""Location.IsAllocatedOnThisPick"",
				""direction"": ""descending""
			}},
			{{
				""propertyPath"": ""Location.PickPathSequence"",
				""direction"": ""ascending""
			}}
        ],
		""groupMustAllocateWholeOrderLineBalance"": false,
		""allocateCases"": true,
		""allocatePallets"": true,
		""allocateSplitCase"": true,
		""canBreakUOMs"": true,
    }}
}}";
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);

			var orderedInvs = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var product1AvailInv = orderedInvs.Single(oi => oi.SupplierPartPK == data.Part1.PK).AvailableInventories[0];
			var product2AvailInvs = orderedInvs.Single(oi => oi.SupplierPartPK == data.Part2.PK).AvailableInventories
				.Cast<WhsPickAvailableInventory>();

			var product2AvailInvLocation1 = product2AvailInvs.Single(ai => ai.LocationPK == location1.PK);
			var product2AvailInvLocation2 = product2AvailInvs.Single(ai => ai.LocationPK == location2.PK);

			pick.AutoAllocateItems();

			CombineAssertions(() =>
			{
				AssertEquals("Should have picked product 1's available inventory.", 10m,
					product1AvailInv.PickLineQuantity);
				AssertEquals("Should *not* have picked product 2's available inventory 1.", 0m,
