			for (var index = 0; index < numberOfSerials; index++)
			{
				var line = Helper.CreateWhsReceiveLine(receive, data.Part1, 1m, data.Whs1.DefaultLocation, "PLT-1");
				line.WE_SerialNumber = "SN" + index;
			}

			receive.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive);
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");

			if (notOrderedFirst)
			{
				Helper.CreateWhsOrderLine(order, data.Part1, numberOfSerials);
			}

			for (var index = 0; index < numberOfSerials; index++)
			{
				var line = Helper.CreateWhsOrderLine(order, data.Part1, 1m);
				line.WE_SerialNumber = "SN" + index;
			}

			if (!notOrderedFirst)
			{
				Helper.CreateWhsOrderLine(order, data.Part1, numberOfSerials);
			}

			Factory.Save();

			var pick = Helper.CreatePickNew(finaliseOrders: false, finalisePick: false, checkPick: true, useAllocMock: false, order);
			AssertContainsExactElementsInAnyOrder(new[] { "SN0", "SN1", "SN2", "SN3", "SN4", "SN5", "SN6", "SN7", "SN8", "SN9", "" }, pick.OrderedInventories.Select(o => o.SerialNumber));
			CombineAssertions(() =>
			{
				AssertEquals("Should have committed 10 units.", 10m, pick.GetAllPickLines().Sum(pl => pl.WZ_Units));

				foreach (var orderedInventory in pick.OrderedInventories.Where(ordInv => !ordInv.SerialNumber.IsEmpty))
				{
					var availableInventory = (WhsPickAvailableInventory)orderedInventory.AvailableInventories.Single();
					AssertEquals("Available Inventory should match ordered Serial.", orderedInventory.SerialNumber, availableInventory.SerialNumber);
					AssertEquals("Available Inventory should be allocated.", 1m, availableInventory.PickLineQuantity);
				}
			});
		}

