		#region TestAutoAllocateItems_InvalidOrderCore

		void TestAutoAllocateItems_InvalidOrderCore(bool validCase)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			Factory.Save();

			var today = ZDateTimeOffset.Today;
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", today, data.Part1, 10m);
			Factory.Save();

			MakeActiveAllocationRuleSetInactive();

			var ruleSet = Factory.New<ProductionRuleSet>();
			ruleSet.PRS_Name = "Rules";
			ruleSet.PRS_Description = "Rules";
			ruleSet.PRS_Context = "PWA";
			ruleSet.PRS_IsLive = true;
			ruleSet.PRS_IsSystem = false;

			CreateRule(ruleSet, "RULE1", "RULE1", 1);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			pick.WP_IsAwaitingReplenishment = true;
			Factory.Save();

			if (validCase)
			{
				AssertAutoAllocateResult(false, "");
				AssertAutoAllocateResult(true, "");
			}
			else
			{
				order.WD_RequiredDate = ZDateTimeOffset.Empty;
				Factory.Save();

				AssertAutoAllocateResult(false,
					"Error occurred while loading data: Order No. O1 cannot be allocated, Required Date is not valid.");
				AssertAutoAllocateResult(true,
					"Error occurred while loading data: Order No. O1 cannot be allocated, Required Date is not valid.");
			}

			void AssertAutoAllocateResult(bool filterInventory, string errorMessage)
			{
				var pickInNewFactory = NewFactory().Load<WhsPick>(pick.PK);
				string result;
				if (filterInventory)
				{
					result = pickInNewFactory.AutoAllocateItems(ZDateTimeOffset.Empty);
				}
				else
				{
					result = pickInNewFactory.AutoAllocateItems();
				}

				AssertEquals("Should not have warning", "", result);
				var notifications = (NotificationBuffer)pickInNewFactory.NotificationSubscriber;
				if (string.IsNullOrEmpty(errorMessage))
				{
					AssertEquals(false, notifications.HasErrors);
					AssertEquals(false, notifications.Events.Length > 0);
				}
				else
				{
					AssertEquals(true, notifications.HasErrors);
					AssertEquals(errorMessage, notifications.Events[0].Message);
				}
			}
		}

		#endregion

		#region TestAutoAllocateItems_BOM_hasShortFallPickOnComponent

		public void TestAutoAllocateItems_BOM_DoTotalShortFallOnOneComponent_AutoAllocateItemsCorrectly()
		{
			using (WarehouseDataRegistry.Instance.EnableSchemaRedesignChanges.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var data = new TestDataSimpleEnvironment(Factory, 2, 1);
				var bike = Helper.CreateProduct(data.Org1, "BIKE");
				bike.OP_IsComponentPickedOnSalesOrder = true;

				var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
				var frame = Helper.CreateProduct(data.Org1, "FRAME");
				Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);
				Helper.CreateProductBOM(bike, frame, 1m, Constants.PkgUnit.Unit);

				var location1 = data.Whs1.FindLocation("A-1");
				var location2 = data.Whs1.FindLocation("A-2");

				var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 6m, location1, palletID: "");
				var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", frame, 3m, location2, palletID: "");

				Factory.Save();

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 3m);
				var pick = Helper.CreatePickNew(order);

				AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);

				var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
				var wheelPickLine1 = wheelOrderLine1.PickLines.Single();
				var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
				var framePickLine1 = frameOrderLine1.PickLines.Single();
				var kitPickLine1 = orderLine1.PickLines.Single();

				AssertEquals("Precondition: Kit receive inventory line transaction quantity should be correct.", 3m, kitPickLine1.InventoryLine.WE_TransactionQuantity);

				wheelPickLine1.InventoryLine.Delete();
				wheelPickLine1.Delete();
				receive1.Lines.DeleteAll();
				kitPickLine1.InventoryLine.Delete();
				kitPickLine1.Delete();

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
				pickInNewFactory.AutoAllocateItemsWithMock();
				var orderLineInNewFactory = pickInNewFactory.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After full shortfall of wheels, it should have correct shortfall quantity.", 3m, orderLineInNewFactory.WE_ShortfallQuantityCached);
				AssertEquals("After full shortfall of wheels, Kit receive inventory line transaction quantity should be 0.", 0, orderLineInNewFactory.PickLines.Count);

				var location3 = data.Whs1.FindLocation("A-3");
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", wheel, 6m, location3, palletID: "");
				Factory.Save();

				var newFactory1 = new BusinessObjectFactory();
				var pickInNewFactory1 = newFactory1.Load<WhsPick>(pick.PK);
				pickInNewFactory1.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory1 = pickInNewFactory1.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After allocating wheels, the shortfall quantity should be correct.", 0m, orderLineInNewFactory1.WE_ShortfallQuantityCached);
				AssertEquals("After allocating wheels, Kit receive inventory line transaction quantity should be 3.", 3m, orderLineInNewFactory1.PickLines[0].InventoryLine.WE_TransactionQuantity);

				var wheelQuantityOfBomPartLines = orderLineInNewFactory1.ChildComponentLines.Where(o => o.WE_OP == wheel.PK).Sum(p => p.WE_TransactionQuantity);
				AssertEquals("Component wheel will not be allocated more stock than actually needed.", 6m, wheelQuantityOfBomPartLines);
				AssertEquals("The main product will not be allocated more stock than actually needed.", 3m, orderLineInNewFactory1.PickLines.Sum(line => line.WZ_Units));
			}
		}

		public void TestAutoAllocateItems_BOM_DoPartialShortFallOnOneComponent_AutoAllocateItemsCorrectly()
		{
			using (WarehouseDataRegistry.Instance.EnableSchemaRedesignChanges.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var data = new TestDataSimpleEnvironment(Factory, 2, 1);
				var bike = Helper.CreateProduct(data.Org1, "BIKE");
				bike.OP_IsComponentPickedOnSalesOrder = true;

				var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
				var frame = Helper.CreateProduct(data.Org1, "FRAME");
				Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);
				Helper.CreateProductBOM(bike, frame, 1m, Constants.PkgUnit.Unit);

				var location1 = data.Whs1.FindLocation("A-1");
				var location2 = data.Whs1.FindLocation("A-2");
				var location3 = data.Whs1.FindLocation("A-3");

				var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 4m, location1, palletID: "");
				var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", wheel, 2m, location1, palletID: "");
				var receive3 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", frame, 3m, location2, palletID: "");
				Factory.Save();

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 5m);
				var pick = Helper.CreatePickNew(order);

				AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);
				AssertEquals("Pick shortfall Quantity should be correct.", 2m, orderLine1.WE_ShortfallQuantityCached);

				var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
				var wheelPickLine1 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 4m);
				var wheelPickLine2 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 2m);
				var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
				var framePickLine1 = frameOrderLine1.PickLines.Single();
				var kitPickLine1 = orderLine1.PickLines.Single();
				var kitReceiveLine = kitPickLine1.InventoryLine;

				AssertEquals("Precondition: Kit receive inventory line transaction quantity should be correct.", 3m, kitPickLine1.InventoryLine.WE_TransactionQuantity);

				DeletePickLineAndRecreateLinks(wheelPickLine1, wheelOrderLine1.PK, kitReceiveLine.PK, 4m);
				receive1.Lines.DeleteAll();
				kitReceiveLine.WE_TransactionQuantity = 1m;
				kitReceiveLine.WE_StockOnHand = 1m;
				kitPickLine1.WZ_Units = 1m;

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
				pickInNewFactory.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory = pickInNewFactory.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After partially shorting wheels, it should have the correct shortfall quantity.", 4m, orderLineInNewFactory.WE_ShortfallQuantityCached);
				AssertEquals("After partially shorting wheels, Kit receive inventory line transaction quantity should be 1.", 1m, orderLineInNewFactory.PickLines[0].InventoryLine.WE_TransactionQuantity);

				var location4 = data.Whs1.FindLocation("A-4");
				var location5 = data.Whs1.FindLocation("A-5");
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", wheel, 8m, location4, palletID: "");
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R5", frame, 2m, location5, palletID: "");
				Factory.Save();

				var newFactory1 = new BusinessObjectFactory();
				var pickInNewFactory1 = newFactory1.Load<WhsPick>(pick.PK);
				pickInNewFactory1.AutoAllocateItemsWithMock();
				newFactory1.Save();

				var orderLineInNewFactory1 = pickInNewFactory1.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After allocating wheels, the shortfall quantity should be correct.", 0m, orderLineInNewFactory1.WE_ShortfallQuantityCached);
				AssertEquals("After allocating wheels, Kit receive inventory line transaction quantity should be 5.", 5m, orderLineInNewFactory1.PickLines[0].InventoryLine.WE_TransactionQuantity);

				var wheelQuantityOfBomPartLines = orderLineInNewFactory1.ChildComponentLines.Where(o => o.WE_OP == wheel.PK).Sum(p => p.WE_TransactionQuantity);
				AssertEquals("Component wheel will not be allocated more stock than actually needed.", 10m, wheelQuantityOfBomPartLines);
				AssertEquals("The main product will not be allocated more stock than actually needed.", 5m, orderLineInNewFactory1.PickLines.Sum(line => line.WZ_Units));
			}
		}

