				var pick = Helper.CreatePickNew(order);

				AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);
				AssertEquals("The pick shortfall quantity should be correct.", 4m, orderLine1.WE_ShortfallQuantityCached);

				var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
				var wheelPickLine1 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 8m);
				var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
				var framePickLine1 = frameOrderLine1.PickLines.Single(pl => pl.WZ_Units == 4m);
				var kitPickLine1 = orderLine1.PickLines.Single();
				var kitReceiveLine = kitPickLine1.InventoryLine;

				AssertEquals("Precondition: Kit receive inventory line transaction quantity should be correct.", 6m, kitPickLine1.InventoryLine.WE_TransactionQuantity);

				DeletePickLineAndRecreateLinks(wheelPickLine1, wheelOrderLine1.PK, kitReceiveLine.PK, 8m);
				DeletePickLineAndRecreateLinks(framePickLine1, frameOrderLine1.PK, kitReceiveLine.PK, 4m);
