				pickInNewFactory.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory = pickInNewFactory.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After partially shorting wheels and frame, it should have the correct shortfall quantity.", 8m, orderLineInNewFactory.WE_ShortfallQuantityCached);
				AssertEquals("After partially shorting wheels and frame, Kit receive inventory line transaction quantity should be 2.", 2m, orderLineInNewFactory.PickLines[0].InventoryLine.WE_TransactionQuantity);

				var location5 = data.Whs1.FindLocation("A-5");
