				var orderLineInNewFactory1 = pickInNewFactory1.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After allocating wheels and frame, the shorfall quantity should be correct.", 0m, orderLineInNewFactory1.WE_ShortfallQuantityCached);
				AssertEquals("After allocating wheels and frame, Kit receive inventory line transaction quantity should be correct.", needMainProductStock ? 9m : 10m, orderLineInNewFactory1.PickLines[0].InventoryLine.WE_TransactionQuantity);
				AssertEquals("The Main product will not be allocated more stock than actually needed.", 10m, orderLineInNewFactory1.PickLines.Sum(line => line.WZ_Units));
