				Helper.CreateProductBOM(mainA, componentB, 3m, Constants.PkgUnit.Unit);

				var location1 = data.Whs1.FindLocation("A-1");
				var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", componentB, 3m, location1, palletID: "");

				Factory.Save();

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				var orderLine1 = Helper.CreateWhsOrderLine(order, mainA, 1m);
				var pick = Helper.CreatePickNew(order);

				AssertEquals("Precondition: component order lines created.", 1, orderLine1.ChildComponentLines.Count);

				var componentBOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == componentB.PK);
				var componentBPickLine1 = componentBOrderLine1.PickLines.Single();
				var kitPickLine1 = orderLine1.PickLines.Single();

				AssertEquals("Precondition: Kit receive inventory line transaction quantity should be correct.", 1m, kitPickLine1.InventoryLine.WE_TransactionQuantity);

				componentBPickLine1.InventoryLine.Delete();
				componentBPickLine1.Delete();
				receive1.Lines.DeleteAll();
				kitPickLine1.InventoryLine.Delete();
				kitPickLine1.Delete();

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
				pickInNewFactory.AutoAllocateItemsWithMock();
				var orderLineInNewFactory = pickInNewFactory.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After a full shortfall of components, it should have the correct shortfall quantity.", 1m, orderLineInNewFactory.WE_ShortfallQuantityCached);
				AssertEquals("After full shortfall of wheels, Kit receive inventory line transaction quantity should be 0.", 0, orderLineInNewFactory.PickLines.Count);

				var location2 = data.Whs1.FindLocation("A-2");
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", componentB, 2m, location2, palletID: "");
				Factory.Save();

				var newFactory1 = new BusinessObjectFactory();
				var pickInNewFactory1 = newFactory1.Load<WhsPick>(pick.PK);
				pickInNewFactory1.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory1 = pickInNewFactory1.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After allocating partial stock, the shortfall quantity should be correct.", 1m, orderLineInNewFactory1.WE_ShortfallQuantityCached);
				AssertEquals("After full shortfall of wheels, Kit receive inventory line transaction quantity should be 0.", 0, orderLineInNewFactory1.PickLines.Count);

				var location3 = data.Whs1.FindLocation("A-3");
				Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", componentB, 1m, location3, palletID: "");
				Factory.Save();

				var newFactory2 = new BusinessObjectFactory();
				var pickInNewFactory2 = newFactory2.Load<WhsPick>(pick.PK);
				pickInNewFactory2.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory2 = pickInNewFactory2.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("After allocating new stock, the shortfall quantity should be correct.", 0m, orderLineInNewFactory2.WE_ShortfallQuantityCached);
				AssertEquals("After allocating new stock, the Transaction quantity should be correct.", 1m, orderLineInNewFactory2.PickLines[0].InventoryLine.WE_TransactionQuantity);

				var componentBQuantityOfBomPartLines = orderLineInNewFactory2.ChildComponentLines.Where(o => o.WE_OP == componentB.PK).Sum(p => p.WE_TransactionQuantity);
				AssertEquals("Component will not be allocated more stock than actually needed.", 3m, componentBQuantityOfBomPartLines);
				AssertEquals("The main product will not be allocated more stock than actually needed.", 1m, orderLineInNewFactory2.PickLines.Sum(line => line.WZ_Units));
			}
		}

		public void TestAutoAllocateItems_BOM_DoPartialShortFallOnSomeComponent_ReceivePlentyComponentsStockAndMainProduct_AutoAllocateWithSerialNumber()
		{
			using (WarehouseDataRegistry.Instance.EnableSchemaRedesignChanges.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var data = new TestDataSimpleEnvironment(Factory, 2, 1);
				Helper.SetClientAttributeType(data.Org1, AttributeNumber.Serial, true);

				var bike = Helper.CreateProduct(data.Org1, "BIKE");
				bike.OP_IsComponentPickedOnSalesOrder = true;
				var wheel = Helper.CreateProduct(data.Org1, "WHEEL");
				var frame = Helper.CreateProduct(data.Org1, "FRAME");
