				Helper.SetProductAttributeUse(data.Org1, frame, AttributeNumber.Serial, true);
				Helper.CreateProductBOM(bike, wheel, 2m, Constants.PkgUnit.Unit);
				Helper.CreateProductBOM(bike, frame, 1m, Constants.PkgUnit.Unit);
				Factory.Save();

				var location1 = data.Whs1.FindLocation("A-1");
				var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", wheel, 2m, location1, "", true, false);
				receive1.Lines[0].WE_SerialNumber = "SN01";
				var sn1 = receive1.Lines[0].SerialNumbers.AddNew();
				sn1.SerialNumberValue = "SN1";
				var sn2 = receive1.Lines[0].SerialNumbers.AddNew();
				sn2.SerialNumberValue = "SN2";
				var location2 = data.Whs1.FindLocation("A-2");
				var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", frame, 1m, location2, "", true, false);
				receive2.Lines[0].WE_SerialNumber = "SN02";
				var sn3 = receive2.Lines[0].SerialNumbers.AddNew();
				sn3.SerialNumberValue = "SN3";
				receive1.FinaliseDocketWithoutUserConfirmation();
				AssertIsFinalisedPrecondition(receive1);
				receive2.FinaliseDocketWithoutUserConfirmation();
				AssertIsFinalisedPrecondition(receive2);
				Factory.Save();

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
				var orderLine1 = Helper.CreateWhsOrderLine(order, bike, 1m);
				var pick = Helper.CreatePickNew(order);

				AssertEquals("Precondition: component order lines created.", 2, orderLine1.ChildComponentLines.Count);

				var wheelOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == wheel.PK);
				var wheelPickLine1 = wheelOrderLine1.PickLines.Single(pl => pl.WZ_Units == 2m);
				var frameOrderLine1 = orderLine1.ChildComponentLines.Single(l => l.WE_OP == frame.PK);
				var framePickLine1 = frameOrderLine1.PickLines.Single(pl => pl.WZ_Units == 1m);
				var kitPickLine1 = orderLine1.PickLines.Single();
				var kitReceiveLine = kitPickLine1.InventoryLine;

				AssertEquals("Precondition: Kit receive inventory line transaction quantity should be correct.", 1m, kitPickLine1.InventoryLine.WE_TransactionQuantity);

				var newFactory = new BusinessObjectFactory();
				var pickInNewFactory = newFactory.Load<WhsPick>(pick.PK);
				pickInNewFactory.AutoAllocateItemsWithMock();
				newFactory.Save();

				var orderLineInNewFactory = pickInNewFactory.Orders[0].Lines.Cast<WhsPickableDocketLine>().Where(l => l.PK == orderLine1.PK).ToList()[0];
				AssertEquals("It should have the correct shortfall quantity.", 0m, orderLineInNewFactory.WE_ShortfallQuantityCached);
				AssertEquals("Kit receive inventory line transaction quantity should be 1.", 1m, orderLineInNewFactory.PickLines[0].InventoryLine.WE_TransactionQuantity);
			}
		}

