		public void TestConstraint_IsAwaitingReplenishment_PickType_Order() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.Created, expectConstraintException: false);
		public void TestConstraint_IsAwaitingReplenishment_PickType_HeldInventoryOrder_IsInvalid() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.HeldInventoryOrder, PickStatus.Codes.Created, expectConstraintException: true);
		public void TestConstraint_IsAwaitingReplenishment_PickType_WorkOrder() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.WorkOrder, PickStatus.Codes.Created, expectConstraintException: false);
		public void TestConstraint_IsAwaitingReplenishment_PickType_DynamicWorkOrder() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.DynamicWorkOrder, PickStatus.Codes.Created, expectConstraintException: false);

		public void TestConstraint_IsAwaitingReplenishment_PickStatus_Building() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.Building, expectConstraintException: false);
		public void TestConstraint_IsAwaitingReplenishment_PickStatus_Cancelled_IsInvalid() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.Cancelled, expectConstraintException: true);
		public void TestConstraint_IsAwaitingReplenishment_PickStatus_Created() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.Created, expectConstraintException: false);
		public void TestConstraint_IsAwaitingReplenishment_PickStatus_Finalised_IsInvalid() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.Finalised, expectConstraintException: true);
		public void TestConstraint_IsAwaitingReplenishment_PickStatus_PickSlip_IsInvalid() => TestConstraint_IsAwaitingReplenishment_Core(PickType.Codes.Order, PickStatus.Codes.PickSlip, expectConstraintException: true);

		void TestConstraint_IsAwaitingReplenishment_Core(string pickType, string pickStatus, bool expectConstraintException)
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pick = Factory.New<WhsPick>();
			pick.WP_PickType = pickType;
			pick.WP_PickStatus = pickStatus;

			if (pickStatus == PickStatus.Codes.Finalised)
			{
				pick.WP_FinalizedDateUtc = DateTime.UtcNow;
			}

			Factory.Save();

			if (expectConstraintException)
			{
				AssertExceptionThrown(typeof(SqlException), "The UPDATE statement conflicted with the CHECK constraint \"Constraint_WP_IsAwaitingReplenishment\".", SetIsAwaitingReplenishment, true);
			}
			else
			{
				AssertNoExceptionThrown(SetIsAwaitingReplenishment);
			}

			void SetIsAwaitingReplenishment() => CargoWise.Database.TestFramework.ObjectModel.WhsPick
				.UpdateWhere(p => p.PK == pick.PK.ToGuid())
				.Set(p => p.WP_IsAwaitingReplenishment, true)
				.Post(TestConnection);
		}

