		#region TestGetInventories_HeldInventoryOrder_ExcludePickFaces

		public void TestGetInventories_HeldInventoryOrder_ExcludePickfaces_IsHeldOrder() => TestGetInventories_HeldInventoryOrder_ExcludePickfaces_Core(isHeldInventoryOrder: true);
		public void TestGetInventories_HeldInventoryOrder_ExcludePickfaces_IsNotHeldOrder() => TestGetInventories_HeldInventoryOrder_ExcludePickfaces_Core(isHeldInventoryOrder: false);

		void TestGetInventories_HeldInventoryOrder_ExcludePickfaces_Core(bool isHeldInventoryOrder)
		{
			using (WarehouseDataRegistry.Instance.EnableHeldGoodsForOrders.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, isHeldInventoryOrder))
			{
				var today = ZDateTimeOffset.Today;
				var data = new TestDataSimpleEnvironment(Factory, 1, 3);

				var normalLocation = data.Whs1.FindLocation("A-1-1");

				var dynamicLocation = data.Whs1.FindLocation("A-1-2");
				var dynamicArea = Helper.CreateDynamicPF(data.Whs1, dynamicLocation);
				Factory.Save();

				var productParams = WhsProduct.GetWhsProduct(data.Part1).ParamsByWhsAndClient.AddNew();
				productParams.W3_OH = data.Org1.PK;
				productParams.W3_WW = data.Whs1.PK;
				productParams.W3_WA_DynamicPickFaceArea = dynamicArea.PK;

				var fixedLocation = data.Whs1.FindLocation("A-1-3");
				Helper.CreateProductPickFace(data.Part1, data.Org1, fixedLocation);
				Factory.Save();

				var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
				var receiveLine1 = Helper.CreateWhsReceiveLine(receive, data.Part1, 10m, normalLocation, "");
				var receiveLine2 = Helper.CreateWhsReceiveLine(receive, data.Part1, 10m, dynamicLocation, "");
				var receiveLine3 = Helper.CreateWhsReceiveLine(receive, data.Part1, 10m, fixedLocation, "");
				receive.FinaliseDocketWithoutUserConfirmation();
				AssertIsFinalisedPrecondition(receive);
				Factory.Save();

				if (isHeldInventoryOrder)
				{
					// Damage the goods in warehouse
					receiveLine1.HeldCodeToChangeTo = InventoryHoldCodes.Codes.Damaged;
					receiveLine2.HeldCodeToChangeTo = InventoryHoldCodes.Codes.Damaged;
					receiveLine3.HeldCodeToChangeTo = InventoryHoldCodes.Codes.Damaged;
					receiveLine1.ChangeInventoryHeldCode(true);
					receiveLine2.ChangeInventoryHeldCode(true);
					receiveLine3.ChangeInventoryHeldCode(true);
					Factory.Save();
				}

				var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Manual);
				var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 30m, "");
				if (isHeldInventoryOrder)
				{
					orderLine1.WE_WHC_NKOrderedHeldCode = InventoryHoldCodes.Codes.Damaged;
				}
				var pick = Helper.CreatePickNew(order);
				Factory.Save();

				var orderedInventory = pick.OrderedInventories[0];
				if (isHeldInventoryOrder)
				{
					AssertEquals("Held Inventory Orders exclude Pickface locations", 1, orderedInventory.AvailableInventories.Count);
					AssertEquals("Held Inventory Orders exclude Pickface locations", normalLocation.PK, orderedInventory.AvailableInventories[0].LocationPK);
				}
				else
				{
					AssertEquals("Available Inventory Orders include Pickface locations", 3, orderedInventory.AvailableInventories.Count);
				}
			}
		}

