		protected override BusinessObject GetNewBusinessObjectForDeleteTest(BusinessObjectFactory factory)
		{
			var pick = (WhsPick)base.GetNewBusinessObjectForDeleteTest(factory);
			pick.Transfers
				.DeleteAll(); // We don't want to do this in release code as it should not be possible to delete a pick when it has transfers.

			return pick;
		}

		WhsPickLine FindPickLine(WhsPick pick, ZGuid prod)
		{
			foreach (var line in pick.GetAllPickLines())
			{
				var inventory = line.Inventory;
				if (inventory.WI_OP == prod)
				{
					return line;
				}
			}
			return null;
		}

		WhsInventoryView FindInvLine(WhsReceive receive, ZGuid prod, ZGuid locn)
		{
			foreach (WhsInventoryView inv in receive.Inventory)
			{
				if (inv.WI_OP == prod && inv.WI_WL == locn)
				{
					return inv;
				}
			}
			return null;
		}

