		void AssertIsDPSFreightMovementRestricted_MultipleOrders(bool enableComplianceRisk)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 5m);
			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 5m);
			var pick = Helper.CreatePickNew(order1, order2);
			Factory.Save();

			var testCases = new[]
			{
				(ScreeningStatusesList.Codes.PermanentClear, false),
				(ScreeningStatusesList.Codes.Clear, false),
				(ScreeningStatusesList.Codes.JobCleared, false),
				(ScreeningStatusesList.Codes.Unknown, true),
				(ScreeningStatusesList.Codes.NotScreened, true),
				(ScreeningStatusesList.Codes.Matched, true),
			};

			using (FreightDataRegistry.Instance.FreightEnableComplianceWise.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty,
				ComplianceWiseRegistryHelper.SetValue(enableComplianceRisk)))
			using (RawDataRegistry.Instance.EnableComplianceRisk.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, enableComplianceRisk))
			using (OrganisationsDataRegistry.Instance.DPSFreightMovementRestrictions.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, DPSFreightMovementRestrictionsOptions.Codes.All))
			{
				CombineAssertions(() =>
				{
					foreach (var (screeningStatus, expected) in testCases)
					{
						order1.WD_ScreeningStatus = screeningStatus;
						order2.WD_ScreeningStatus = ScreeningStatusesList.Codes.Clear;

						var restricted = ((ICreditControlledDocumentDelivery)pick).IsDPSFreightMovementRestricted;

						AssertEquals($"Restriction for status {screeningStatus} should be {expected}", expected, restricted);
					}
				});
			}
		}

