		ProductionRule CreateRule(
			ProductionRuleSet ruleSet,
			string name,
			string description,
			short priority,
			bool canPickSplitCase = true)
		{
			var rule = Factory.New<ProductionRule>();
			rule.PRL_PRS_RuleSet = ruleSet.PK;
			rule.PRL_Name = name;
			rule.PRL_Description = description;
			rule.PRL_Priority = priority;

			var splitCaseString = canPickSplitCase ? "true" : "false";
			rule.PRL_RuleDefinition = $@"{{
    ""conditions"": [
    ],
    ""action"": {{
        ""$type"": ""AllocateStockActionState"",
        ""conditions"": [
        ],
        ""sortByCriteria"": [
			{{
				""propertyPath"": ""ArrivalDate"",
				""direction"": ""descending""
			}}
        ],
		""allocateCases"": true,
		""allocatePallets"": true,
		""allocateSplitCase"": {splitCaseString},
		""canBreakUOMs"": true,
    }}
}}";

			return rule;
		}

		void MakeActiveAllocationRuleSetInactive()
		{
			var query = new ZQuery(ProductionRuleSetSchema.PRS_Context, "PWA");
			query.AddToFilter(ProductionRuleSetSchema.PRS_IsLive, true);

			var ruleSet = Factory.LoadTop1<ProductionRuleSet>(query);
			if (ruleSet != null)
			{
				ruleSet.PRS_IsLive = false;
			}
		}

