		public void TestITaskPlanningJob_GetCannotUpdateTaskPlanningStatusReason_Finalised()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 20m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 20m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();
			AssertNullOrEmptyOrWhitespace(pick.WP_TaskPlanningStatus);

			pick.WP_TaskPlanningStatus = TaskPlanningStatus.Codes.Ready;
			AssertEquals(TaskPlanningStatus.Codes.Ready, pick.WP_TaskPlanningStatus);
			pick.FinaliseAllOrders();
			pick.FinalisePick();
			Factory.Save();

			var job = (ITaskPlanningJob)pick;
			AssertEquals(true, job.IsFinalisedOrCancelled);
			AssertEquals("Cannot change Task Planning Status as the Pick is finalized or canceled.", job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: true));
			AssertEquals("Cannot change Task Planning Status as the Pick is finalized or canceled.", job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: false));
		}

		public void TestITaskPlanningJob_GetCannotUpdateTaskPlanningStatusReason_Cancelled()
		{
			var pick = Factory.New<WhsPick>();
			Factory.Save();

			var job = (ITaskPlanningJob)pick;
			AssertEquals(string.Empty, job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: true));
			AssertEquals(string.Empty, job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: false));

			pick.CancelPick();
			Factory.Save();

			AssertEquals(true, job.IsFinalisedOrCancelled);
			AssertEquals("Cannot change Task Planning Status as the Pick is finalized or canceled.", job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: true));
			AssertEquals("Cannot change Task Planning Status as the Pick is finalized or canceled.", job.GetCannotUpdateTaskPlanningStatusReason(changeStatusToReady: false));
		}

