		#region TestAllocationLog

		[TestDate(2025, 4, 4, 11, 11, 11)]
		public void TestAllocationLog_AutoAllocate()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var receive1 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 15m);
			var receive2 = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", data.Part2, 15m);
			receive1.Lines[0].WE_AllocationKey = "ABC";
			receive2.Lines[0].WE_AllocationKey = "DEF";

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			order.WD_PickOption = WhsPickOption.Codes.Manual;
			var orderLine1 = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			var orderLine2 = Helper.CreateWhsOrderLine(order, data.Part2, 10m);
			orderLine1.WE_AllocationKey = "ABC";
			orderLine2.WE_AllocationKey = "DEF";
			var currentTime = data.Whs1.GetWarehouseBranchDateTimeOffset(ZDateTime.UtcNow).ToString("[yyyy-MM-dd HH:mm:ss]");
			Factory.Save();

			var pick = Helper.CreatePickNew(order);
			var orderedInvs = pick.OrderedInventories.Cast<WhsPickOrderedInventory>();
			var orderedInventory1 = orderedInvs.Single(inv => inv.SupplierPartPK == data.Part1.PK);
			var availableInventory1 = orderedInventory1.AvailableInventories[0];

			var orderedInventory2 = orderedInvs.Single(inv => inv.SupplierPartPK == data.Part2.PK);
			var availableInventory2 = orderedInventory2.AvailableInventories[0];

			var result1 = new AllocationResultFact(
				Guid.NewGuid(),
				"Ruler1",
				null,
				orderLine1.PK.ToGuid(),
				orderedInventory1.PK.ToGuid(),
				availableInventory1.PK.ToGuid(),
				6m);

			var result2 = new AllocationResultFact(
				Guid.NewGuid(),
				"Ruler2",
				null,
				orderLine2.PK.ToGuid(),
				orderedInventory2.PK.ToGuid(),
				availableInventory2.PK.ToGuid(),
				8m);

			var processor = new AllocationResultProcessor();
			var processedResult = processor.ProcessResults(pick, new[] { result1, result2 });
			AssertEquals("6 Units allocated from Rule: Ruler1" + System.Environment.NewLine, availableInventory1.AllocationLog);
			AssertEquals("8 Units allocated from Rule: Ruler2" + System.Environment.NewLine, availableInventory2.AllocationLog);

			var allocationLog = pick.Notes.FindByDescription(PredefinedNoteTypes.Instance.AllocationLog.Description).SingleOrDefault();
			AssertNull(allocationLog);

			pick.WP_SystemLastEditTimeUtc = DateTime.UtcNow;
			Factory.Save();
			AssertNullOrEmpty("non persist allocation logs should be clear after Saving.", availableInventory1.AllocationLog);
			AssertNullOrEmpty("non persist allocation logs should be clear after Saving.", availableInventory2.AllocationLog);

			allocationLog = pick.Notes.FindByDescription(PredefinedNoteTypes.Instance.AllocationLog.Description).SingleOrDefault();
			var expectedAllocationLogText = string.Format(@"{0}:
Inventory Info:Client:111, Product:P1, Location:A-1, Arrival Date:{1}, Inventory Status:AVL, Allocation Key:ABC
6 Units allocated from Rule: Ruler1
Inventory Info:Client:111, Product:P2, Location:A-2, Arrival Date:{2}, Inventory Status:AVL, Allocation Key:DEF
8 Units allocated from Rule: Ruler2", currentTime, availableInventory1.Inventory[0].WI_ArrivalDate.ToString("[yyyy-MM-dd HH:mm:ss]"), availableInventory2.Inventory[0].WI_ArrivalDate.ToString("[yyyy-MM-dd HH:mm:ss]"));
			AssertEquals("Allocation Log Notes should created and recorded the allocation logs", expectedAllocationLogText, allocationLog.ST_NoteText);
		}

