			AssertEquals("Allocation Log Notes should created and recorded the allocation logs", expectedAllocationLogText1, allocationLog.ST_NoteText);

			availableInventory = pick.OrderedInventories[0].AvailableInventories[0];
			availableInventory.PickLineQuantity = 8m;
			AssertEquals("3 Units manually allocated by user" + System.Environment.NewLine, availableInventory.AllocationLog);
			availableInventory.PickLineQuantity = 3m;
			AssertEquals(@"3 Units manually allocated by user
5 Units manually deallocated by user" + System.Environment.NewLine, availableInventory.AllocationLog);

			pick.WP_SystemLastEditTimeUtc = DateTime.UtcNow;
			Factory.Save();
			AssertNullOrEmpty("non persist allocation logs should be clear after Saving.", availableInventory.AllocationLog);

			var expectedAllocationLogText2 = string.Format(@"{0}:
Inventory Info:Client:111, Product:P1, Location:A-1, Arrival Date:{1}, Inventory Status:AVL, Allocation Key:ABC
5 Units manually allocated by user

{0}:
Inventory Info:Client:111, Product:P1, Location:A-1, Arrival Date:{1}, Inventory Status:AVL, Allocation Key:ABC
3 Units manually allocated by user
5 Units manually deallocated by user", currentTime, availableInventory.Inventory[0].WI_ArrivalDate.ToString("[yyyy-MM-dd HH:mm:ss]"));
			AssertEquals("Allocation Log Notes should created and recorded the allocation logs", expectedAllocationLogText2, allocationLog.ST_NoteText);
		}

