	#region WhsPickMOPTest

	public class WhsPickMOPTest : WhsTestCaseWithFactory
	{
		#region TestCreatePickOrdersAreNull

		[ExpectException(typeof(ArgumentException))]
		public void TestCreatePickOrdersAreNull()
		{
			Pick.CreatePick_OBSOLETE(null);
		}

		#endregion

		#region TestValidateOrdersBelongToOneWarehouse

		public void TestValidateOrdersBelongToOneWarehouse()
		{
			WhsReceive receive1 = CreateSimpleInventoryWithAssertion(Client1, Whs1, Part1, 100m);

			WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 10m);
			WhsOrder order2 = CreateSimpleOrder(Client1, Whs2, Part1, 20m);
			WhsOrder order3 = CreateSimpleOrder(Client1, Whs1, Part1, 20m);
			Factory.Save();

			Pick.CreatePick_OBSOLETE(order1, order2);
			Assert("Error - Picking across warehouse",
				Pick.RowErrors.ContainsNotificationContaining("The orders you have selected belong to more than one warehouse"));
			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1, order3 });
			}
			Assert("No Error",
				!Pick.RowErrors.ContainsNotificationContaining(
					"The orders you have selected to pick belong to more than one warehouse"));
		}

		#endregion

		#region TestValidateAtleastThereIsOneOrderToPick

		public void TestValidateAtleastThereIsOneOrderToPick()
		{
			Pick.CreatePick_OBSOLETE(Array.Empty<WhsPickableDocket>());
			Assert("Error - No Orders selected to pick",
				Pick.RowErrors.ContainsNotificationContaining("At least one order must be selected to pick."));

			WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 10m);
			Factory.Save();

			bool exceptionThrown = false;
			try
			{
				using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
				{
					Pick.CreatePick_OBSOLETE(new WhsPickableDocket[1] { order1 });
				}
			}
			catch (PickFailedException)
			{
				exceptionThrown = true;
			}
			Assert("No Error", !Pick.RowErrors.ContainsNotificationContaining("At least one order must be selected to pick."));
			AssertEquals("Exception not thrown", true, exceptionThrown);
		}

		#endregion

		#region TestValidatePickIsNotCancelledOrFinalised

		public void TestValidatePickIsNotCancelledOrFinalised()
		{
			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 10m);
				Factory.Save();

				Pick.WP_PickStatus = PickStatus.Codes.Finalised;
				Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1 });
				Assert("Error - Pick Finalised",
					Pick.RowErrors.ContainsNotificationContaining("This pick is either Finalized or Canceled."));

				Pick.WP_PickStatus = PickStatus.Codes.Cancelled;
				Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1 });
				Assert("Error - Pick Cancelled",
					Pick.RowErrors.ContainsNotificationContaining("This pick is either Finalized or Canceled."));

				Pick.WP_PickStatus = PickStatus.Codes.Created;
				bool exceptionThrown = false;
				try
				{
					Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1 });
				}
				catch (PickFailedException)
				{
					exceptionThrown = true;
				}
				Assert("No Error",
					!Pick.RowErrors.ContainsNotificationContaining("This pick is either Finalized or Canceled."));
				AssertEquals("Exception not thrown", true, exceptionThrown);
			}
		}

		#endregion

		#region TestAnyErrorPickShouldNotCreateSuccessfully

		public void TestAnyErrorPickShouldNotCreateSuccessfully()
		{
			WhsReceive receive1 = CreateSimpleInventoryWithAssertion(Client1, Whs1, Part1, 100m);
			WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 10m);
			WhsOrder order2 = CreateSimpleOrder(Client1, Whs2, Part1, 20m);

			Factory.Save();

			Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1, order2 });
			AssertEquals("Pick should have errors", true, Pick.HasErrors);
			AssertEquals("Order1 should not be IsPicking", false, order1.IsAttachedToPickButNotFinalised);
			AssertEquals("Order2 should not be IsPicking", false, order2.IsAttachedToPickButNotFinalised);

			using (ObjectFactory.Substitute<IAllocationEngineManager>(new AllocateFIFOLegacyMock()))
			{
				Pick.CreatePick_OBSOLETE(new WhsPickableDocket[] { order1 });
			}
			AssertEquals("Pick should not have error", false, Pick.HasErrors);
			AssertEquals("Order1 should be IsPicking", true, order1.IsAttachedToPickButNotFinalised);
		}

		#endregion

