		#region TestPickWithMultipleClients

		public void TestPickWithMultipleClients()
		{
			Factory.Save(); // save data created in SetUp... ewww...

			// Purposely swapped the order so that there is chance of picking stock of wrong client
			WhsReceive receiveForClient2 = CreateSimpleInventoryWithAssertion(Client2, Whs1, Part1, 100m);
			WhsReceive receiveForClient1 = CreateSimpleInventoryWithAssertion(Client1, Whs1, Part1, 100m);
			AssertEquals("Assert Placed Loc", "BA-2", receiveForClient1.Inventory[0].LocationString);
			AssertEquals("Assert Placed Loc", "BA-1", receiveForClient2.Inventory[0].LocationString);

			WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 20m);
			WhsOrder order2 = CreateSimpleOrder(Client1, Whs1, Part1, 30m);
			Factory.Save();

			Pick.PickOrdersWithAllocationMock(new WhsPickableDocket[] { order1, order2 });

			Assert("Order1 Status - Picking", order1.IsAttachedToPickButNotFinalised);
			Assert("Order2 Status - Picking", order2.IsAttachedToPickButNotFinalised);
			AssertEquals("Pick Status - Picking", PickStatus.Codes.Created, Pick.WP_PickStatus);

			AssertEquals("Pick's Committed Units", 50m,
				receiveForClient1.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("No Stock Removed By Pick", 100m, receiveForClient1.Inventory[0].WI_TotalUnits);

			AssertEquals("Diff Client - No Commit By Pick", 0m,
				receiveForClient2.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Diff Client - Inventory Untouched", 100m, receiveForClient2.Inventory[0].WI_TotalUnits);
		}

