			AssertEquals("Assert Placed Loc", "AA-1", receiveForWhs2.Inventory[0].LocationString);

			WhsOrder order1 = CreateSimpleOrder(Client1, Whs1, Part1, 20m);
			WhsOrder order2 = CreateSimpleOrder(Client1, Whs1, Part1, 30m);
			Factory.Save();

			CreatePickWithAssertion(Pick, new WhsPickableDocket[] { order1, order2 });

			AssertEquals("Pick's Committed Units", 50m,
				receiveForWhs1.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("No Stock Removed By Pick", 100m, receiveForWhs1.Inventory[0].WI_TotalUnits);

			AssertEquals("Diff Whs - Nothing Should Happen", 0m,
				receiveForWhs2.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Diff Whs - Nothing Should Happen", 100m, receiveForWhs2.Inventory[0].WI_TotalUnits);

			CancelPickWithAssertion(Pick);

			AssertEquals("Cancel Pick should Uncommit Stock", 0m,
				receiveForWhs1.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("No Stock Removed By Pick", 100m, receiveForWhs1.Inventory[0].WI_TotalUnits);

			AssertEquals("Diff Whs - Nothing Should Happen", 0m,
				receiveForWhs2.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);
			AssertEquals("Diff Whs - Nothing Should Happen", 100m, receiveForWhs2.Inventory[0].WI_TotalUnits);
		}

