		#region Implementation

		void CreatePickWithAssertion(WhsPick pick, WhsPickableDocket[] ordersToPick)
		{
			pick.PickOrdersWithAllocationMock(ordersToPick);
			foreach (WhsPickableDocket order in ordersToPick)
			{
				Assert("Order Status - Picking", order.IsAttachedToPickButNotFinalised);
			}
			AssertEquals("Pick Status - Picking", PickStatus.Codes.Created, pick.WP_PickStatus);
		}

		void CancelPickWithAssertion(WhsPick pick)
		{
			pick.CancelPick();
			foreach (WhsPickableDocket order in pick.Orders)
			{
				AssertEquals("Order Status - Entered", DocketStatus.Codes.Entered, order.WD_DocketStatus);
			}
			AssertEquals("Pick Status - Cancelled", PickStatus.Codes.Cancelled, pick.WP_PickStatus);
		}

		void FinalisePickWithAssertion(WhsPick pick)
		{
			foreach (WhsPickableDocket order in pick.Orders)
			{
				order.FinaliseDocket();
			}
			pick.FinalisePick();

			foreach (WhsPickableDocket order in pick.Orders)
			{
				Assert("Order should be finalised", order.IsFinalised);
			}
			Assert("Pick should be finalised", pick.IsFinalised);
		}

		WhsReceive CreateSimpleInventoryWithAssertion(OrgHeader client, WhsWarehouse whs, OrgSupplierPart part, decimal units)
		{
			WhsReceive receive = Helper.CreateWhsReceive(client, whs, GetRandomReference(), Notify);
			Helper.CreateWhsReceiveInventoryLine(receive, part, units);

			receive.AllocateLocationsWithMock();
			receive.FinaliseDocket();

			Assert("Check Receive Finalised", receive.IsFinalised);
			AssertEquals("Check Inventory", units, receive.Inventory[0].WI_TotalUnits);
			AssertEquals("Check Committed Units ", 0m, receive.Inventory[0].CommittedQuantityIncludingUnfinalisedReceipt);

			return receive;
		}

		WhsOrder CreateSimpleOrder(OrgHeader client, WhsWarehouse whs, OrgSupplierPart part, decimal units)
		{
			WhsOrder order = Helper.CreateWhsOrder(client, whs, GetRandomReference(), Notify);
			WhsOrderLine line = Helper.CreateWhsOrderLine(order, part, units);
			return order;
		}

		string GetRandomReference()
		{
			return ZGuid.NewZGuid().ToString().Substring(0, 35);
		}

