		void TestPrintPackageLabels_ForWorkOrderShowsErrorMessage(Func<TestDataSimpleEnvironment, WhsComponentOrder> createComponentOrder)
		{
			const string PackageLabelsMenuItemName = "Package Labels";

			var data = new TestDataSimpleEnvironment(Factory);
			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(createComponentOrder(data));

			var docEvents = new MockDocumentEventSource();
			pick.DocumentSupporter.Initialise(docEvents);

			var menuItem = Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch, PackageLabelsMenuItemName));
			var args = new DocumentCancelEventArgs(menuItem);

			AssertEquals("Precondition", false, args.Cancel);
			docEvents.FireDocumentPrintRequested(args);

			AssertEquals("WorkOrders does not support printing Package Labels, e.Cancel should be true.", true, args.Cancel);
			AssertEquals("Work Orders do not require Package Labels.", UnitTestUserNotification.Instance.LastMessage.Text);
		}

