		#region TestGetDocumentWrappers_ForPickShortfallItemsDataContext

		public void TestGetDocumentWrappers_ForPickShortfallItemsDataContext()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory(true);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order);

			var docSupporter = pick.DocumentSupporter;
			AssertEquals("Precondition", true, pick.HasShortfallItems);
			var wrappersWithShortfall = docSupporter.GetDocumentWrappers(Constants.DataContext.WhsPickShortfallItems, null);
			AssertEquals("DocWhsPick", wrappersWithShortfall[0].GetType().Name);
			AssertEquals(pick, wrappersWithShortfall[0].WrappedObject);

			pick.AutoAllocateItemsWithMock();
			AssertEquals("Precondition", false, pick.HasShortfallItems);
			var wrappersNoShortfall = docSupporter.GetDocumentWrappers(Constants.DataContext.WhsPickShortfallItems, null);
			AssertNull(wrappersNoShortfall);
		}

