		#region TestIDocumentEvents_DocumentPrinted

		public void TestIDocumentEvents_DocumentPrinted()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.None;
			Helper.CreateWhsOrderLine(order, data.Part1, 5);
			var pick = Helper.CreatePickNew(order);
			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultOutboundDockDoor;

			var supporter = new WhsPickDocumentSupporter(pick);
			var eventSource = new MockDocumentEventSource();
			supporter.Initialise(eventSource);

			// legacy picking slip
			AssertEquals("Pre-condition:", false, pick.IsPickSlipPrinted);
			var queryLegacy = new DocumentZQuery(BusinessContext.WhsDespatch, "Picking Slip");
			queryLegacy.AddToFilter(StmMenuItemSchema.SU_MenuPath, SQLComparisonOperator.Contains, "Legacy");
			var legacyPickingSlipCommand = Factory.LoadTop1<DocumentCommand>(queryLegacy);
			var argsLegacy = new DocumentPrintedEventArgs(DeliveryInstructionDestination.None, legacyPickingSlipCommand);
			eventSource.FireDocumentPrinted(argsLegacy);
			AssertEquals("After printed Legacy Picking Slip, Pick status should be Pick Slip Printed.", true,
				pick.IsPickSlipPrinted);

			// picking slip
			pick.WP_PickStatus = PickStatus.Codes.Created;
			AssertEquals("Pre-condition:", false, pick.IsPickSlipPrinted);
			var query = new DocumentZQuery(BusinessContext.WhsDespatch, "Picking Slip");
			query.AddToFilter(StmMenuItemSchema.SU_MenuPath, SQLComparisonOperator.NotContains, "Legacy");
			var pickingSlipCommand = Factory.LoadTop1<DocumentCommand>(query);
			var args = new DocumentPrintedEventArgs(DeliveryInstructionDestination.None, pickingSlipCommand);
			eventSource.FireDocumentPrinted(args);
			AssertEquals("After printed Picking Slip, Pick status should be Pick Slip Printed", true, pick.IsPickSlipPrinted);
		}

		public void TestIDocumentEvents_DocumentPrinted_PrintAllDocument()
		{
			var data = new TestDataForInventory(Factory);
			data.CreateSimpleInventory();
			Factory.Save();

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "Order Ref #1");
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			Helper.CreateWhsOrderLine(order, data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);

			var packingHelper = new PackingTestHelper(Factory);
			var package1 = packingHelper.CreatePackage(order.PackageJob, "PKG1", 1, "BOX");
			var package2 = packingHelper.CreatePackage(order.PackageJob, "PKG2", 1, "BOX");
			AssertEquals(false, package1.IsLabelPrinted);
			AssertEquals(false, package2.IsLabelPrinted);
			var picklines = pick.GetAllPickLines().ToList();
			packingHelper.CreatePackageDivot(package1, picklines[0]);
			packingHelper.CreatePackageDivot(package2, picklines[1]);

			Factory.Save();

			var supporter = new WhsPickDocumentSupporter(pick);
			var eventSource = new MockDocumentEventSource();
			supporter.Initialise(eventSource);

			var commond = PackageLabelsHelper.GetDocCommandInNewReadOnlyFactory();
			var args = new DocumentPrintedEventArgs(DeliveryInstructionDestination.None, commond);
			eventSource.FireDocumentPrinted(args);

			foreach (var package in pick.OuterPackages)
			{
				AssertEquals(true, package.IsLabelPrinted);
			}
		}

		public void TestIDocumentEvents_DocumentPrinted_SavesChanges()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();
			AssertEquals("Precondition", 10m, pick.GetAllPickLines().Sum(pl => pl.WZ_Units));
			AssertEquals("Precondition", PickStatus.Codes.Created, pick.WP_PickStatus);
			AssertEquals("Precondition", false, pick.IsPickSlipPrinted);

			var pickingSlipQuery = new ZQuery();
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuName, "Picking Slip");
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuPath, ""); // get new document, not legacy

			var menuItem = Factory.LoadTop1<DocumentCommand>(pickingSlipQuery);
			var args = new DocumentPrintedEventArgs(DeliveryInstructionDestination.TakenFromContact, menuItem);

			var documentEvents = new MockDocumentEventSource();
			pick.DocumentSupporter.Initialise(documentEvents);
			documentEvents.FireDocumentPrinted(args);
			AssertEquals("Should have changed status of pick.", true, pick.IsPickSlipPrinted);

			var otherFactory2 = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInOtherFactory2 = otherFactory2.Load<WhsPick>(pick.PK);
			AssertEquals("Changes to pick should have been saved.", true, pickInOtherFactory2.IsPickSlipPrinted);
		}

		public void TestIDocumentEvents_DocumentPrinted_WithErrors()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();
			AssertEquals("Precondition", 10m, pick.GetAllPickLines().Sum(pl => pl.WZ_Units));
			AssertEquals("Precondition", PickStatus.Codes.Created, pick.WP_PickStatus);
			AssertEquals("Precondition", false, pick.IsPickSlipPrinted);

			var pickingSlipQuery = new ZQuery();
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuName, "Picking Slip");
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuPath, ""); // get new document, not legacy

			var menuItem = Factory.LoadTop1<DocumentCommand>(pickingSlipQuery);
			var args = new DocumentPrintedEventArgs(DeliveryInstructionDestination.TakenFromContact, menuItem);

			// simulate validation error of some sort to ensure it prevents save
			pick.WP_PickStatusInfo.ValueChanged += (o, e) =>
			{
				pick.AddRowError("Some Error");
			};

			var documentEvents = new MockDocumentEventSource();
			pick.DocumentSupporter.Initialise(documentEvents);
			documentEvents.FireDocumentPrinted(args);
			AssertEquals("Should have changed status of pick.", true, pick.IsPickSlipPrinted);
			AssertEquals("Should have reported problem to user.", true, UnitTestUserNotification.Instance.LastMessage.Text.Contains("Some Error"));

			var otherFactory2 = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInOtherFactory2 = otherFactory2.Load<WhsPick>(pick.PK);
			AssertEquals("Changes to pick should NOT have been saved due to error.", false, pickInOtherFactory2.IsPickSlipPrinted);
		}

