		public void TestIDocumentEvents_PickSlipPrinted_AwaitingReplenishment_DoesNotUpdatePickStatus()
		{
			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var pickFaceLocation = data.Whs1.FindLocation("A-1");
			var bulkLocation = data.Whs1.FindLocation("A-2");
			Helper.CreateProductPickFace(data.Part1, data.Org1, pickFaceLocation);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m, bulkLocation, "");
			Factory.Save();

			var transfer = Helper.CreateWhsTransfer(data.Org1, data.Whs1);
			var transferLine = Helper.CreateWhsTransferLine(transfer, data.Part1, 10m, bulkLocation, pickFaceLocation);
			transferLine.RunPreSaveValidation();
			Factory.Save();
			AssertEquals("Precondition", false, transfer.IsFinalised);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 10m);
			Factory.Save();

			var pick = Factory.New<WhsPick>();
			pick.UpdatePickStatusIfRequired(true);
			pick.PickOrdersWithAllocationMock(order, saveFactory: false);
			AssertEquals("Precondition: pick is waiting replenishment.", true, pick.WP_IsAwaitingReplenishment);
			AssertEquals("Precondition: pick has 'NEW'(Created) status.", PickStatus.Codes.Created, pick.WP_PickStatus);
			Factory.Save();

			var pickingSlipQuery = new ZQuery();
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuName, "Picking Slip");
			pickingSlipQuery.AddToFilter(StmMenuItemSchema.SU_MenuPath, ""); // get new document, not legacy

			var menuItem = Factory.LoadTop1<DocumentCommand>(pickingSlipQuery);
			var args = new DocumentPrintedEventArgs(DeliveryInstructionDestination.TakenFromContact, menuItem);

			UnitTestUserNotification.Instance.ClearMessages();

			var documentEvents = new MockDocumentEventSource();
			pick.DocumentSupporter.Initialise(documentEvents);
			AssertNoExceptionThrown(() => documentEvents.FireDocumentPrinted(args));
			AssertEquals("There should have been no errors", true, UnitTestUserNotification.Instance.LastMessage.WasNone);
			AssertEquals("Should not have changed status of pick.", false, pick.IsPickSlipPrinted);

			var otherFactory2 = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInOtherFactory2 = otherFactory2.Load<WhsPick>(pick.PK);
			AssertEquals("Should not have changed status of pick.", false, pickInOtherFactory2.IsPickSlipPrinted);
		}

