		public void TestGetContactOrganisationIfNoCurrentOrder()
		{
			var client = Helper.CreateClient();
			var consignee = Helper.CreateClient();
			var transportCo = Helper.CreateClient();

			var order1 = Factory.New<WhsOrder>();
			var order2 = Factory.New<WhsOrder>();

			order1.WD_OH_Client = client.PK;
			order1.ConsigneePK = consignee.PK;
			order1.TransportCoPK = transportCo.PK;
			order1.Lines.AddNew();
			order2.WD_OH_Client = client.PK;
			order2.Lines.AddNew();

			var pick = Factory.New<WhsPick>();
			pick.Orders.Add(order1);
			pick.Orders.Add(order2);

			var contact =
				pick.DocumentSupporter.GetContactOrganisation(ZString.Empty, ContactType.Warehouse3PL, DocumentDirection.ANY);
			AssertNull(pick.CurrentPickableDocket);
			AssertEquals("Orders count should be bigger than 0", 2, pick.Orders.Count);
			AssertEquals("The contact should pulling from Order1 client", order1.Client.PK, contact.OrgHeader.PK);
			AssertEquals("The contact related organization should be Order1 consignee", order1.Consignee.PK,
				contact.RelatedOrgHeader.PK);

			contact = pick.DocumentSupporter.GetContactOrganisation("Cartage Advice", ContactType.Warehouse3PL,
				DocumentDirection.ANY);
			AssertEquals("The contact should pulling from Order1 TransportCo", order1.TransportCoPK, contact.OrgHeader.PK);
			AssertEquals("The contact related organization should be Order1 consignee", order1.Consignee.PK,
				contact.RelatedOrgHeader.PK);
		}

		public void TestGetContactOrganisationIfCurrentOrder()
		{
			var client = Helper.CreateClient();
			var consignee = Helper.CreateClient();
			var transportCo = Helper.CreateClient();

			var order1 = Factory.New<WhsOrder>();
			order1.WD_OH_Client = client.PK;
			order1.ConsigneePK = consignee.PK;
			order1.TransportCoPK = transportCo.PK;
			order1.Lines.AddNew();

			var pick = Factory.New<WhsPick>();
			order1.WD_WP = pick.PK;

			var contact =
				pick.DocumentSupporter.GetContactOrganisation(ZString.Empty, ContactType.Warehouse3PL, DocumentDirection.ANY);
			AssertEquals("The contact should be the client", pick.CurrentPickableDocket.Client.PK, contact.OrgHeader.PK);
			AssertEquals("The contact related organization should be the consignee", pick.CurrentOrder.Consignee.PK,
				contact.RelatedOrgHeader.PK);

			contact = pick.DocumentSupporter.GetContactOrganisation("Cartage Advice", ContactType.Warehouse3PL,
				DocumentDirection.ANY);
			AssertEquals("The contact should be the TransportCo", pick.CurrentPickableDocket.TransportCoPK,
				contact.OrgHeader.PK);
			AssertEquals("The contact related organization should be the consignee", pick.CurrentOrder.Consignee.PK,
				contact.RelatedOrgHeader.PK);
		}

