			var pickingShortfallAndNonPicked =
				Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch,
					"Picking Shortfall And Non Picked Items"));
			var pickingShortfall =
				Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch,
					"Picking Shortfall items"));
			var nonPickedItems =
				Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch, "Non Picked Items"));
			var pickOrderSummary =
				Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch, "Pick Order Summary"));

			var supporter = new WhsPickDocumentSupporter(pick);
			var eventSource = new MockDocumentEventSource();
			supporter.Initialise(eventSource);

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(pickingShortfallAndNonPicked));
			AssertNull(UnitTestUserNotification.Instance.LastMessage.Text);

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(pickingShortfall));
			AssertNull(UnitTestUserNotification.Instance.LastMessage.Text);

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(nonPickedItems));
			AssertNull(UnitTestUserNotification.Instance.LastMessage.Text);

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(documentsPack));
			AssertEquals("Pick Documents Pack cannot be printed until Fulfillment Rules are met or overridden.",
				UnitTestUserNotification.Instance.LastMessage.Text);
			UnitTestUserNotification.Instance.ClearMessagesAndAnswers();

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(pickingSlip));
			AssertEquals("Picking Slip cannot be printed until Fulfillment Rules are met or overridden.",
				UnitTestUserNotification.Instance.LastMessage.Text);

			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(pickOrderSummary));
			AssertEquals("Pick Order Summary cannot be printed until Fulfillment Rules are met or overridden.",
				UnitTestUserNotification.Instance.LastMessage.Text);
		}

