		#region TestDocumentsWithFulfillmentRule_PickSlipCanBePrintedWhenUserManuallyDeallocatesThenReAllocatesStock

		public void TestDocumentsWithFulfillmentRule_PickSlipCanBePrintedWhenUserManuallyDeallocatesThenReAllocatesStock()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m, WhsPickOption.Codes.ManualWithAutoAllocate);
			order.WD_WhsOrderFulfillmentRule = WhsOrderFulfillmentRuleList.Codes.All;

			var pick = Helper.CreatePickNew(order);
			var orderedInventory = pick.OrderedInventories[0];
			pick.ClearAllocatedItems();
			AssertEquals("Precondition: OrderedInventory is in shortfall.", 10m, orderedInventory.QuantityShort);

			pick.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			AssertEquals("Precondition: OrderedInventory is not in shortfall.", 0m, orderedInventory.QuantityShort);
			Factory.Save(); // need to save to update Pick Status

			var documentSupporter = new WhsPickDocumentSupporter(pick);
			var eventSource = new MockDocumentEventSource();
			documentSupporter.Initialise(eventSource);

			var pickingSlip = Factory.LoadTop1<DocumentCommand>(new DocumentZQuery(BusinessContext.WhsDespatch, "Picking Slip"));
			eventSource.FireDocumentPrintRequested(new DocumentCancelEventArgs(pickingSlip));
			AssertEquals("Order is not in shortfall, should not display error message.", true, UnitTestUserNotification.Instance.LastMessage.WasNone);
		}

