		#region TestWhsPickDocumentSupporter

		public void TestWhsPickDocumentSupporter()
		{
			var assertions = new List<Action>();
			var pick = Factory.New<WhsPick>();
			var supporter = new WhsPickDocumentSupporter(pick);
			foreach (DataContext dataContext in Enum.GetValues(typeof(DataContext)))
			{
				var documentWrappers = supporter.GetDocumentWrappers(dataContext, null);
				if (documentWrappers != null && !(documentWrappers.Length > 0))
				{
					assertions.Add(() => AssertEquals(
						$"Should returns a reason when attempt to print without underlying data. (DataContext: {dataContext})"
						, false,
						string.IsNullOrEmpty(
							supporter.GetBODocDataProvidersNotFoundMessage(new DataContextValue(dataContext.ToString()), null))));
				}
			}
			CombineAssertions(() => assertions.ForEach(assertion => assertion()));
		}

		#endregion

