		void AssertGetBODocDataProvidersNotFoundMessageReturnOneReasonCore(TestDataForInventory data, string reasonMessage,
			DataContext dataContext)
		{
			var pick = Factory.New<WhsPick>();
			var supporter = new WhsPickDocumentSupporter(pick);
			var documentWrapper = supporter.GetDocumentWrappers(dataContext, null);
			var notFoundMessage =
				supporter.GetBODocDataProvidersNotFoundMessage(new DataContextValue(dataContext.ToString()), null);
			AssertEquals($"Should returns a reason when attempt to print without underlying data. (DataContext: {dataContext})",
				reasonMessage, notFoundMessage);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1);
			pick.Orders.Add(order);
			notFoundMessage = supporter.GetBODocDataProvidersNotFoundMessage(new DataContextValue(dataContext.ToString()), null);
