	#region WhsPickWorkflowProviderTest

	[TestedType(typeof(WhsPick))]
	public class WhsPickWorkflowProviderTest : WorkflowProviderTest<WhsPick, WhsPickProcessTaskCollection>
	{
		#region TestGetTemplateFilterCriteria_SingleOrderPick

		public void TestGetTemplateFilterCriteria_SingleOrderPick() => TestGetTemplateFilterCriteria_SingleOrderPick_Core((client, whs) => Helper.CreateWhsOrder(client, whs));

		public void TestGetTemplateFilterCriteria_WorkOrder() => TestGetTemplateFilterCriteria_SingleOrderPick_Core((client, whs) => Helper.CreateWhsWorkOrder(client, whs));

		void TestGetTemplateFilterCriteria_SingleOrderPick_Core(Func<OrgHeader, WhsWarehouse, WhsPickableDocket> createPickableDocket)
		{
			var whs1 = Helper.CreateWarehouse("Wh1");
			var whs2 = Helper.CreateWarehouse("Wh2");
			var client1 = Helper.CreateClient("Cl1");
			var client2 = Helper.CreateClient("Cl2");

			var pick = BusinessObject;
			var pickableDocket = createPickableDocket(client1, whs1);
			pick.Orders.Add(pickableDocket);
			Factory.Save();

			// Client
			AssertGetTemplateFilterCriteria(pickableDocket.WD_OH_ClientInfo, ProcessTaskTemplate.P0_OH_ClientInfo, client1.PK, client2.PK, ZGuid.Empty);

			// Cannot test Whs by changing the Pick alone with AssertGetTemplateFilterCriteria as it would hit a concurrency check
			// Run similar checks manually
			ProcessTaskTemplate.P0_WW = whs1.PK;
			Factory.Save();

			var workflowProvider = (IWorkflowProvider)pick;
			workflowProvider.WorkflowItems.Tasks.RemoveAndDeleteAll();
			AssertEquals("Precondition: Workflow Items reset.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should have created workflow items as the Whs matches.", 1, workflowProvider.WorkflowItems.Tasks.Count);

			pick.WP_WW_Whs = whs2.PK;
			workflowProvider.WorkflowItems.Tasks.RemoveAndDeleteAll();
			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should *not* have created workflow items as the Whs does *not* match.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			pick.WP_WW_Whs = whs1.PK; // Prevent concurrency check save failure (whs must match orders)
			ProcessTaskTemplate.P0_OH_Client = ZGuid.Empty;
			Factory.Save();
			AssertEquals("Should have created Workflow Items as the template did not specify a warehouse.", 1, workflowProvider.WorkflowItems.Tasks.Count);
		}

		#endregion

		#region TestGetTemplateFilterCriteria_MultiOrderPick_SingleClient

		public void TestGetTemplateFilterCriteria_MultiOrderPick_SingleClient()
		{
			var whs1 = Helper.CreateWarehouse("Wh1");
			var client1 = Helper.CreateClient("Cl1");
			var client2 = Helper.CreateClient("Cl2");

			var pick = BusinessObject;
			var order1 = Helper.CreateWhsOrder(client1, whs1, "O1");
			var order2 = Helper.CreateWhsOrder(client1, whs1, "O2");
			pick.Orders.Add(order1);
			pick.Orders.Add(order2);
			Factory.Save();

			AssertGetTemplateFilterCriteria(
				(clientPK) =>
				{
					order1.WD_OH_Client = clientPK;
					order2.WD_OH_Client = clientPK;
				},
				ProcessTaskTemplate.P0_OH_ClientInfo, client1.PK, client2.PK, ZGuid.Empty);
		}

		#endregion

		#region TestGetTemplateFilterCriteria_MultiOrderPick_MultiClient

		public void TestGetTemplateFilterCriteria_MultiOrderPick_MultiClient()
		{
			var whs1 = Helper.CreateWarehouse("Wh1");
			var client1 = Helper.CreateClient("Cl1");
			var client2 = Helper.CreateClient("Cl2");

			var pick = BusinessObject;
			var order1 = Helper.CreateWhsOrder(client1, whs1, "O1");
			var order2 = Helper.CreateWhsOrder(client2, whs1, "O2");

			var processTaskTemplate = Factory.NewWithValidTestData<ProcessTaskTemplate>();
			processTaskTemplate.P0_ProcessType = ExpectedWorkflowType;
			processTaskTemplate.WorkflowItems.AddNew();
			processTaskTemplate.P0_OH_Client = client1.PK;
			Factory.Save();

			var workflowProvider = (IWorkflowProvider)pick;
			AssertEquals("Precondition: No Workflow Items.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should not have created Workflow Items as the pick has no client.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			pick.Orders.AddRange(new[] { order1, order2 });
			Factory.Save();
			workflowProvider.WorkflowItems.Tasks.RemoveAndDeleteAll();
			AssertEquals("Precondition: No Workflow Items.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should not have created Workflow Items as the pick has multiple clients.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			processTaskTemplate.P0_OH_Client = client2.PK;
			Factory.Save();
			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should not have created Workflow Items as the pick has multiple clients.", 0, workflowProvider.WorkflowItems.Tasks.Count);

			processTaskTemplate.P0_OH_Client = ZGuid.Empty;
			Factory.Save();
			workflowProvider.WorkflowItems.Tasks.CreateItemsFromTemplate();
			AssertEquals("Should have created Workflow Items as the pick has multiple clients.", 1, workflowProvider.WorkflowItems.Tasks.Count);
		}

		#endregion

