	#region TestConcurrencyProblems

	public class TestConcurrencyProblems : TestCase
	{
		#region TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTaken

		[UseSnapshotProtection]
		public void TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTaken()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "1", data.Part1, 10m);
			Factory.Save();

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 5m);
			var pick = Helper.CreatePickNew(order);
			Factory.Save();

			var mutex = new ZGlobalMutex(MutexIDs.WhsPickAllocatingPackageLabels, pick.PK.ToString());
			mutex.Lock();

			using (mutex)
			using (Db.DisposableActionForDbConnection())
			using (var connectionForSecondUser = Db.NewExtraConnectionToMainDb())
			{
				var factory2 = new BusinessObjectFactory(connectionForSecondUser) { RefreshEnabled = false };
				var pickInOtherFactory = factory2.Load<WhsPick>(pick.PK);
				pickInOtherFactory.WP_PickOption = WhsPickOption.Codes.ManualWithAutoAllocate;
				Helper.AssertZCannotSaveExceptionThrown("This Pick is in the process of having Package Labels allocated in another instance. Reload the Pick to make changes", factory2.Save);
			}
		}

		[UseSnapshotProtection]
		public void TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTaken_ChangeToNotRelatedTable()
		{
			// ensure that saving some unrelated changes does not take lock.
#pragma warning disable CW1198 // Do Not Use Logs.AddNew() With Audit Events Rule.
			TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTakenCore(p => p.Logs.AddNew(Events.EditedARecord)); // add log to pick;
#pragma warning restore CW1198 // Do Not Use Logs.AddNew() With Audit Events Rule.
		}

		[UseSnapshotProtection]
		public void TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTaken_ChangeToNotRelatedFields()
		{
			// ensure that saving some unrelated changes does not take lock.
			TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTakenCore(p => p.WP_PercentageComplete = 20); // add some unrelated changes to pick;
		}

		void TestOnFactorySaving_AttemptToSaveWhileIsCartonisingLockTakenCore(Action<WhsPick> changeThatShouldNotBeBlocked)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickByAttachingOrders(order);
			Factory.Save();
			AssertEquals("Precondition", pick.GetAllPickLines().Count(), 0);

			WhsTestHelperFunctions.DisablePageLocks(Db.Connection);

			Exception exception = null;
			var secondOperatorThread = new Thread(() =>
			{
				try
				{
					using (Db.DisposableActionForDbConnection())
					using (var connectionForUser2 = Db.NewExtraConnectionToMainDb())
					{
						var otherFactory2 = new BusinessObjectFactory(connectionForUser2) { RefreshEnabled = false };
						var pickInOtherFactory2 = otherFactory2.Load<WhsPick>(pick.PK);
						pickInOtherFactory2.AutoAllocateItemsWithMock(); // change related pick data to cause lock

						try
						{
							otherFactory2.Save();
						}
						catch (Exception ex)
						{
							exception = ex;
						}
					}
				}
				catch
				{
					// to prevent CW1 from crashing
				}
			});

			var secondThreadWasBlocked = true;
			using (Db.DisposableActionForDbConnection())
			using (var connectionForUser1 = Db.NewExtraConnectionToMainDb())
			{
				var otherFactory1 = new BusinessObjectFactory(connectionForUser1) { RefreshEnabled = false };
				var pickInOtherFactory1 = otherFactory1.Load<WhsPick>(pick.PK);
				changeThatShouldNotBeBlocked(pickInOtherFactory1);

				EventHandler runSecondThread = (s, e) =>
				{
					secondOperatorThread.Start();
					secondThreadWasBlocked = !secondOperatorThread.Join(5000); // wait and ensure that second thread is not blocked (true if ended within 5 seconds, i.e. not blocked).
				};

				otherFactory1.ServiceContainer.AddAfterOnSavingService(new DummyAfterOnSavingBOProcessingService(otherFactory1, (bisOs) => runSecondThread(this, EventArgs.Empty)));

				try
				{
					otherFactory1.Save(); // pass the critical part and run second thread
					otherFactory1.ServiceContainer.RemoveAfterOnSavingService<DummyAfterOnSavingBOProcessingService>();
				}
				catch (Exception ex)
				{
					exception = ex;
				}
			}
			AssertNull("Both threads should save with no issues and no blocking.", exception);
			AssertEquals("First thread should not take any locks, as it only saves logs.", false, secondThreadWasBlocked);
		}

