		void TestCanNotAddUnPickedPickLinesToFinalisedPickCore<T>(DbConnection connection, BusinessObjectFactory factory,
			WhsTestHelperFunctions helper, Func<OrgHeader, WhsWarehouse, OrgSupplierPart, ZDecimal, T> createPickableDocket)
			where T : WhsPickableDocket
		{
			var data = new TestDataSimpleEnvironment(factory, 2, 1);
			var bomComponentProduct1 = helper.CreateProduct(data.Org1, "BOM1");
			var bomPartForMainProduct1 = helper.CreateProductBOM(data.Part1, bomComponentProduct1, 2m, Constants.PkgUnit.Unit);
			helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 5m);
			helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R2", bomComponentProduct1, 10m);
			factory.Save();

			var finalisedPickableDocket = createPickableDocket(data.Org1, data.Whs1, data.Part1, 10m);
			var finalisedPick = helper.CreatePickNew(finalisedPickableDocket);
			finalisedPick.WP_WL_DockDoor = data.Whs1.WW_DefaultOutboundDockDoor;
			finalisedPick.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 5m;
			var pickLine = finalisedPick.GetAllPickLines().Single();

			finalisedPick.FinaliseAllOrders();
			factory.Save();
			WhsTestCaseWithFactory.AssertIsFinalisedPrecondition(finalisedPickableDocket);
			AssertEquals("Precondition.", false, finalisedPick.IsFinalised);

			pickLine.WZ_PickedDateTime = ZDateTimeOffset.Today;
			pickLine.WZ_GS_NKAssignedTo = "E";

			// testing a specific case for the trigger, so mock out creation of in-transit transfers
			using (OutboundDockDoorHelper.MockOutboundDockDoorCreator())
			{
				AssertNoExceptionThrown("Precondition: Should be allowed to change PickedDateTime.", factory.Save);
			}

			connection.ExecuteNonQuery(
				"DISABLE TRIGGER TG_WhsPickLine_PreventCriticalFieldChangeWhenLineIsFinalized ON WhsPickLine"); // This test relies on a bad datashape

			// It is not valid to un-pick a Pick Line but for the sake of testing the trigger we will do so.
			var pickLineRow = ((IBusinessObjectInternals)pickLine).Row;
			pickLineRow[WhsPickLineSchema.Constants.WZ_PickedDateTime] = DBNull.Value;
			pickLine.HasChanges = true;
			pickLine.InventoryLine.WE_StockOnHand += pickLine.WZ_Units; // increase stock back simulating an un-pick
			AssertNoExceptionThrown("Should be allowed to clear PickedDateTime.", factory.Save);

			finalisedPick.FinalisePick();
			WhsTestCaseWithFactory.AssertIsFinalisedPrecondition(finalisedPick);
			AssertEquals("Precondition.", false, pickLine.WZ_PickedDateTime.IsEmpty);
			factory.Save();

			// change below will trigger 3 triggers, suspend 2 check procedure to test other fails.
			WhsTestHelperFunctions.SuspendDatabaseProcForTest($"{WhsValidationHelper.WhsCheckStockOnHandIsBalanced} (@InventoryPKsToCheck dbo.TVP_uniqueidentifier READONLY)", "0", connection);
			WhsTestHelperFunctions.SuspendDatabaseProcForTest($"{WhsValidationHelper.WhsCheckPickLinesAreNotOverCommitting} (@InventoryPKs dbo.TVP_uniqueidentifier READONLY)", "0", connection);

			// It is not valid to un-pick a Pick Line but for the sake of testing the trigger we will attempt to clear the existing pick line's Picked time.
			NUnit.Framework.Assert.That(() =>
				{
					using (connection.BeginTransactionWithManager())
					{
						CargoWise.Database.TestFramework.ObjectModel.WhsPickLine.UpdateWhere(pickLine.PK.ToGuid()).Set(l => l.WZ_PickedDateTime, null).AsSQL();
						connection.ExecuteNonQuery(WhsPickLineDO.UpdateWhere(pickLine.PK.ToGuid()).Set(l => l.WZ_PickedDateTime, null).AsSQL());
					}
				}, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), "Attempt to save unpicked PickLines that are attached to a Finalised Job.", true), "Should have thrown an exception.");

			// It is not valid to change the Pick Time once it is saved, but we need to revert the Picked Time to a valid one so we use the row setter.
			pickLineRow[WhsPickLineSchema.Constants.WZ_PickedDateTime] = DateTimeOffset.UtcNow;
			AssertNoExceptionThrown(factory.Save);
			// Try adding another Pick line with no picked time set
			var receive2 = helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R3", data.Part1, 5m);
			helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R4", bomComponentProduct1, 10m);
			factory.Save();

			NUnit.Framework.Assert.That(() =>
				{
					using (connection.BeginTransactionWithManager())
					{
						connection.ExecuteNonQuery($@"
INSERT dbo.WhsPickLine (WZ_PK, WZ_F3_NKAllocatedPackType, WZ_GS_NKAssignedTo, WZ_IsPicking, WZ_OriginalReservedQty, WZ_PickedDateTime, WZ_Units, WZ_VerifiedEmpty, WZ_WE_InventoryLine, WZ_WE_TransactionLine, WZ_SystemCreateTimeUtc, WZ_SystemCreateUser, WZ_SystemLastEditTimeUtc, WZ_SystemLastEditUser) VALUES
(NewID(), '{pickLine.WZ_F3_NKAllocatedPackType}', '{pickLine.WZ_GS_NKAssignedTo}',
0, {pickLine.WZ_OriginalReservedQty}, NULL,
{pickLine.WZ_Units}, '{pickLine.WZ_VerifiedEmpty}', '{receive2.Lines[0].PK}', '{pickLine.WZ_WE_TransactionLine}', GetUtcDate(), '~BP', GetUtcDate(), '~BP')
");
					}
				}, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), "Attempt to save unpicked PickLines that are attached to a Finalised Job.", true), "Should have thrown an exception.");

			AssertNoExceptionThrown(factory.Save);

			var unfinalisedPickableDocket = createPickableDocket(data.Org1, data.Whs1, data.Part1, 5m);
			unfinalisedPickableDocket.WD_ExternalReference = "2";
			var unfinalisedPick = helper.CreatePickNew(unfinalisedPickableDocket);
			unfinalisedPick.WP_WL_DockDoor = data.Whs1.WW_DefaultOutboundDockDoor;
			factory.Save();

			var pickLineOnOtherDocket = unfinalisedPick.GetAllPickLines().First();
			NUnit.Framework.Assert.That(() =>
				{
					using (connection.BeginTransactionWithManager())
					{
						connection.ExecuteNonQuery(WhsPickLineDO.UpdateWhere(pickLineOnOtherDocket.PK.ToGuid())
								.Set(l => l.WZ_WE_TransactionLine, finalisedPickableDocket.AllLines
								.Single(l => l.PickLines.Count > 0).PK.ToSqlParameter())
								.AsSQL());
					}
				}, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), "Attempt to save unpicked PickLines that are attached to a Finalised Job.", true), "Should have thrown an exception.");

			pickLineOnOtherDocket.WZ_WE_TransactionLine = unfinalisedPick.OrderedInventories[0].Owners[0].PK;
			AssertNoExceptionThrown(factory.Save);
		}

