		#region TestLockIsWorkingWithPickLineChangeOnFinalisedPick

		[UseSnapshotProtection]
		[ExpectNoExceptions]
		public void TestLockIsWorkingWithPickLineChangeOnFinalisedPick()
		{
			using (var conn1 = Db.NewExtraConnectionToMainDb())
			using (var conn2 = Db.NewExtraConnectionToMainDb())
			{
				var factory = new BusinessObjectFactory(conn1) { RefreshEnabled = false };
				var helper = new WhsTestHelperFunctions(factory);
				var data = new TestDataSimpleEnvironment(factory);
				var receive = helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 20m);
				factory.Save();

				var order1 = helper.CreateWhsOrder(data.Org1, data.Whs1, "O1");
				var orderLine1 = helper.CreateWhsOrderLine(order1, data.Part1, 10m);
				var pick1 = helper.CreatePickNew(order1);
				var pickLine1 = pick1.GetAllPickLines().Single();
				pickLine1.WZ_Units = 5m;

				var order2 = helper.CreateWhsOrder(data.Org1, data.Whs1, "O2");
				var orderLine2 = helper.CreateWhsOrderLine(order2, data.Part1, 10m);
				var pick2 = helper.CreatePickNew(order2);
				var pickLine2 = pick2.GetAllPickLines().First();
				pickLine2.WZ_Units = 5m;
				factory.Save();

				conn1.BeginTransaction();
				conn2.BeginTransaction();

				using (var command2 =
					conn2.Command(WhsPickLineDO.UpdateWhere(pickLine2.PK.ToGuid()).Set(l => l.WZ_WE_TransactionLine, orderLine1.PK.ToSqlParameter()).AsSQL()))
				{
					bool command2IsInTransaction = false;
					bool addingUnpickedPickLinePrevented = false;

					var task = new Task(() =>
					{
						command2IsInTransaction = true;
						NUnit.Framework.Assert.That(delegate
						{
							command2.ExecuteNonQuery();
						}, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), "Attempt to save unpicked PickLines that are attached to a Finalised Job.", true), "Should have thrown an exception.");
						addingUnpickedPickLinePrevented = true;
					});

					pick1.FinaliseAllOrders();
					pick1.FinalisePick();
					WhsTestCaseWithFactory.AssertIsFinalisedPrecondition(pick1);
					factory.Save();

					task.Start();
					Thread.Sleep(5000);
					AssertEquals("SQL Command to Pick the PickLine the should have executed.", true, command2IsInTransaction);
					AssertEquals("SQL Command to Pick the PickLine should be blocked by the SQL Lock.", false,
						addingUnpickedPickLinePrevented);

					conn1.CommitTransaction();
					task.Wait();
					AssertEquals("SQL Command to add the PickLine should have finished and been prevented by the Trigger.", true,
						addingUnpickedPickLinePrevented);
				}
			}
		}

		#endregion

		#region TestLockIsWorkingWithPickWarehouseChange

		[UseSnapshotProtection]
		[ExpectNoExceptions]
		public void TestLockIsWorkingWithPickWarehouseChange()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var differentWarehouse = Helper.CreateWarehouse("W2", "Z", 1, 1);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 1m);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 1m);
			var pick = Helper.CreatePickNew();
			pick.WP_WW_Whs = data.Whs1.PK;
			pick.WP_PickOption = WhsPickOption.Codes.Auto;
			Factory.Save();
			AssertEquals("Pick should be in Database", true, pick.IsInDatabase);

			((IDbConnected)Factory).Connection.BeginTransaction();
			pick.WP_WW_Whs = differentWarehouse.PK;
			Factory.Save();

			bool isSecondUserLocked = false;
			bool threwException = false;
			var task = Task.Factory.StartNew(() =>
			{
				using (Db.DisposableActionForDbConnection())
				using (var connectionForSecondUser = Db.NewExtraConnectionToMainDb())
				{
					var secondFactory = new BusinessObjectFactory(connectionForSecondUser) { RefreshEnabled = false };
					var pickInSecondFactory = secondFactory.Load<WhsPick>(pick.PK);
					var orderInSecondFactory = secondFactory.Load<WhsOrder>(order.PK);

					connectionForSecondUser.BeginTransaction();
					isSecondUserLocked = true;
					try
					{
						pickInSecondFactory.Orders.Add(orderInSecondFactory);
						pickInSecondFactory.SetConcurrencyPolicy(WhsPickSchema.Constants.WP_WW_Whs, ConcurrencyPolicy.Ignore);
						pickInSecondFactory.SetConcurrencyPolicy(WhsPickSchema.Constants.WP_WL_DockDoor, ConcurrencyPolicy.Ignore);
						NUnit.Framework.Assert.That(delegate
						{
							secondFactory.Save();
						}, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), "Order / Work Order warehouse does not match Pick warehouse."), "Since the pick has order from other warehouse, exception should be thrown.");
						isSecondUserLocked = false;
					}
					catch (Exception)
					{
						threwException = true;
					}
					finally
					{
						connectionForSecondUser.RollbackTransaction();
					}
				}
			});

			Thread.Sleep(5000);
			AssertEquals("Should not have thrown exception, should have been waiting for first transaction to complete.", false,
				threwException);
			AssertEquals("Second user should be currently locked.", true, isSecondUserLocked);
			AssertEquals(true, (Factory as IDbConnected).Connection.IsInTransaction);

			((IDbConnected)Factory).Connection.CommitTransaction();
			task.Wait();
			AssertEquals("Should not have thrown exception, should have been waiting for first transaction to complete.", false,
				threwException);
			AssertEquals("Second user should not be locked anymore.", false, isSecondUserLocked);
			AssertEquals(false, (Factory as IDbConnected).Connection.IsInTransaction);
		}

		#endregion

