		#region TestDeadLock_PickingSameInventoryMultiplePicksWithSameDDL

		[UseSnapshotProtection]
		public void TestDeadLock_PickingSameInventoryMultiplePicksWithSameDDL()
		{
			// ensure our test service is first in list to be run
			var service = new AfterSaveInTransactionService_ForTesting(Factory);
			Factory.ServiceContainer.AddAfterSaveInTransactionService(service);

			var data = new TestDataSimpleEnvironment(Factory, 2, 1);
			var receive = Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 100m);
			Factory.Save();

			var order1 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick1 = Helper.CreatePickNew(order1);
			var pickLine1 = pick1.GetAllPickLines().Single();

			var order2 = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O2", data.Part1, 10m);
			var pick2 = Helper.CreatePickNew(order2);
			var pickLine2 = pick2.GetAllPickLines().Single();
			Factory.Save();

			WhsTestHelperFunctions.DisablePageLocks(Db.Connection);

			// change below will create imbalance in 2 places, suspend one check procedure to test other fails.
			WhsTestHelperFunctions.SuspendDatabaseProcForTest($"{WhsValidationHelper.WhsCheckStockOnHandIsBalanced} (@InventoryPKsToCheck dbo.TVP_uniqueidentifier READONLY)", "0");

			Exception exception = null;
			var secondOperatorThread = new Thread(() =>
			{
				using (Db.DisposableActionForDbConnection())
				using (var connectionForSecondUser = Db.NewExtraConnectionToMainDb())
				{
					var otherFactory = new BusinessObjectFactory(connectionForSecondUser) { RefreshEnabled = false };
					var pick2InOtherFactory = otherFactory.Load<WhsPick>(pick2.PK);

					pick2InOtherFactory.GetAllPickLines().Single().WZ_PickedDateTime = ZDateTimeOffset.Today;
					try
					{
						otherFactory.Save();
					}
					catch (Exception ex)
					{
						exception = ex;
					}
				}
			});

			service.BeforeFinalCheck_ForTesting += (o, e) =>
			{
				secondOperatorThread.Start();
				Thread.Sleep(5000); // give time for the second thread apply its own locks and to get locked on the first thread locks
			};

			pickLine1.WZ_PickedDateTime = ZDateTimeOffset.Now;
			Factory.Save();
			secondOperatorThread.Join(); // give time for the second thread to finish its actions once unlocked
			AssertEquals("Should get concurrency save exception.", typeof(ZSaveConcurrencyException), exception.GetType());
			AssertEquals("Should be concurrency of changing WE_StockOnHand by two threads.", true, exception.Message.Contains("WE_StockOnHand"));

			var otherFactory2 = new BusinessObjectFactory();
			var inventoryInOtherFactory2 = otherFactory2.LoadTop1<WhsInventoryView>(new ZQuery(WhsInventoryViewSchema.WI_WD, receive.PK));
			var pickLine1InOtherFactory2 = otherFactory2.Load<WhsPickLine>(pickLine1.PK);
			var pickLine2InOtherFactory2 = otherFactory2.Load<WhsPickLine>(pickLine2.PK);
			AssertEquals("Inventory should be reduced correctly.", 90m, inventoryInOtherFactory2.WI_TotalUnits);
			AssertEquals("PickLine1 should be not picked, as transfer pick line is picked.", true, pickLine1InOtherFactory2.WZ_PickedDateTime.IsEmpty);
			AssertEquals("PickLine2 should be not picked, as save was rolled back due to concurrency.", true, pickLine2InOtherFactory2.WZ_PickedDateTime.IsEmpty);

			var transfersInOtherFactory2 = otherFactory2.Load<WhsTransfer>(new ZQuery(WhsDocketSchema.WD_WP_ParentPickForTransfer, new[] { pick1.PK, pick2.PK }));
			AssertEquals("Only 1 transfer should be created.", 1, transfersInOtherFactory2.Length);
			AssertEquals("Transfer line should be picked.", true, !transfersInOtherFactory2[0].Lines[0].PickedTime.IsEmpty);
		}

		class AfterSaveInTransactionService_ForTesting : IAfterSaveInTransactionService
		{
			public AfterSaveInTransactionService_ForTesting(BusinessObjectFactory factory)
			{
				Factory = factory;
			}

			[System.Diagnostics.CodeAnalysis.SuppressMessage("CodeQuality", "IDE0052:Remove unread private members", Justification = "Used in AfterSaveInTransactionService_ForTesting")]
			readonly BusinessObjectFactory Factory;

			public event EventHandler BeforeFinalCheck_ForTesting;

			void IAfterSaveInTransactionService.DoFinalCheckBeforeCommit(IEnumerable<BusinessObject> businessObjectsInOnSavingOrder)
