		#region TestDeadLock_SavingPickAndOrderAtTheSameTime

		[UseSnapshotProtection]
		public void TestDeadLock_SavingPickAndOrderAtTheSameTime()
		{
			// time pick and order save to create a deadlock
			var data = new TestDataSimpleEnvironment(Factory);
			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 10m);

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickByAttachingOrders(order);
			Factory.Save();
			AssertEquals("Precondition", pick.GetAllPickLines().Count(), 0);

			WhsTestHelperFunctions.DisablePageLocks(Db.Connection);

			Exception exception = null;
			var secondOperatorThread = new Thread(() =>
			{
				try
				{
					using (Db.DisposableActionForDbConnection())
					using (var connectionForUser2 = Db.NewExtraConnectionToMainDb())
					{
						var otherFactory2 = new BusinessObjectFactory(connectionForUser2) { RefreshEnabled = false };
						var pickInOtherFactory2 = otherFactory2.Load<WhsPick>(pick.PK);
						pickInOtherFactory2.AutoAllocateItemsWithMock();

						try
						{
							otherFactory2.Save();
						}
						catch (Exception ex)
						{
							exception = ex;
						}
					}
				}
				catch
				{
					// to prevent CW1 from crashing
				}
			});

			using (Db.DisposableActionForDbConnection())
			using (var connectionForUser1 = Db.NewExtraConnectionToMainDb())
			{
				var otherFactory1 = new BusinessObjectFactory(connectionForUser1) { RefreshEnabled = false };
				var orderInOtherFactory1 = otherFactory1.Load<WhsOrder>(order.PK);
				orderInOtherFactory1.Pick.AutoAllocateItemsWithMock();
				orderInOtherFactory1.Pick.WP_PickStatus = PickStatus.Codes.Building; // a way to hook into FactorySaving event which will change status back to NEW

				EventHandler runSecondThread = (s, e) =>
				{
					secondOperatorThread.Start();
					Thread.Sleep(5000); // let second thread to get locked
				};

				orderInOtherFactory1.Pick.WP_PickStatusInfo.ValueChanged += runSecondThread;

				try
				{
					otherFactory1.Save(); // take lock on pick while other user is slowed down
					secondOperatorThread.Join();
				}
				catch (Exception ex)
				{
					exception = ex;
				}
			}
			AssertEquals("Should not fail with deadlock.", true, !exception.Message.Contains("was deadlocked on lock resources with another process and has been chosen as the deadlock victim"));
		}

		#endregion

		#region TestICriticalChangesVersionID

		public void TestICriticalChangesVersionID_IsImmutableStatus()
		{
			var pick = Factory.New<WhsPick>();
			AssertEquals("Precondition", false, pick.IsFinalisedOrCancelled);

			AssertEquals(false, ((ICriticalChangesVersionID)pick).IsImmutableStatus);
			pick.WP_PickStatus = PickStatus.Codes.Cancelled;

			AssertEquals("Precondition", true, pick.IsFinalisedOrCancelled);
			AssertEquals(true, ((ICriticalChangesVersionID)pick).IsImmutableStatus);
		}

		public void TestICriticalChangesVersionID_CriticalChangesVersionID()
		{
			var pick = (ICriticalChangesVersionID)Factory.New<WhsPick>();
			var newGuid = ZGuid.NewZGuid();
			AssertNotEquals("Precondition", newGuid, pick.CriticalChangesVersionID);

			pick.CriticalChangesVersionID = newGuid;
			AssertEquals("Should be able to cast and set and get value", newGuid, pick.CriticalChangesVersionID);
		}

