		#region TestCriticalChanges_ExtendedLinePrice

		[TestDate(2024, 5, 7)]
		[UseSnapshotProtection]
		public void TestCriticalChanges_ExtendedLinePrice() // WI00744085
		{
			var data = new TestDataSimpleEnvironment(Factory);
			data.Org1.MiscServ.OM_WhsIsRecalculateOrderPricing = true;
			data.Part1.RelatedOrganisations[0].OU_UnitPrice = 10m;
			data.Part1.RelatedOrganisations[0].OU_RX_NKUnitPriceCurrency = "AUD";

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, "O1", data.Part1, 10m);
			var pick = Helper.CreatePickByAttachingOrders(order);
			Factory.Save();

			Helper.CreateWhsReceiveWithInventory(data.Org1, data.Whs1, "R1", data.Part1, 6m);
			Factory.Save();

			var factory1 = new BusinessObjectFactory() { RefreshEnabled = false };
			var factory2 = new BusinessObjectFactory() { RefreshEnabled = false };
			var pickInFactory1 = factory1.Load<WhsPick>(pick.PK);
			var pickInFactory2 = factory2.Load<WhsPick>(pick.PK);

			pickInFactory1.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			pickInFactory1.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 5m;

			pickInFactory2.OrderedInventories[0].AvailableInventories[0].Allocate = true;
			pickInFactory2.OrderedInventories[0].AvailableInventories[0].PickLineQuantity = 1m;

			factory1.Save();

			try
			{
				factory2.Save();
				Fail("Should throw concurrency exception");
			}
			catch (ZSaveConcurrencyException ex)
			{
				var notificationHandler = new TestNotificationHandler();
				ZExceptionReporting.HandleZSaveConcurrencyException(ex, notificationHandler);

				AssertContains("Error message should be correct (contains Extended Price).", @"While you have been working with this form, another user has made changes.

The system cannot automatically merge your changes because there are conflicts with critical fields.
Please cancel your changes and reload the form.

The following objects have critical changes and cannot be merged:
Docket Line (CargoWise Support @ 07 May 2024 00:00:00)
	Extended Price (Critical change)", notificationHandler.ReportedMessage);

				AssertExceptionThrown<ZSaveConcurrencyException>("Factory Saving Should always be rejected.", factory2.Save);// Retry
			}

			var newFactory = new BusinessObjectFactory();
			var orderInNewFactory = newFactory.Load<WhsOrder>(order.PK);
			var orderLineInNewFactory = orderInNewFactory.Lines[0];
			AssertEquals("Extended Price should match with Quantity Met.", 50m, orderLineInNewFactory.WE_ExtendedLinePrice);
			AssertEquals("Extended Price should match with Quantity Met.", 5m, orderLineInNewFactory.SumOfUnitsMet);
		}

