	#region TG_PreventUnPickedPickLinesOnFinalisedPicksTest

	class TG_PreventUnPickedPickLinesOnFinalisedPicksTest : WhsTestCaseWithFactory
	{
		#region TestTrigger_FinaliseWhsPickWithPickline

		[UseSnapshotProtection]
		[ExpectNoExceptions]
		public void TestTrigger_FinaliseWhsPickWithPickedPickline()
		{
			TestTrigger_FinaliseAdjustmentLineWithPickline(true);
		}

		[UseSnapshotProtection]
		[ExpectNoExceptions]
		public void TestTrigger_FinaliseWhsPickWithUnpickedPickline()
		{
			TestTrigger_FinaliseAdjustmentLineWithPickline(false);
		}

		void TestTrigger_FinaliseAdjustmentLineWithPickline(bool isPicked)
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var receive = Helper.CreateWhsReceive(data.Org1, data.Whs1, "R1");
			Helper.CreateWhsReceiveInventoryLine(receive, data.Part1, 10m);
			receive.AllocateLocationsWithMock();
			receive.FinaliseDocketWithoutUserConfirmation();
			AssertIsFinalisedPrecondition(receive);

			var order = Helper.CreateWhsOrder(data.Org1, data.Whs1, "O1", WhsPickOption.Codes.Auto);
			var orderLine = Helper.CreateWhsOrderLine(order, data.Part1, 10m);
			Factory.Save();
			var pick = Helper.CreatePickNew(true, false, order);

			orderLine.PickLines[0].WZ_PickedDateTime = isPicked ? ZDateTimeOffset.Today : ZDateTimeOffset.Empty;
			pick.WP_PickStatus = PickStatus.Codes.Finalised;
			pick.WP_FinalizedDateUtc = ZDateTime.UtcNow;
			order.WD_DocketStatus = WhsOrderStatus.Codes.Departed;
			AssertIsFinalisedPrecondition(pick);
			AssertIsFinalisedPrecondition(pick.Orders[0]);

			if (isPicked)
			{
				AssertNoExceptionThrown("Pick is finalised with picked picklines. Should not throw exception", Factory.Save);
			}
			else
			{
				NUnit.Framework.Assert.That(Factory.Save, CustomConstraints.InnermostExceptionThrown(typeof(SqlException), WhsPick.PreventUnPickedPickLinesOnFinalisedPicks), "Pick is finalised with any unpicked picklines. Should have thrown an exception");
			}
		}

		#endregion
	}

