	#region Triggers_WhsPickTests class

	class Triggers_WhsPickTests : WhsTestCaseWithFactory
	{
		#region TestTG_WhsPick_HasCorrectWarehouse

		public void TestTG_WhsPick_HasCorrectWarehouse()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var whs2 = Helper.CreateWarehouse("WH2");

			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 1m);
			var pick = Helper.CreatePickByAttachingOrders(order);

			Factory.Save();

			// change whs of pick to ensure trigger will prevent the change
			var exception = AssertExceptionThrown<SqlException>("Trigger should have prevented save.",
				() => CargoWise.Database.TestFramework.ObjectModel.WhsPick
					.UpdateWhere(l => l.PK == pick.PK.ToGuid())
					.Set(l => l.WP_WW_Whs, whs2.PK.ToSqlParameter())
					.Set(l => l.WP_WL_DockDoor, whs2.WW_DefaultOutboundDockDoor.ToSqlParameter())
					.Post(Db.Connection));
			AssertEquals(true, exception.Message.Contains(WhsDocket.PreventOrderAndWorkOrderWarehouseNotMatchingPicksWarehouse));
		}

		#endregion

		#region TG_WhsPick_EnsureDockDoorAssignmentsAreReferenced_ByAPick

		public void TestTG_WhsPick_EnsureDockDoorAssignmentsAreReferenced_ByAPick()
		{
			var data = new TestDataSimpleEnvironment(Factory);
			var order = Helper.CreateWhsOrderWithOrderLine(data.Org1, data.Whs1, data.Part1, 1m);
			var	pick = Helper.CreatePickByAttachingOrders(order);
			var assignment = Factory.New<WhsDockDoorAssignment>();
			assignment.WDA_WL_AssignedDockDoor = data.Whs1.WW_DefaultOutboundDockDoor;
			pick.WP_WL_DockDoor = ZGuid.Empty;
			pick.WP_WDA_DockDoorAssignment = assignment.PK;

			AssertNoExceptionThrown("Expect no error", Factory.Save);

			pick.WP_WDA_DockDoorAssignment = ZGuid.Empty;
			pick.WP_WL_DockDoor = data.Whs1.WW_DefaultOutboundDockDoor;

			var exception = AssertExceptionThrown<ZSaveException>("Trigger should have prevented save.", Factory.Save);
			AssertEquals(true, exception.Message.Contains("Attempt to leave a Dock Door Assignment with no referencing Picks."));
		}

		#endregion
	}

